ASSET_DIR = Path(os.environ.get('STUDY_ASSET_DIR', 'publication_assets')).expanduser().resolve()
MASTER_FILENAME = '骨密度與血紅素_重整總表_最終優化版.csv'
SOURCE_FILES = ['骨密度及宏碁骨密清單(去個資化)_20230101～20231231.csv', '骨密度及宏碁骨密清單(去個資化)_20240101～20241231.csv', '骨密度及宏碁骨密清單(去個資化)_20220101～20221231.csv', '骨密度及宏碁骨密清單(長期)(去個資化)_20200101～20201231.csv', '骨密度及宏碁骨密清單(去個資化)_20200101～20201231.csv', '骨密度及宏碁骨密清單(長期)(去個資化)_20180101～20181231.csv', '骨密度及宏碁骨密清單(長期)(去個資化)_20190101～20191231.csv', '骨密度及宏碁骨密清單(去個資化)_20210101～20211231.csv']
ANNUAL_FILES = [f'{year}.csv' for year in range(2017, 2025)]
WEATHER_FILENAME = '29沙鹿.csv'
FIG2_FILENAME = 'Fig2_20260921.tif'
REQUIRED_VERSIONS = {'numpy': '2.4.6', 'pandas': '2.2.3', 'scipy': '1.16.3', 'statsmodels': '0.15.0', 'patsy': '1.0.3', 'matplotlib': '3.10.0', 'sklearn': '1.6.1', 'xgboost': '3.4.1', 'lightgbm': '4.6.0', 'openpyxl': '3.1.5', 'PIL': '11.3.0', 'IPython': '9.18.1'}

if not DATA_DIR.is_dir(): raise FileNotFoundError(f'Raw data directory not found: {DATA_DIR}')
for name in SOURCE_FILES + ANNUAL_FILES + [WEATHER_FILENAME]:
    if not (DATA_DIR/name).is_file(): raise FileNotFoundError(f'Required raw input missing: {DATA_DIR/name}')
if not (ASSET_DIR/FIG2_FILENAME).is_file():
    raise FileNotFoundError(f'Required unchanged Fig 2 asset missing: {ASSET_DIR/FIG2_FILENAME}')
if OUTPUT_DIR.exists() and any(OUTPUT_DIR.iterdir()):
    raise FileExistsError('OUTPUT_DIR must be empty; select a new run directory to retain prior results.')
# 原OUTPUT是研究資料夾的子目錄；來源只讀取明列的根目錄 CSV，沒有遞迴掃描。
# 允許 DATA_DIR/OUTPUT/<本次目錄>，仍禁止把原始資料根目錄或其父目錄當作公開輸出。
if OUTPUT_DIR == DATA_DIR or OUTPUT_DIR in DATA_DIR.parents:
    raise ValueError('Public output cannot be the raw data directory or its ancestor.')
if OUTPUT_DIR == PRIVATE_ROOT or OUTPUT_DIR in PRIVATE_ROOT.parents or PRIVATE_ROOT in OUTPUT_DIR.parents:
    raise ValueError('Private runtime files must remain outside the public output directory.')
SLIM_RUNTIME_VERSIONS = {'python':sys.version}
for module, expected in REQUIRED_VERSIONS.items():
    try: imported = importlib.import_module(module)
    except ImportError as exc:
        raise ImportError(f'Missing {module}. Install requirements.txt and restart the kernel.') from exc
    actual = imported.__version__
    SLIM_RUNTIME_VERSIONS[module] = actual
    if module != 'IPython' and actual != expected:
        raise RuntimeError(f'{module}: expected {expected}, found {actual}. Install requirements.txt and restart; no alternate version is selected.')
print(json.dumps(SLIM_RUNTIME_VERSIONS, indent=2))

PRIVATE_ROOT.mkdir(parents=True, exist_ok=True)
PRIVATE_RUN_DIR = PRIVATE_ROOT / (datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')+'_'+uuid.uuid4().hex[:8])
