folder_path = str(PRIVATE_RUN_DIR) + os.sep
print('Raw inputs validated. All row-level working files stay in the private runtime directory.')

"""## 1 Data loading and validation

Builds the current master from raw reports, then replays the existing ID/serialization validation. This replay does not independently validate the source records.

"""

import os
import glob
import re
import io
import json
import hashlib
import uuid
from pathlib import Path
from datetime import datetime, timezone
import numpy as np
import pandas as pd

R04_LEGACY_COLUMNS = [
    '去個資編號', '年齡', '性別', '骨密度檢查執行日期', '來源檔案',
    'L_BMD', 'L_T', 'Left_BMD', 'Left_T', 'Right_BMD', 'Right_T',
    'Hb_Date', 'Hb_Value',
]

R04_ORIGINAL_MASK_LIMITS = {
    'L_BMD': (0.3, 3.0), 'Left_BMD': (0.3, 3.0), 'Right_BMD': (0.3, 3.0),
    'L_T': (-8, 5), 'Left_T': (-8, 5), 'Right_T': (-8, 5), 'Hb_Value': (5, 22),
}


def parse_hb(text):
    if not isinstance(text, str): return []
    matches = re.findall(r"報告日期[：:]\s*(\d{4}-\d{2}-\d{2})[，,]\s*數值[：:]\s*(\d+\.?\d*)", text)
    return [{'Hb_Date': m[0], 'Hb_Value': float(m[1])} for m in matches]


def parse_bmd_report(text):
    if not isinstance(text, str): return {}
    text = text.replace("-l.", "-1.").replace(" l.", " 1.").replace("T- score", "T-score")
    res = {'L_BMD': np.nan, 'L_T': np.nan, 'Left_BMD': np.nan, 'Left_T': np.nan, 'Right_BMD': np.nan, 'Right_T': np.nan}
    for part, pattern in [('L', r"(?:L-spine|L1-L?4|Lumbar)(.*?)(?:Femoral|Hip|Right|Left|$)"),
                         ('Left', r"(?:Femoral.*\(left\)|Left\s*hip|Left:)(.*?)(?:Femoral|Right|L-spine|$)"),
                         ('Right', r"(?:Femoral.*\(right\)|Right\s*hip|Right:)(.*?)(?:Femoral|Left|L-spine|$)")]:
        match = re.search(pattern, text, re.IGNORECASE | re.DOTALL)
        if match:
            chunk = match.group(1)
            bmd_m = re.search(r"\b(\d+\.\d+)\s*g/cm2", chunk)
            t_m = re.search(r"T-?score\s*(?:of|=|:)?\s*([+-]?\d+\.?\d*)", chunk, re.IGNORECASE)
            if bmd_m: res[f'{part}_BMD'] = float(bmd_m.group(1))
            if t_m: res[f'{part}_T'] = float(t_m.group(1))
    return res


def r04_sha256(data):
    return hashlib.sha256(data).hexdigest()


def r04_raw_id(filename, file_sha256, source_row_id):
    payload = json.dumps([filename, file_sha256, int(source_row_id)], ensure_ascii=False)
    return 'raw_' + r04_sha256(payload.encode('utf-8'))


def r04_csv_text(data):
    # 字串讀取用於逐列比對序列化結果；不拿此資料取代分析欄位的原本型態。
    return pd.read_csv(io.BytesIO(data), dtype=str, keep_default_na=False)


def r04_run(folder):
    root = Path(folder)
    master = root / '骨密度與血紅素_重整總表_最終優化版.csv'
    if not master.is_file():
        raise FileNotFoundError(
            f'找不到明確指定的既有總表：{master}。R04 必須與它逐列核對；'
            '不會改找其他總表或用固定筆數推定來源。'
        )
    baseline_bytes = master.read_bytes()
    baseline_sha = r04_sha256(baseline_bytes)
    baseline = r04_csv_text(baseline_bytes)
    missing = set(R04_LEGACY_COLUMNS) - set(baseline.columns)
    if missing:
        raise ValueError(f'既有總表缺少原分析欄位：{sorted(missing)}')
    # 第一次接受原版欄位；重跑只接受本版已知的追蹤欄位，避免抹掉其他修訂。
    id_cols = ['source_file', 'source_file_sha256', 'source_row_id', 'raw_row_id',
               'pairing_sub_id', 'pairing_row_id', 'Hb_record_present']
    raw_cols = [x + suffix for x in R04_ORIGINAL_MASK_LIMITS
                for suffix in ['_raw', '_outlier_flag']]
    unknown = set(baseline.columns) - set(R04_LEGACY_COLUMNS + id_cols + raw_cols)
    if unknown:
        raise ValueError(f'既有總表有本輪未定義欄位，停止以免遺失：{sorted(unknown)}')

    stamp = datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ') + '_' + uuid.uuid4().hex[:8]
    out = root / 'Revision_R04_Source_ID' / stamp
    out.mkdir(parents=True, exist_ok=False)
    checks, inventory, expansion = [], [], []
    status = {'Completed': False, 'Master_replaced': False, 'Models_updated': False,
              'True_exam_identity_verified': False, 'Baseline_sha256': baseline_sha}

    def save(name, table):
        table.to_csv(out / name, index=False, encoding='utf-8-sig')

    def check(name, value):
        ok = bool(value)
        checks.append({'Check': name, 'Passed': ok})
        if not ok:
            raise ValueError(f'R04 驗證失敗：{name}；診斷位置：{out}')

    try:
        all_files = glob.glob(os.path.join(str(root), '*.csv'))
        raw_files = [str(root / filename) for filename in SOURCE_FILES]
        check('Source_files_found', len(raw_files) > 0)
        check('Source_filenames_unique', len({Path(f).name for f in raw_files}) == len(raw_files))
        print(f'R04：找到 {len(raw_files)} 個來源檔；保留原讀取與展開規則。')
        dfs = []
        required = {'去個資編號', '年齡', '性別', '骨密度檢查執行日期', '骨密度檢查報告', 'hb'}
        for read_order, f in enumerate(raw_files, 1):
            p = Path(f)
            source_bytes = p.read_bytes()
            digest = r04_sha256(source_bytes)
            df = pd.read_csv(io.BytesIO(source_bytes), low_memory=False)
            check(f'Required_columns_present_file_{read_order}', required.issubset(df.columns))
            check(f'No_reserved_ID_columns_file_{read_order}', not (set(id_cols) & set(df.columns)))
            # 1 起算的 CSV 資料紀錄位置（不含表頭）；不是多行引號文字的實體檔案行號。
            df['source_file'] = p.name
            df['source_file_sha256'] = digest
            df['source_row_id'] = np.arange(1, len(df) + 1, dtype=np.int64)
            df['raw_row_id'] = [r04_raw_id(p.name, digest, i) for i in df['source_row_id']]
            dfs.append(df)
            inventory.append({'Read_order': read_order, 'File': p.name, 'Source_rows': len(df),
                              'File_SHA256': digest})
        full_df = pd.concat(dfs, ignore_index=True)
        check('Source_rows_nonempty', len(full_df) > 0)
        check('Raw_IDs_unique_before_expansion', full_df['raw_row_id'].is_unique)
        # 與原版完全相同的排序鍵，不增加日期解析、去重或新的同順位規則。
        full_df = full_df.sort_values(['去個資編號', '骨密度檢查執行日期'])
        processed_rows = []
        for _, row in full_df.iterrows():
            bmd_data = parse_bmd_report(row.get('骨密度檢查報告'))
            hb_entries = parse_hb(row.get('hb'))
            clean_date = str(row.get('骨密度檢查執行日期')).strip().split(' ')[0]
            base_record = {
                '去個資編號': row.get('去個資編號'), '年齡': row.get('年齡'), '性別': row.get('性別'),
                '骨密度檢查執行日期': clean_date, '來源檔案': row.get('source_file'), **bmd_data,
                **{c: row[c] for c in id_cols[:4]},
            }
            # 無可解析 Hb 仍保留一列；sub_id=0 是占位列，不代表一次 Hb 檢查。
            entries = list(enumerate(hb_entries, 1)) if hb_entries else [(0, {'Hb_Date': np.nan, 'Hb_Value': np.nan})]
            for sub_id, hb in entries:
                rec = base_record.copy()
                rec.update(hb)
                rec.update(pairing_sub_id=sub_id,
                           pairing_row_id=row['raw_row_id'] + ':hb_' + str(sub_id),
                           Hb_record_present=(sub_id > 0))
                processed_rows.append(rec)
            expansion.append({'raw_row_id': row['raw_row_id'], 'source_file': row['source_file'],
                              'Parsed_Hb_entries': len(hb_entries), 'Expected_pairing_rows': max(1, len(hb_entries))})
        final_df = pd.DataFrame(processed_rows)
        # 明確列出原欄位；極端值遮罩前的解析數值另存 _raw，不改變遮罩後分析數值。
        for col in R04_ORIGINAL_MASK_LIMITS:
            if col not in final_df:
                final_df[col] = np.nan
        final_df = final_df[R04_LEGACY_COLUMNS + id_cols].copy()
        mask_summary = []
        for col, (lo, hi) in R04_ORIGINAL_MASK_LIMITS.items():
            final_df[col + '_raw'] = final_df[col]
            flag = (final_df[col] < lo) | (final_df[col] > hi)
            final_df[col + '_outlier_flag'] = flag
            final_df.loc[flag, col] = np.nan
            check('Mask_preserves_unflagged_' + col,
                  final_df.loc[~flag, col].equals(final_df.loc[~flag, col + '_raw']))
            check('Mask_nulls_flagged_' + col, final_df.loc[flag, col].isna().all())
            mask_summary.append({'Field': col, 'Lower_inclusive': lo, 'Upper_inclusive': hi,
                                 'Masked_pairing_rows': int(flag.sum()),
                                 'Missing_before_mask': int(final_df[col + '_raw'].isna().sum())})

        expansion = pd.DataFrame(expansion)
        counts = final_df.groupby('raw_row_id', sort=False).size()
        expected = expansion.set_index('raw_row_id')['Expected_pairing_rows']
        check('Expansion_counts_match_each_source_row', counts.reindex(expected.index).equals(expected))
        check('All_source_rows_represented', set(counts.index) == set(full_df['raw_row_id']))
        check('Pairing_IDs_nonmissing', final_df['pairing_row_id'].notna().all())
        check('Pairing_IDs_unique', final_df['pairing_row_id'].is_unique)
        check('Source_file_alias_matches', final_df['source_file'].equals(final_df['來源檔案']))
        check('Pairing_ID_matches_source_and_position', final_df['pairing_row_id'].equals(
            final_df['raw_row_id'] + ':hb_' + final_df['pairing_sub_id'].astype(str)))
        check('Placeholder_has_no_Hb', final_df.loc[~final_df['Hb_record_present'], ['Hb_Date', 'Hb_Value_raw']].isna().all().all())
        check('Original_source_age_preserved', final_df['年齡'].reset_index(drop=True).equals(
            final_df['raw_row_id'].map(full_df.set_index('raw_row_id')['年齡']).reset_index(drop=True)))

        candidate = out / 'R04_candidate_master_PRIVATE.csv'
        final_df.to_csv(candidate, index=False, na_rep='', encoding='utf-8-sig')
        candidate_bytes = candidate.read_bytes()
        candidate_text = r04_csv_text(candidate_bytes)
        # 使用相同 CSV 讀回方式檢查；含列順序、識別碼字串、日期、缺失值與分析數值。
        check('Pairing_rows_equal_existing_master', len(candidate_text) == len(baseline))
        comparison, differences = [], []
        for col in R04_LEGACY_COLUMNS:
            unequal = baseline[col].ne(candidate_text[col])
            comparison.append({'Column': col, 'Compared_rows': len(baseline),
                               'Changed_or_reordered_rows': int(unequal.sum())})
            if unequal.any():
                differences.append(pd.DataFrame({'Output_row_1based': np.flatnonzero(unequal) + 1,
                    'Column': col, 'Before': baseline.loc[unequal, col].to_numpy(),
                    'After': candidate_text.loc[unequal, col].to_numpy()}))
        comparison = pd.DataFrame(comparison)
        save('legacy_columns_comparison.csv', comparison)
        if differences:
            save('value_or_order_differences_PRIVATE.csv', pd.concat(differences, ignore_index=True))
        check('All_original_values_and_order_unchanged', comparison['Changed_or_reordered_rows'].eq(0).all())
        check('CSV_roundtrip_pairing_IDs_unique', candidate_text['pairing_row_id'].is_unique)
        check('CSV_roundtrip_pairing_IDs_exact', candidate_text['pairing_row_id'].equals(final_df['pairing_row_id']))
        previous_has_ids = set(id_cols).issubset(baseline.columns)
        if set(id_cols) & set(baseline.columns):
            check('Previous_ID_schema_complete', previous_has_ids)
            check('Previous_tracking_values_reproduced', baseline[id_cols + raw_cols].equals(candidate_text[id_cols + raw_cols]))

        inventory = pd.DataFrame(inventory)
        per_file = expansion.groupby('source_file', sort=False).agg(
            Pairing_rows=('Expected_pairing_rows', 'sum'), Parsed_Hb_entries=('Parsed_Hb_entries', 'sum'),
            No_parsed_Hb_source_rows=('Parsed_Hb_entries', lambda s: int(s.eq(0).sum())))
        inventory = inventory.merge(per_file, left_on='File', right_index=True, validate='one_to_one')
        save('source_inventory.csv', inventory)
        mask_summary = pd.DataFrame(mask_summary)
        save('mask_summary.csv', mask_summary)
        id_summary = pd.DataFrame([{'Source_files': len(inventory), 'Source_rows': len(full_df),
            'Pairing_rows': len(final_df), 'Unique_raw_row_IDs': final_df['raw_row_id'].nunique(),
            'Unique_pairing_IDs': final_df['pairing_row_id'].nunique(),
            'Parsed_Hb_entry_rows': int(final_df['Hb_record_present'].sum()),
            'No_parsed_Hb_placeholder_rows': int((~final_df['Hb_record_present']).sum()),
            'Previous_master_had_IDs': previous_has_ids}])
        save('ID_summary.csv', id_summary)
        # 來源檔變動會改變該檔所有追蹤 ID；不同版本不可當成同一版直接混接。
        manifest = {'ID_schema': 'R04_file_version_source_row_and_Hb_position_v1',
            'Source_row_id_definition': '1-based parsed CSV record, excluding header; not physical line number',
            'Raw_ID_inputs': ['source_file', 'source_file_sha256', 'source_row_id'],
            'Pairing_ID_inputs': ['raw_row_id', 'pairing_sub_id'],
            'Pairing_sub_id': '1-based Hb parser match order; 0 means no parsed Hb placeholder',
            'Hb_date_meaning': 'laboratory_report_date', 'IDs_are_exam_or_specimen_IDs': False,
            'Raw_numeric_fields': 'parsed numeric values before original outlier masking; not report text',
            'Age_policy_changed': False, 'Parser_changed': False, 'File_order_changed': False,
            'Mask_limits': R04_ORIGINAL_MASK_LIMITS, 'Baseline_sha256': baseline_sha,
            'Candidate_sha256': r04_sha256(candidate_bytes),
            'Source_files': inventory.to_dict('records')}
        (out / 'manifest.json').write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding='utf-8')
        # 所有核對通過才備份並更新原總表；任一來源或基準在途中變動即停止。
        check('Baseline_unchanged_during_run', r04_sha256(master.read_bytes()) == baseline_sha)
        check('Sources_unchanged_during_run', all(
            r04_sha256((root / r['File']).read_bytes()) == r['File_SHA256']
            for r in inventory.to_dict('records')))
        backup = out / 'R04_previous_master_PRIVATE.csv'
        backup.write_bytes(baseline_bytes)
        check('Backup_byte_identical', r04_sha256(backup.read_bytes()) == baseline_sha)
        staged = root / ('.R04_staged_' + stamp + '.tmp')
        try:
            staged.write_bytes(candidate_bytes)
            check('Staged_file_verified', r04_sha256(staged.read_bytes()) == r04_sha256(candidate_bytes))
            os.replace(staged, master)
            status['Master_replaced'] = True
            check('Updated_master_verified', r04_sha256(master.read_bytes()) == r04_sha256(candidate_bytes))
        finally:
            if staged.exists():
                staged.unlink()
        status.update(Completed=True, Original_columns_and_order_unchanged=True,
                      Source_files=len(inventory), Source_rows=len(full_df), Pairing_rows=len(final_df),
                      ID_schema=manifest['ID_schema'], Backup_file=str(backup))
        print('\n=== 請回傳：R04 1 來源檔與展開 ===')
        print(inventory.drop(columns='File_SHA256').to_string(index=False))
        print('\n=== 請回傳：R04 2 來源列與配對列 ID ===')
        print(id_summary.to_string(index=False))
        print('\n=== 請回傳：R04 3 原有欄位與列順序核對 ===')
        print(comparison.to_string(index=False))
        print('\n=== 請回傳：R04 4 原遮罩規則與保留值 ===')
        print(mask_summary.to_string(index=False))
        print('\n=== 請回傳：R04 5 最終驗證 ===')
        print(pd.DataFrame([{'Checks': len(checks), 'All_passed': all(c['Passed'] for c in checks),
            'Completed': True, 'Master_backed_up': True, 'Master_updated_with_IDs': True,
            'Original_values_or_order_changed': False, 'Models_updated': False,
            'True_exam_identity_verified': False}]).to_string(index=False))
        print(f'\n診斷與備份位置：{out}')

        return {'data': final_df, 'sources': full_df, 'checks': pd.DataFrame(checks),
                'inventory': inventory, 'output_dir': str(out), 'status': status}
    except Exception as exc:
        status.update(Error_type=type(exc).__name__, Error=str(exc))
        print(f'R04 已停止；Master_replaced={status["Master_replaced"]}；診斷位置：{out}')
        raise
    finally:
        save('validation.csv', pd.DataFrame(checks))
        (out / 'run_status.json').write_text(json.dumps(status, ensure_ascii=False, indent=2), encoding='utf-8')


def build_current_master_from_raw(root):
    """Create the verification master in this run, using the unchanged source parsers.

    This replaces the dependency on an earlier notebook's master CSV. The replay
    verifies parsing/serialization consistency; it is not independent EHR validation.
    """
    destination = Path(root) / MASTER_FILENAME
    if destination.exists():
        raise FileExistsError('Fresh staging is required; an earlier master is not accepted: ' + str(destination))
    parts = []
    for filename in SOURCE_FILES:
        table = pd.read_csv(Path(root) / filename, low_memory=False)
        table['來源檔案'] = filename
        parts.append(table)
    joined = pd.concat(parts, ignore_index=True)
    joined = joined.sort_values(['去個資編號', '骨密度檢查執行日期'])
    records = []
    for _, row in joined.iterrows():
        base = {'去個資編號':row.get('去個資編號'), '年齡':row.get('年齡'),
            '性別':row.get('性別'),
            '骨密度檢查執行日期':str(row.get('骨密度檢查執行日期')).strip().split(' ')[0],
            '來源檔案':row['來源檔案'], **parse_bmd_report(row.get('骨密度檢查報告'))}
        entries = parse_hb(row.get('hb'))
        for hb in (entries if entries else [{'Hb_Date':np.nan,'Hb_Value':np.nan}]):
            records.append(dict(base, **hb))
    current = pd.DataFrame(records)
    for column, (lower, upper) in R04_ORIGINAL_MASK_LIMITS.items():
        if column not in current: current[column] = np.nan
        current.loc[(current[column] < lower) | (current[column] > upper), column] = np.nan
    current = current[R04_LEGACY_COLUMNS]
    current.to_csv(destination, index=False, na_rep='', encoding='utf-8-sig')
    print(f'Created current-run master from {len(joined)} source rows: {len(current)} pairing rows.')
    return destination

build_current_master_from_raw(Path(folder_path))

R04 = None  # 若本次失敗，不讓上次成功的 R04 物件被誤認為新結果。
R04 = r04_run(folder_path)
final_df = R04['data']
full_df = R04['sources']

"""## 2 Cohort construction

Input objects are produced by preceding cells in this notebook. Outputs remain private working artifacts until the publication export section.

"""

import os
import numpy as np
import pandas as pd

def r05_load_existing_inputs(folder_path):
    weather_files = [f"{folder_path}29沙鹿.csv"]
    temp_list, rh_list = [], []

    for f in weather_files:
        try:
            df_w = pd.read_csv(f, low_memory=False)
            hour_cols = [str(i) for i in range(24)]

            df_temp = df_w[df_w['測項'] == 'AMB_TEMP'].copy()
            df_temp[hour_cols] = df_temp[hour_cols].apply(pd.to_numeric, errors='coerce').where(lambda x: (x >= 0) & (x <= 45))
            df_temp['T_daily_mean'] = df_temp[hour_cols].mean(axis=1)
            df_temp['DTR_daily'] = df_temp[hour_cols].max(axis=1) - df_temp[hour_cols].min(axis=1)
            temp_list.append(df_temp[['日期', 'T_daily_mean', 'DTR_daily']])

            df_rh = df_w[df_w['測項'] == 'RH'].copy()
            df_rh[hour_cols] = df_rh[hour_cols].apply(pd.to_numeric, errors='coerce').where(lambda x: (x >= 0) & (x <= 100))
            df_rh['RH_daily_mean'] = df_rh[hour_cols].mean(axis=1)
            rh_list.append(df_rh[['日期', 'RH_daily_mean']])
        except Exception as err:
            raise RuntimeError(f"R05 無法讀取指定氣象檔 {f}") from err

    temp_df = pd.concat(temp_list).groupby('日期').mean().reset_index() if temp_list else pd.DataFrame()
    rh_df = pd.concat(rh_list).groupby('日期').mean().reset_index() if rh_list else pd.DataFrame()

    if not temp_df.empty and not rh_df.empty:
        weather_df = pd.merge(temp_df, rh_df, on='日期', how='inner')
        weather_df['日期'] = pd.to_datetime(weather_df['日期'])
        weather_df = weather_df.sort_values('日期')

        # 基礎 30 天暴露
        weather_df['T_mean_30d'] = weather_df['T_daily_mean'].rolling(window=30, min_periods=15).mean()
        weather_df['DTR_mean_30d'] = weather_df['DTR_daily'].rolling(window=30, min_periods=15).mean()
        weather_df['RH_mean_30d'] = weather_df['RH_daily_mean'].rolling(window=30, min_periods=15).mean()

        # THI 計算
        weather_df['THI_daily_raw'] = weather_df['T_daily_mean'] - 0.55 * (1 - weather_df['RH_daily_mean']/100) * (weather_df['T_daily_mean'] - 14.4)
        weather_df['THI_mean_30d'] = weather_df['T_mean_30d'] - 0.55 * (1 - weather_df['RH_mean_30d']/100) * (weather_df['T_mean_30d'] - 14.4)

        # 氣候波動性與熱浪趨勢衝擊特徵
        weather_df['THI_std_30d'] = weather_df['THI_daily_raw'].rolling(window=30, min_periods=15).std()
        weather_df['T_std_30d'] = weather_df['T_daily_mean'].rolling(window=30, min_periods=15).std()

        # 嚴格使用 180 天滑動平均氣溫與濕度計算，修正誤乘 30 天氣溫之錯誤
        weather_df['T_mean_180d'] = weather_df['T_daily_mean'].rolling(window=180, min_periods=90).mean()
        weather_df['RH_mean_180d'] = weather_df['RH_daily_mean'].rolling(window=180, min_periods=90).mean()
        weather_df['THI_mean_180d'] = (
            weather_df['T_mean_180d'] - 0.55 * (1 - weather_df['RH_mean_180d'] / 100) * (weather_df['T_mean_180d'] - 14.4)
        )
        weather_df['THI_hot_days_365d'] = (weather_df['THI_daily_raw'] >= 27).rolling(window=365, min_periods=180).sum()
        weather_df['THI_Trend_Shock'] = weather_df['THI_mean_30d'] - weather_df['THI_mean_180d']
        weather_df.drop(columns=['THI_daily_raw'], inplace=True)
    else:
        raise ValueError("R05 指定氣象來源沒有溫度或濕度列；停止。")

    # 歷年精確年齡補全
    all_yearly_data = []
    ID_COL, DATE_COL, AGE_COL = '去個資編號', '骨密度檢查執行日期', '年齡'
    for year in range(2017, 2025):
        try:
            df_yr = pd.read_csv(f"{folder_path}{year}.csv", low_memory=False)
            yr_id = '去個資編號' if '去個資編號' in df_yr.columns else ('seq_encode' if 'seq_encode' in df_yr.columns else None)
            yr_date = '骨密度檢查執行日期' if '骨密度檢查執行日期' in df_yr.columns else ('exe_date' if 'exe_date' in df_yr.columns else None)
            yr_age = '年齡' if '年齡' in df_yr.columns else ('age' if 'age' in df_yr.columns else None)
            if yr_id and yr_date and yr_age:
                df_yr[yr_date] = pd.to_datetime(df_yr[yr_date], errors='coerce')
                all_yearly_data.append(df_yr[[yr_id, yr_date, yr_age]].rename(columns={yr_id: ID_COL, yr_date: DATE_COL, yr_age: AGE_COL}))
            else:
                raise ValueError(f'{year}.csv 缺少原程式所需的 ID、日期或年齡欄位')
        except Exception as err:
            raise RuntimeError(f'R05 無法依現有規則載入 {year}.csv；不會略過該來源') from err

    df_correct_age = pd.concat(all_yearly_data).drop_duplicates(subset=[ID_COL, DATE_COL]).rename(columns={AGE_COL: 'Correct_Age'}) if all_yearly_data else pd.DataFrame()
    return weather_df, df_correct_age

def r05_original_cohorts(master, df_correct_age, weather_df):
    ID_COL, DATE_COL, AGE_COL = "去個資編號", "骨密度檢查執行日期", "年齡"
    df_summary = master.copy()
    df_summary['Hb_Date'] = pd.to_datetime(df_summary['Hb_Date'], errors='coerce')
    df_summary[DATE_COL] = pd.to_datetime(df_summary[DATE_COL], errors='coerce')

    # 嚴格實施 180 天時間窗配對防護
    df_summary['Time_Gap_Days'] = (df_summary[DATE_COL] - df_summary['Hb_Date']).dt.days.abs()
    n_before = len(df_summary)
    df_summary = df_summary[df_summary['Time_Gap_Days'] <= 180].copy()
    print(f"[時間窗篩選] 日期不可評估或間隔 >180 天：{n_before - len(df_summary):,} 筆；R05 下方分列原因。")

    df_summary['overall_T'] = df_summary[['L_T', 'Left_T', 'Right_T']].apply(pd.to_numeric, errors='coerce').min(axis=1)
    df_summary['sex_bin'] = df_summary['性別'].map({'男': 1, '女': 0})

    if not df_correct_age.empty:
        df_summary = pd.merge(df_summary, df_correct_age, on=[ID_COL, DATE_COL], how='left')
        df_summary['年齡'] = df_summary['Correct_Age'].fillna(df_summary['年齡'])

    df_clean = pd.merge(
        df_summary.dropna(subset=['Hb_Date', 'Hb_Value', 'overall_T', '年齡', 'sex_bin']),
        weather_df, left_on='Hb_Date', right_on='日期', how='left'
    ).dropna(subset=['T_mean_30d', 'DTR_mean_30d', 'RH_mean_30d', 'THI_mean_30d', 'THI_std_30d', 'THI_Trend_Shock', 'Hb_Value', 'overall_T'])

    # 臨床極端值與異常數據過濾
    df_clean = df_clean[
        (df_clean['Hb_Value'] >= 5) & (df_clean['Hb_Value'] <= 22) &
        (df_clean['overall_T'] >= -8) & (df_clean['overall_T'] <= 5) &
        (df_clean['年齡'] >= 20) & (df_clean['年齡'] <= 110) &
        (df_clean['DTR_mean_30d'] >= 0) & (df_clean['DTR_mean_30d'] <= 25)
    ].copy()

    # 建立分組標籤
    df_clean['BMD_Status'] = np.select(
        [df_clean['overall_T'] <= -2.5, (df_clean['overall_T'] > -2.5) & (df_clean['overall_T'] < -1.0), df_clean['overall_T'] >= -1.0],
        ['1. 骨質疏鬆 (T<=-2.5)', '2. 骨質缺乏 (-2.5<T<-1.0)', '3. 正常 (T>=-1.0)'],
        default='Unknown'
    )
    df_clean['is_osteoporosis'] = np.where(df_clean['overall_T'] <= -2.5, 1, 0)
    df_clean['is_anemic'] = np.where(((df_clean['sex_bin'] == 1) & (df_clean['Hb_Value'] < 13)) | ((df_clean['sex_bin'] == 0) & (df_clean['Hb_Value'] < 12)), 1, 0)
    df_clean['Hb_Status'] = np.where(df_clean['is_anemic'] == 1, '貧血 (Anemia)', '正常 (Normal)')
    df_clean['Age_Group'] = np.select(
        [df_clean['年齡'] < 65, (df_clean['年齡'] >= 65) & (df_clean['年齡'] < 80), df_clean['年齡'] >= 80],
        ['1. 中壯年 (<65歲)', '2. 高齡者 (65-79歲)', '3. 超高齡者 (>=80歲)'],
        default='Unknown'
    )
    df_clean['THI_Label'] = np.select(
        [df_clean['THI_mean_30d'] < 21.0, (df_clean['THI_mean_30d'] >= 21.0) & (df_clean['THI_mean_30d'] < 24.0),
         (df_clean['THI_mean_30d'] >= 24.0) & (df_clean['THI_mean_30d'] < 27.0), df_clean['THI_mean_30d'] >= 27.0],
        ['1. 舒適區 (THI < 21)', '2. 溫暖區 (THI 21-24)', '3. 悶熱區/輕度熱壓力 (THI 24-27)', '4. 極熱區/重度熱壓力 (THI >= 27)'],
        default='Unknown'
    )


    # 2. 病患層級去重：主分析世代 (N=5,003) 與 敏感度分析世代 (N=19,515)

    print("\n" + "="*80)
    print("[2/8] 執行病患級別去重：建立 Primary Cohort 與 Sensitivity Cohort...")
    print("="*80)


    # 🛡️ 雙欄位別名防護：同時註冊 '年齡' 與 'Age'，保證全篇程式碼無論讀哪個都 100% 不報錯

    df_clean['Age'] = df_clean['年齡']
    #df_primary['Age'] = df_primary['年齡']
    #df_sensitivity['Age'] = df_sensitivity['年齡']


    # 主分析集：嚴格一人一筆，選取抽血與骨密檢查天數差最小者
    df_primary = (
        df_clean.sort_values(by=['去個資編號', 'Time_Gap_Days', '骨密度檢查執行日期'])
        .drop_duplicates(subset=['去個資編號'], keep='first')
        .copy()
        .reset_index(drop=True)
    )

    # 敏感度集：保留全體 19,515 筆縱向重複觀測紀錄
    df_sensitivity = df_clean.copy().reset_index(drop=True)
    return {"df_primary": df_primary, "df_sensitivity": df_sensitivity,
            "df_summary": df_summary, "df_clean": df_clean}

# R05 僅描述既有世代的形成，不配適模型、不改變篩選條件。
import io
import json
import hashlib
import uuid
from pathlib import Path
from datetime import datetime, timezone

R05_PATIENT = '去個資編號'
R05_DXA_DATE = '骨密度檢查執行日期'
R05_ID = 'pairing_row_id'
R05_WEATHER = ['T_mean_30d', 'DTR_mean_30d', 'RH_mean_30d',
               'THI_mean_30d', 'THI_std_30d', 'THI_Trend_Shock']
R05_MODEL_FIELDS = [R05_PATIENT, R05_DXA_DATE, 'Hb_Date', '年齡', '性別',
                    'L_T', 'Left_T', 'Right_T', 'Hb_Value', 'overall_T',
                    'sex_bin', 'Time_Gap_Days', 'Age'] + R05_WEATHER


def r05_assert_same_values(a, b, cols):
    left, right = a[cols].reset_index(drop=True).copy(), b[cols].reset_index(drop=True).copy()
    for col in [R05_DXA_DATE, 'Hb_Date']:
        if col in cols:
            left[col] = pd.to_datetime(left[col], errors='coerce')
            right[col] = pd.to_datetime(right[col], errors='coerce')
    # 型態不同不等同數值不同；浮點容忍僅供序列化/計算的捨入誤差。
    pd.testing.assert_frame_equal(left, right, check_dtype=False, check_exact=False,
                                  rtol=1e-12, atol=1e-12, check_names=True)


def r05_audit(master, age_lookup, weather, primary, repeated, previous, out):
    checks = []

    def check(name, ok):
        checks.append({'Check': name, 'Passed': bool(ok)})
        if not ok:
            pd.DataFrame(checks).to_csv(out/'validation.csv', index=False, encoding='utf-8-sig')
            raise ValueError(f'R05 驗證失敗：{name}；請保留診斷，不執行 7B。')

    required = [R05_ID, 'raw_row_id', 'source_file', 'source_row_id',
                R05_PATIENT, R05_DXA_DATE, 'Hb_Date', 'Hb_Value', '年齡', '性別',
                'L_T', 'Left_T', 'Right_T']
    check('R04_ID_and_analysis_columns_present', set(required).issubset(master.columns))
    check('Master_pairing_ID_unique_and_present', master[R05_ID].notna().all() and master[R05_ID].is_unique)
    check('Patient_ID_present', master[R05_PATIENT].notna().all())
    check('Weather_dates_unique_and_present', weather['日期'].notna().all() and weather['日期'].is_unique)
    if not age_lookup.empty:
        check('Existing_age_lookup_keys_unique', not age_lookup.duplicated([R05_PATIENT, R05_DXA_DATE]).any())
    check('Sensitivity_pairing_ID_unique', repeated[R05_ID].is_unique)
    check('Primary_pairing_ID_unique', primary[R05_ID].is_unique)
    check('Primary_one_row_per_patient', primary[R05_PATIENT].is_unique)

    a = master.copy()
    a['_R05_input_order'] = np.arange(len(a))
    a['R05_original_source_age'] = a['年齡']
    a[R05_DXA_DATE] = pd.to_datetime(a[R05_DXA_DATE], errors='coerce')
    a['Hb_Date'] = pd.to_datetime(a['Hb_Date'], errors='coerce')
    a['Time_Gap_Days'] = (a[R05_DXA_DATE] - a['Hb_Date']).dt.days.abs()
    a['overall_T'] = a[['L_T', 'Left_T', 'Right_T']].apply(pd.to_numeric, errors='coerce').min(axis=1)
    a['sex_bin'] = a['性別'].map({'男': 1, '女': 0})
    if not age_lookup.empty:
        # 無有效 DXA 日期的排除列沒有相同日期可匹配，描述仍採來源年齡。
        age_valid_date = age_lookup[age_lookup[R05_DXA_DATE].notna()]
        a = a.merge(age_valid_date, on=[R05_PATIENT, R05_DXA_DATE], how='left',
                    sort=False, validate='many_to_one')
        a['年齡'] = a['Correct_Age'].fillna(a['年齡'])
    a['Age'] = a['年齡']
    a = a.merge(weather, left_on='Hb_Date', right_on='日期', how='left', sort=False,
                validate='many_to_one', indicator='_R05_weather_merge')
    check('Audit_preserves_master_rows_and_order',
          a[R05_ID].tolist() == master[R05_ID].tolist())


    flags = {
        'crit_date_evaluable': a[[R05_DXA_DATE, 'Hb_Date']].notna().all(axis=1),
        'crit_gap_within_180d': a['Time_Gap_Days'].le(180),
        'crit_dxa_complete': a['overall_T'].notna(),
        'crit_hb_complete': a['Hb_Value'].notna(),
        'crit_age_complete': a['年齡'].notna(),
        'crit_sex_complete': a['sex_bin'].notna(),
        'crit_weather_complete': a[R05_WEATHER].notna().all(axis=1),
        'crit_hb_range': a['Hb_Value'].between(5, 22),
        'crit_t_range': a['overall_T'].between(-8, 5),
        'crit_age_range': a['年齡'].between(20, 110),
        'crit_dtr_range': a['DTR_mean_30d'].between(0, 25),
    }
    for name, flag in flags.items():
        a[name] = flag.fillna(False).astype(bool)
    stages = [
        ('Stage1a_Date_unevaluable', 'crit_date_evaluable', 'Temporal'),
        ('Stage1b_Gap_over_180d', 'crit_gap_within_180d', 'Temporal'),
        ('Stage2a_DXA_missing_after_mask', 'crit_dxa_complete', 'Clinical_complete'),
        ('Stage2b_Hb_missing_after_mask', 'crit_hb_complete', 'Clinical_complete'),
        ('Stage2c_Age_missing', 'crit_age_complete', 'Clinical_complete'),
        ('Stage2d_Sex_unmapped_or_missing', 'crit_sex_complete', 'Clinical_complete'),
        ('Stage3_Weather_incomplete', 'crit_weather_complete', 'Weather_complete'),
        ('Stage4a_Hb_outside_range', 'crit_hb_range', 'Plausibility'),
        ('Stage4b_T_outside_range', 'crit_t_range', 'Plausibility'),
        ('Stage4c_Age_outside_range', 'crit_age_range', 'Plausibility'),
        ('Stage4d_DTR_outside_range', 'crit_dtr_range', 'Plausibility'),
    ]
    alive = pd.Series(True, index=a.index)
    a['R05_exclusion_stage'] = 'Included_repeated'
    flow, stage_inputs = [], {}
    for label, flag, phase in stages:
        stage_inputs[label] = alive.copy()
        removed = alive & ~a[flag]
        remains = alive & a[flag]
        a.loc[removed, 'R05_exclusion_stage'] = label
        flow.append({'Stage': label, 'Original_pipeline_phase': phase,
                     'Rows_entering': int(alive.sum()), 'Rows_removed': int(removed.sum()),
                     'Rows_remaining': int(remains.sum()),
                     'Patients_with_removed_pairs': a.loc[removed, R05_PATIENT].nunique(),
                     'Patients_with_remaining_pairs': a.loc[remains, R05_PATIENT].nunique()})
        alive = remains
    flow = pd.DataFrame(flow)
    a['is_included_sensitivity'] = alive
    a['is_included_primary'] = a[R05_ID].isin(primary[R05_ID])
    check('Audit_final_IDs_equal_original_pipeline_IDs',
          a.loc[alive, R05_ID].tolist() == repeated[R05_ID].tolist())
    check('Exclusion_rows_each_have_one_stage',
          (a['R05_exclusion_stage'].ne('Included_repeated') == ~alive).all())
    check('Flow_removed_plus_retained_equals_master',
          int(flow['Rows_removed'].sum()) + len(repeated) == len(master))
    check('Primary_is_subset_and_covers_eligible_patients',
          set(primary[R05_ID]).issubset(set(repeated[R05_ID])) and
          set(primary[R05_PATIENT]) == set(repeated[R05_PATIENT]))
    selected_by_original_rule = repeated.sort_values(
        [R05_PATIENT, 'Time_Gap_Days', R05_DXA_DATE]).drop_duplicates(R05_PATIENT, keep='first')
    check('Primary_selection_rule_and_order_unchanged',
          selected_by_original_rule[R05_ID].tolist() == primary[R05_ID].tolist())
    aligned = a.set_index(R05_ID).loc[repeated[R05_ID]].reset_index()
    r05_assert_same_values(aligned, repeated, R05_MODEL_FIELDS)
    check('Audit_values_equal_actual_analysis_values', True)
    for name, d in [('Primary', primary), ('Sensitivity', repeated)]:
        check(name+'_R04_tracking_columns_retained', set(required).issubset(d.columns))
        provenance = ['raw_row_id', 'source_file', 'source_row_id']
        pd.testing.assert_frame_equal(d.set_index(R05_ID)[provenance],
            master.set_index(R05_ID).loc[d[R05_ID], provenance], check_dtype=False)
        check(name+'_source_ID_mapping_preserved', True)

    # 非互斥原因：總母體與該原因所屬原篩選階段的分母分別列出。
    date_ok = a['crit_date_evaluable']
    after_time = date_ok & a['crit_gap_within_180d']
    clinical_ok = a[['crit_dxa_complete', 'crit_hb_complete', 'crit_age_complete', 'crit_sex_complete']].all(axis=1)
    before_weather = after_time & clinical_ok
    before_ranges = before_weather & a['crit_weather_complete']
    definitions = [
        ('DXA_date_missing_or_unparseable', a[R05_DXA_DATE].isna(), pd.Series(True, index=a.index)),
        ('Hb_report_date_missing_or_unparseable', a['Hb_Date'].isna(), pd.Series(True, index=a.index)),
        ('Evaluable_gap_over_180d', date_ok & ~a['crit_gap_within_180d'], date_ok),
        ('No_available_T_after_mask', ~a['crit_dxa_complete'], after_time),
        ('Hb_missing_after_mask', ~a['crit_hb_complete'], after_time),
        ('Age_missing', ~a['crit_age_complete'], after_time),
        ('Sex_unmapped_or_missing', ~a['crit_sex_complete'], after_time),
        ('No_match_in_current_weather_table', a['_R05_weather_merge'].eq('left_only'), before_weather),
    ]
    definitions += [('Missing_'+c, a[c].isna(), before_weather) for c in R05_WEATHER]
    for label, col, flag in [('Hb', 'Hb_Value', 'crit_hb_range'), ('T', 'overall_T', 'crit_t_range'),
                             ('Age', '年齡', 'crit_age_range'), ('DTR', 'DTR_mean_30d', 'crit_dtr_range')]:
        definitions.append((label+'_nonmissing_outside_range', a[col].notna() & ~a[flag], before_ranges))
    reasons = pd.DataFrame([{'Reason': label, 'Rows_in_master': int(mask.sum()),
                             'Rows_entering_relevant_phase': int(phase.sum()),
                             'Affected_rows_at_relevant_phase': int((mask & phase).sum())}
                            for label, mask, phase in definitions])
    # 僅描述；排除組的缺失率/極端值沿用遮罩後數值，不能將缺失當成正常或陰性。
    groups = {'Master': a, 'Included_repeated': a[alive],
              'Primary': a[a['is_included_primary']], 'Excluded_from_repeated': a[~alive]}
    cohorts, continuous, sex_rows = [], [], []
    variables = {'年齡': 'Age', 'Hb_Value': 'Hemoglobin', 'overall_T': 'Minimum_T_score',
                 'Time_Gap_Days': 'Absolute_gap_days'}
    for name, d in groups.items():
        cohorts.append({'Cohort': name, 'Pairing_rows': len(d),
                        'Unique_patients': d[R05_PATIENT].nunique(),
                        'Age_n': d['年齡'].notna().sum(), 'Sex_evaluable_n': d['sex_bin'].notna().sum(),
                        'Hb_n': d['Hb_Value'].notna().sum(), 'Minimum_T_n': d['overall_T'].notna().sum()})
        for col, label in variables.items():
            values = pd.to_numeric(d[col], errors='coerce')
            observed = values.dropna()
            continuous.append({'Cohort': name, 'Variable': label, 'Nonmissing_n': len(observed),
                'Missing_n': int(values.isna().sum()), 'Mean': observed.mean(), 'SD': observed.std(ddof=1),
                'Median': observed.median(), 'Q1': observed.quantile(.25), 'Q3': observed.quantile(.75)})
        denominator = int(d['sex_bin'].notna().sum())
        females = int(d['sex_bin'].eq(0).sum())
        sex_rows.append({'Cohort': name, 'Sex_evaluable_n': denominator, 'Female_n': females,
                        'Female_percent_evaluable': 100*females/denominator if denominator else np.nan,
                        'Sex_missing_or_unmapped_n': int(d['sex_bin'].isna().sum())})
    cohorts, continuous, sex_rows = map(pd.DataFrame, [cohorts, continuous, sex_rows])
    included_patients = set(a.loc[alive, R05_PATIENT])
    excluded_patients = set(a.loc[~alive, R05_PATIENT])
    patient_overlap = pd.DataFrame([{
        'Master_patients': a[R05_PATIENT].nunique(),
        'Only_included_pairs': len(included_patients - excluded_patients),
        'Both_included_and_excluded_pairs': len(included_patients & excluded_patients),
        'Only_excluded_pairs': len(excluded_patients - included_patients),
    }])
    check('Patient_membership_categories_partition_master',
          int(patient_overlap.iloc[0, 1:].sum()) == a[R05_PATIENT].nunique())

    previous_checks = []
    for name, current in [('df_primary', primary), ('df_sensitivity', repeated)]:
        prior = previous[name]
        if prior is None:
            previous_checks.append({'Dataset': name, 'Previous_runtime_available': False,
                                    'Values_and_order_match': None, 'Previous_IDs_available': False,
                                    'IDs_match': None})
        else:
            # 明確比對指定變數；不依筆數搜尋記憶體，不用日期鍵補猜舊 ID。
            r05_assert_same_values(prior, current, R05_MODEL_FIELDS)
            had_ids = R05_ID in prior.columns
            if had_ids:
                check(name+'_previous_IDs_and_order_match', prior[R05_ID].tolist() == current[R05_ID].tolist())
            check(name+'_previous_values_and_order_match', True)
            previous_checks.append({'Dataset': name, 'Previous_runtime_available': True,
                'Values_and_order_match': True, 'Previous_IDs_available': had_ids,
                'IDs_match': True if had_ids else None})
    previous_checks = pd.DataFrame(previous_checks)
    date_rows = []
    for name, d in groups.items():
        for col in [R05_DXA_DATE, 'Hb_Date']:
            date_rows.append({'Scope': name, 'Date_field': col,
                             'Date_min': d[col].min(), 'Date_max': d[col].max(),
                             'Nonmissing_pairing_rows': int(d[col].notna().sum())})
    date_rows.append({'Scope': 'Current_weather_feature_table', 'Date_field': '日期',
                      'Date_min': weather['日期'].min(), 'Date_max': weather['日期'].max(),
                      'Nonmissing_pairing_rows': np.nan})
    totals = pd.DataFrame([{
        'Master_pairing_rows': len(master),
        'Date_unevaluable_rows': int((~date_ok).sum()),
        'Evaluable_gap_over_180d_rows': int((date_ok & ~a['crit_gap_within_180d']).sum()),
        'Rows_after_temporal_filter': int(after_time.sum()),
        'Additional_clinical_weather_excluded_rows': int((after_time & ~alive).sum()),
        'Final_sensitivity_rows': len(repeated), 'Total_excluded_rows': int((~alive).sum()),
        'Primary_rows': len(primary), 'Eligible_pairs_not_selected_for_primary': len(repeated)-len(primary),
    }])
    tables = {'sequential_attrition': flow, 'attrition_totals': totals, 'overlapping_reasons': reasons,
              'cohort_denominators': cohorts, 'group_continuous_description': continuous,
              'group_sex_description': sex_rows, 'patient_overlap': patient_overlap,
              'previous_runtime_comparison': previous_checks, 'date_ranges': pd.DataFrame(date_rows),
              'validation': pd.DataFrame(checks)}
    for name, table in tables.items():
        table.to_csv(out/(name+'.csv'), index=False, encoding='utf-8-sig')
    private_cols = required + ['R05_original_source_age', 'Age', 'sex_bin', 'overall_T', 'Time_Gap_Days']
    private_cols += R05_WEATHER + list(flags) + ['R05_exclusion_stage', 'is_included_sensitivity', 'is_included_primary']
    a[list(dict.fromkeys(private_cols))].to_csv(out/'row_flags_PRIVATE.csv', index=False, encoding='utf-8-sig')
    # 簡明輸出結案摘要；完整描述表保存在同一資料夾。
    print('\n=== 請回傳：R05 1 逐步排除流程 ===')
    print(flow.drop(columns='Original_pipeline_phase').to_string(index=False))
    print(totals.to_string(index=False))
    print('\n=== 請回傳：R05 2 排除原因（非互斥） ===')
    print(reasons.to_string(index=False))
    print('\n=== 請回傳：R05 3 世代分母 ===')
    print(cohorts.to_string(index=False))
    print('\n=== 請回傳：R05 4 組別描述 ===')
    print(continuous[['Cohort', 'Variable', 'Nonmissing_n', 'Mean', 'SD']].round(4).to_string(index=False))
    print(sex_rows.round(2).to_string(index=False))
    print('\n=== 請回傳：R05 5 病人重疊與既有世代核對 ===')
    print(patient_overlap.to_string(index=False))
    print(previous_checks.to_string(index=False))
    print('\n=== 請回傳：R05 6 驗證 ===')
    print(pd.DataFrame([{'Checks': len(checks), 'All_passed': all(x['Passed'] for x in checks),
        'Final_IDs_match_original_pipeline': True, 'Primary_selection_unchanged': True,
        'Models_updated': False, 'Formal_tables_replaced': False}]).to_string(index=False))
    return {'tables': tables, 'row_flags': a, 'Completed': True, 'Output_dir': str(out)}


def r05_run(folder, previous):
    root = Path(folder)
    out = root/'Revision_R05_Attrition'/(datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')+'_'+uuid.uuid4().hex[:8])
    out.mkdir(parents=True, exist_ok=False)
    status = {'Completed': False, 'Models_updated': False, 'Formal_tables_replaced': False}
    try:
        master_path = root/'骨密度與血紅素_重整總表_最終優化版.csv'
        master_bytes = master_path.read_bytes()
        master = pd.read_csv(io.BytesIO(master_bytes), low_memory=False)
        if R05_ID not in master or master[R05_ID].isna().any() or not master[R05_ID].is_unique:
            raise ValueError('總表缺少唯一 pairing_row_id；請先完成已提供的 R04。')
        weather, age_lookup = r05_load_existing_inputs(str(root)+'/')
        if weather.empty or weather['日期'].isna().any() or not weather['日期'].is_unique:
            raise ValueError('現有氣象表為空或日期鍵不唯一；停止，不改用其他氣象版本。')
        bundle = r05_original_cohorts(master, age_lookup, weather)
        result = r05_audit(master, age_lookup, weather, bundle['df_primary'],
                           bundle['df_sensitivity'], previous, out)
        result.update(bundle)
        result.update(weather_df=weather, df_correct_age=age_lookup)
        metadata = {
            'Base_notebook': 'self-contained analysis implementation', 'Reviewer_comments': ['R1 Major 7', 'R2-5'],
            'Master_sha256': hashlib.sha256(master_bytes).hexdigest(),
            'Weather_version': 'Original_Cell7_row_based_windows_unchanged',
            'Age_policy': 'Original_Cell7_annual_exact_match_then_original_source_unchanged',
            'Hb_date_meaning': 'laboratory_report_date',
            'Temporal_rule': 'abs((DXA_Date - Hb_Date).days) <= 180; retain original pandas day calculation',
            'Within_phase_reporting_order': 'DXA, Hb, age, sex for clinical completeness; Hb, T, age, DTR for ranges',
            'Sequential_counts_depend_on_order': True, 'Overlapping_reasons_are_not_additive': True,
            'Group_description_unit': 'Pairing rows; primary has one row per patient',
            'Patient_groups_may_overlap': True, 'Group_comparison_P_values_produced': False,
            'Excluded_age_description': 'Same annual exact-date age lookup; no valid date retains original source age',
            'Long_window_and_hourly_coverage_verified_here': False,
            'Limits': {'Gap_days_inclusive': 180, 'Hb': [5,22], 'T': [-8,5], 'Age': [20,110], 'DTR': [0,25]},
        }
        (out/'analysis_specification.json').write_text(json.dumps(metadata, ensure_ascii=False, indent=2), encoding='utf-8')
        status.update(Completed=True, Master_rows=len(master), Sensitivity_rows=len(bundle['df_sensitivity']),
                      Primary_rows=len(bundle['df_primary']))
        print(f'\nR05 輸出位置：{out}')

        return result
    except Exception as exc:
        status.update(Error_type=type(exc).__name__, Error=str(exc))
        print(f'R05 停止，未更新正式世代變數；診斷位置：{out}')
        raise
    finally:
        (out/'run_status.json').write_text(json.dumps(status, ensure_ascii=False, indent=2), encoding='utf-8')

# 只查看這兩個明確名稱；無既有 runtime 時仍按原程式重建，狀態會明列未做跨執行比較。
_R05_previous = {name: globals()[name].copy(deep=True) if name in globals() else None
                 for name in ['df_primary', 'df_sensitivity']}
R05 = None
R05 = r05_run(folder_path, _R05_previous)
# 只有整輪成功才發布帶有 R04 ID 的原規則世代；原總表檔案不改寫。
df_primary = R05['df_primary']
df_sensitivity = R05['df_sensitivity']
df_summary = R05['df_summary']
df_clean = R05['df_clean']
weather_df = R05['weather_df']
df_correct_age = R05['df_correct_age']
ID_COL, DATE_COL, AGE_COL = '去個資編號', '骨密度檢查執行日期', '年齡'
file_summary = folder_path + '骨密度與血紅素_重整總表_最終優化版.csv'

"""## 3–6 Calculations in dependency order

Input objects are produced by preceding cells in this notebook. Outputs remain private working artifacts until the publication export section.

"""

from pathlib import Path
from datetime import datetime, timezone
from uuid import uuid4
import json
import numpy as np
import pandas as pd

R01_DXA_AVAILABILITY = None  # 本格失敗時，不保留上一次的成功結果。


def r01_audit_site_availability(primary, repeated):
    patient = '去個資編號'
    sites = ['L_T', 'Left_T', 'Right_T']
    labels = {'L_T': 'Lumbar field', 'Left_T': 'Left hip field',
              'Right_T': 'Right hip field'}
    required = [patient] + sites + ['overall_T']
    t_lower, t_upper = -8.0, 5.0
    tolerance = 1e-10  # 僅用於數值相等檢查。
    checks, denominators, availability, counts, combinations = [], [], [], [], []
    inputs = {'Primary': primary, 'Repeated_records': repeated}
    originals = {}

    def check(name, condition):
        passed = bool(condition)
        checks.append({'Check': name, 'Passed': passed})
        if not passed:
            raise ValueError(f'R01 驗證失敗：{name}。已停止；未修改輸入資料。')

    for cohort, data in inputs.items():
        if not isinstance(data, pd.DataFrame) or data.empty:
            raise ValueError(f'{cohort} 必須是非空 DataFrame；請先完成前置步驟。')
        check(f'{cohort}: unique_column_names', data.columns.is_unique)
        missing = [c for c in required if c not in data.columns]
        if missing:
            raise ValueError(f'{cohort} 缺少欄位：{missing}；不使用替代資料集。')
        originals[cohort] = data[required].copy(deep=True)
        bad_id = data[patient].isna() | data[patient].astype(str).str.strip().eq('')
        check(f'{cohort}: patient_ID_present', not bad_id.any())

    check('Primary: one_row_per_patient', not primary[patient].duplicated().any())
    check('Cohorts: same_patient_set',
          set(primary[patient]) == set(repeated[patient]))

    for cohort, data in inputs.items():
        numeric = pd.DataFrame(index=data.index)
        for col in sites + ['overall_T']:
            try:
                numeric[col] = pd.to_numeric(data[col], errors='raise')
            except (ValueError, TypeError):
                raise ValueError(f'{cohort}.{col} 含非數值內容，請檢查上游；不轉為缺失。') from None
            check(f'{cohort}: {col}_no_infinite_values',
                  not np.isinf(numeric[col].to_numpy(dtype=float, na_value=np.nan)).any())
        valid = numeric[sites].notna()
        n_sites = valid.sum(axis=1)
        check(f'{cohort}: at_least_one_available_site', n_sites.ge(1).all())
        within = numeric[sites].isna() | (
            numeric[sites].ge(t_lower) & numeric[sites].le(t_upper))
        check(f'{cohort}: site_scores_follow_original_bounds', within.to_numpy().all())
        recalculated = numeric[sites].min(axis=1)
        check(f'{cohort}: overall_T_equals_available_site_minimum',
              np.isclose(numeric['overall_T'].to_numpy(dtype=float, na_value=np.nan),
                         recalculated.to_numpy(dtype=float, na_value=np.nan),
                         rtol=0, atol=tolerance, equal_nan=False).all())

        n, patients = len(data), data[patient].nunique()
        denominators.append({'Cohort': cohort, 'Analysis_rows': n,
                             'Unique_patients': patients,
                             'Rows_with_zero_sites': int(n_sites.eq(0).sum()),
                             'Rows_with_all_three_sites': int(n_sites.eq(len(sites)).sum())})
        for site in sites:
            mask = valid[site]
            availability.append({
                'Cohort': cohort, 'Site_field': site, 'Field_label': labels[site],
                'Row_denominator': n, 'Available_rows': int(mask.sum()),
                'Unavailable_rows': int((~mask).sum()),
                'Available_row_percent': 100 * mask.mean(),
                'Patients_with_available_site': data.loc[mask, patient].nunique()})

        for k in range(len(sites) + 1):
            mask = n_sites.eq(k)
            counts.append({'Cohort': cohort, 'Available_site_count': k,
                           'Analysis_rows': int(mask.sum()), 'Row_percent': 100 * mask.mean(),
                           'Unique_patients': data.loc[mask, patient].nunique()})

        # 每列只有一個精確組合；三個欄位共有 2**3 種可能組合。
        codes = sum(valid[col].astype(int) * (1 << j) for j, col in enumerate(sites))
        cohort_combinations = []
        for code in range(1 << len(sites)):
            present = [s for j, s in enumerate(sites) if code & (1 << j)]
            mask = codes.eq(code)
            cohort_combinations.append({
                'Cohort': cohort, 'Available_fields': ' + '.join(present) or 'None',
                'Available_site_count': len(present), 'Analysis_rows': int(mask.sum()),
                'Row_percent': 100 * mask.mean(),
                'Unique_patients': data.loc[mask, patient].nunique()})
        combinations.extend(cohort_combinations)
        check(f'{cohort}: combinations_partition_all_rows',
              sum(r['Analysis_rows'] for r in cohort_combinations) == n)
        check(f'{cohort}: site_counts_partition_all_rows',
              sum(r['Analysis_rows'] for r in counts if r['Cohort'] == cohort) == n)
        check(f'{cohort}: inputs_unchanged', data[required].equals(originals[cohort]))

    return {
        'cohort_denominators': pd.DataFrame(denominators),
        'site_availability': pd.DataFrame(availability),
        'available_site_counts': pd.DataFrame(counts),
        'site_combinations': pd.DataFrame(combinations),
        'validation': pd.DataFrame(checks)}


_r01_missing = [name for name in ('df_primary', 'df_sensitivity', 'folder_path')
                if name not in globals()]
if _r01_missing:
    raise NameError(f'尚缺前置步驟 的物件：{_r01_missing}。請先執行該格。')
if not isinstance(folder_path, (str, Path)) or not str(folder_path).strip():
    raise ValueError('前置步驟 的 folder_path 無效，請確認 Google Drive 路徑。')
_r01_base = Path(folder_path)
if not _r01_base.is_dir():
    raise FileNotFoundError(f'folder_path 不存在：{_r01_base}；不另選輸出位置。')

_r01_tables = r01_audit_site_availability(df_primary, df_sensitivity)
_r01_run = datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ') + '_' + uuid4().hex[:8]
_r01_out = _r01_base / 'Revision_R01_DXA_site_availability' / _r01_run
_r01_out.mkdir(parents=True, exist_ok=False)
for _r01_name, _r01_table in _r01_tables.items():
    _r01_table.to_csv(_r01_out / f'{_r01_name}.csv', index=False, encoding='utf-8-sig')
_r01_notes = {
    'module': 'R01_DXA_site_availability_v1',
    'baseline_notebook': 'self-contained analysis implementation',
    'inputs': ['df_primary', 'df_sensitivity'],
    'availability_definition': 'Nonmissing site T-score after the original cleaning pipeline',
    'counting_unit': 'Analysis rows; repeated rows are not unique DXA examinations',
    'patient_count_note': 'Patients can occur in multiple repeated-record site combinations',
    'hip_ROI': 'Not established by field names or this audit',
    'raw_missing_vs_masked': 'Not distinguishable from these cleaned fields',
    'new_models_fitted': False,
    'age_values_changed': False,
    'formal_tables_replaced': False}
(_r01_out / 'run_notes.json').write_text(
    json.dumps(_r01_notes, ensure_ascii=False, indent=2), encoding='utf-8')

for _r01_title, _r01_name in [
    ('1 世代分母', 'cohort_denominators'),
    ('2 各部位可用性', 'site_availability'),
    ('3 每列可用部位數', 'available_site_counts'),
    ('4 精確部位組合', 'site_combinations')]:
    print(f'\n=== 請回傳：R01 DXA {_r01_title} ===')
    print(_r01_tables[_r01_name].to_string(index=False, float_format=lambda x: f'{x:.2f}'))
print('\n=== 請回傳：R01 DXA 5 驗證 ===')
print(pd.DataFrame([{'Checks': len(_r01_tables['validation']),
                     'All_passed': bool(_r01_tables['validation']['Passed'].all()),
                     'New_models_fitted': False, 'Formal_tables_replaced': False}]).to_string(index=False))
print(f'\n彙總檔位置：{_r01_out}')

R01_DXA_AVAILABILITY = {'tables': _r01_tables, 'output_dir': str(_r01_out), 'notes': _r01_notes}

"""## Fixed-site and common-subset sensitivity

Input objects are produced by preceding cells in this notebook. Outputs remain private working artifacts until the publication export section.

"""

from pathlib import Path
from datetime import datetime, timezone
from uuid import uuid4
import json
import warnings
import numpy as np
import pandas as pd
import statsmodels
import statsmodels.formula.api as smf

R02_FIXED_SITE = None


def r02_fit_fixed_sites(primary, repeated, r01_result, r01_audit):
    if not isinstance(r01_result, dict) or 'tables' not in r01_result:
        raise ValueError('請先成功執行 R01；不能略過部位盤點。')
    # 重新核對現在的世代與 R01 彙總，避免沿用不同執行批次的分母。
    current_r01 = r01_audit(primary, repeated)
    for key in ('cohort_denominators', 'site_availability',
                'available_site_counts', 'site_combinations'):
        if key not in r01_result['tables'] or not current_r01[key].equals(r01_result['tables'][key]):
            raise ValueError(f'目前資料與 R01 的 {key} 不一致，請先重新執行 R01。')

    patient, date = '去個資編號', '骨密度檢查執行日期'
    sites = ['L_T', 'Left_T', 'Right_T']
    covariates = ['Hb_Value', 'THI_mean_30d', 'DTR_mean_30d', '年齡', 'sex_bin']
    required = [patient, date, 'overall_T'] + sites + covariates
    missing = [c for c in required if c not in primary.columns]
    if missing:
        raise ValueError(f'df_primary 缺少：{missing}；不改用其他資料集。')
    original = primary.copy(deep=True)
    data = primary[required].copy(deep=True).reset_index(drop=True)
    checks = [{'Check': 'Current_cohorts_match_R01_summaries', 'Passed': True}]

    def check(name, condition):
        passed = bool(condition)
        checks.append({'Check': name, 'Passed': passed})
        if not passed:
            raise ValueError(f'R02 驗證失敗：{name}；停止，不刪列、不簡化模型。')

    for col in ['overall_T'] + sites + covariates:
        try:
            data[col] = pd.to_numeric(data[col], errors='raise').astype(float)
        except (ValueError, TypeError):
            raise ValueError(f'{col} 含非數值，請回查上游；不自動轉為缺失。') from None
    check('All_primary_adjustment_variables_complete_and_finite',
          np.isfinite(data[covariates + ['overall_T']].to_numpy()).all())
    check('Sex_coding_matches_original_binary_definition', data['sex_bin'].isin([0, 1]).all())
    try:
        dxa_date = pd.to_datetime(data[date], errors='raise')
    except (ValueError, TypeError):
        raise ValueError('DXA 日期無法解析；不使用 Hb 日期或替代日期。') from None
    check('All_primary_DXA_dates_present', dxa_date.notna().all())
    data['exam_year'] = dxa_date.dt.year
    data['sin_month'] = np.sin(2 * np.pi * dxa_date.dt.month / 12)
    data['cos_month'] = np.cos(2 * np.pi * dxa_date.dt.month / 12)
    # 日期欄位只在本格的副本轉型，原始 df_primary 不變。
    data[date] = dxa_date

    rhs = ('Hb_Value + THI_mean_30d + DTR_mean_30d + 年齡 + sex_bin '
           '+ sin_month + cos_month + C(exam_year)')
    masks = {'Primary_all': pd.Series(True, index=data.index)}
    for site in sites:
        masks[f'{site}_available'] = data[site].notna()
    masks['All_three_available'] = data[sites].notna().all(axis=1)
    outcomes = {'Primary_all': ['overall_T'],
                'L_T_available': ['overall_T', 'L_T'],
                'Left_T_available': ['overall_T', 'Left_T'],
                'Right_T_available': ['overall_T', 'Right_T'],
                'All_three_available': ['overall_T'] + sites}
    labels = {'overall_T': 'Minimum of available fields', 'L_T': 'Lumbar spine',
              'Left_T': 'Left hip (subregion unverified)',
              'Right_T': 'Right hip (subregion unverified)'}
    cohort_rows, coefficient_rows, diagnostics, warning_rows, models = [], [], [], [], {}

    for cohort, mask in masks.items():
        sub = data.loc[mask].copy()
        check(f'{cohort}: nonempty', len(sub) > 0)
        check(f'{cohort}: one_row_per_patient', sub[patient].nunique() == len(sub))
        cohort_rows.append({
            'Cohort': cohort, 'Rows': len(sub), 'Patients': sub[patient].nunique(),
            'Retained_percent_of_primary': 100 * len(sub) / len(data),
            'Age_mean': sub['年齡'].mean(), 'Hb_mean': sub['Hb_Value'].mean(),
            'Minimum_T_mean': sub['overall_T'].mean(),
            'DXA_date_min': sub[date].min().date().isoformat(),
            'DXA_date_max': sub[date].max().date().isoformat()})
        reference_X = None
        for outcome in outcomes[cohort]:
            model_id = f'{cohort}__{outcome}'
            formula = f'{outcome} ~ {rhs}'
            check(f'{model_id}: complete_outcome', sub[outcome].notna().all())
            specification = smf.ols(formula, data=sub, missing='raise')
            X = specification.exog
            rank = np.linalg.matrix_rank(X)
            check(f'{model_id}: no_implicit_row_dropping', X.shape[0] == len(sub))
            check(f'{model_id}: full_rank_with_residual_df', rank == X.shape[1] and len(sub) > rank)
            if reference_X is None:
                reference_X = X.copy()
            else:
                check(f'{model_id}: identical_design_within_subset', np.array_equal(X, reference_X))
            # HC3 在 leverage = 1 時沒有有限定義，明確停止。
            Q, _ = np.linalg.qr(X, mode='reduced')
            max_leverage = float(np.square(Q).sum(axis=1).max())
            check(f'{model_id}: HC3_leverage_valid', max_leverage < 1 - 1e-12)
            with warnings.catch_warnings(record=True) as caught:
                warnings.simplefilter('always')
                fitted = specification.fit(cov_type='HC3', use_t=False)
                interval = fitted.conf_int(alpha=0.05)
                full_inference = np.column_stack([
                    fitted.params, fitted.bse, fitted.pvalues, interval.to_numpy()])
            check(f'{model_id}: finite_inference', np.isfinite(full_inference).all())
            check(f'{model_id}: finite_covariance', np.isfinite(fitted.cov_params()).all().all())
            check(f'{model_id}: HC3_normal_inference', fitted.cov_type == 'HC3' and not fitted.use_t)
            for w in caught:
                warning_rows.append({'Model': model_id, 'Category': w.category.__name__, 'Message': str(w.message)})
            coefficient_rows.append({
                'Cohort': cohort, 'Outcome': outcome, 'Outcome_label': labels[outcome],
                'N': int(fitted.nobs), 'Hb_beta': fitted.params['Hb_Value'],
                'HC3_SE': fitted.bse['Hb_Value'], 'CI_low': interval.loc['Hb_Value', 0],
                'CI_high': interval.loc['Hb_Value', 1], 'P': fitted.pvalues['Hb_Value'],
                'Inference': 'HC3_normal_Wald'})
            diagnostics.append({
                'Model': model_id, 'N': int(fitted.nobs), 'Design_columns': X.shape[1],
                'Design_rank': rank, 'Residual_df': fitted.df_resid,
                'Max_leverage': max_leverage, 'Condition_number': fitted.condition_number,
                'Year_reference': int(sub['exam_year'].min()), 'Warning_count': len(caught),
                'Formula': formula})
            models[model_id] = fitted  # 僅留在 runtime，不輸出含個案資料的模型物件。

    check('Input_df_primary_unchanged', primary.equals(original))
    coefficients = pd.DataFrame(coefficient_rows)
    # 係數差僅為描述，沒有把兩個相關估計當成獨立估計做檢定。
    full_beta = coefficients.loc[
        coefficients['Cohort'].eq('Primary_all'), 'Hb_beta'].iloc[0]
    contrasts = []
    for cohort in masks:
        block = coefficients.loc[coefficients['Cohort'].eq(cohort)]
        minimum_beta = block.loc[block['Outcome'].eq('overall_T'), 'Hb_beta'].iloc[0]
        for _, row in block.loc[block['Outcome'].ne('overall_T')].iterrows():
            contrasts.append({
                'Cohort': cohort, 'Site_outcome': row['Outcome'], 'N': int(row['N']),
                'Minimum_T_beta_in_same_subset': minimum_beta,
                'Site_beta': row['Hb_beta'],
                'Minimum_subset_minus_full_beta': minimum_beta - full_beta,
                'Site_minus_minimum_same_subset_beta': row['Hb_beta'] - minimum_beta})

    return {'tables': {
        'cohort_summary': pd.DataFrame(cohort_rows), 'hb_coefficients': coefficients,
        'descriptive_beta_differences': pd.DataFrame(contrasts),
        'model_diagnostics': pd.DataFrame(diagnostics),
        'warnings': pd.DataFrame(warning_rows, columns=['Model', 'Category', 'Message']),
        'validation': pd.DataFrame(checks)}, 'models': models}


_r02_required = ('df_primary', 'df_sensitivity', 'folder_path',
                 'R01_DXA_AVAILABILITY', 'r01_audit_site_availability')
_r02_missing = [name for name in _r02_required if name not in globals()]
if _r02_missing:
    raise NameError(f'請先完成前置步驟 與 R01，尚缺：{_r02_missing}')
if not isinstance(folder_path, (str, Path)) or not str(folder_path).strip() or not Path(folder_path).is_dir():
    raise FileNotFoundError('原 folder_path 不存在，請確認 Google Drive 路徑。')
print('R02：使用既有 Primary，一人一列；開始固定部位與共同完整子集分析。')
_r02_result = r02_fit_fixed_sites(
    df_primary, df_sensitivity, R01_DXA_AVAILABILITY, r01_audit_site_availability)
_r02_out = (Path(folder_path) / 'Revision_R02_fixed_site_sensitivity' /
            (datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ') + '_' + uuid4().hex[:8]))
_r02_out.mkdir(parents=True, exist_ok=False)
for _r02_name, _r02_table in _r02_result['tables'].items():
    _r02_table.to_csv(_r02_out / f'{_r02_name}.csv', index=False, encoding='utf-8-sig')
_r02_notes = {
    'module': 'R02_fixed_site_sensitivity_v1',
    'baseline_notebook': 'self-contained analysis implementation',
    'source': 'Existing df_primary; no representative-record reselection',
    'adjustment_source': 'Original Cell 11 f_adj_b; same clinical and DXA-calendar terms',
    'age_source': 'Existing 年齡 column from original Cell 7, unchanged',
    'weather_source': 'Existing THI_mean_30d and DTR_mean_30d from original Cell 7, unchanged',
    'field_labels_confirmed_by_user': {'L_T': 'L-spine', 'Left_T': 'Left hip', 'Right_T': 'Right hip'},
    'hip_subregion_ROI_verified': False, 'temporal_dependence_addressed_by_this_cell': False,
    'inference': 'OLS HC3, use_t=False; 95% pointwise normal Wald intervals',
    'comparison_note': 'Beta differences are descriptive, without contrast CI/P or multiplicity adjustment',
    'formal_tables_replaced': False,
    'software': {'statsmodels': statsmodels.__version__, 'pandas': pd.__version__, 'numpy': np.__version__}}
(_r02_out / 'run_notes.json').write_text(json.dumps(_r02_notes, ensure_ascii=False, indent=2), encoding='utf-8')
for _r02_title, _r02_key in [
    ('1 分析子集', 'cohort_summary'), ('2 Hb關聯係數', 'hb_coefficients'),
    ('3 同樣本描述性係數比較', 'descriptive_beta_differences')]:
    print(f'\n=== 請回傳：R02 {_r02_title} ===')
    print(_r02_result['tables'][_r02_key].to_string(index=False, float_format=lambda x: f'{x:.7g}'))
print('\n=== 請回傳：R02 4 配適診斷 ===')
print(_r02_result['tables']['model_diagnostics'].drop(columns='Formula').to_string(index=False, float_format=lambda x: f'{x:.7g}'))
print('\n=== 請回傳：R02 5 驗證與警告 ===')
print(pd.DataFrame([{
    'Models_fitted': len(_r02_result['models']),
    'Checks': len(_r02_result['tables']['validation']),
    'All_passed': bool(_r02_result['tables']['validation']['Passed'].all()),
    'Warning_count': len(_r02_result['tables']['warnings']),
    'Formal_tables_replaced': False}]).to_string(index=False))
if not _r02_result['tables']['warnings'].empty:
    print(_r02_result['tables']['warnings'].to_string(index=False))
print(f'\n彙總檔位置：{_r02_out}')

R02_FIXED_SITE = {**_r02_result, 'output_dir': str(_r02_out), 'notes': _r02_notes}

"""## Date-proxy reuse and three skeletal models

Input objects are produced by preceding cells in this notebook. Outputs remain private working artifacts until the publication export section.

"""

import json
import time
import uuid
import warnings
from pathlib import Path
from datetime import datetime, timezone
import numpy as np
import pandas as pd
import patsy
import scipy
from scipy.stats import norm
import statsmodels
import statsmodels.api as sm

R06_PATIENT = '去個資編號'
R06_PAIR = 'pairing_row_id'
R06_DXA = '骨密度檢查執行日期'
R06_WEATHER = ['T_mean_30d', 'DTR_mean_30d', 'RH_mean_30d',
               'THI_mean_30d', 'THI_std_30d', 'THI_Trend_Shock']
R06_NUMERIC = ['overall_T', 'Hb_Value', 'Age', '年齡', 'sex_bin',
               'THI_mean_30d', 'DTR_mean_30d', 'Time_Gap_Days']
R06_ALPHA = 0.05
R06_MAXITER = 1000


def r06_dates(frame):
    d = frame.copy(deep=True).reset_index(drop=True)
    for source, dest in [(R06_DXA, '_R06_DXA_day'), ('Hb_Date', '_R06_Hb_day')]:
        d[dest] = pd.to_datetime(d[source], errors='coerce').dt.normalize()
    return d


def r06_keys(d, day):
    return pd.MultiIndex.from_frame(d[[R06_PATIENT, day]])


def r06_conflicts(d, day, values):
    valid = d[day].notna()
    g = d.loc[valid].groupby([R06_PATIENT, day], sort=False)
    distinct = g[values].nunique(dropna=True)
    value_keys = distinct.index[distinct.gt(1).any(axis=1)]
    nonmissing = g[values].count()
    missingness_keys = nonmissing.index[(nonmissing.gt(0) & nonmissing.lt(g.size(), axis=0)).any(axis=1)]
    return value_keys, missingness_keys


def r06_prepare(master, primary, repeated):
    required = [R06_PATIENT, R06_PAIR, 'raw_row_id', R06_DXA, 'Hb_Date',
                'L_T', 'Left_T', 'Right_T', 'Hb_Value_raw'] + R06_NUMERIC + R06_WEATHER
    for name, d in [('Master', master), ('Primary', primary), ('Repeated', repeated)]:
        missing = set(required) - set(d.columns)
        if missing:
            raise ValueError(f'{name} 缺欄：{sorted(missing)}；請使用本次 R05 的明確輸出。')
        if not d.columns.is_unique or not d[R06_PAIR].is_unique or d[R06_PAIR].isna().any():
            raise ValueError(f'{name} 欄名或 pairing_row_id 不唯一／缺失。')
    m, p, d = [r06_dates(x) for x in [master, primary, repeated]]
    if not {'is_included_sensitivity', 'is_included_primary'}.issubset(m.columns):
        raise ValueError('R05 母體沒有納入旗標。')
    if (m.loc[m['is_included_sensitivity'], R06_PAIR].tolist() != d[R06_PAIR].tolist()
            or set(m.loc[m['is_included_primary'], R06_PAIR]) != set(p[R06_PAIR])):
        raise ValueError('目前世代 ID 與 R05 已驗證旗標不一致。')
    if not p[R06_PATIENT].is_unique or set(p[R06_PATIENT]) != set(d[R06_PATIENT]):
        raise ValueError('Primary 必須一人一列，並涵蓋與 repeated 相同的病人。')
    for name, frame in [('Primary', p), ('Repeated', d)]:
        if frame.empty or frame[['_R06_DXA_day', '_R06_Hb_day', R06_PATIENT]].isna().any().any():
            raise ValueError(f'{name} 為空或缺少可用病人／日期。')
        vals = frame[R06_NUMERIC].apply(pd.to_numeric, errors='raise')
        if not np.isfinite(vals.to_numpy(dtype=float)).all():
            raise ValueError(f'{name} 有非有限模型數值；不會由模型自行刪列。')
        if not np.array_equal(vals['Age'].to_numpy(), vals['年齡'].to_numpy()) or not vals['sex_bin'].isin([0, 1]).all():
            raise ValueError(f'{name} 年齡別名或性別編碼與 R05 不一致。')
    compare = list(dict.fromkeys([R06_PATIENT, 'raw_row_id', R06_DXA, 'Hb_Date',
                                   'L_T', 'Left_T', 'Right_T'] + R06_NUMERIC + R06_WEATHER))
    for child, parent in [(d, m), (p, d)]:
        pd.testing.assert_frame_equal(child.set_index(R06_PAIR)[compare],
            parent.set_index(R06_PAIR).loc[child[R06_PAIR], compare], check_dtype=False)

    # 排序使用現有納入資料的列順序；不依 Hb 數值或雜湊 ID 大小選取。
    d['_R06_eligible_order'] = np.arange(len(d))
    d['_R06_DXA_timestamp'] = pd.to_datetime(d[R06_DXA], errors='raise')
    ranked = d.sort_values([R06_PATIENT, '_R06_DXA_day', 'Time_Gap_Days',
                            '_R06_DXA_timestamp', '_R06_eligible_order'], kind='mergesort')
    selected = ranked.drop_duplicates([R06_PATIENT, '_R06_DXA_day'], keep='first').copy().reset_index(drop=True)
    # 保留完整原始列，避免 groupby.first() 逐欄挑選非缺失值而拼成新列。
    pd.testing.assert_frame_equal(selected[list(repeated.columns)].reset_index(drop=True),
        repeated.set_index(R06_PAIR, drop=False).loc[selected[R06_PAIR], list(repeated.columns)].reset_index(drop=True),
        check_dtype=False)
    if not set(p[R06_PAIR]).issubset(set(selected[R06_PAIR])):
        raise ValueError('每日期選取沒有保留現有 Primary 代表列；停止，不能靜默改選取規則。')
    if selected.duplicated([R06_PATIENT, '_R06_DXA_day']).any():
        raise ValueError('每 DXA 日期仍有多列。')
    master_hb_conflict, _ = r06_conflicts(m, '_R06_Hb_day', ['Hb_Value_raw'])
    eligible_hb_conflict, _ = r06_conflicts(d, '_R06_Hb_day', ['Hb_Value'])
    for frame in [m, p, d, selected]:
        frame['R06_Hb_proxy_conflict_in_master'] = r06_keys(frame, '_R06_Hb_day').isin(master_hb_conflict)
        frame['R06_Hb_proxy_conflict_in_eligible'] = r06_keys(frame, '_R06_Hb_day').isin(eligible_hb_conflict)
    minimum = d.groupby([R06_PATIENT, '_R06_DXA_day'])['Time_Gap_Days'].transform('min')
    candidates = d[d['Time_Gap_Days'].eq(minimum)].copy()
    tie_sizes = candidates.groupby([R06_PATIENT, '_R06_DXA_day']).size()
    tied_keys = tie_sizes.index[tie_sizes.gt(1)]
    tied = candidates[r06_keys(candidates, '_R06_DXA_day').isin(tied_keys)]
    tie_hb, _ = r06_conflicts(tied, '_R06_DXA_day', ['Hb_Value'])
    tie_dates, _ = r06_conflicts(tied, '_R06_DXA_day', ['_R06_Hb_day'])
    tie_weather, _ = r06_conflicts(tied, '_R06_DXA_day', R06_WEATHER)
    selection = pd.DataFrame([{
        'Eligible_pairing_rows': len(d), 'Selected_rows': len(selected),
        'Selected_patients': selected[R06_PATIENT].nunique(),
        'Selected_DXA_date_proxies_NOT_exam_count': len(selected),
        'Primary_rows_retained': int(p[R06_PAIR].isin(selected[R06_PAIR]).sum()),
        'Eligible_pairs_not_selected_for_this_sensitivity': len(d)-len(selected),
        'DXA_proxy_keys_with_minimum_gap_ties': len(tied_keys),
        'Tied_minimum_gap_candidate_rows': len(tied),
        'Tied_keys_with_different_Hb': len(tie_hb),
        'Tied_keys_with_different_Hb_report_dates': len(tie_dates),
        'Tied_keys_with_different_weather': len(tie_weather),
    }])
    return {'Master': m, 'Eligible_repeated': d, 'Primary': p,
            'One_per_DXA_date_proxy': selected}, selection


def r06_inventory(data):
    denominators, reuse, conflicts, distributions, summaries, gaps = [], [], [], [], [], []
    for name, d in data.items():
        dx = d.dropna(subset=['_R06_DXA_day']).drop_duplicates([R06_PATIENT, '_R06_DXA_day'])
        hb = d.dropna(subset=['_R06_Hb_day']).drop_duplicates([R06_PATIENT, '_R06_Hb_day'])
        patient_counts = d.groupby(R06_PATIENT, sort=False).size().rename('Pairing_rows').to_frame()
        patient_counts['DXA_date_proxies'] = dx.groupby(R06_PATIENT).size().reindex(patient_counts.index, fill_value=0)
        patient_counts['Hb_report_date_proxies'] = hb.groupby(R06_PATIENT).size().reindex(patient_counts.index, fill_value=0)
        denominators.append({'Scope': name, 'Pairing_rows': len(d), 'Patients': len(patient_counts),
            'DXA_date_proxies_NOT_exam_count': len(dx), 'Hb_report_date_proxies_NOT_specimen_count': len(hb),
            'Patients_with_multiple_DXA_dates': int(patient_counts['DXA_date_proxies'].gt(1).sum())})
        for metric in patient_counts:
            values = patient_counts[metric]
            for count, frequency in values.value_counts().sort_index().items():
                distributions.append({'Scope': name, 'Metric': metric, 'Count_per_patient': int(count),
                                      'Patients': int(frequency)})
            summaries.append({'Scope': name, 'Metric': metric, 'Patients': len(values),
                'Min': values.min(), 'Median': values.median(), 'Q1': values.quantile(.25),
                'Q3': values.quantile(.75), 'Max': values.max()})
        for kind, day in [('DXA_date_proxy', '_R06_DXA_day'), ('Hb_report_date_proxy', '_R06_Hb_day')]:
            valid = d.dropna(subset=[day])
            sizes = valid.groupby([R06_PATIENT, day]).size()
            multiple = sizes.gt(1)
            across_dxa = (valid.groupby([R06_PATIENT, day])['_R06_DXA_day'].nunique().gt(1).sum()
                          if kind == 'Hb_report_date_proxy' else np.nan)
            reuse.append({'Scope': name, 'Key_type': kind, 'Date_evaluable_pairing_rows': len(valid),
                'Proxy_keys': len(sizes), 'Proxies_with_multiple_pairs': int(multiple.sum()),
                'Percent_proxies_with_multiple_pairs': 100*multiple.mean() if len(sizes) else np.nan,
                'Rows_on_multiple_pair_proxies': int(sizes[multiple].sum()),
                'Pairing_rows_beyond_one_per_proxy': int((sizes-1).sum()),
                'Hb_proxies_linked_to_multiple_DXA_dates': across_dxa})
        raw_conflict, missing_conflict = r06_conflicts(d, '_R06_Hb_day', ['Hb_Value_raw'])
        analysis_conflict, _ = r06_conflicts(d, '_R06_Hb_day', ['Hb_Value'])
        dx_conflict, dx_missing = r06_conflicts(d, '_R06_DXA_day', ['L_T', 'Left_T', 'Right_T'])
        conflicts.append({'Scope': name, 'Hb_proxies_with_raw_value_conflict': len(raw_conflict),
            'Hb_proxies_with_analysis_value_conflict': len(analysis_conflict),
            'Hb_proxies_with_raw_missingness_difference': len(missing_conflict),
            'DXA_proxies_with_site_T_value_conflict': len(dx_conflict),
            'DXA_proxies_with_site_missingness_difference': len(dx_missing),
            'Rows_on_master_Hb_conflict_proxies': int(d['R06_Hb_proxy_conflict_in_master'].sum()),
            'Rows_on_eligible_Hb_conflict_proxies': int(d['R06_Hb_proxy_conflict_in_eligible'].sum())})
        dx = dx.sort_values([R06_PATIENT, '_R06_DXA_day'])
        intervals = dx.groupby(R06_PATIENT)['_R06_DXA_day'].diff().dt.days.dropna()
        gaps.append({'Scope': name, 'Consecutive_DXA_date_intervals': len(intervals),
                     'Min_days': intervals.min(), 'Q1_days': intervals.quantile(.25),
                     'Median_days': intervals.median(), 'Q3_days': intervals.quantile(.75),
                     'Max_days': intervals.max()})
    return {name: pd.DataFrame(rows) for name, rows in [
        ('cohort_denominators', denominators), ('proxy_multiplicity', reuse), ('proxy_value_conflicts', conflicts),
        ('per_patient_frequency', distributions), ('per_patient_summary', summaries), ('DXA_date_intervals', gaps)]}


def r06_fit_models(data, out, alpha=R06_ALPHA, maxiter=R06_MAXITER):
    repeated = data['Eligible_repeated'].copy()
    dates = pd.to_datetime(repeated[R06_DXA], errors='raise')
    repeated['dxa_year'] = dates.dt.year.astype(int)
    repeated['dxa_sin'] = np.sin(2*np.pi*dates.dt.month/12)
    repeated['dxa_cos'] = np.cos(2*np.pi*dates.dt.month/12)
    reference = int(repeated['dxa_year'].min())
    formula = ('overall_T ~ Hb_Value + THI_mean_30d + DTR_mean_30d + Age + sex_bin + dxa_sin + dxa_cos '
               f'+ C(dxa_year, Treatment(reference={reference}))')
    y, X = patsy.dmatrices(formula, repeated, return_type='dataframe', NA_action='raise', eval_env=-1)
    if len(X) != len(repeated) or not np.isfinite(X.to_numpy()).all():
        raise ValueError('模型設計包含缺失或列數改變。')
    positions = pd.Series(np.arange(len(repeated)), index=repeated[R06_PAIR])
    model_data = [('Primary_OLS_HC3', data['Primary']), ('Repeated_pairs_LMM', data['Eligible_repeated']),
                  ('One_per_DXA_date_proxy_LMM', data['One_per_DXA_date_proxy'])]
    models, fixed, diagnostics, warnings_log, design_rows = {}, [], [], [], []
    q = norm.ppf(1-alpha/2)
    try:
        for name, frame in model_data:
            pos = positions.loc[frame[R06_PAIR]].to_numpy()
            xx, yy = X.iloc[pos].reset_index(drop=True), y.iloc[pos, 0].reset_index(drop=True)
            is_lmm = name != 'Primary_OLS_HC3'
            counts = frame.groupby(R06_PATIENT).size()
            if len(xx) <= xx.shape[1] or np.linalg.matrix_rank(xx.to_numpy()) != xx.shape[1]:
                raise ValueError(f'{name} 設計不滿秩或自由度不足；不自動刪調整項。')
            if is_lmm and not counts.gt(1).any():
                raise ValueError(f'{name} 無病人有多列，無法分別識別隨機截距與殘差變異數。')
            if not is_lmm:
                Q, _ = np.linalg.qr(xx.to_numpy(), mode='reduced')
                if np.square(Q).sum(axis=1).max() >= 1-1e-12:
                    raise ValueError('Primary 槓桿值接近 1，HC3 無法可靠計算。')
            groups, _ = pd.factorize(frame[R06_PATIENT], sort=False)
            design_rows.append({'Model': name, 'Rows': len(frame), 'Patients': len(counts),
                'Patients_with_multiple_rows': int(counts.gt(1).sum()), 'Design_columns': xx.shape[1],
                'Design_rank': np.linalg.matrix_rank(xx.to_numpy()), 'Age_mean': frame['Age'].mean(),
                'Hb_mean': frame['Hb_Value'].mean(), 'Minimum_T_mean': frame['overall_T'].mean()})
            diag = {'Model': name, 'Optimizer': 'bfgs' if is_lmm else 'OLS_closed_form',
                    'Converged': None, 'Iterations': np.nan, 'Iteration_count_source': 'not_applicable',
                    'Function_calls': np.nan, 'Fit_exception': None, 'Warning_count': 0}
            diagnostics.append(diag)
            print(f'R06 配適 {name}：{len(frame):,} 列、{len(counts):,} 位病人。', flush=True)
            began = time.perf_counter()
            with warnings.catch_warnings(record=True) as caught:
                warnings.simplefilter('always')
                try:
                    if is_lmm:
                        fit = sm.MixedLM(yy, xx, groups=groups, exog_re=np.ones((len(yy), 1)), missing='raise').fit(
                            reml=True, method='bfgs', maxiter=maxiter, gtol=1e-6, full_output=True, disp=False)
                        diag['Converged'] = bool(fit.converged)
                        history = fit.hist[-1] if getattr(fit, 'hist', None) else {}
                        if 'iterations' in history:
                            diag.update(Iterations=history['iterations'], Iteration_count_source='optimizer_iterations')
                        elif 'allvecs' in history:
                            diag.update(Iterations=len(history['allvecs'])-1, Iteration_count_source='history_allvecs_minus_initial')
                        else:
                            diag['Iteration_count_source'] = 'not_reported_by_software'
                        diag['Function_calls'] = history.get('fcalls', np.nan)
                    else:
                        fit = sm.OLS(yy, xx, missing='raise').fit(cov_type='HC3', use_t=False)
                except Exception as exc:
                    diag['Fit_exception'] = f'{type(exc).__name__}: {exc}'
                    raise
                finally:
                    diag['Seconds'] = time.perf_counter()-began
                    diag['Warning_count'] = len(caught)
                    warnings_log.extend({'Model': name, 'Category': type(w.message).__name__, 'Message': str(w.message)} for w in caught)
            critical = any(any(word in str(w.message).lower() for word in ['hessian', 'singular', 'failed', 'did not converge']) for w in caught)
            if is_lmm and (not fit.converged or critical):
                raise RuntimeError(f'{name} 未收斂或有關鍵配適警告；診斷已保留，不改用另一資料集／模型。')
            beta, se = (fit.fe_params, fit.bse_fe) if is_lmm else (fit.params, fit.bse)
            if not (np.isfinite(beta).all() and np.isfinite(se).all() and (se > 0).all()):
                raise ValueError(f'{name} 固定係數或 SE 無效。')
            tau = float(np.asarray(fit.cov_re)[0, 0]) if is_lmm else np.nan
            sigma = float(fit.scale)
            if is_lmm and (not np.isfinite([tau, sigma]).all() or tau < 0 or sigma <= 0):
                raise ValueError(f'{name} 原尺度變異數無效。')
            diag.update(Residual_variance=sigma, Random_intercept_variance=tau,
                        ICC=tau/(tau+sigma) if is_lmm else np.nan)
            for term in xx.columns:
                fixed.append({'Model': name, 'Term': term, 'Beta': beta[term], 'SE': se[term],
                    'CI_low': beta[term]-q*se[term], 'CI_high': beta[term]+q*se[term],
                    'P': 2*norm.sf(abs(beta[term]/se[term])), 'Rows': len(frame), 'Patients': len(counts),
                    'Inference': 'LMM_model_based_normal_Wald' if is_lmm else 'HC3_normal_Wald'})
            models[name] = fit
    finally:
        pd.DataFrame(diagnostics).to_csv(out/'fit_diagnostics.csv', index=False, encoding='utf-8-sig')
        pd.DataFrame(warnings_log, columns=['Model','Category','Message']).to_csv(out/'fit_warnings.csv', index=False, encoding='utf-8-sig')
        pd.DataFrame(design_rows).to_csv(out/'model_design.csv', index=False, encoding='utf-8-sig')
    full = pd.DataFrame(fixed)
    comparison = full[full['Term'].eq('Hb_Value')].reset_index(drop=True)
    return models, full, comparison, pd.DataFrame(diagnostics), pd.DataFrame(warnings_log), formula


def r06_run(master, primary, repeated, out):
    out = Path(out)
    out.mkdir(parents=True, exist_ok=False)
    checks = []
    status = {'Completed': False, 'True_exam_identity_verified': False, 'Formal_tables_replaced': False}
    original = [d.copy(deep=True) for d in [master, primary, repeated]]
    try:
        data, selection = r06_prepare(master, primary, repeated)
        checks.extend({'Check': name, 'Passed': True} for name in [
            'Explicit_R05_input_columns_and_unique_IDs', 'Current_cohort_values_match_R05_master',
            'Primary_is_one_per_patient_with_same_patient_set', 'Selected_rows_are_whole_original_rows',
            'One_selected_row_per_DXA_date_proxy', 'Primary_representatives_retained'])
        inventory = r06_inventory(data)
        for name, table in inventory.items():
            table.to_csv(out/(name+'.csv'), index=False, encoding='utf-8-sig')
        selection.to_csv(out/'selection_summary.csv', index=False, encoding='utf-8-sig')
        data['One_per_DXA_date_proxy'].to_csv(out/'selected_rows_PRIVATE.csv', index=False, encoding='utf-8-sig')
        # 各個分布須回到同一分母；未以固定人數或日期替代結果。
        frequency = inventory['per_patient_frequency']
        for scope, frame in data.items():
            for metric in ['Pairing_rows', 'DXA_date_proxies', 'Hb_report_date_proxies']:
                f = frequency[(frequency.Scope == scope) & (frequency.Metric == metric)]
                if int(f['Patients'].sum()) != frame[R06_PATIENT].nunique():
                    raise ValueError(f'{scope} {metric} 分布分母不一致。')
            checks.append({'Check': scope+'_patient_distribution_denominators_match', 'Passed': True})
        models, fixed, comparison, diagnostics, warning_table, formula = r06_fit_models(data, out)
        checks.extend({'Check': name+'_finite_full_rank_fit', 'Passed': True} for name in models)
        for label, before, after in zip(['Master','Primary','Repeated'], original, [master,primary,repeated]):
            pd.testing.assert_frame_equal(before, after)
            checks.append({'Check': label+'_input_unchanged', 'Passed': True})
        comparison.to_csv(out/'S9_R06_ModelB_comparison_candidate.csv', index=False, encoding='utf-8-sig')
        fixed.to_csv(out/'ModelB_full_fixed_coefficients.csv', index=False, encoding='utf-8-sig')
        specification = {
            'Base_notebook': 'self-contained analysis implementation', 'Reviewer': 'R1 Major 2',
            'Inputs': ['R05.row_flags','df_primary','df_sensitivity'], 'Formula_all_models': formula,
            'Calendar_anchor': 'DXA date', 'Hb_date_meaning': 'laboratory_report_date',
            'Selection': ['patient + normalized DXA date groups', 'smallest original Time_Gap_Days',
                          'earliest original DXA timestamp for within-day ties', 'original eligible-row order'],
            'Conflicts': 'Retained and counted; different same-day values are not averaged or assumed to be errors',
            'Proxy_multiplicity_meaning': 'Counts of paired rows per date proxy; not confirmed reuse of a unique examination',
            'Missing_date_records': 'Retained in Master row count; excluded only from date-proxy denominators requiring that date',
            'True_exam_identity_verified': False, 'Age_and_weather_values_changed': False,
            'LMM': {'REML': True, 'Random_effect': 'Patient intercept', 'Optimizer': 'bfgs', 'maxiter': R06_MAXITER, 'gtol': 1e-6},
            'Alpha': R06_ALPHA, 'Variance_inference': 'Only original-scale point estimates shown as diagnostics; no variance-component SE/CI/P produced',
            'Temporal_dependence_resolved_here': False, 'Mundlak_fitted_here': False,
            'Software': {'pandas':pd.__version__, 'numpy':np.__version__, 'scipy':scipy.__version__, 'statsmodels':statsmodels.__version__},
        }
        (out/'analysis_specification.json').write_text(json.dumps(specification, ensure_ascii=False, indent=2), encoding='utf-8')
        status.update(Completed=True, Models_fitted=len(models), Age_values_changed=False, Weather_values_changed=False,
                      Original_cohorts_changed=False, Warning_count=len(warning_table))
        for title, table in [
            ('1 世代與日期替代鍵分母', inventory['cohort_denominators']),
            ('2 重用與每人分布', inventory['proxy_multiplicity']),
            ('3 每DXA日期一列選取', selection),
            ('4 Model B Hb係數', comparison),
            ('5 模型配適診斷', diagnostics)]:
            print(f'\n=== 請回傳：R06 {title} ===')
            print(table.to_string(index=False, float_format=lambda v:f'{v:.8g}'))
            if title.startswith('2 '):
                print(inventory['per_patient_summary'].query("Scope == 'Eligible_repeated'").to_string(index=False))
                print(inventory['DXA_date_intervals'].query("Scope == 'Eligible_repeated'").to_string(index=False))
            if title.startswith('3 '):
                print(inventory['proxy_value_conflicts'].to_string(index=False))
        print('\n=== 請回傳：R06 6 最終驗證 ===')
        print(pd.DataFrame([{'Checks':len(checks), 'All_passed':all(x['Passed'] for x in checks), **status}]).to_string(index=False))
        if not warning_table.empty:
            print(warning_table.to_string(index=False))
        print(f'\n輸出位置：{out}')

        return {'Completed':True, 'selected':data['One_per_DXA_date_proxy'], 'models':models,
                'comparison':comparison, 'inventory':inventory, 'selection':selection,
                'output_dir':str(out), 'status':status}
    except Exception as exc:
        status.update(Error_type=type(exc).__name__, Error=str(exc))
        print(f'R06 停止；已產生的診斷保留於 {out}，尚未完成比較表。')
        raise
    finally:
        pd.DataFrame(checks).to_csv(out/'validation.csv', index=False, encoding='utf-8-sig')
        (out/'run_status.json').write_text(json.dumps(status, ensure_ascii=False, indent=2), encoding='utf-8')


R06 = None
_r06_missing = [n for n in ['R05','df_primary','df_sensitivity','folder_path'] if n not in globals()]
if _r06_missing:
    raise NameError(f'請先執行本版 R05 7A；缺少：{_r06_missing}')
if not isinstance(R05, dict) or not R05.get('Completed', False) or 'row_flags' not in R05:
    raise ValueError('R05 未成功完成，不能使用舊世代代替。')
_r06_out = Path(folder_path)/'Revision_R06_DXA_Proxy'/(
    datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')+'_'+uuid.uuid4().hex[:8])
R06 = r06_run(R05['row_flags'], df_primary, df_sensitivity, _r06_out)

"""## Between/within-person Mundlak model

Input objects are produced by preceding cells in this notebook. Outputs remain private working artifacts until the publication export section.

"""

from pathlib import Path
from datetime import datetime, timezone
import json
import re
import time
import uuid
import warnings
import numpy as np
import pandas as pd
import scipy
from scipy.stats import norm
import statsmodels
import statsmodels.api as sm

R07_ALPHA = 0.05                 # 預先指定的推論設定，不是預期結果。
R07_MAXITER = 1000
R07_PATIENT = '去個資編號'
R07_DXA = '骨密度檢查執行日期'


def r07_basis(frame):
    """保留全部調整空間；僅移除數學上冗餘方向，不按 P 值選變數。"""
    a = frame.to_numpy(dtype=float)
    center = a.mean(axis=0)
    centered = a-center
    scale = np.sqrt(np.mean(centered**2, axis=0))
    active = scale > 100*np.finfo(float).eps*np.maximum(1, np.max(np.abs(a), axis=0))
    z = centered[:, active]/scale[active]
    if z.shape[1]:
        u, s, vh = np.linalg.svd(z, full_matrices=False)
        threshold = max(z.shape)*np.finfo(float).eps*s[0]
        rank = int((s > threshold).sum())
        q = u[:, :rank]
        loadings = np.zeros((a.shape[1], rank))
        loadings[active] = vh[:rank].T*np.sqrt(len(a))/s[:rank]
        error = np.linalg.norm(z-q@(q.T@z))/max(np.linalg.norm(z), 1.)
    else:
        q, rank, threshold, error = np.empty((len(a), 0)), 0, 0., 0.
        loadings = np.empty((a.shape[1], 0))
    names = [f'Nuisance_basis_{i+1}' for i in range(rank)]
    basis = pd.DataFrame(q*np.sqrt(len(a)), columns=names)
    scaling = pd.DataFrame({'Component':frame.columns, 'Center':center, 'RMS_scale':scale, 'Active':active})
    loading_table = pd.DataFrame(loadings, index=frame.columns, columns=names).rename_axis('Component').reset_index()
    return basis, scaling, loading_table, float(threshold), float(error)


def r07_prepare(previous):
    if not isinstance(previous, dict) or not previous.get('Completed', False):
        raise ValueError('R06 尚未完成；請執行最新版 R06，不使用舊資料代替。')
    data = previous['selected'].copy(deep=True).reset_index(drop=True)
    base_fit = previous['models']['One_per_DXA_date_proxy_LMM']
    required = [R07_PATIENT, 'pairing_row_id', R07_DXA, 'Hb_Date', 'overall_T', 'Hb_Value',
                'Age', 'sex_bin', 'THI_mean_30d', 'DTR_mean_30d',
                'R06_Hb_proxy_conflict_in_master', 'R06_Hb_proxy_conflict_in_eligible']
    if set(required)-set(data):
        raise ValueError(f'R06 選取資料缺欄：{sorted(set(required)-set(data))}')
    if data[[R07_PATIENT,'pairing_row_id']].isna().any().any() or data['pairing_row_id'].duplicated().any():
        raise ValueError('病人／配對列 ID 缺失或配對列 ID 重複。')
    dates = pd.to_datetime(data[R07_DXA], errors='raise')
    hb_dates = pd.to_datetime(data['Hb_Date'], errors='raise')
    if dates.isna().any() or hb_dates.isna().any():
        raise ValueError('R06 選取列含缺失日期。')
    dxa_key = pd.MultiIndex.from_arrays([data[R07_PATIENT], dates.dt.normalize()])
    hb_key = pd.MultiIndex.from_arrays([data[R07_PATIENT], hb_dates.dt.normalize()])
    if dxa_key.duplicated().any():
        raise ValueError('並非每個病人＋DXA 日期一列；不在本格重選。')
    groups, patients = pd.factorize(data[R07_PATIENT], sort=False)
    X = pd.DataFrame(np.asarray(base_fit.model.exog), columns=base_fit.model.exog_names)
    y = np.asarray(base_fit.model.endog, dtype=float).reshape(-1)
    if not bool(base_fit.converged) or len(X) != len(data) or not np.array_equal(groups, base_fit.model.groups):
        raise ValueError('R06 模型未收斂或與選取資料列序不符。')
    expected = {'Intercept':np.ones(len(data)), 'dxa_sin':np.sin(2*np.pi*dates.dt.month/12),
                'dxa_cos':np.cos(2*np.pi*dates.dt.month/12)}
    expected.update({c:pd.to_numeric(data[c], errors='raise') for c in
                    ['Hb_Value','THI_mean_30d','DTR_mean_30d','Age','sex_bin']})
    for c in X.columns:
        if c not in expected:
            match = re.fullmatch(r'C\(dxa_year, Treatment\(reference=\d+\)\)\[T\.(\d+)\]', c)
            if not match:
                raise ValueError(f'未識別的 R06 設計欄：{c}；請依本次模型規格修訂，不猜測來源。')
            expected[c] = dates.dt.year.eq(int(match.group(1))).astype(float)
    expected_x = pd.DataFrame(expected)[X.columns].to_numpy(dtype=float)
    if (not np.isfinite(expected_x).all() or not np.isfinite(y).all()
        or not np.allclose(X.to_numpy(), expected_x, rtol=1e-12, atol=1e-12)
        or not np.array_equal(y, data['overall_T'].to_numpy(dtype=float))):
        raise ValueError('R06 模型設計／結果值與目前選取列不同或非有限；請重跑 R06。')
    # 均值一律由本次實際估計樣本計算，未使用重複配對世代的均值。
    values = X.drop(columns='Intercept')
    means = values.groupby(groups, sort=False).transform('mean')
    within = values-means
    variation, nuisance, definitions = [], {}, []
    patient_sizes = pd.Series(groups).value_counts(sort=False)
    within_df = len(data)-len(patients)
    for c in values:
        tolerance = 100*np.finfo(float).eps*max(1., float(values[c].abs().max()))
        ranges = values[c].groupby(groups).max()-values[c].groupby(groups).min()
        variable_groups = ranges > tolerance
        constant_rows = ~pd.Series(groups).map(variable_groups).to_numpy(dtype=bool)
        within.loc[constant_rows, c] = 0.
        means.loc[constant_rows, c] = values.loc[constant_rows, c]
        ss = float(np.square(within[c]).sum())
        variation.append({'Variable':c, 'Patients_with_within_variation':int(variable_groups.sum()),
                          'Within_sum_squares':ss, 'Pooled_within_SD':np.sqrt(ss/within_df) if within_df else np.nan,
                          'Numerical_zero_tolerance':tolerance})
        if c != 'Hb_Value':
            parts = [('between',means[c]),('within',within[c])] if variable_groups.any() else [('invariant',values[c])]
            for component, array in parts:
                name = c+'__'+component
                nuisance[name] = array
                definitions.append({'Component':name, 'Original_design_column':c, 'Transformation':component})
    if not np.allclose(means+within, values, rtol=1e-12, atol=1e-12):
        raise ValueError('病人均值＋病人內偏差無法重建原設計。')
    nuisance = pd.DataFrame(nuisance)
    basis, scaling, loadings, threshold, error = r07_basis(nuisance)
    fit_x = pd.DataFrame({'Intercept':np.ones(len(data)), 'Hb_between':means.Hb_Value, 'Hb_within':within.Hb_Value})
    fit_x = pd.concat([fit_x,basis], axis=1)
    scaled_x = fit_x.to_numpy()/np.maximum(np.linalg.norm(fit_x.to_numpy(), axis=0), np.finfo(float).tiny)
    rank = int(np.linalg.matrix_rank(scaled_x))
    # 直接去均值估計，只核對 within 係數；不將其 SE 當成 LMM 的 SE。
    within_nuisance = within.drop(columns='Hb_Value')
    w_basis, _, _, _, _ = r07_basis(within_nuisance)
    wq = w_basis.to_numpy()/np.sqrt(len(data))
    hw = within.Hb_Value.to_numpy()
    yw = y-pd.Series(y).groupby(groups).transform('mean').to_numpy()
    y_tolerance = 100*np.finfo(float).eps*max(1.,float(np.max(np.abs(y))))
    y_range = pd.Series(y).groupby(groups).max()-pd.Series(y).groupby(groups).min()
    variation.append({'Variable':'overall_T (outcome)',
        'Patients_with_within_variation':int((y_range > y_tolerance).sum()),
        'Within_sum_squares':float(yw@yw),
        'Pooled_within_SD':np.sqrt(float(yw@yw)/within_df) if within_df else np.nan,
        'Numerical_zero_tolerance':y_tolerance})
    hr, yr = hw-wq@(wq.T@hw), yw-wq@(wq.T@yw)
    residual_ss = float(hr@hr)
    residual_tol = 100*np.finfo(float).eps*max(1.,float(hw@hw))
    identifiable = bool(rank == fit_x.shape[1] and len(data) > fit_x.shape[1] and residual_ss > residual_tol)
    design = pd.DataFrame([{'Original_R06_design_columns':X.shape[1], 'Nuisance_components':nuisance.shape[1],
        'Nuisance_centered_rank':basis.shape[1], 'Nuisance_redundant_dimensions':nuisance.shape[1]-basis.shape[1],
        'Fitted_design_columns':fit_x.shape[1], 'Fitted_design_rank':rank, 'Adjustment_space_relative_error':error,
        'SVD_rank_threshold':threshold, 'Within_nuisance_rank':w_basis.shape[1],
        'Hb_within_SS_after_adjustment':residual_ss, 'Hb_between_and_within_identifiable':identifiable}])
    if error > 1e-10:
        raise ValueError('調整空間重建失敗；不刪除調整項繼續分析。')
    denominator = pd.DataFrame([{'Rows':len(data), 'Patients':len(patients),
        'DXA_date_proxies_NOT_exam_count':len(dxa_key.unique()),
        'Hb_report_date_proxies_NOT_specimen_count':len(hb_key.unique()),
        'Patients_with_one_row':int(patient_sizes.eq(1).sum()),
        'Patients_with_multiple_rows':int(patient_sizes.gt(1).sum()), 'Within_DF_before_covariates':within_df,
        'Rows_on_master_Hb_conflict_keys':int(data.R06_Hb_proxy_conflict_in_master.sum()),
        'Rows_on_eligible_Hb_conflict_keys':int(data.R06_Hb_proxy_conflict_in_eligible.sum())}])
    return {'data':data, 'groups':groups, 'y':y, 'X':fit_x, 'nuisance':nuisance, 'within':within,
        'direct_within_beta':float(hr@yr/residual_ss) if residual_ss > residual_tol else np.nan,
        'identifiable':identifiable, 'tables':{'denominators':denominator, 'within_information':pd.DataFrame(variation),
        'design_diagnostics':design, 'nuisance_definitions':pd.DataFrame(definitions),
        'nuisance_scaling':scaling, 'nuisance_basis_loadings':loadings}}


def r07_run(previous, out, alpha=R07_ALPHA, maxiter=R07_MAXITER):
    out = Path(out)
    out.mkdir(parents=True, exist_ok=False)
    tables, checks, fit = {}, [], None
    status = {'Completed':False, 'Assessment_completed':False, 'Model_fitted':False,
              'True_exam_identity_verified':False, 'Formal_tables_replaced':False}
    original = previous['selected'].copy(deep=True) if isinstance(previous, dict) and 'selected' in previous else None
    def check(name, ok):
        checks.append({'Check':name, 'Passed':bool(ok)})
        if not ok:
            raise ValueError('R07 驗證失敗：'+name)
    try:
        prepared = r07_prepare(previous)
        tables.update(prepared['tables'])
        checks.extend({'Check':s,'Passed':True} for s in ['Explicit_completed_R06_input',
            'Unique_pairing_IDs_and_one_row_per_DXA_date', 'R06_model_values_and_order_reproduced',
            'Same_calendar_and_clinical_adjustment_inputs', 'Means_computed_on_actual_selected_sample',
            'Between_plus_within_reconstruct_original_values', 'Nuisance_adjustment_space_preserved'])
        y, x, groups = prepared['y'], prepared['X'], prepared['groups']
        specification = {'Base_notebook':'self-contained analysis implementation', 'Reviewer':'R2-4',
            'Input':'R06.selected + R06.models.One_per_DXA_date_proxy_LMM',
            'Model':'Patient random-intercept within-between (Mundlak/hybrid) LMM',
            'Outcome':'overall_T', 'Hb_unit':'g/dL', 'Calendar_anchor':'DXA date',
            'Hb_date_meaning':'laboratory_report_date', 'Age_column':'Age (unchanged from R06)',
            'Mean_sample':'Actual R06 one-row-per-patient-DXA-date-proxy estimation sample; no weighting by Hb-pair count',
            'Time_varying_covariates':'Separate patient means and deviations for every varying original design column, including calendar indicators',
            'Time_invariant_covariates':'Entered once', 'Nuisance_basis':'Centered/scaled SVD, preserving the full adjustment column space',
            'Inference':'LMM model-based normal-Wald; between-minus-within uses full fixed-effect covariance',
            'Direct_demeaned_check':'Coefficient equality only; no alternative SE or replacement model',
            'REML':True, 'Optimizer':'bfgs', 'Maxiter':maxiter, 'gtol':1e-6, 'Alpha':alpha,
            'Variance_component_inference_produced':False, 'Temporal_dependence_resolved_here':False,
            'True_exam_identity_verified':False, 'Formal_tables_replaced':False,
            'Software':{'numpy':np.__version__,'pandas':pd.__version__,'scipy':scipy.__version__,'statsmodels':statsmodels.__version__}}
        (out/'analysis_specification.json').write_text(json.dumps(specification,ensure_ascii=False,indent=2),encoding='utf-8')
        if not prepared['identifiable']:
            status.update(Assessment_completed=True, Not_estimable_reason='Hb within/between design or residual within information insufficient')
            print('R07 可估計性評估完成：現有資料不足以分別估計 Hb 病人間／病人內係數。')
            print('已輸出資料與設計摘要；不改選資料、不自行刪調整項，可據此記載限制。')
            for key in ['denominators','within_information','design_diagnostics']:
                print(tables[key].to_string(index=False))
            print(f'輸出位置：{out}')
            return {'Completed':False, 'Assessment_completed':True, 'Model_fitted':False,
                    'tables':tables, 'output_dir':str(out), 'status':status}
        diag = {'Optimizer':'bfgs', 'REML':True, 'Converged':None, 'Iterations':np.nan,
                'Iteration_count_source':'not_reported_by_software', 'Function_calls':np.nan, 'Fit_exception':None}
        began = time.perf_counter()
        varying_n = int(tables['within_information'].set_index('Variable').loc['Hb_Value','Patients_with_within_variation'])
        print(f'R07 Mundlak 配適：{len(y):,} 列、{len(np.unique(groups)):,} 位病人；Hb 有病人內變動者 {varying_n:,} 位。',flush=True)
        with warnings.catch_warnings(record=True) as caught:
            warnings.simplefilter('always')
            try:
                fit = sm.MixedLM(y,x,groups=groups,exog_re=np.ones((len(y),1)),missing='raise').fit(
                    reml=True,method='bfgs',maxiter=maxiter,gtol=1e-6,full_output=True,disp=False)
                diag['Converged'] = bool(fit.converged)
                history = fit.hist[-1] if getattr(fit,'hist',None) else {}
                if 'iterations' in history:
                    diag.update(Iterations=history['iterations'],Iteration_count_source='optimizer_iterations')
                elif 'allvecs' in history:
                    diag.update(Iterations=len(history['allvecs'])-1,Iteration_count_source='history_allvecs_minus_initial')
                diag['Function_calls'] = history.get('fcalls',np.nan)
                tau, sigma = float(np.asarray(fit.cov_re)[0,0]), float(fit.scale)
                diag.update(Random_intercept_variance=tau,Residual_variance=sigma,ICC=tau/(tau+sigma))
            except Exception as exc:
                diag['Fit_exception'] = f'{type(exc).__name__}: {exc}'
                raise
            finally:
                warning_text = ' '.join(str(w.message).lower() for w in caught)
                diag.update(Seconds=time.perf_counter()-began,Warning_count=len(caught),
                            Boundary_warning='boundary' in warning_text,
                            Hessian_or_singular_warning='hessian' in warning_text or 'singular' in warning_text)
                tables['fit_diagnostics'] = pd.DataFrame([diag])
                tables['fit_warnings'] = pd.DataFrame([{'Category':w.category.__name__,'Message':str(w.message)} for w in caught],
                                                       columns=['Category','Message'])
        check('Mundlak_converged',fit.converged)
        critical = any(s in warning_text for s in ['hessian','singular','failed','did not converge']) or any(issubclass(w.category,RuntimeWarning) for w in caught)
        check('No_critical_numerical_warning',not critical)
        check('Original_scale_variance_points_valid',np.isfinite([tau,sigma]).all() and tau >= 0 and sigma > 0)
        p = x.shape[1]
        beta = np.asarray(fit.fe_params)
        cov = np.asarray(fit.cov_params())[:p,:p]
        check('Fixed_covariance_positive_definite',np.isfinite(cov).all() and np.linalg.eigvalsh((cov+cov.T)/2).min() > 0)
        check('Fixed_coefficients_finite',np.isfinite(beta).all())
        q = norm.ppf(1-alpha/2)
        rows = []
        for label, weights in [('Between_person_association',(1.,0.)),('Within_person_association',(0.,1.)),
                               ('Between_minus_within',(1.,-1.))]:
            contrast = np.zeros(p);contrast[1:3] = weights
            b, se = float(contrast@beta), float(np.sqrt(contrast@cov@contrast))
            check(label+'_finite_SE',np.isfinite(se) and se > 0)
            rows.append({'Association':label,'Beta':b,'SE':se,'CI_low':b-q*se,'CI_high':b+q*se,
                         'P':2*norm.sf(abs(b/se)),'Inference':'LMM_model_based_normal_Wald'})
        direct = prepared['direct_within_beta']
        matches = bool(np.isclose(beta[2],direct,rtol=1e-7,atol=1e-8))
        tables['demeaned_crosscheck'] = pd.DataFrame([{'Mundlak_within_beta':beta[2],
            'Direct_demeaned_beta':direct,'Matches':matches}])
        check('Within_coefficient_matches_direct_demeaned_estimate',matches)
        pd.testing.assert_frame_equal(original,previous['selected'])
        check('R06_selected_rows_and_values_unchanged',True)
        tables['S9_R07_Mundlak_candidate'] = pd.DataFrame(rows)
        status.update(Completed=True,Assessment_completed=True,Model_fitted=True,
                      Original_cohorts_changed=False,Age_values_changed=False,Weather_values_changed=False)
        for title,key in [('1 資料分母','denominators'),('2 病人內變動資訊','within_information'),
                          ('3 設計與可識別性','design_diagnostics'),('4 Hb關聯分解','S9_R07_Mundlak_candidate'),
                          ('5 配適診斷','fit_diagnostics')]:
            print(f'\n=== 請回傳：R07 {title} ===')
            table = tables[key]
            print(table.to_string(index=False,float_format=lambda v:f'{v:.8g}'))
        print('\n=== 請回傳：R07 6 去均值核對與驗證 ===')
        print(tables['demeaned_crosscheck'].to_string(index=False,float_format=lambda v:f'{v:.10g}'))
        print(pd.DataFrame([{'Checks':len(checks),'All_passed':all(c['Passed'] for c in checks),**status}]).to_string(index=False))
        print('警告：無。' if tables['fit_warnings'].empty else tables['fit_warnings'].to_string(index=False))
        print(f'\n輸出位置：{out}')

        return {'Completed':True,'Assessment_completed':True,'Model_fitted':True,'model':fit,
                'tables':tables,'output_dir':str(out),'status':status}
    except Exception as exc:
        status.update(Error_type=type(exc).__name__,Error=str(exc))
        print(f'R07 未完成；診斷保留於 {out}。不使用舊結果或替代模型。')
        raise
    finally:
        for name,table in tables.items():
            table.to_csv(out/(name+'.csv'),index=False,encoding='utf-8-sig')
        pd.DataFrame(checks,columns=['Check','Passed']).to_csv(out/'validation.csv',index=False,encoding='utf-8-sig')
        (out/'run_status.json').write_text(json.dumps(status,ensure_ascii=False,indent=2),encoding='utf-8')


R07 = None
if 'R06' not in globals() or 'folder_path' not in globals():
    raise NameError('請先執行前置步驟（R05 7A）與前置步驟（R06），再執行 R07。')
_r07_out = Path(folder_path)/'Revision_R07_Mundlak'/(
    datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')+'_'+uuid.uuid4().hex[:8])
R07 = r07_run(R06,_r07_out)

"""## Calendar dependence diagnostics and dependent wild bootstrap

Input objects are produced by preceding cells in this notebook. Outputs remain private working artifacts until the publication export section.

"""

import json
import uuid
import warnings
from datetime import datetime, timezone
from pathlib import Path
import numpy as np
import pandas as pd
import patsy
import scipy
from scipy.stats import norm, t
import statsmodels
import statsmodels.api as sm
import matplotlib.pyplot as plt

R08_B = 1000
R08_SPANS = (30, 60, 90)  # 預先指定的相依範圍敏感度，不是資料筆數或最佳區塊長度宣稱。
R08_MAX_LAG = 180         # 診斷延伸至最長模擬範圍以外；不是新增 180 天氣象特徵。
R08_SEED = 42
R08_ALPHA = 0.05
R08_PID, R08_DXA = '去個資編號', '骨密度檢查執行日期'


def r08_prepare(r05, r06):
    if not isinstance(r05, dict) or not r05.get('Completed', False):
        raise ValueError('R05 尚未完成；不以舊世代代替。')
    if not isinstance(r06, dict) or not r06.get('Completed', False):
        raise ValueError('R06 尚未完成；需要其主分析模型核對。')
    d = r05['df_primary'].copy(deep=True).reset_index(drop=True)
    numeric = ['Age','sex_bin','Hb_Value','overall_T','THI_mean_30d','DTR_mean_30d']
    required = [R08_PID,'pairing_row_id',R08_DXA,'Hb_Date']+numeric
    if d.empty or not d.columns.is_unique or set(required)-set(d):
        raise ValueError('R05 Primary 為空、欄名重複或缺少必要欄位。')
    if d[[R08_PID,'pairing_row_id']].isna().any().any() or d[R08_PID].duplicated().any() or d.pairing_row_id.duplicated().any():
        raise ValueError('Primary 必須一人一列，且病人／配對列 ID 不得缺失或重複。')
    d[numeric] = d[numeric].apply(pd.to_numeric,errors='raise').astype(float)
    if not np.isfinite(d[numeric]).all().all():
        raise ValueError('模型欄位含缺失／非有限值；不在 R08 自動刪列。')
    selected = r06['selected'].set_index('pairing_row_id',verify_integrity=True)
    if not d.pairing_row_id.isin(selected.index).all():
        raise ValueError('Primary ID 與 R06 不一致；請重跑相應上游。')
    matched = selected.loc[d.pairing_row_id].reset_index()
    if not np.array_equal(d[R08_PID].to_numpy(),matched[R08_PID].to_numpy()) or not np.array_equal(
            d[numeric].to_numpy(),matched[numeric].to_numpy(dtype=float)):
        raise ValueError('Primary 數值與 R06 不一致；不混用版本。')
    for prefix,col in [('hb','Hb_Date'),('dxa',R08_DXA)]:
        d[col] = pd.to_datetime(d[col],errors='raise')
        if d[col].isna().any() or not np.array_equal(d[col],pd.to_datetime(matched[col],errors='raise')):
            raise ValueError(f'{col} 缺失或與 R06 不一致。')
        d[prefix+'_year'] = d[col].dt.year.astype(int)
        d[prefix+'_sin'] = np.sin(2*np.pi*d[col].dt.month/12)
        d[prefix+'_cos'] = np.cos(2*np.pi*d[col].dt.month/12)
    models, specs = {}, []
    for name,target,outcome,prefix in [('A','THI_mean_30d','Hb_Value','hb'),('B','Hb_Value','overall_T','dxa')]:
        reference = int(d[prefix+'_year'].min())
        predictors = ('THI_mean_30d + DTR_mean_30d + Age + sex_bin' if name=='A' else
                      'Hb_Value + THI_mean_30d + DTR_mean_30d + Age + sex_bin')
        formula = f'{outcome} ~ {predictors} + {prefix}_sin + {prefix}_cos + C({prefix}_year, Treatment(reference={reference}))'
        y,X = patsy.dmatrices(formula,d,return_type='dataframe',NA_action='raise',eval_env=-1)
        if len(X)!=len(d) or np.linalg.matrix_rank(X)!=X.shape[1] or len(X)<=X.shape[1]:
            raise ValueError(f'Model {name} 設計不滿秩或列數改變；不刪除調整項。')
        fit = sm.OLS(y.iloc[:,0],X,missing='raise').fit()
        hc3 = fit.get_robustcov_results(cov_type='HC3',use_t=False)
        if not np.isfinite(hc3.params).all() or not np.isfinite(hc3.bse).all() or (hc3.bse<=0).any():
            raise ValueError(f'Model {name} 的 HC3 估計／SE 無效。')
        models[name] = {'fit':fit,'hc3':hc3,'target':target,'j':list(X.columns).index(target),'X':X,'y':y.iloc[:,0].to_numpy()}
        specs.append({'Model':name,'Target':target,'Rows':len(d),'Patients':d[R08_PID].nunique(),
            'Design_columns':X.shape[1],'Reference_year':reference,'Model_calendar_anchor':prefix,'Formula':formula})
    baseline = r06['models']['Primary_OLS_HC3']
    current = models['B']['hc3']; j = models['B']['j']
    base_j = baseline.model.exog_names.index('Hb_Value')
    if (baseline.model.exog_names!=list(models['B']['X'])
        or not np.allclose(baseline.model.exog,models['B']['X'],rtol=1e-12,atol=1e-12)
        or not np.array_equal(baseline.model.endog,models['B']['y'])):
        raise ValueError('Model B 與 R06 原主分析的設計／列序不同。')
    baseline_check = pd.DataFrame([{'Metric':metric,'R06':old,'R08':new,
        'Matches':bool(np.isclose(old,new,rtol=1e-8,atol=1e-10))} for metric,old,new in [
        ('Beta',np.asarray(baseline.params)[base_j],current.params[j]),
        ('HC3_SE',np.asarray(baseline.bse)[base_j],current.bse[j]),
        ('P',np.asarray(baseline.pvalues)[base_j],current.pvalues[j])]])
    if not baseline_check.Matches.all():
        raise ValueError('Model B 未重現 R06 主分析。')
    return d,models,pd.DataFrame(specs),baseline_check


def r08_calendar(model, dates, max_lag):
    days = pd.DatetimeIndex(pd.to_datetime(dates)).normalize()
    calendar = pd.date_range(days.min(),days.max(),freq='D')
    day_index = calendar.get_indexer(days)
    count = np.bincount(day_index,minlength=len(calendar))
    fit,j = model['fit'],model['j']
    e = np.asarray(fit.resid)
    # HC1 有限樣本尺度修正，與 bootstrap 本身的相依結構分開定義。
    factor = np.sqrt(len(e)/(len(e)-model['X'].shape[1]))
    influence = np.asarray(fit.model.pinv_wexog)*(e*factor)[None,:]
    daily = np.zeros((len(calendar),influence.shape[0]))
    np.add.at(daily,day_index,influence.T)
    residual_mean = np.full(len(calendar),np.nan)
    residual_mean[count>0] = np.bincount(day_index,weights=e,minlength=len(calendar))[count>0]/count[count>0]
    # 空日無觀測，其 score 貢獻為 0；這不是把缺失的臨床殘差當成 0。
    diagnostic_score = daily[:,j].copy();diagnostic_score[count==0] = np.nan
    def pair_correlation(values,lag):
        a,b = values[:-lag],values[lag:]
        ok = np.isfinite(a)&np.isfinite(b)
        n = int(ok.sum())
        if n<3 or np.ptp(a[ok])==0 or np.ptp(b[ok])==0:
            return n,np.nan
        return n,float(np.corrcoef(a[ok],b[ok])[0,1])
    diagnostics=[]
    for lag in range(1,min(max_lag,len(calendar)-1)+1):
        n,r = pair_correlation(residual_mean,lag)
        ns,s = pair_correlation(diagnostic_score,lag)
        if n!=ns:
            raise ValueError('殘差與 influence 診斷的日期對分母不同。')
        diagnostics.append({'Lag_calendar_days':lag,'Observed_date_pairs':n,
            'Daily_mean_residual_correlation':r,'Target_daily_influence_correlation':s})
    summary={'Calendar_start':calendar.min().date().isoformat(),'Calendar_end':calendar.max().date().isoformat(),
        'Calendar_days':len(calendar),'Observed_dates':int((count>0).sum()),'Days_without_patient_records':int((count==0).sum()),
        'Dates_with_multiple_patients':int((count>1).sum()),'Max_patients_per_date':int(count.max()),
        'Median_patients_per_observed_date':float(np.median(count[count>0]))}
    return {'calendar':calendar,'day_index':day_index,'daily_influence':daily,'residual_factor':factor,
            'diagnostics':pd.DataFrame(diagnostics),'summary':summary}


def r08_multipliers(rng, calendar_days, span):
    # 額外產生邊界外的隨機數，不把研究期末日期接回期初。
    # E(xi_d)=0，Var(xi_d)=1，Cov(xi_d,xi_(d+h))=max(1-|h|/span,0)。
    z = rng.standard_normal(calendar_days+span-1)
    cumulative = np.concatenate(([0.],np.cumsum(z)))
    return (cumulative[span:]-cumulative[:-span])/np.sqrt(span)


def r08_bootstrap(model, cal, name, clock, span, B, seed, alpha, out):
    stream = [int(seed),ord(name),0 if clock=='Hb_report' else 1,int(span)]
    rng = np.random.default_rng(np.random.SeedSequence(stream))
    fit,j = model['fit'],model['j']
    observed = np.asarray(fit.params)
    D = len(cal['calendar'])
    ledger, crosscheck = [], []
    path = Path(out)/f'bootstrap_draws_{name}_{clock}_{span}d.csv'
    for draw in range(B):
        rec={'Model':name,'Dependence_clock':clock,'Span_calendar_days':span,'Draw':draw+1,
             'Status':'success','Beta':np.nan,'Error':''}
        try:
            xi = r08_multipliers(rng,D,span)
            candidate = observed+np.einsum('dp,d->p',cal['daily_influence'],xi,optimize=False)
            if not np.isfinite(candidate).all() or not np.isfinite(xi).all():
                rec['Status']='nonfinite_failed';rec['Error']='Non-finite multiplier or coefficient'
            else:
                rec['Beta']=float(candidate[j])
                if draw==0:
                    y_star = np.asarray(fit.fittedvalues)+np.asarray(fit.resid)*cal['residual_factor']*xi[cal['day_index']]
                    direct = sm.OLS(y_star,model['X'],missing='raise').fit()
                    error = float(np.max(np.abs(candidate-np.asarray(direct.params))))
                    match = bool(np.allclose(candidate,direct.params,rtol=1e-7,atol=1e-8))
                    crosscheck.append({'Model':name,'Dependence_clock':clock,'Span_calendar_days':span,
                                       'First_draw_max_abs_coefficient_difference':error,'Matches':match})
                    if not match:
                        rec['Status']='refit_check_failed';rec['Error']='Daily-influence projection differs from direct OLS refit'
        except Exception as exc:
            rec['Status']='other_failed';rec['Error']=f'{type(exc).__name__}: {exc}'
        ledger.append(rec)
        if rec['Status']!='success':
            print(f'R08 {name}/{clock}/{span}d 第 {draw+1} 次失敗：{rec["Status"]}，{rec["Error"]}',flush=True)
        if (draw+1)%250==0 or draw+1==B:
            successes=sum(r['Status']=='success' for r in ledger)
            print(f'R08 {name}/{clock}/{span}d：已嘗試 {draw+1}/{B}，成功 {successes}，失敗 {draw+1-successes}。',flush=True)
            pd.DataFrame(ledger).to_csv(path,index=False,encoding='utf-8-sig')
    draws=pd.DataFrame(ledger)
    ok=draws.Status.eq('success')
    # 本格只有固定設計、閉式 OLS；rank 在模擬前已核對，不會逐次改選資料或丟棄年份。
    valid=bool(ok.all() and len(draws)==B and len(crosscheck)==1 and crosscheck[0]['Matches'])
    v=cal['daily_influence'][:,j]
    exact_se=float(np.linalg.norm(np.convolve(v,np.ones(span)/np.sqrt(span),mode='full')))
    summary={'Model':name,'Dependence_clock':clock,'Span_calendar_days':span,'Requested':B,'Attempted':len(draws),
        'Succeeded':int(ok.sum()),'Failed':int((~ok).sum()),'Rank_failed':0,
        'Nonfinite_failed':int(draws.Status.eq('nonfinite_failed').sum()),
        'Refit_check_failed':int(draws.Status.eq('refit_check_failed').sum()),
        'Other_failed':int(draws.Status.eq('other_failed').sum()),'All_requested_draws_succeeded':valid,
        'Fixed_rows_per_draw':len(model['y']),'Seed_stream':json.dumps(stream),
        'Bootstrap_SE':np.nan,'Exact_kernel_SE':exact_se,'Bootstrap_SE_over_exact_kernel_SE':np.nan,
        'Bootstrap_bias':np.nan,'CI_low':np.nan,'CI_high':np.nan}
    if valid:
        values=draws.Beta.to_numpy();delta=values-observed[j]
        lo,hi=np.quantile(delta,[alpha/2,1-alpha/2])
        se=float(np.std(values,ddof=1))
        summary.update(Bootstrap_SE=se,Bootstrap_SE_over_exact_kernel_SE=se/exact_se if exact_se>0 else np.nan,
                       Bootstrap_bias=float(delta.mean()),CI_low=float(observed[j]-hi),CI_high=float(observed[j]-lo))
    return draws,summary,pd.DataFrame(crosscheck)


def r08_plot(diagnostics, out):
    streams=list(diagnostics.groupby(['Model','Dependence_clock'],sort=False))
    fig,axes=plt.subplots(len(streams),2,figsize=(11,2.7*len(streams)),squeeze=False,constrained_layout=True)
    for row,((model,clock),frame) in enumerate(streams):
        for col,(field,label) in enumerate([('Daily_mean_residual_correlation','Daily mean residual'),
                                            ('Target_daily_influence_correlation','Target daily influence')]):
            ax=axes[row,col];ax.plot(frame.Lag_calendar_days,frame[field],lw=.85,color='#176b87')
            ax.axhline(0,color='0.5',lw=.7)
            ax.set(title=f'Model {model} | {clock} | {label}',xlabel='Exact calendar lag (days)',ylabel='Pairwise correlation')
            ax.grid(alpha=.15)
    fig.suptitle('Descriptive calendar-lag diagnostics; only observed date pairs; no IID significance bands',fontsize=11)
    fig.savefig(Path(out)/'R08_calendar_lag_diagnostics.png',dpi=300)
    plt.close(fig)


def r08_run(r05,r06,out,B=R08_B,spans=R08_SPANS,max_lag=R08_MAX_LAG,seed=R08_SEED,alpha=R08_ALPHA):
    out=Path(out);out.mkdir(parents=True,exist_ok=False)
    tables,checks,models={ },[],{}
    status={'Completed':False,'Formal_tables_replaced':False,'Original_cohorts_changed':False}
    original=r05['df_primary'].copy(deep=True) if isinstance(r05,dict) and 'df_primary' in r05 else None
    warnings_log=[]
    def check(name,ok):
        checks.append({'Check':name,'Passed':bool(ok)})
        if not ok:raise ValueError('R08 驗證失敗：'+name)
    try:
        check('Configuration_valid',isinstance(B,int) and B>=2 and 0<alpha<1 and isinstance(seed,int) and seed>=0
              and len(spans)>0 and len(set(spans))==len(spans) and all(isinstance(s,int) and s>=1 for s in spans)
              and isinstance(max_lag,int) and max_lag>=1)
        with warnings.catch_warnings(record=True) as caught:
            warnings.simplefilter('always')
            d,models,specs,baseline=r08_prepare(r05,r06)
        warnings_log.extend({'Stage':'prepare','Category':w.category.__name__,'Message':str(w.message)} for w in caught)
        check('No_numerical_preparation_warning',not any(issubclass(w.category,RuntimeWarning) for w in caught))
        checks.extend({'Check':s,'Passed':True} for s in ['Explicit_R05_R06_input_and_matching_IDs',
            'Primary_one_complete_row_per_patient','R06_data_values_and_dates_preserved',
            'Both_original_model_designs_full_rank','R06_ModelB_HC3_reproduced'])
        tables.update(model_specifications=specs,R06_baseline_check=baseline)
        comparisons,denominators,diagnostics,summaries,crosschecks=[],[],[],[],[]
        def inference_row(name,clock,method,beta,se,lo,hi,p=np.nan,span=np.nan):
            base=models[name]['hc3'];j=models[name]['j']
            return {'Model':name,'Target':models[name]['target'],'Dependence_clock':clock,'Method':method,
                'Span_calendar_days':span,'Rows':len(d),'Beta':float(beta),'SE':float(se),'CI_low':float(lo),
                'CI_high':float(hi),'P':float(p),'CI_includes_zero':bool(lo<=0<=hi),
                'SE_ratio_to_HC3':float(se/base.bse[j]),
                'CI_zero_status_changed_vs_HC3':bool((lo<=0<=hi)!=(base.conf_int(alpha)[j,0]<=0<=base.conf_int(alpha)[j,1]))}
        for name,m in models.items():
            fit,j=m['hc3'],m['j'];ci=fit.conf_int(alpha)[j]
            comparisons.append(inference_row(name,'Not_applied','HC3_normal_Wald',fit.params[j],fit.bse[j],*ci,fit.pvalues[j]))
        specification={'Base_notebook':'self-contained analysis implementation','Reviewers':['R1 Major 3','R2-1'],
            'Input':'R05.df_primary; validated against R06 selected rows and Primary_OLS_HC3',
            'Method':'Fixed-design unrestricted Gaussian dependent wild bootstrap; calendar Bartlett multipliers',
            'Pseudo_outcome':'y_star = fitted + residual * sqrt(N/(N-p)) * xi_calendar_day',
            'Multiplier_covariance':'max(1-abs(calendar_day_difference)/span,0); same date shares one multiplier',
            'Calendar':'Complete calendar, no compression of unobserved days; no endpoint wrap-around',
            'CI':'Basic bootstrap: beta_hat - quantiles(beta_star-beta_hat), reversed endpoints',
            'Bootstrap_P':'Not computed; original HC3 and exact-date cluster P values kept with their own method labels',
            'Cluster_comparator':'One-way exact-date cluster CR1 correction; t reference with G-1 degrees of freedom',
            'B_per_stream':B,'Spans_days':list(spans),'Seed':seed,'Alpha':alpha,'Diagnostic_max_lag':max_lag,
            'Span_rationale':'30 days relates to nominal 30-day exposure; 60/90 assess longer dependence; not a data-estimated optimum',
            'Model_A_dependence_clocks':['Hb_report'],'Model_B_dependence_clocks':['DXA','Hb_report'],
            'Separate_clock_limit':'Model B clock analyses are separate sensitivities, not a joint two-clock covariance model',
            'Diagnostic':'Pearson correlation at exact calendar lags among observed date pairs; descriptive, no IID ACF tests',
            'Empty_calendar_days':'No clinical residual imputation; zero contribution only to the sum of estimating influences',
            'Original_age_weather_and_cohort_changed':False,'Weather_reconstructed_here':False,
            'Formal_tables_replaced':False,'Failure_policy':'Every attempt logged; any failed draw prevents accepted CI for that stream and completion',
            'Assumption_limit':'Sensitivity under short-range calendar dependence; not proof of independence, no causal or confounding correction',
            'Software':{'numpy':np.__version__,'pandas':pd.__version__,'scipy':scipy.__version__,'statsmodels':statsmodels.__version__}}
        (out/'analysis_specification.json').write_text(json.dumps(specification,ensure_ascii=False,indent=2),encoding='utf-8')
        for name,clock,date_col in [('A','Hb_report','Hb_Date'),('B','DXA',R08_DXA),('B','Hb_report','Hb_Date')]:
            m=models[name];cal=r08_calendar(m,d[date_col],max_lag)
            check(name+'_'+clock+'_span_within_observed_calendar',max(spans)<len(cal['calendar']))
            denominators.append({'Model':name,'Dependence_clock':clock,'Rows':len(d),'Patients':d[R08_PID].nunique(),**cal['summary']})
            di=cal['diagnostics'].copy();di.insert(0,'Dependence_clock',clock);di.insert(0,'Model',name);diagnostics.append(di)
            with warnings.catch_warnings(record=True) as caught:
                warnings.simplefilter('always')
                cluster=m['fit'].get_robustcov_results(cov_type='cluster',groups=cal['day_index'],
                    use_correction=True,df_correction=True,use_t=True)
            warnings_log.extend({'Stage':name+'_'+clock+'_cluster','Category':w.category.__name__,'Message':str(w.message)} for w in caught)
            j=m['j'];G=cal['summary']['Observed_dates']
            check(name+'_'+clock+'_date_cluster_valid',G>1 and np.isfinite(cluster.bse[j]) and cluster.bse[j]>0)
            check(name+'_'+clock+'_cluster_uses_date_df',np.isclose(cluster.df_resid_inference,G-1))
            ci=cluster.conf_int(alpha)[j]
            comparisons.append(inference_row(name,clock,'Exact_date_cluster_t',cluster.params[j],cluster.bse[j],*ci,cluster.pvalues[j]))
            for span in spans:
                draws,summary,cross=r08_bootstrap(m,cal,name,clock,span,B,seed,alpha,out)
                summaries.append(summary);crosschecks.append(cross)
                tables['bootstrap_summary']=pd.DataFrame(summaries)
                tables['first_draw_OLS_crosscheck']=pd.concat(crosschecks,ignore_index=True)
                if summary['All_requested_draws_succeeded']:
                    comparisons.append(inference_row(name,clock,'DWB_basic_CI',m['fit'].params.iloc[j],
                        summary['Bootstrap_SE'],summary['CI_low'],summary['CI_high'],span=span))
        tables['calendar_denominators']=pd.DataFrame(denominators)
        tables['calendar_lag_diagnostics']=pd.concat(diagnostics,ignore_index=True)
        tables['inference_comparison_diagnostic']=pd.DataFrame(comparisons)
        check('All_requested_draws_succeeded_in_every_stream',tables['bootstrap_summary'].All_requested_draws_succeeded.all())
        check('Every_stream_matches_direct_OLS_refit',tables['first_draw_OLS_crosscheck'].Matches.all())
        check('Bootstrap_failure_counts_reconcile',(tables['bootstrap_summary'].Attempted==
              tables['bootstrap_summary'].Succeeded+tables['bootstrap_summary'].Failed).all())
        check('All_bootstrap_SE_and_CI_finite',np.isfinite(tables['bootstrap_summary'][['Bootstrap_SE','CI_low','CI_high']]).all().all()
              and tables['bootstrap_summary'].Bootstrap_SE.gt(0).all())
        pd.testing.assert_frame_equal(original,r05['df_primary'])
        check('R05_primary_unchanged',True)
        tables['S10_R08_candidate']=pd.DataFrame(comparisons)
        r08_plot(tables['calendar_lag_diagnostics'],out)
        status.update(Completed=True,Models_fitted=len(models),Dependence_clocks=len(denominators),
                      Bootstrap_streams=len(summaries),Requested_draws_total=B*len(summaries),
                      Successful_draws_total=int(tables['bootstrap_summary'].Succeeded.sum()),
                      Age_values_changed=False,Weather_values_changed=False)
        for title,table in [('1 模型與日期分母',tables['calendar_denominators']),
            ('2 主分析重現',baseline),
            ('3 殘差與目標係數的日曆相關',tables['calendar_lag_diagnostics'].query('Lag_calendar_days in [1,7,14,30,60,90,180]')),
            ('4 推論敏感度',tables['S10_R08_candidate']),
            ('5 重抽樣紀錄',tables['bootstrap_summary'])]:
            print(f'\n=== 請回傳：R08 {title} ===');print(table.to_string(index=False,float_format=lambda v:f'{v:.8g}'))
        print('\n=== 請回傳：R08 6 配適核對與驗證 ===')
        print(tables['first_draw_OLS_crosscheck'].to_string(index=False))
        print(pd.DataFrame([{'Checks':len(checks),'All_passed':all(c['Passed'] for c in checks),**status}]).to_string(index=False))
        print('警告：無。' if not warnings_log else pd.DataFrame(warnings_log).to_string(index=False))
        print(f'\n輸出位置：{out}')

        return {'Completed':True,'models':models,'tables':tables,'status':status,'output_dir':str(out)}
    except Exception as exc:
        status.update(Error_type=type(exc).__name__,Error=str(exc))
        print(f'R08 尚未完成；診斷保留於 {out}，不沿用舊結果。')
        raise
    finally:
        for name,table in tables.items():table.to_csv(out/(name+'.csv'),index=False,encoding='utf-8-sig')
        pd.DataFrame(checks,columns=['Check','Passed']).to_csv(out/'validation.csv',index=False,encoding='utf-8-sig')
        pd.DataFrame(warnings_log,columns=['Stage','Category','Message']).to_csv(out/'fit_warnings.csv',index=False,encoding='utf-8-sig')
        (out/'run_status.json').write_text(json.dumps(status,ensure_ascii=False,indent=2),encoding='utf-8')


R08=None
if any(k not in globals() for k in ['R05','R06','folder_path']):
    raise NameError('請先執行前置步驟（R05 7A）及前置步驟（R06），再執行 R08。')
_r08_out=Path(folder_path)/'Revision_R08_Temporal_Dependence'/(
    datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')+'_'+uuid.uuid4().hex[:8])
R08=r08_run(R05,R06,_r08_out)

"""## Joint hourly completeness

Input objects are produced by preceding cells in this notebook. Outputs remain private working artifacts until the publication export section.

"""

from pathlib import Path
from datetime import datetime, timezone
import hashlib
import json
import uuid
import numpy as np
import pandas as pd

R09_STATION = '沙鹿'
R09_THRESHOLDS = (18, 20, 24)  # 敏感度設定：75%、83.3%、100%；不是宣稱官方統一門檻。
R09_BOUNDS = {'AMB_TEMP':(0.,45.), 'RH':(0.,100.)}  # 沿用 R05 的數值篩選。
R09_HOURS = [str(h) for h in range(24)]
R09_VERSION = 'station_hour_intersection_calendar_daily_v1'
R09_DUPLICATE_POLICY = 'exclude_conflicting_or_validity_discordant_hour; collapse_only_identical_valid_values'


def r09_read(path, station, out):
    path=Path(path)
    if not path.is_file():raise FileNotFoundError(f'找不到明確指定的來源：{path}')
    digest=hashlib.sha256()
    with path.open('rb') as handle:
        for chunk in iter(lambda:handle.read(1024*1024),b''):digest.update(chunk)
    raw=pd.read_csv(path,dtype='string',keep_default_na=False,encoding='utf-8-sig',low_memory=False)
    required=['日期','測站','測項']+R09_HOURS
    if not raw.columns.is_unique or set(required)-set(raw):
        raise ValueError(f'氣象表缺少必要欄位或欄名重複：{sorted(set(required)-set(raw))}')
    raw['Source_record_1based']=np.arange(1,len(raw)+1)
    for col in ['日期','測站','測項']:raw[col]=raw[col].str.strip()
    stations=raw.groupby('測站',dropna=False).size().rename('Source_rows').reset_index()
    stations.to_csv(Path(out)/'source_station_inventory.csv',index=False,encoding='utf-8-sig')
    if set(raw['測站'])!={station}:
        raise ValueError(f'指定單站檔的測站欄不是單一「{station}」；已輸出測站盤點，未混合測站。')
    dates=pd.to_datetime(raw['日期'],format='mixed',errors='coerce')
    bad=dates.isna()|dates.ne(dates.dt.normalize())
    if bad.any():
        raw.loc[bad,['Source_record_1based','日期','測站','測項']].to_csv(Path(out)/'invalid_source_dates.csv',index=False,encoding='utf-8-sig')
        raise ValueError('來源有缺失、不可解析或非午夜的每日日期；未猜測日期或移動小時。')
    raw['日期']=dates
    q=raw.loc[raw['測項'].isin(R09_BOUNDS),required+['Source_record_1based']].copy()
    if set(q['測項'])!=set(R09_BOUNDS):raise ValueError('來源必須同時包含 AMB_TEMP 與 RH。')
    metadata={'File':path.name,'SHA256':digest.hexdigest(),'Station':station,'Source_rows_all_items':len(raw),
        'Source_rows_TRH':len(q),'File_date_min':raw['日期'].min().date().isoformat(),
        'File_date_max':raw['日期'].max().date().isoformat(),'File_observed_dates':raw['日期'].nunique(),
        'TRH_date_min':q['日期'].min().date().isoformat(),'TRH_date_max':q['日期'].max().date().isoformat(),
        'TRH_observed_dates':q['日期'].nunique()}
    return q,metadata,pd.DatetimeIndex(raw['日期'].unique())


def r09_hours(q, out):
    long=q.melt(id_vars=['測站','日期','測項','Source_record_1based'],value_vars=R09_HOURS,
                var_name='Hour',value_name='Raw_value')
    long['Hour']=long['Hour'].astype(int)
    token=long['Raw_value'].astype('string').str.strip()
    number=pd.to_numeric(token,errors='coerce').astype(float)
    finite=pd.Series(np.isfinite(number),index=long.index)
    low=long['測項'].map({k:v[0] for k,v in R09_BOUNDS.items()})
    high=long['測項'].map({k:v[1] for k,v in R09_BOUNDS.items()})
    valid=finite&number.ge(low)&number.le(high)
    long['Raw_numeric']=number
    long['Raw_status']=np.select([token.eq('').to_numpy(dtype=bool),number.isna(),~finite,finite&~valid],
        ['blank','non_numeric_or_flag','nonfinite','outside_existing_bounds'],default='valid')
    long['Valid_value']=number.where(valid)
    quality=long.groupby(['測項','Raw_status'],sort=True).size().rename('Raw_hour_cells').reset_index()
    invalid=long.loc[long.Raw_status.ne('valid')]
    invalid.to_csv(Path(out)/'invalid_hour_cells.csv',index=False,encoding='utf-8-sig')
    tokens=invalid.groupby(['測項','Raw_status','Raw_value'],dropna=False).size().rename('Raw_hour_cells').reset_index()
    tokens.to_csv(Path(out)/'invalid_token_frequency.csv',index=False,encoding='utf-8-sig')
    keys=['測站','日期','測項','Hour']
    g=long.groupby(keys,sort=True,dropna=False)
    hourly=g.agg(Source_records=('Raw_value','size'),Valid_records=('Valid_value','count'),
        Distinct_valid_values=('Valid_value','nunique'),Distinct_numeric_values=('Raw_numeric','nunique'),
        One_identical_value=('Valid_value','min')).reset_index()
    hourly['Value_conflict']=hourly.Distinct_numeric_values.gt(1)
    hourly['Validity_discordant']=hourly.Valid_records.gt(0)&hourly.Valid_records.lt(hourly.Source_records)
    hourly['Excluded_conflict_hour']=hourly.Value_conflict|hourly.Validity_discordant
    # 只有所有重複來源皆有效且數值相同，才取得該唯一值；不同值不平均、不選較完整列。
    accept=(hourly.Valid_records.eq(hourly.Source_records)&hourly.Distinct_valid_values.eq(1)&~hourly.Excluded_conflict_hour)
    hourly['Clean_value']=hourly.One_identical_value.where(accept)
    dup=hourly.Source_records.gt(1)
    detail=long.merge(hourly.loc[dup,keys+['Source_records','Value_conflict','Validity_discordant','Excluded_conflict_hour']],
                      on=keys,how='inner',validate='many_to_one')
    detail.to_csv(Path(out)/'duplicate_hour_source_detail.csv',index=False,encoding='utf-8-sig')
    audit=[]
    for item in R09_BOUNDS:
        h=hourly.loc[hourly['測項'].eq(item)];r=long.loc[long['測項'].eq(item)]
        audit.append({'Item':item,'Source_daily_rows':q['測項'].eq(item).sum(),'Raw_hour_cells':len(r),
            'Unique_hour_keys':len(h),'Duplicate_hour_keys':h.Source_records.gt(1).sum(),
            'Identical_valid_duplicate_keys':(h.Source_records.gt(1)&h.Clean_value.notna()).sum(),
            'Value_conflict_hour_keys':h.Value_conflict.sum(),'Validity_discordant_hour_keys':h.Validity_discordant.sum(),
            'Excluded_conflict_hour_keys':h.Excluded_conflict_hour.sum(),'Accepted_valid_hour_keys':h.Clean_value.notna().sum()})
    hourly.drop(columns='One_identical_value').to_csv(Path(out)/'hourly_reconciled.csv',index=False,encoding='utf-8-sig')
    return hourly,quality,pd.DataFrame(audit)


def r09_daily(hourly, metadata, file_dates, thresholds):
    calendar=pd.date_range(metadata['File_date_min'],metadata['File_date_max'],freq='D',name='日期')
    values={}
    for item in R09_BOUNDS:
        part=hourly.loc[hourly['測項'].eq(item)]
        values[item]=part.pivot(index='日期',columns='Hour',values='Clean_value').reindex(index=calendar,columns=range(24))
    temperature,humidity=values['AMB_TEMP'],values['RH']
    t_ok,rh_ok=temperature.notna(),humidity.notna()
    joint=t_ok&rh_ok
    d=pd.DataFrame(index=calendar)
    d['Station']=metadata['Station'];d['File_has_any_record']=calendar.isin(file_dates)
    for item,prefix in [('AMB_TEMP','T'),('RH','RH')]:
        part=hourly.loc[hourly['測項'].eq(item)]
        d[prefix+'_has_source_record']=calendar.isin(part['日期'].unique())
        excluded=part.groupby('日期').Excluded_conflict_hour.sum()
        d[prefix+'_excluded_conflict_hours']=excluded.reindex(calendar,fill_value=0).astype(int)
    d['T_valid_hours']=t_ok.sum(axis=1);d['RH_valid_hours']=rh_ok.sum(axis=1)
    d['Joint_valid_hours']=joint.sum(axis=1)
    d['Naive_min_hours']=np.minimum(d.T_valid_hours,d.RH_valid_hours)
    d['Naive_min_minus_joint_hours']=d.Naive_min_hours-d.Joint_valid_hours
    d['T_mean_all_valid']=temperature.mean(axis=1);d['RH_mean_all_valid']=humidity.mean(axis=1)
    d['T_mean_joint']=temperature.where(joint).mean(axis=1)
    d['RH_mean_joint']=humidity.where(joint).mean(axis=1)
    d['THI_from_joint_means']=d.T_mean_joint-0.55*(1-d.RH_mean_joint/100)*(d.T_mean_joint-14.4)
    d['DTR_T_all_valid']=(temperature.max(axis=1)-temperature.min(axis=1)).where(d.T_valid_hours.ge(2))
    tj=temperature.where(joint)
    d['DTR_joint_hours']=(tj.max(axis=1)-tj.min(axis=1)).where(d.Joint_valid_hours.ge(2))
    candidates={}
    for threshold in thresholds:
        c=d[['Station','File_has_any_record','T_has_source_record','RH_has_source_record',
             'T_valid_hours','RH_valid_hours','Joint_valid_hours','T_excluded_conflict_hours','RH_excluded_conflict_hours']].copy()
        c['Minimum_hours']=threshold;c['Pass_T_hours']=d.T_valid_hours.ge(threshold)
        c['Pass_RH_hours']=d.RH_valid_hours.ge(threshold);c['Pass_joint_hours']=d.Joint_valid_hours.ge(threshold)
        for source,target in [('T_mean_joint','T_daily_mean'),('RH_mean_joint','RH_daily_mean'),('THI_from_joint_means','THI_daily')]:
            c[target]=d[source].where(c.Pass_joint_hours)
        # DTR 取全日有效溫度極值，避免 RH 缺值抹掉真正溫度極值；共同小時 DTR 另列敏感度。
        c['DTR_daily']=d.DTR_T_all_valid.where(c.Pass_T_hours)
        c['DTR_daily_joint_sensitivity']=d.DTR_joint_hours.where(c.Pass_joint_hours)
        c['All_daily_fields_available']=c[['T_daily_mean','RH_daily_mean','THI_daily','DTR_daily']].notna().all(axis=1)
        c['Weather_version']=R09_VERSION
        candidates[threshold]=c
    return d,candidates


def r09_coverage(d, candidates, scopes):
    coverage,annual,distributions,dtr,hour_coverage=[],[],[],[],[]
    def one_scope(label,frame,scope_start,scope_end,year=None):
        for h,c in candidates.items():
            aligned=c.reindex(frame.index)
            n=len(frame)
            eligible_dates=frame.index[frame.Joint_valid_hours.ge(h)]
            row={'Scope':label,'Minimum_hours':h,'Calendar_start':scope_start,'Calendar_end':scope_end,'Calendar_days':n,
                'First_joint_eligible_date':str(eligible_dates.min().date()) if len(eligible_dates) else None,
                'Last_joint_eligible_date':str(eligible_dates.max().date()) if len(eligible_dates) else None,
                'Days_outside_file_span':int((~frame.index.isin(d.index)).sum()),
                'Days_without_any_file_record':int((~frame.File_has_any_record.eq(True)).sum()),
                'Days_without_T_record':int((~frame.T_has_source_record.eq(True)).sum()),
                'Days_without_RH_record':int((~frame.RH_has_source_record.eq(True)).sum()),
                'T_hours_pass_days':int(frame.T_valid_hours.ge(h).sum()),'RH_hours_pass_days':int(frame.RH_valid_hours.ge(h).sum()),
                'Joint_hours_pass_days':int(frame.Joint_valid_hours.ge(h).sum()),
                'Joint_coverage_percent':100*frame.Joint_valid_hours.ge(h).sum()/n,
                'Naive_min_false_pass_days':int((frame.Naive_min_hours.ge(h)&~frame.Joint_valid_hours.ge(h)).sum())}
            if year is not None:row['Year']=int(year);annual.append(row)
            else:
                coverage.append(row)
                temp=aligned.DTR_daily.dropna();paired=aligned.loc[aligned.All_daily_fields_available.eq(True)]
                delta=paired.DTR_daily_joint_sensitivity-paired.DTR_daily
                dtr.append({'Scope':label,'Minimum_hours':h,'T_only_eligible_days':len(temp),
                    'DTR_T_only_mean':temp.mean(),'DTR_T_only_SD':temp.std(),'DTR_T_only_median':temp.median(),
                    'DTR_T_only_P95':temp.quantile(.95),'Joint_eligible_days':len(paired),
                    'DTR_T_only_mean_on_joint_days':paired.DTR_daily.mean(),
                    'DTR_joint_hours_mean_on_same_days':paired.DTR_daily_joint_sensitivity.mean(),
                    'Days_joint_DTR_lower':int(delta.lt(-1e-10).sum()),'Mean_joint_minus_T_only_DTR':delta.mean(),
                    'Largest_DTR_loss_from_joint_hours':float((-delta).max()) if len(delta) else np.nan})
    for label,(start,end) in scopes.items():
        idx=pd.date_range(start,end,freq='D',name='日期');frame=d.reindex(idx)
        hour_row={'Scope':label,'Calendar_days':len(idx),'Expected_station_hours':len(idx)*len(R09_HOURS)}
        for prefix in ['T','RH','Joint']:
            valid_hours=int(frame[prefix+'_valid_hours'].sum())
            hour_row[prefix+'_valid_hours']=valid_hours
            hour_row[prefix+'_hour_coverage_percent']=100*valid_hours/hour_row['Expected_station_hours']
        hour_coverage.append(hour_row)
        one_scope(label,frame,str(idx.min().date()),str(idx.max().date()))
        for year,part in frame.groupby(frame.index.year):
            one_scope(label,part,str(part.index.min().date()),str(part.index.max().date()),year)
        for metric in ['T_valid_hours','RH_valid_hours','Joint_valid_hours']:
            counts=frame[metric].fillna(0).astype(int).value_counts().reindex(range(25),fill_value=0)
            distributions.extend({'Scope':label,'Metric':metric,'Valid_hours':int(hours),'Calendar_days':int(n)} for hours,n in counts.items())
    return {'coverage_by_threshold':pd.DataFrame(coverage),'hourly_coverage':pd.DataFrame(hour_coverage),'annual_coverage':pd.DataFrame(annual),
            'valid_hour_distribution':pd.DataFrame(distributions),'DTR_hour_threshold_sensitivity':pd.DataFrame(dtr)}


def r09_compare_legacy(legacy, candidates):
    required=['日期','T_daily_mean','RH_daily_mean','DTR_daily']
    if set(required)-set(legacy):raise ValueError('R05 weather_df 缺少原日摘要欄位，無法明確比較。')
    old=legacy[required].copy();old['日期']=pd.to_datetime(old['日期'],errors='raise')
    if old['日期'].isna().any() or old['日期'].duplicated().any():raise ValueError('R05 舊日摘要日期缺失或重複。')
    old=old.set_index('日期')
    old['THI_daily']=old.T_daily_mean-0.55*(1-old.RH_daily_mean/100)*(old.T_daily_mean-14.4)
    rows=[]
    for h,c in candidates.items():
        new=c.reindex(old.index)
        for col in ['T_daily_mean','RH_daily_mean','THI_daily','DTR_daily']:
            a=pd.to_numeric(old[col],errors='raise');b=new[col];both=a.notna()&b.notna();delta=b[both]-a[both]
            rows.append({'Minimum_hours':h,'Field':col,'Legacy_calendar_rows':len(old),
                'Both_nonmissing_days':int(both.sum()),'Missingness_mismatch_days':int((a.isna()!=b.isna()).sum()),
                'Numeric_change_days':int((~np.isclose(a[both],b[both],rtol=1e-10,atol=1e-10)).sum()),
                'Mean_new_minus_legacy':delta.mean(),'Max_absolute_difference':delta.abs().max()})
    return pd.DataFrame(rows)


def r09_run(r05, source, out, thresholds=R09_THRESHOLDS, station=R09_STATION):
    out=Path(out);out.mkdir(parents=True,exist_ok=False)
    tables,checks,candidates={},[],{}
    status={'Completed':False,'Daily_candidates_ready':False,'Formal_weather_replaced':False,
            'Cohorts_changed':False,'Models_updated':False,'Long_windows_reconstructed':False}
    def check(name,ok):
        checks.append({'Check':name,'Passed':bool(ok)})
        if not ok:raise ValueError('R09 驗證失敗：'+name)
    try:
        check('Explicit_completed_R05_input',isinstance(r05,dict) and r05.get('Completed',False))
        check('Valid_predeclared_hour_thresholds',bool(thresholds) and len(set(thresholds))==len(thresholds)
              and all(isinstance(h,int) and 2<=h<=24 for h in thresholds))
        original_weather=r05['weather_df'].copy(deep=True)
        flags=r05['row_flags']
        raw_dates=flags['Hb_Date'];hb_dates=pd.to_datetime(raw_dates,format='mixed',errors='coerce')
        nonempty=raw_dates.notna()&raw_dates.astype(str).str.strip().ne('')
        check('Master_Hb_dates_parse_without_hidden_losses',not (nonempty&hb_dates.isna()).any() and hb_dates.notna().any())
        hb_days=hb_dates.dropna().dt.normalize()
        q,metadata,file_dates=r09_read(source,station,out)
        hourly,quality,conflicts=r09_hours(q,out)
        tables['hourly_value_quality']=quality;tables['hour_key_reconciliation']=conflicts
        d,candidates=r09_daily(hourly,metadata,file_dates,thresholds)
        scopes={'Full_station_file_calendar':(d.index.min(),d.index.max()),
                'TRH_source_calendar':(pd.Timestamp(metadata['TRH_date_min']),pd.Timestamp(metadata['TRH_date_max'])),
                'Research_Hb_link_calendar':(hb_days.min(),hb_days.max())}
        tables.update(r09_coverage(d,candidates,scopes))
        tables['legacy_daily_comparison']=r09_compare_legacy(original_weather,candidates)
        metadata.update(Complete_file_calendar_days=len(d),File_calendar_dates_without_any_records=int((~d.File_has_any_record).sum()),
            Research_Hb_date_min=hb_days.min().date().isoformat(),Research_Hb_date_max=hb_days.max().date().isoformat(),
            Master_rows_with_Hb_date=int(hb_dates.notna().sum()),
            Dates_naive_min_overstates_joint_hours=int(d.Naive_min_minus_joint_hours.gt(0).sum()),
            Maximum_hour_overstatement=int(d.Naive_min_minus_joint_hours.max()),
            Conflicting_or_discordant_hour_keys_excluded=int(hourly.Excluded_conflict_hour.sum()))
        tables['source_and_calendar_summary']=pd.DataFrame(list(metadata.items()),columns=['Metric','Value'])
        check('Hourly_input_cell_counts_reconcile',int(quality.Raw_hour_cells.sum())==len(q)*len(R09_HOURS))
        check('Resolved_hour_keys_unique',not hourly.duplicated(['測站','日期','測項','Hour']).any())
        check('No_conflict_hour_accepted',hourly.loc[hourly.Excluded_conflict_hour,'Clean_value'].isna().all())
        check('Complete_daily_calendar_preserved',d.index.equals(pd.date_range(d.index.min(),d.index.max(),name='日期')))
        check('Joint_hours_never_exceed_either_component',d.Joint_valid_hours.le(d.T_valid_hours).all()&d.Joint_valid_hours.le(d.RH_valid_hours).all())
        check('All_hour_counts_between_zero_and_24',d[['T_valid_hours','RH_valid_hours','Joint_valid_hours']].ge(0).all().all()
              and d[['T_valid_hours','RH_valid_hours','Joint_valid_hours']].le(24).all().all())
        check('Hourly_coverage_uses_full_calendar_denominator',all(
            tables['hourly_coverage'][prefix+'_valid_hours'].le(tables['hourly_coverage'].Expected_station_hours).all()
            for prefix in ['T','RH','Joint']))
        check('Joint_DTR_never_exceeds_temperature_DTR',(d.DTR_joint_hours-d.DTR_T_all_valid).dropna().le(1e-10).all())
        for h,c in candidates.items():
            check(f'{h}h_daily_availability_matches_joint_requirement',np.array_equal(c.All_daily_fields_available,c.Pass_joint_hours))
            check(f'{h}h_inadequate_hours_not_silently_used',c.loc[~c.Pass_joint_hours,['T_daily_mean','RH_daily_mean','THI_daily']].isna().all().all()
                  and c.loc[~c.Pass_T_hours,'DTR_daily'].isna().all())
            c.to_csv(out/f'daily_calendar_{h}h_candidate.csv',index=True,encoding='utf-8-sig')
        for lo,hi in zip(sorted(thresholds)[:-1],sorted(thresholds)[1:]):
            check(f'{hi}h_is_subset_of_{lo}h',(~candidates[hi].Pass_joint_hours|candidates[lo].Pass_joint_hours).all())
        for scope,(start,end) in scopes.items():
            denom=(end-start).days+1
            for metric,part in tables['valid_hour_distribution'].query('Scope==@scope').groupby('Metric'):
                check(scope+'_'+metric+'_denominator',int(part.Calendar_days.sum())==denom)
        pd.testing.assert_frame_equal(original_weather,r05['weather_df'])
        check('Existing_R05_weather_unchanged',True)
        d.to_csv(out/'daily_calendar_before_hour_threshold.csv',index=True,encoding='utf-8-sig')
        specification={'Base_notebook':'self-contained analysis implementation','Reviewer':'R1 Major 4','Version':R09_VERSION,
            'Source_file':str(source),'Source_sha256':metadata['SHA256'],'Station_field':station,
            'Source_date_convention':'Original daily date plus hour columns 0..23; no timezone conversion or date shift',
            'Numeric_bounds_inherited_from_R05':R09_BOUNDS,'Hour_thresholds':list(thresholds),
            'Threshold_rationale':'18/24,20/24,24/24 descriptive sensitivity; not an asserted regulatory requirement',
            'Duplicate_policy':R09_DUPLICATE_POLICY,'Value_conflict_test':'Different numeric values at same station/date/item/hour; exact comparison',
            'Invalid_tokens':'Blank, flags/non-numeric, nonfinite and values outside inherited bounds remain unusable; never strip flags to recover numbers',
            'Daily_T_RH':'Means over intersecting valid T and RH hours; joint count is not min of separate valid counts',
            'Daily_THI':'T_joint_mean - 0.55*(1-RH_joint_mean/100)*(T_joint_mean-14.4); not mean of hourly THI',
            'Daily_DTR':'Max-min of ALL valid T hours, subject to T-hour threshold; joint-hour DTR saved separately',
            'DTR_sensitivity_limit':'Threshold-specific means use different eligible day sets; this does not identify true DTR on unobserved hours',
            'Coverage':'Full source-file calendar, T/RH source calendar, and all evaluable master Hb-report-date calendar; no clipping of requested research period',
            'Legacy_comparison_domain':'Dates in existing R05 weather_df only; comparison of daily summaries, not rolling features',
            'Missing_THI':'Remains NaN; no hot-day indicator or long window created here',
            'Official_weather_threshold_selected':False,'Formal_weather_replaced':False,'Models_updated':False,
            'Software':{'numpy':np.__version__,'pandas':pd.__version__}}
        (out/'analysis_specification.json').write_text(json.dumps(specification,ensure_ascii=False,indent=2),encoding='utf-8')
        status.update(Completed=True,Daily_candidates_ready=any(c.All_daily_fields_available.any() for c in candidates.values()),
                      Conflict_hour_exclusion_policy_applied=True,Excluded_conflict_hour_keys=int(hourly.Excluded_conflict_hour.sum()),
                      Official_hour_threshold_selected=False,Age_values_changed=False)
        for title,table in [('1 來源與日曆範圍',tables['source_and_calendar_summary']),
            ('2 小時值品質與重複鍵',conflicts),('3 各小時門檻與完整日曆覆蓋',tables['coverage_by_threshold']),
            ('4 DTR 小時門檻敏感度',tables['DTR_hour_threshold_sensitivity'].query("Scope!='TRH_source_calendar'")),
            ('5 舊版與共同小時日摘要比較',tables['legacy_daily_comparison'])]:
            print(f'\n=== 請回傳：R09 {title} ===');print(table.to_string(index=False,float_format=lambda v:f'{v:.8g}'))
            if title.startswith('2 '):print(quality.to_string(index=False))
            if title.startswith('3 '):print(tables['hourly_coverage'].to_string(index=False,float_format=lambda v:f'{v:.8g}'))
        print('\n=== 請回傳：R09 6 驗證與狀態 ===')
        print(pd.DataFrame([{'Checks':len(checks),'All_passed':all(c['Passed'] for c in checks),**status}]).to_string(index=False))
        print(f'\n輸出位置：{out}')

        return {'Completed':True,'daily_candidates':candidates,'daily_before_threshold':d,'tables':tables,
                'metadata':metadata,'status':status,'output_dir':str(out)}
    except Exception as exc:
        status.update(Error_type=type(exc).__name__,Error=str(exc))
        print(f'R09 未完成；已有診斷保留於 {out}，不退回舊資料繼續。')
        raise
    finally:
        for name,table in tables.items():table.to_csv(out/(name+'.csv'),index=False,encoding='utf-8-sig')
        pd.DataFrame(checks,columns=['Check','Passed']).to_csv(out/'validation.csv',index=False,encoding='utf-8-sig')
        (out/'run_status.json').write_text(json.dumps(status,ensure_ascii=False,indent=2),encoding='utf-8')


R09=None
if 'R05' not in globals() or 'folder_path' not in globals():
    raise NameError('請先執行前置步驟（R05 7A），再執行 R09。')
_r09_out=Path(folder_path)/'Revision_R09_Hourly_Calendar'/(
    datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')+'_'+uuid.uuid4().hex[:8])
R09=r09_run(R05,Path(folder_path)/'29沙鹿.csv',_r09_out)

"""## Reconstructed calendar windows

Input objects are produced by preceding cells in this notebook. Outputs remain private working artifacts until the publication export section.

"""

from pathlib import Path
from datetime import datetime, timezone
import json
import uuid
import numpy as np
import pandas as pd

R10_WINDOWS = (30,180,365)       # 研究視窗設定，不是預期資料筆數。
R10_MIN_VALID_FRACTION = 0.90    # 延伸原手稿嚴格 27/30 日的規則；向上取整。
R10_HOT_THRESHOLD = 27.0        # 沿用原 THI 數值界值，不宣稱臨床熱傷害閾值。
R10_VERSION = 'calendar_windows_joint_days_90pct_v1'
R10_PID, R10_PAIR = '去個資編號','pairing_row_id'
R10_DAILY = ['T_daily_mean','RH_daily_mean','DTR_daily','THI_daily']
R10_SHORT = ['T_mean_30d','RH_mean_30d','DTR_mean_30d','THI_mean_30d','THI_std_30d','T_std_30d']
R10_LEGACY_SIX = ['T_mean_30d','DTR_mean_30d','RH_mean_30d','THI_mean_30d','THI_std_30d','THI_Trend_Shock']


def r10_prepare(r05,r09):
    if not isinstance(r05,dict) or not r05.get('Completed',False):raise ValueError('請先完成本版 R05。')
    if not isinstance(r09,dict) or not r09.get('Completed',False):raise ValueError('請先完成本版 R09；不退回舊氣象。')
    required=[R10_PAIR,R10_PID,'Hb_Date','is_included_primary','is_included_sensitivity']
    master=r05['row_flags']
    if set(required)-set(master):raise ValueError('R05 缺少配對 ID、Hb 日期或世代旗標。')
    pairs=master[required].copy(deep=True).reset_index(drop=True)
    if pairs[[R10_PAIR,R10_PID]].isna().any().any() or not pairs[R10_PAIR].is_unique:
        raise ValueError('母體病人／配對 ID 缺失或配對 ID 重複。')
    for flag in ['is_included_primary','is_included_sensitivity']:
        if pairs[flag].isna().any() or not pairs[flag].isin([True,False]).all():raise ValueError('世代旗標非明確布林值。')
        pairs[flag]=pairs[flag].astype(bool)
    if (pairs.is_included_primary&~pairs.is_included_sensitivity).any():raise ValueError('Primary 不是 repeated 子集。')
    if pairs.loc[pairs.is_included_primary,R10_PID].duplicated().any():raise ValueError('目前 Primary 並非一人一列。')
    for flag,key in [('is_included_primary','df_primary'),('is_included_sensitivity','df_sensitivity')]:
        if set(pairs.loc[pairs[flag],R10_PAIR])!=set(r05[key][R10_PAIR]):raise ValueError(f'R05 {key} ID 與旗標不符。')
    date=pd.to_datetime(pairs.Hb_Date,format='mixed',errors='coerce')
    nonempty=pairs.Hb_Date.notna()&pairs.Hb_Date.astype(str).str.strip().ne('')
    if (nonempty&date.isna()).any() or not date.notna().any():raise ValueError('Hb 日期不可解析或全部缺失，未自行忽略。')
    pairs['Hb_report_day']=date.dt.normalize()
    metadata=r09['metadata']
    if (pairs.Hb_report_day.min()!=pd.Timestamp(metadata['Research_Hb_date_min'])
        or pairs.Hb_report_day.max()!=pd.Timestamp(metadata['Research_Hb_date_max'])
        or date.notna().sum()!=metadata['Master_rows_with_Hb_date']):
        raise ValueError('R05 日期範圍／可評估列數與 R09 不符；請先同步上游。')
    first,last=pd.Timestamp(metadata['File_date_min']),pd.Timestamp(metadata['File_date_max'])
    candidates=r09['daily_candidates']
    if not candidates:raise ValueError('R09 沒有明確日摘要候選。')
    for h,c in candidates.items():
        cols=R10_DAILY+['Minimum_hours','All_daily_fields_available','Joint_valid_hours','Weather_version']
        if set(cols)-set(c):raise ValueError(f'R09 {h}h 缺少必要日摘要欄位。')
        if not c.index.equals(pd.date_range(first,last,name=c.index.name)) or not c.index.is_unique:
            raise ValueError(f'R09 {h}h 日曆不連續、日期範圍不同或有重複日期。')
        if not c.Minimum_hours.eq(h).all():raise ValueError('R09 候選小時門檻標籤不一致。')
        a=c[R10_DAILY].to_numpy(dtype=float)
        if np.isinf(a).any():raise ValueError('日摘要含無限值，不靜默轉成缺失。')
        valid=c[R10_DAILY].notna().all(axis=1)
        if not np.array_equal(valid,c.All_daily_fields_available) or not np.array_equal(valid,c.Joint_valid_hours.ge(h)):
            raise ValueError('日摘要可用性與共同有效小時旗標不符。')
        if not c.Weather_version.eq('station_hour_intersection_calendar_daily_v1').all():raise ValueError('不是本次 R09 的日摘要版本。')
    return pairs,first,last


def r10_build(daily,h,first,last,first_hb,last_hb,fraction,hot_threshold):
    # 內部多補 max(W)-1 個空日，讓每個輸出日期的視窗都有精確 W 個日曆位置。
    target_start=min(first,first_hb);target_end=max(last,last_hb)
    calc=pd.date_range(target_start-pd.Timedelta(days=max(R10_WINDOWS)-1),target_end,freq='D',name='日期')
    keep=pd.date_range(target_start,target_end,freq='D',name='日期')
    values=daily[R10_DAILY].reindex(calc)
    joint=values.notna().all(axis=1)
    values=values.where(joint,axis=0)  # 所有窗格平均及 SD 均使用同一批合格日期。
    in_source=pd.Series((calc>=first)&(calc<=last),index=calc)
    feature=pd.DataFrame(index=calc)
    feature['Window_end_day']=calc
    feature['Link_day_inside_source']=in_source
    feature['Minimum_hours']=h
    feature['Daily_joint_valid']=joint
    # 三態：有效且熱=1；有效且未達界值=0；THI 缺失=NaN。
    hot=values.THI_daily.ge(hot_threshold).where(joint).astype(float)
    feature['Daily_hot_indicator']=hot
    for W in R10_WINDOWS:
        minimum=int(np.ceil(W*fraction))
        rolling=lambda s,n=1:s.rolling(f'{W}D',closed='right',min_periods=n)
        start=pd.Series(calc-pd.Timedelta(days=W-1),index=calc)
        count=rolling(joint.astype(int)).sum().astype(int)
        source_count=rolling(in_source.astype(int)).sum().astype(int)
        geometric=source_count.eq(W)
        pass_window=in_source&geometric&count.ge(minimum)
        feature[f'Window_start_{W}d']=start
        feature[f'Required_valid_days_{W}d']=minimum
        feature[f'Valid_days_{W}d']=count
        feature[f'Valid_fraction_{W}d']=count/W
        feature[f'Source_span_days_{W}d']=source_count
        feature[f'Outside_source_days_{W}d']=W-source_count
        feature[f'Missing_within_source_days_{W}d']=source_count-count
        feature[f'Window_starts_before_source_{W}d']=start.lt(first)
        feature[f'Insufficient_valid_days_{W}d']=count.lt(minimum)
        feature[f'Window_ready_{W}d']=pass_window
        feature[f'Window_complete_{W}d']=in_source&geometric&count.eq(W)
        feature[f'Window_status_{W}d']=np.select([~in_source,start.lt(first),count.lt(minimum)],
            ['link_date_outside_source','window_starts_before_source','insufficient_valid_days'],default='available')
        if W in (30,180):
            for src,dst in [('T_daily_mean','T_mean'),('RH_daily_mean','RH_mean')]:
                feature[f'{dst}_{W}d']=rolling(values[src],minimum).mean().where(pass_window)
            tm,rm=feature[f'T_mean_{W}d'],feature[f'RH_mean_{W}d']
            feature[f'THI_mean_{W}d']=tm-.55*(1-rm/100)*(tm-14.4)
        if W==30:
            feature['DTR_mean_30d']=rolling(values.DTR_daily,minimum).mean().where(pass_window)
            feature['THI_std_30d']=rolling(values.THI_daily,minimum).std(ddof=1).where(pass_window)
            feature['T_std_30d']=rolling(values.T_daily_mean,minimum).std(ddof=1).where(pass_window)
        if W==365:
            observed=rolling(hot).sum()  # 沒有任何有效 THI 的視窗仍是 NaN，不會變成 0。
            feature['Hot_days_observed_365d_unqualified']=observed
            feature['THI_hot_days_365d_observed']=observed.where(pass_window)
            feature['THI_hot_fraction_365d']=(observed/count.replace(0,np.nan)).where(pass_window)
            feature['THI_hot_days_365d_complete']=observed.where(feature.Window_complete_365d)
    feature['THI_Trend_Shock']=feature.THI_mean_30d-feature.THI_mean_180d
    feature['Short30_features_ready']=feature[R10_SHORT].notna().all(axis=1)
    feature['Original_six_feature_names_ready']=feature[R10_LEGACY_SIX].notna().all(axis=1)
    feature['Secondary_frequency_bundle_ready']=feature.Short30_features_ready&feature.Window_ready_180d&feature.Window_ready_365d
    feature['Secondary_complete_count_bundle_ready']=feature.Short30_features_ready&feature.Window_ready_180d&feature.Window_complete_365d
    feature['Weather_version']=R10_VERSION
    return feature.loc[keep]


def r10_link(pairs,features):
    aligned=features.reindex(pd.DatetimeIndex(pairs.Hb_report_day)).reset_index(drop=True)
    linked=pd.concat([pairs.reset_index(drop=True),aligned],axis=1)
    no_date=linked.Hb_report_day.isna()
    for W in R10_WINDOWS:
        linked.loc[no_date,f'Window_status_{W}d']='no_evaluable_Hb_date'
    return linked


def r10_summaries(linked,h):
    availability,reasons,bundles,heat,distributions=[],[],[],[],[]
    masks={'Master':pd.Series(True,index=linked.index),'Current_repeated':linked.is_included_sensitivity,
           'Current_primary':linked.is_included_primary}
    for scope,mask in masks.items():
        d=linked.loc[mask]
        bundles.append({'Minimum_hours':h,'Cohort':scope,'Current_rows':len(d),'Current_patients':d[R10_PID].nunique(),
            'Short30_ready_rows':int(d.Short30_features_ready.eq(True).sum()),
            'Original_six_names_ready_rows':int(d.Original_six_feature_names_ready.eq(True).sum()),
            'Secondary_frequency_ready_rows':int(d.Secondary_frequency_bundle_ready.eq(True).sum()),
            'Secondary_complete_count_ready_rows':int(d.Secondary_complete_count_bundle_ready.eq(True).sum())})
        for W in R10_WINDOWS:
            ok=d[f'Window_ready_{W}d'].eq(True);valid=d[f'Valid_days_{W}d'].dropna()
            required=int(linked[f'Required_valid_days_{W}d'].dropna().iloc[0])
            availability.append({'Minimum_hours':h,'Cohort':scope,'Window_days':W,'Required_valid_days':required,
                'Current_rows':len(d),'Rows_with_Hb_date':int(d.Hb_report_day.notna().sum()),
                'Available_rows':int(ok.sum()),'Patients_with_available_rows':d.loc[ok,R10_PID].nunique(),
                'Unavailable_rows':int((~ok).sum()),'Complete_window_rows':int(d[f'Window_complete_{W}d'].eq(True).sum()),
                'Valid_days_min':valid.min(),'Valid_days_median':valid.median(),'Valid_days_max':valid.max()})
            for reason,part in d.groupby(f'Window_status_{W}d',dropna=False):
                reasons.append({'Minimum_hours':h,'Cohort':scope,'Window_days':W,'Reason':reason,
                                'Pairing_rows':len(part),'Patients':part[R10_PID].nunique()})
            counts=d.groupby(f'Valid_days_{W}d',dropna=False).size()
            distributions.extend({'Minimum_hours':h,'Cohort':scope,'Window_days':W,'Valid_days':n,'Pairing_rows':int(count)} for n,count in counts.items())
        if scope=='Current_primary':
            available=d.loc[d.Window_ready_365d.eq(True)]
            heat.append({'Minimum_hours':h,'Cohort':scope,'Current_rows':len(d),'Available_365d_rows':len(available),
                'Complete_365d_rows':int(d.Window_complete_365d.eq(True).sum()),
                'Available_but_missing_some_days_rows':int(available.Valid_days_365d.lt(365).sum()),
                'Valid_days_min_among_available':available.Valid_days_365d.min(),
                'Valid_days_max_among_available':available.Valid_days_365d.max(),
                'Observed_hot_days_mean':available.THI_hot_days_365d_observed.mean(),
                'Observed_day_hot_fraction_mean':available.THI_hot_fraction_365d.mean()})
    return {'window_availability':pd.DataFrame(availability),'window_reasons':pd.DataFrame(reasons),
            'bundle_availability':pd.DataFrame(bundles),'heat_365_summary':pd.DataFrame(heat),
            'valid_day_distribution':pd.DataFrame(distributions)}


def r10_legacy_compare(linked,legacy,h):
    fields=['THI_mean_30d','DTR_mean_30d','THI_std_30d','T_std_30d','THI_mean_180d','THI_Trend_Shock']
    if set(fields+['日期'])-set(legacy):raise ValueError('R05 weather_df 缺少明確指定的舊特徵，未換來源。')
    old=legacy[['日期']+fields].copy();old['日期']=pd.to_datetime(old['日期'],format='mixed',errors='raise')
    if old['日期'].isna().any() or old['日期'].duplicated().any():raise ValueError('舊氣象日期缺失／重複，不能多對多連結。')
    d=linked.loc[linked.is_included_primary].copy()
    aligned=old.set_index('日期').reindex(pd.DatetimeIndex(d.Hb_report_day)).reset_index(drop=True)
    rows=[]
    for field in fields:
        a=pd.to_numeric(aligned[field],errors='raise');b=d[field].reset_index(drop=True)
        both=a.notna()&b.notna();delta=b[both]-a[both]
        rows.append({'Minimum_hours':h,'Cohort':'Current_primary','Feature':field,'Current_rows':len(d),
            'Both_nonmissing_rows':int(both.sum()),'Missingness_mismatch_rows':int((a.isna()!=b.isna()).sum()),
            'Numeric_change_rows':int((~np.isclose(a[both],b[both],rtol=1e-10,atol=1e-10)).sum()),
            'Mean_new_minus_legacy':delta.mean(),'Max_absolute_difference':delta.abs().max()})
    return pd.DataFrame(rows)


def r10_run(r05,r09,out,fraction=R10_MIN_VALID_FRACTION,hot_threshold=R10_HOT_THRESHOLD):
    out=Path(out);out.mkdir(parents=True,exist_ok=False)
    tables,checks,weather,linked_all={},[],{},{}
    status={'Completed':False,'Exposure_candidates_ready':False,'Formal_weather_replaced':False,
            'Cohorts_changed':False,'Primary_reselected':False,'Models_updated':False,'Formal_tables_replaced':False}
    def check(name,ok):
        checks.append({'Check':name,'Passed':bool(ok)})
        if not ok:raise ValueError('R10 驗證失敗：'+name)
    try:
        check('Valid_minimum_day_fraction',0<fraction<=1 and int(np.ceil(min(R10_WINDOWS)*fraction))>=2 and np.isfinite(hot_threshold))
        pairs,first,last=r10_prepare(r05,r09)
        original_master=r05['row_flags'].copy(deep=True);original_weather=r05['weather_df'].copy(deep=True)
        originals={h:c.copy(deep=True) for h,c in r09['daily_candidates'].items()}
        checks.extend({'Check':s,'Passed':True} for s in ['Explicit_completed_R05_R09_inputs',
            'Pair_IDs_unique_and_current_cohort_flags_match','Hb_dates_match_R09_scope','Every_R09_candidate_has_complete_calendar_and_joint_day_flags'])
        first_hb,last_hb=pairs.Hb_report_day.min(),pairs.Hb_report_day.max()
        settings=[('Weather_source_start',str(first.date())),('Weather_source_end',str(last.date())),
            ('Master_Hb_report_start',str(first_hb.date())),('Master_Hb_report_end',str(last_hb.date())),
            ('Earliest_required_365d_start',str((first_hb-pd.Timedelta(days=max(R10_WINDOWS)-1)).date())),
            ('Earliest_365d_start_inside_source_span',first_hb-pd.Timedelta(days=max(R10_WINDOWS)-1)>=first),
            ('Window_includes_Hb_report_day',True),('Minimum_valid_day_fraction',fraction),
            ('Hot_THI_threshold',hot_threshold),('Hour_candidates',','.join(str(h) for h in sorted(originals))),
            ('Master_pairing_rows',len(pairs)),('Master_rows_without_Hb_date',int(pairs.Hb_report_day.isna().sum())),
            ('Master_rows_with_Hb_date_outside_source',int((pairs.Hb_report_day.lt(first)|pairs.Hb_report_day.gt(last)).sum()))]
        tables['settings_and_periods']=pd.DataFrame(settings,columns=['Metric','Value'])
        combined={};legacy_tables=[];earliest=[];daily_hot_audit=[]
        for h,daily in originals.items():
            f=r10_build(daily,h,first,last,first_hb,last_hb,fraction,hot_threshold)
            linked=r10_link(pairs,f);weather[h]=f;linked_all[h]=linked
            summaries=r10_summaries(linked,h)
            for key,table in summaries.items():combined.setdefault(key,[]).append(table)
            legacy_tables.append(r10_legacy_compare(linked,original_weather,h))
            earliest.append({'Minimum_hours':h,'Hb_report_day':str(first_hb.date()),
                'Window_start_365d':str(f.loc[first_hb,'Window_start_365d'].date()),
                'Valid_days_365d':int(f.loc[first_hb,'Valid_days_365d']),
                'Required_valid_days_365d':int(f.loc[first_hb,'Required_valid_days_365d']),
                'Outside_source_days_365d':int(f.loc[first_hb,'Outside_source_days_365d']),
                'Window_status_365d':f.loc[first_hb,'Window_status_365d']})
            daily_hot_audit.append({'Minimum_hours':h,'Feature_calendar_days':len(f),
                'Valid_THI_days':int(f.Daily_joint_valid.sum()),'Missing_THI_indicator_days':int(f.Daily_hot_indicator.isna().sum()),
                'Observed_nonhot_days':int(f.Daily_hot_indicator.eq(0).sum()),'Observed_hot_days':int(f.Daily_hot_indicator.eq(1).sum())})
            check(f'{h}h_link_preserves_master_ID_order',linked[R10_PAIR].tolist()==pairs[R10_PAIR].tolist() and len(linked)==len(pairs))
            check(f'{h}h_missing_THI_not_false',np.array_equal(f.Daily_hot_indicator.isna(),~f.Daily_joint_valid))
            for W in R10_WINDOWS:
                check(f'{h}h_{W}d_exact_window_boundaries',(f.Window_end_day-f[f'Window_start_{W}d']).dt.days.eq(W-1).all())
                check(f'{h}h_{W}d_missing_day_partition',f[f'Valid_days_{W}d'].add(f[f'Missing_within_source_days_{W}d']).add(f[f'Outside_source_days_{W}d']).eq(W).all())
                check(f'{h}h_{W}d_reason_matches_eligibility',np.array_equal(f[f'Window_status_{W}d'].eq('available'),f[f'Window_ready_{W}d']))
                check(f'{h}h_{W}d_no_extrapolation',not f.loc[~f.Link_day_inside_source,f'Window_ready_{W}d'].any())
            check(f'{h}h_short_features_match_30d_flag',np.array_equal(f.Short30_features_ready,f.Window_ready_30d))
            complete=f.Window_complete_365d
            check(f'{h}h_complete_heat_count_requires_all_365_days',np.array_equal(f.THI_hot_days_365d_complete.notna(),complete))
            qualified=f.Window_ready_365d
            check(f'{h}h_heat_counts_have_explicit_valid_denominator',f.loc[qualified,'THI_hot_days_365d_observed'].between(0,f.loc[qualified,'Valid_days_365d']).all()
                  and f.loc[qualified,'THI_hot_fraction_365d'].between(0,1).all())
            for scope,part in summaries['window_availability'].groupby('Cohort'):
                check(f'{h}h_{scope}_available_plus_unavailable',part.Available_rows.add(part.Unavailable_rows).eq(part.Current_rows).all())
                for W,n in zip(part.Window_days,part.Current_rows):
                    r=summaries['window_reasons'].query('Cohort==@scope and Window_days==@W')
                    check(f'{h}h_{scope}_{W}d_reasons_partition_rows',int(r.Pairing_rows.sum())==n)
            pd.testing.assert_frame_equal(daily,r09['daily_candidates'][h])
            check(f'{h}h_R09_daily_input_unchanged',True)
            f.to_csv(out/f'calendar_features_{h}h_candidate.csv',index=True,encoding='utf-8-sig')
            linked.to_csv(out/f'pairing_window_audit_{h}h_PRIVATE.csv',index=False,encoding='utf-8-sig')
        tables.update({key:pd.concat(parts,ignore_index=True) for key,parts in combined.items()})
        tables['legacy_primary_comparison']=pd.concat(legacy_tables,ignore_index=True)
        tables['earliest_Hb_365d_check']=pd.DataFrame(earliest);tables['daily_heat_indicator_audit']=pd.DataFrame(daily_hot_audit)
        pd.testing.assert_frame_equal(original_master,r05['row_flags']);pd.testing.assert_frame_equal(original_weather,r05['weather_df'])
        check('R05_master_and_legacy_weather_unchanged',True)
        specification={'Base_notebook':'self-contained analysis implementation','Reviewer':'R1 Major 4','Version':R10_VERSION,
            'Input':'R09.daily_candidates and R05.row_flags; no source guessing or fallback',
            'R09_source_sha256':r09['metadata']['SHA256'],'Windows_days':list(R10_WINDOWS),
            'Window_interval':'[Hb_report_day-(W-1) days, Hb_report_day]; includes report calendar day',
            'Minimum_valid_fraction':fraction,'Required_days':{W:int(np.ceil(W*fraction)) for W in R10_WINDOWS},
            'Minimum_rule_rationale':'Extends manuscript strict 27/30 valid-day criterion to 180/365 days; not a validated physiologic cutoff',
            'Full_source_span_required':True,'Endpoint_rule':'Out-of-file Hb dates stay in audit and get no qualified exposure',
            'Same_day_missing_observation':'Inside-file endpoint may have missing daily weather; qualify only if whole-window criteria pass',
            'Common_valid_days':'T, RH, daily THI and DTR all available; DTR within each retained day uses all valid T hours from R09',
            'THI_mean_formula':'THI of window-mean T and window-mean RH, preserving original formula; NOT mean of daily THI',
            'SD_formula':'SD of joint-valid daily THI or temperature, ddof=1',
            'Hot_indicator':'1 for observed THI >= threshold, 0 for observed below threshold, NaN for missing THI',
            'Hot_threshold':hot_threshold,'Observed_hot_count':'Count among actually valid days; not a complete-year count',
            'Hot_fraction':'Observed hot count / valid days; no annualization or imputation',
            'Complete_year_hot_count':'Only available when all 365 days valid and within file span',
            'Legacy_THI_hot_days_365d_alias_created':False,
            'Availability_scope':'Current cohort records without reselecting representatives; not final revised cohort sizes',
            'Reasons':'Mutually exclusive per row/window; patients may appear under multiple row-level reasons',
            'Formal_weather_replaced':False,'Cohorts_changed':False,'Models_updated':False,
            'Software':{'numpy':np.__version__,'pandas':pd.__version__}}
        (out/'analysis_specification.json').write_text(json.dumps(specification,ensure_ascii=False,indent=2),encoding='utf-8')
        status.update(Completed=True,Exposure_candidates_ready=True,Hour_candidates=len(weather),
                      Long_windows_reconstructed=True,Age_values_changed=False)
        for title,table in [('1 設定與回溯期間',tables['settings_and_periods']),
            ('2 各視窗有效日數與目前世代可用列',tables['window_availability']),
            ('3 視窗不足原因',tables['window_reasons'].query("Reason!='available'")),
            ('4 熱日缺失與分母',tables['heat_365_summary']),('5 新暴露完整度與舊版比較',tables['bundle_availability'])]:
            print(f'\n=== 請回傳：R10 {title} ===');print(table.to_string(index=False,float_format=lambda v:f'{v:.8g}'))
            if title.startswith('1 '):print(tables['earliest_Hb_365d_check'].to_string(index=False))
            if title.startswith('4 '):print(tables['daily_heat_indicator_audit'].to_string(index=False))
            if title.startswith('5 '):print(tables['legacy_primary_comparison'].to_string(index=False,float_format=lambda v:f'{v:.8g}'))
        print('\n=== 請回傳：R10 6 驗證與狀態 ===')
        print(pd.DataFrame([{'Checks':len(checks),'All_passed':all(c['Passed'] for c in checks),**status}]).to_string(index=False))
        print(f'\n輸出位置：{out}')

        return {'Completed':True,'weather_candidates':weather,'linked_candidates':linked_all,
                'tables':tables,'status':status,'output_dir':str(out)}
    except Exception as exc:
        status.update(Error_type=type(exc).__name__,Error=str(exc))
        print(f'R10 未完成；已有診斷保留於 {out}，不改用舊氣象或舊結果。')
        raise
    finally:
        for name,table in tables.items():table.to_csv(out/(name+'.csv'),index=False,encoding='utf-8-sig')
        pd.DataFrame(checks,columns=['Check','Passed']).to_csv(out/'validation.csv',index=False,encoding='utf-8-sig')
        (out/'run_status.json').write_text(json.dumps(status,ensure_ascii=False,indent=2),encoding='utf-8')


R10=None
if any(name not in globals() for name in ['R05','R09','folder_path']):
    raise NameError('請先完成前置步驟（R05 7A）與前置步驟（R09 程式）。')
_r10_out=Path(folder_path)/'Revision_R10_Calendar_Windows'/(
    datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')+'_'+uuid.uuid4().hex[:8])
R10=r10_run(R05,R09,_r10_out)

"""## Primary models using reconstructed weather

Input objects are produced by preceding cells in this notebook. Outputs remain private working artifacts until the publication export section.

"""

from pathlib import Path
from datetime import datetime, timezone
import contextlib
import json
import uuid
import warnings
import numpy as np
import pandas as pd
import patsy
import statsmodels
import statsmodels.api as sm

R11_HOURS=(18,20,24)          # 事先明列的 R09/R10 小時門檻候選，不依模型結果選門檻。
R11_B=1000
R11_SPANS=(30,60,90)         # 沿用 R08 的日曆相依範圍，非氣象視窗長度。
R11_SEED=42
R11_ALPHA=.05
R11_MAX_LAG=180
R11_DTR_BOUNDS=(0.,25.)      # 沿用 R05 的研究 QC 條件，不是從本次資料極值推估。
R11_PID,R11_PAIR,R11_DXA='去個資編號','pairing_row_id','骨密度檢查執行日期'
R11_SIX=['T_mean_30d','DTR_mean_30d','RH_mean_30d','THI_mean_30d','THI_std_30d','THI_Trend_Shock']
R11_CLINICAL=['Age','sex_bin','Hb_Value','overall_T']
R11_CLOCKS=(('A','Hb_report','Hb_Date'),('B','DXA',R11_DXA),('B','Hb_report','Hb_Date'))
R11_NEW_VERSION='calendar_windows_joint_days_90pct_v1'


def r11_require(ok,message):
    if not bool(ok):raise ValueError(message)


def r11_prepare(r05,r08,r10,alpha):
    for name,obj in [('R05',r05),('R08',r08),('R10',r10)]:
        r11_require(isinstance(obj,dict) and obj.get('Completed',False),f'{name} 未完成；不能用舊資料替代。')
    p=r05['df_primary'];master=r05['row_flags']
    cols=[R11_PAIR,R11_PID,R11_DXA,'Hb_Date']+R11_CLINICAL+R11_SIX
    r11_require(not p.empty and p.columns.is_unique and not (set(cols)-set(p)),'R05 Primary 為空或缺少必要欄位。')
    r11_require(p[[R11_PAIR,R11_PID]].notna().all().all() and p[R11_PAIR].is_unique and p[R11_PID].is_unique,
                'Primary 必須一人一列，配對 ID 與病人 ID 不得缺失／重複。')
    r11_require(master[R11_PAIR].notna().all() and master[R11_PAIR].is_unique,'R05 母體配對 ID 無效。')
    r11_require(set(p[R11_PAIR])==set(master.loc[master.is_included_primary,R11_PAIR]),'Primary ID 與 R05 旗標不符。')
    pd.testing.assert_frame_equal(p.set_index(R11_PAIR)[cols[1:]],
        master.set_index(R11_PAIR).loc[p[R11_PAIR],cols[1:]],check_dtype=False)
    d=p[cols].copy(deep=True).reset_index(drop=True)
    d[R11_CLINICAL+R11_SIX]=d[R11_CLINICAL+R11_SIX].apply(pd.to_numeric,errors='raise').astype(float)
    r11_require(np.isfinite(d[R11_CLINICAL+R11_SIX]).all().all(),'舊 Primary 模型欄位缺失／非有限；不自動刪列。')
    for prefix,col in [('hb','Hb_Date'),('dxa',R11_DXA)]:
        d[col]=pd.to_datetime(d[col],format='mixed',errors='raise')
        r11_require(d[col].notna().all(),f'{col} 缺失。')
        d[prefix+'_year']=d[col].dt.year.astype(int)
        d[prefix+'_sin']=np.sin(2*np.pi*d[col].dt.month/12)
        d[prefix+'_cos']=np.cos(2*np.pi*d[col].dt.month/12)
    templates,baseline,specs={ },[],[]
    oldspec=r08['tables']['model_specifications'].set_index('Model',verify_integrity=True)
    for name,target,outcome,prefix in [('A','THI_mean_30d','Hb_Value','hb'),('B','Hb_Value','overall_T','dxa')]:
        reference=int(d[prefix+'_year'].min())
        predictors=('THI_mean_30d + DTR_mean_30d + Age + sex_bin' if name=='A' else
                    'Hb_Value + THI_mean_30d + DTR_mean_30d + Age + sex_bin')
        formula=f'{outcome} ~ {predictors} + {prefix}_sin + {prefix}_cos + C({prefix}_year, Treatment(reference={reference}))'
        r11_require(oldspec.loc[name,'Formula']==formula,f'Model {name} 公式與已完成 R08 不符。')
        y,X=patsy.dmatrices(formula,d,return_type='dataframe',NA_action='raise',eval_env=-1)
        old=r08['models'][name]
        r11_require(list(X)==list(old['X']) and np.array_equal(y.iloc[:,0],old['y'])
            and X.shape==old['X'].shape and np.allclose(X,old['X'],rtol=1e-12,atol=1e-12),
            f'Model {name} 舊版資料／列序與 R08 不符；不能比較不同上游版本。')
        j=list(X).index(target)
        r11_require(old['target']==target and old['j']==j,'R08 目標係數索引不符。')
        r11_require(np.array_equal(old['fit'].model.endog,y.iloc[:,0])
            and np.allclose(old['fit'].model.exog,X,rtol=1e-12,atol=1e-12),'R08 配適物件與設計資料不符。')
        templates[name]={'X_info':X.design_info,'y_info':y.design_info,'formula':formula,'target':target,'j':j}
        # 同一設計重新計算 HC3 核對；不重跑已完成的 R08 拔靴法。
        current=old['fit'].get_robustcov_results(cov_type='HC3',use_t=False)
        for metric,a,b in [('Beta',current.params[j],old['hc3'].params[j]),('HC3_SE',current.bse[j],old['hc3'].bse[j]),
            ('CI_low',current.conf_int(alpha)[j,0],old['hc3'].conf_int(alpha)[j,0]),
            ('CI_high',current.conf_int(alpha)[j,1],old['hc3'].conf_int(alpha)[j,1]),('P',current.pvalues[j],old['hc3'].pvalues[j])]:
            baseline.append({'Model':name,'Metric':metric,'R08':float(b),'Current':float(a),
                             'Matches':bool(np.isclose(a,b,rtol=1e-8,atol=1e-10))})
        specs.append({'Model':name,'Target':target,'Formula':formula,'Reference_year':reference,
            'Calendar_adjustment_date':'Hb_report' if name=='A' else 'DXA','Design_columns':X.shape[1]})
    r11_require(all(x['Matches'] for x in baseline),'R08 原主分析未重現。')
    r11_require(set(r10['linked_candidates'])==set(R11_HOURS) and set(r10['weather_candidates'])==set(R11_HOURS),
                'R10 必須明確提供 18／20／24 小時的全部候選。')
    cases={};retention=[];reason_tables=[];members=[]
    for h in R11_HOURS:
        linked=r10['linked_candidates'][h]
        r11_require(linked[R11_PAIR].notna().all() and linked[R11_PAIR].is_unique
            and set(linked[R11_PAIR])==set(master[R11_PAIR]),f'{h}h R10 母體 ID 與 R05 不符。')
        r11_require(set(linked.loc[linked.is_included_primary,R11_PAIR])==set(d[R11_PAIR]),f'{h}h R10 Primary 旗標不符。')
        q=linked.set_index(R11_PAIR).loc[d[R11_PAIR]].reset_index()
        r11_require(np.array_equal(q[R11_PID],d[R11_PID]) and
            np.array_equal(pd.to_datetime(q.Hb_Date,format='mixed'),d.Hb_Date) and
            np.array_equal(pd.to_datetime(q.Hb_report_day),d.Hb_Date.dt.normalize()),f'{h}h 日期／病人對應不符。')
        r11_require(q.Minimum_hours.eq(h).all() and q.Weather_version.eq(R11_NEW_VERSION).all(),'R10 氣象版本標記不符。')
        new=q[R11_SIX].apply(pd.to_numeric,errors='raise').astype(float)
        r11_require(not np.isinf(new.to_numpy()).any(),'R10 特徵含無限值，未視為一般缺失。')
        feature=r10['weather_candidates'][h]
        r11_require(feature.index.is_unique,'R10 日曆特徵日期重複。')
        aligned=feature.reindex(pd.DatetimeIndex(q.Hb_report_day))[R11_SIX].reset_index(drop=True)
        pd.testing.assert_frame_equal(new,aligned.astype(float),check_dtype=False)
        complete=new.notna().all(axis=1)
        r11_require(np.array_equal(complete,q.Original_six_feature_names_ready.eq(True)) and
            np.array_equal(complete,q.Window_ready_30d.eq(True)&q.Window_ready_180d.eq(True)),
            f'{h}h R10 六欄完整度與視窗旗標不符。')
        expected=r10['tables']['bundle_availability'].query('Minimum_hours==@h and Cohort=="Current_primary"')
        r11_require(len(expected)==1 and int(expected.Current_rows.iloc[0])==len(d) and
            int(expected.Original_six_names_ready_rows.iloc[0])==int(complete.sum()),'R10 已報摘要與目前連結資料不符。')
        dtr_ok=new.DTR_mean_30d.between(*R11_DTR_BOUNDS)
        keep=complete&dtr_ok
        r11_require(keep.any(),f'{h}h 沒有合格 Primary 列；停止而非退回舊世代。')
        old=d.loc[keep].copy().reset_index(drop=True);changed=old.copy(deep=True)
        changed[R11_SIX]=new.loc[keep].reset_index(drop=True)
        pd.testing.assert_frame_equal(old.drop(columns=R11_SIX),changed.drop(columns=R11_SIX))
        for kind,frame in [('legacy',old),('calendar',changed)]:
            cases[f'H{h}_{kind}']={'data':frame,'Hours':h,'Weather':kind}
        retention.append({'Minimum_hours':h,'Original_primary_rows':len(d),'Six_features_complete':int(complete.sum()),
            'Incomplete_weather_rows':int((~complete).sum()),'DTR_outside_range_after_completeness':int((complete&~dtr_ok).sum()),
            'Retained_rows':int(keep.sum()),'Retained_patients':old[R11_PID].nunique(),
            'Excluded_rows':int((~keep).sum()),'Retention_percent':100*keep.mean(),
            'Old_new_same_ID_order':old[R11_PAIR].tolist()==changed[R11_PAIR].tolist()})
        reason=np.select([~q.Window_ready_30d.eq(True),~q.Window_ready_180d.eq(True),~dtr_ok],
            ['30d_window_not_ready','180d_window_not_ready','DTR_outside_range'],default='retained')
        counts=pd.Series(reason).value_counts().rename_axis('Reason').reset_index(name='Rows');counts.insert(0,'Minimum_hours',h)
        reason_tables.append(counts)
        members.append(pd.DataFrame({'Minimum_hours':h,R11_PAIR:d[R11_PAIR],R11_PID:d[R11_PID],
                                    'Retained':keep,'Reason':reason}))
    return d,templates,cases,pd.DataFrame(specs),pd.DataFrame(baseline),pd.DataFrame(retention),pd.concat(reason_tables),pd.concat(members)


def r11_fit(data,template):
    y,X=patsy.build_design_matrices([template['y_info'],template['X_info']],data,NA_action='raise',return_type='dataframe')
    r11_require(len(X)==len(data) and len(X)>X.shape[1] and np.isfinite(X).all().all()
        and np.linalg.matrix_rank(X)==X.shape[1], '子集設計有缺失或不滿秩；不刪年份調整項或改用其他模型。')
    fit=sm.OLS(y.iloc[:,0],X,missing='raise').fit()
    hc3=fit.get_robustcov_results(cov_type='HC3',use_t=False)
    r11_require(np.isfinite(hc3.params).all() and np.isfinite(hc3.bse).all() and (hc3.bse>0).all(),
                'HC3 配適非有限或 SE 無效。')
    return {'fit':fit,'hc3':hc3,'target':template['target'],'j':template['j'],'X':X,'y':y.iloc[:,0].to_numpy()}


def r11_result(case,h,weather,name,m,clock,method,se,lo,hi,p=np.nan,span=np.nan,origin='R11_refit'):
    return {'Case':case,'Minimum_hours':h,'Weather':weather,'Model':name,'Target':m['target'],
        'Dependence_clock':clock,'Method':method,'Span_calendar_days':span,'Rows':len(m['y']),
        'Beta':float(np.asarray(m['fit'].params)[m['j']]),'SE':float(se),'CI_low':float(lo),'CI_high':float(hi),
        'P':float(p),'CI_includes_zero':bool(lo<=0<=hi),'Result_origin':origin}


def r11_run(r05,r08,r10,out,calendar_fn,bootstrap_fn,B=R11_B,spans=R11_SPANS,seed=R11_SEED,alpha=R11_ALPHA,max_lag=R11_MAX_LAG):
    out=Path(out);out.mkdir(parents=True,exist_ok=False)
    tables,checks,models={ },[],{}
    status={'Completed':False,'Sensitivity_models_updated':False,'Original_cohorts_changed':False,
            'Primary_reselected':False,'Formal_weather_replaced':False,'Formal_tables_replaced':False}
    warning_log=[]
    def check(label,ok):
        checks.append({'Check':label,'Passed':bool(ok)})
        r11_require(ok,'R11 驗證失敗：'+label)
    def tag(frame,case,h,weather):
        frame=frame.copy();frame.insert(0,'Weather',weather);frame.insert(0,'Minimum_hours',h);frame.insert(0,'Case',case)
        return frame
    try:
        check('Configuration_valid',isinstance(B,int) and B>=2 and isinstance(seed,int) and seed>=0 and 0<alpha<1
              and len(set(spans))==len(spans)>0 and all(isinstance(s,int) and s>0 for s in spans)
              and isinstance(max_lag,int) and max_lag>0 and callable(calendar_fn) and callable(bootstrap_fn))
        d,templates,cases,specs,baseline,retention,reasons,membership=r11_prepare(r05,r08,r10,alpha)
        original=r05['df_primary'].copy(deep=True);master_before=r05['row_flags'].copy(deep=True)
        linked_before={h:c.copy(deep=True) for h,c in r10['linked_candidates'].items()}
        weather_before={h:c.copy(deep=True) for h,c in r10['weather_candidates'].items()}
        tables.update(model_specifications=specs,R08_baseline_check=baseline,subset_retention=retention,subset_reasons=reasons)
        membership.to_csv(out/'subset_membership_PRIVATE.csv',index=False,encoding='utf-8-sig')
        checks.extend({'Check':s,'Passed':True} for s in ['R05_R08_R10_explicit_completed_sources',
            'R08_original_design_and_outcomes_reproduced','Primary_one_row_per_patient',
            'R10_ID_date_value_and_version_alignment','Same_subset_ID_order_and_nonweather_values_preserved'])
        # 原完整世代結果明確取自已完成 R08，先核對模型與表格，避免重跑同一拔靴法。
        full=r08['tables']['S10_R08_candidate'].copy()
        for name in templates:
            m=r08['models'][name];hc3=m['hc3'];j=m['j']
            q=full.query('Model==@name and Method=="HC3_normal_Wald"')
            check(name+'_R08_result_table_matches_model',len(q)==1 and np.allclose(
                q[['Beta','SE','CI_low','CI_high','P']].iloc[0].to_numpy(dtype=float),
                [hc3.params[j],hc3.bse[j],*hc3.conf_int(alpha)[j],hc3.pvalues[j]],rtol=1e-8,atol=1e-10))
            check(name+'_R08_all_inference_rows_same_current_estimate',
                full.loc[full.Model.eq(name),'Rows'].eq(len(d)).all() and np.allclose(
                    full.loc[full.Model.eq(name),'Beta'],hc3.params[j],rtol=1e-10,atol=1e-12))
        full['Case']='Full_legacy';full['Minimum_hours']=np.nan;full['Weather']='legacy'
        full['Result_origin']='R08_verified_existing'

        comparisons=full.to_dict('records');denominators=[];diagnostics=[];summaries=[];crosschecks=[];designs=[]
        specification={'Base_notebook':'self-contained analysis implementation','Reviewers':['R1 Major 4','R1 Major 3','R2-1'],
            'Primary_rule':'Hold R05 one-record-per-patient choices fixed; no reselection',
            'Subset_rule':'R10 original six weather fields complete (30d and 180d) AND DTR in inherited [0,25]; no 365d requirement',
            'Comparisons':'Full legacy; legacy restricted to retained IDs; reconstructed weather on the identical retained IDs',
            'Age_outcome_clinical_calendar_covariates':'Unchanged; R08 formulas and full-primary design columns frozen',
            'Hourly_candidates':list(R11_HOURS),'Weather_version':R11_NEW_VERSION,
            'Baseline':'Existing R08 model/results after design, outcome, coefficient and HC3 CI checks',
            'Inference':'HC3 normal Wald; exact-date CR1 cluster t(G-1); R08 fixed-design Gaussian calendar DWB basic CI',
            'DWB_functions':'Call existing r08_calendar and r08_bootstrap; no patient/case bootstrap substitution',
            'DWB_covariance':'Bartlett: max(1-abs(calendar_lag)/span,0); same day shares multiplier; full calendar, no wrap',
            'DWB_residual_scaling':'sqrt(N/(N-p)); identical R08 HC1 scaling',
            'Spans_days':list(spans),'B_per_stream':B,'Seed':seed,'Alpha':alpha,
            'Clocks':{'A':['Hb_report'],'B':['DXA','Hb_report']},
            'Clock_limit':'Separate clock sensitivities, not a joint two-clock covariance model',
            'Coefficient_differences':'Descriptive differences only; no difference P, no subtraction of CI endpoints as a difference CI',
            'Failure_policy':'Every draw logged; any failed stream prevents completion, no extra replacement draws',
            'All_cases_reported':True,'No_threshold_selected_by_significance':True,
            'Original_cohorts_changed':False,'Formal_tables_replaced':False,
            'Software':{'numpy':np.__version__,'pandas':pd.__version__,'patsy':patsy.__version__,'statsmodels':statsmodels.__version__}}
        (out/'analysis_specification.json').write_text(json.dumps(specification,ensure_ascii=False,indent=2),encoding='utf-8')
        print(f'R11：{len(cases)} 個子集／氣象版本，各配適 Model A、B；R08 原完整世代結果已核對。',flush=True)
        for case,info in cases.items():
            data,h,weather=info['data'],info['Hours'],info['Weather'];models[case]={}
            subdir=out/case;subdir.mkdir()
            for name,template in templates.items():
                with warnings.catch_warnings(record=True) as caught:
                    warnings.simplefilter('always');m=r11_fit(data,template)
                warning_log.extend({'Case':case,'Model':name,'Stage':'OLS','Category':w.category.__name__,'Message':str(w.message)} for w in caught)
                check(case+'_'+name+'_no_numerical_fit_warning',not any(issubclass(w.category,RuntimeWarning) for w in caught))
                models[case][name]=m;hc3=m['hc3'];j=m['j']
                comparisons.append(r11_result(case,h,weather,name,m,'Not_applied','HC3_normal_Wald',
                    hc3.bse[j],*hc3.conf_int(alpha)[j],p=hc3.pvalues[j]))
                designs.append({'Case':case,'Minimum_hours':h,'Weather':weather,'Model':name,'Rows':len(data),
                    'Patients':data[R11_PID].nunique(),'Design_columns':m['X'].shape[1],
                    'Design_rank':np.linalg.matrix_rank(m['X']),'Age_mean':data.Age.mean(),'Age_SD':data.Age.std(),
                    'THI_mean':data.THI_mean_30d.mean(),'DTR_mean':data.DTR_mean_30d.mean()})
            if weather=='calendar':
                for name,m in models[case].items():
                    old=models[f'H{h}_legacy'][name]
                    keepcols=[col for col in m['X'] if col not in ['THI_mean_30d','DTR_mean_30d']]
                    check(case+'_'+name+'_only_weather_predictors_changed',np.array_equal(old['y'],m['y'])
                        and np.array_equal(old['X'][keepcols],m['X'][keepcols]))
            for name,clock,date_col in R11_CLOCKS:
                m=models[case][name];cal=calendar_fn(m,data[date_col],max_lag)
                check(case+'_'+name+'_'+clock+'_calendar_longer_than_span',len(cal['calendar'])>max(spans))
                denominators.append({'Case':case,'Minimum_hours':h,'Weather':weather,'Model':name,
                    'Dependence_clock':clock,'Rows':len(data),'Patients':data[R11_PID].nunique(),**cal['summary']})
                di=cal['diagnostics'].copy();di['Model']=name;di['Dependence_clock']=clock
                diagnostics.append(tag(di,case,h,weather))
                with warnings.catch_warnings(record=True) as caught:
                    warnings.simplefilter('always')
                    cluster=m['fit'].get_robustcov_results(cov_type='cluster',groups=cal['day_index'],
                        use_correction=True,df_correction=True,use_t=True)
                warning_log.extend({'Case':case,'Model':name,'Stage':clock+'_cluster','Category':w.category.__name__,'Message':str(w.message)} for w in caught)
                j=m['j'];G=cal['summary']['Observed_dates'];ci=cluster.conf_int(alpha)[j]
                check(case+'_'+name+'_'+clock+'_cluster_valid',G>1 and np.isfinite([cluster.bse[j],*ci,cluster.pvalues[j]]).all()
                      and cluster.bse[j]>0 and np.isclose(cluster.df_resid_inference,G-1))
                comparisons.append(r11_result(case,h,weather,name,m,clock,'Exact_date_cluster_t',
                    cluster.bse[j],*ci,p=cluster.pvalues[j]))
                for span in spans:
                    # 詳細 250 次進度保留在檔案；Colab 顯示每個 stream 的完成狀態。
                    with (subdir/'bootstrap_progress.log').open('a',encoding='utf-8') as log,contextlib.redirect_stdout(log):
                        draws,summary,cross=bootstrap_fn(m,cal,name,clock,span,B,seed,alpha,subdir)
                    summary={'Case':case,'Minimum_hours':h,'Weather':weather,**summary};summaries.append(summary)
                    crosschecks.append(tag(cross,case,h,weather))
                    tables['bootstrap_summary']=pd.DataFrame(summaries)
                    tables['first_draw_OLS_crosscheck']=pd.concat(crosschecks,ignore_index=True)
                    print(f'R11 {case} / {name} / {clock} / {span}d：成功 {summary["Succeeded"]}/{summary["Attempted"]}，失敗 {summary["Failed"]}。',flush=True)
                    check(case+'_'+name+'_'+clock+f'_{span}d_all_draws_valid',summary['All_requested_draws_succeeded']
                          and summary['Requested']==B and summary['Attempted']==B and summary['Succeeded']==B
                          and summary['Failed']==0 and len(draws)==B and cross.Matches.all())
                    check(case+'_'+name+'_'+clock+f'_{span}d_CI_finite',np.isfinite(
                        [summary['Bootstrap_SE'],summary['CI_low'],summary['CI_high']]).all() and summary['Bootstrap_SE']>0)
                    comparisons.append(r11_result(case,h,weather,name,m,clock,'DWB_basic_CI',summary['Bootstrap_SE'],
                        summary['CI_low'],summary['CI_high'],span=span))
        all_results=pd.DataFrame(comparisons)
        tables.update(inference_all=all_results,model_designs=pd.DataFrame(designs),calendar_denominators=pd.DataFrame(denominators),
                      calendar_lag_diagnostics=pd.concat(diagnostics,ignore_index=True))
        hc3=all_results.query('Method=="HC3_normal_Wald"').copy();tables['HC3_comparison']=hc3
        delta=[]
        for h in R11_HOURS:
            for name in templates:
                base=hc3.query('Case=="Full_legacy" and Model==@name').iloc[0]
                old=hc3.query('Case==@old_case and Model==@name',local_dict={'old_case':f'H{h}_legacy','name':name}).iloc[0]
                new=hc3.query('Case==@new_case and Model==@name',local_dict={'new_case':f'H{h}_calendar','name':name}).iloc[0]
                sample=float(old.Beta-base.Beta);exposure=float(new.Beta-old.Beta);total=float(new.Beta-base.Beta)
                check(f'{h}h_{name}_coefficient_differences_add_up',np.isclose(sample+exposure,total,rtol=1e-10,atol=1e-12))
                delta.append({'Minimum_hours':h,'Model':name,'Retained_rows':int(new.Rows),'Full_legacy_beta':base.Beta,
                    'Subset_legacy_beta':old.Beta,'Subset_calendar_beta':new.Beta,'Subset_minus_full_legacy':sample,
                    'Calendar_minus_legacy_same_rows':exposure,'Calendar_subset_minus_full_legacy':total})
        tables['descriptive_coefficient_changes']=pd.DataFrame(delta)
        dwb=all_results.query('Method=="DWB_basic_CI" and Case!="Full_legacy"')
        keys=['Minimum_hours','Model','Dependence_clock','Span_calendar_days','Rows']
        stats=['SE','CI_low','CI_high','CI_includes_zero']
        paired=dwb.query('Weather=="legacy"')[keys+stats].merge(
            dwb.query('Weather=="calendar"')[keys+stats],on=keys,suffixes=('_legacy','_calendar'),validate='one_to_one')
        check('Every_DWB_legacy_calendar_pair_present',len(paired)==len(R11_HOURS)*len(R11_CLOCKS)*len(spans))
        tables['DWB_same_rows_comparison']=paired
        boot=tables['bootstrap_summary']
        tables['bootstrap_counts_by_case']=boot.groupby(['Case','Minimum_hours','Weather'],sort=False).agg(
            Streams=('Attempted','size'),Requested=('Requested','sum'),Attempted=('Attempted','sum'),
            Succeeded=('Succeeded','sum'),Failed=('Failed','sum'),Rank_failed=('Rank_failed','sum'),
            Nonfinite_failed=('Nonfinite_failed','sum'),Refit_check_failed=('Refit_check_failed','sum'),Other_failed=('Other_failed','sum'),
            Min_MC_SE_over_exact=('Bootstrap_SE_over_exact_kernel_SE','min'),Max_MC_SE_over_exact=('Bootstrap_SE_over_exact_kernel_SE','max')).reset_index()
        check('All_draw_counts_reconcile',boot.Attempted.eq(boot.Succeeded+boot.Failed).all())
        check('Bootstrap_P_not_borrowed_from_HC3',dwb.P.isna().all())
        pd.testing.assert_frame_equal(original,r05['df_primary']);pd.testing.assert_frame_equal(master_before,r05['row_flags'])
        for h in R11_HOURS:
            pd.testing.assert_frame_equal(linked_before[h],r10['linked_candidates'][h])
            pd.testing.assert_frame_equal(weather_before[h],r10['weather_candidates'][h])
        check('R05_and_R10_inputs_unchanged',True)
        tables['S6_R11_candidate']=all_results.copy()
        status.update(Completed=True,Sensitivity_models_updated=True,New_OLS_models_fitted=sum(len(v) for v in models.values()),
            Verified_R08_baseline_models=len(templates),New_bootstrap_streams=len(boot),
            New_requested_draws_total=int(boot.Requested.sum()),New_successful_draws_total=int(boot.Succeeded.sum()),
            Age_values_changed=False,Official_hour_threshold_selected=False,Warning_count=len(warning_log))
        for title,table in [('1 保留子集與模型規格',retention),('2 原主分析核對與 HC3 結果',hc3[
            ['Case','Model','Rows','Beta','SE','CI_low','CI_high','P']]),('3 樣本與氣象變動的係數差',tables['descriptive_coefficient_changes']),
            ('4 同列舊新氣象的時間相依區間',paired),('5 本輪重抽樣紀錄',tables['bootstrap_counts_by_case'])]:
            print(f'\n=== 請回傳：R11 {title} ===');print(table.to_string(index=False,float_format=lambda v:f'{v:.8g}'))
            if title.startswith('1 '):print(specs.to_string(index=False));print(reasons.to_string(index=False))
            if title.startswith('2 '):print(baseline.to_string(index=False,float_format=lambda v:f'{v:.8g}'))
        print('\n=== 請回傳：R11 6 驗證與狀態 ===')
        print(pd.DataFrame([{'Checks':len(checks),'All_passed':all(c['Passed'] for c in checks),**status}]).to_string(index=False))
        print('警告：無。' if not warning_log else pd.DataFrame(warning_log).to_string(index=False))
        print(f'\n輸出位置：{out}')

        return {'Completed':True,'models':models,'cases':cases,'tables':tables,'status':status,'output_dir':str(out)}
    except Exception as exc:
        status.update(Error_type=type(exc).__name__,Error=str(exc))
        print(f'R11 未完成；已產生的診斷保留於 {out}。不以舊模型或其他資料集代替。')
        raise
    finally:
        for name,table in tables.items():table.to_csv(out/(name+'.csv'),index=False,encoding='utf-8-sig')
        pd.DataFrame(checks,columns=['Check','Passed']).to_csv(out/'validation.csv',index=False,encoding='utf-8-sig')
        pd.DataFrame(warning_log,columns=['Case','Model','Stage','Category','Message']).to_csv(out/'fit_warnings.csv',index=False,encoding='utf-8-sig')
        (out/'run_status.json').write_text(json.dumps(status,ensure_ascii=False,indent=2),encoding='utf-8')


R11=None
if any(name not in globals() for name in ['R05','R08','R10','folder_path','r08_calendar','r08_bootstrap']):
    raise NameError('請先完成前置步驟（R05 7A）、前置步驟（R08）與前置步驟（R10）；勿執行舊 R05 7B 代替。')
_r11_out=Path(folder_path)/'Revision_R11_Primary_Calendar_Sensitivity'/(
    datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')+'_'+uuid.uuid4().hex[:8])
R11=r11_run(R05,R08,R10,_r11_out,calendar_fn=r08_calendar,bootstrap_fn=r08_bootstrap)

"""## Forward classification with clinical/calendar/weather features

Input objects are produced by preceding cells in this notebook. Outputs remain private working artifacts until the publication export section.

"""

from pathlib import Path
from datetime import datetime, timezone
import json
import uuid
import warnings
import time
import numpy as np
import pandas as pd
try:
    import sklearn
    import xgboost
    from sklearn.pipeline import Pipeline
    from sklearn.preprocessing import StandardScaler
    from sklearn.linear_model import LogisticRegression
    from sklearn.metrics import roc_auc_score, brier_score_loss
    from sklearn.exceptions import ConvergenceWarning
    from xgboost import XGBClassifier
except ImportError as exc:
    raise ImportError('缺少分類套件；在 Colab 先執行 %pip install scikit-learn xgboost，再重跑本格。未換成其他模型。') from exc

R12_HOURS=(18,20,24)
R12_WARMUP_YEARS=2           # 預先指定前兩個日曆年為起始期間；不是固定研究起訖年。
R12_WINDOW_DAYS=365
R12_SEED=42
R12_DTR_BOUNDS=(0.,25.)      # 沿用 R05 的研究 QC 條件。
R12_PID,R12_PAIR,R12_DXA='去個資編號','pairing_row_id','骨密度檢查執行日期'
R12_CLINICAL=['Age','sex_bin','Hb_Value']
R12_CALENDAR=['DXA_year','DXA_sin_m','DXA_cos_m','Hb_year','Hb_sin_m','Hb_cos_m']
R12_WEATHER=['THI_mean_30d','DTR_mean_30d','THI_std_30d','T_std_30d',
             'THI_mean_180d','THI_hot_fraction_365d','THI_Trend_Shock']
R12_SIX=['T_mean_30d','DTR_mean_30d','RH_mean_30d','THI_mean_30d','THI_std_30d','THI_Trend_Shock']
R12_FEATURES={'Clinical':R12_CLINICAL,'Clinical_Calendar':R12_CLINICAL+R12_CALENDAR,
              'Clinical_Calendar_Weather':R12_CLINICAL+R12_CALENDAR+R12_WEATHER}
R12_ALGORITHMS=('Logistic_Regression','XGBoost')
R12_VERSION='calendar_windows_joint_days_90pct_v1'


def r12_require(ok,message):
    if not bool(ok):raise ValueError(message)


def r12_prepare(r05,r10,r11,warmup_years):
    for name,obj in [('R05',r05),('R10',r10),('R11',r11)]:
        r12_require(isinstance(obj,dict) and obj.get('Completed',False),f'{name} 尚未完成；不使用其他來源代替。')
    cols=[R12_PAIR,R12_PID,R12_DXA,'Hb_Date']+R12_CLINICAL+['overall_T','is_osteoporosis']
    p=r05['df_primary'];master=r05['row_flags']
    r12_require(not p.empty and p.columns.is_unique and not(set(cols)-set(p)),'Primary 為空、欄名重複或缺少分類欄位。')
    r12_require(p[[R12_PAIR,R12_PID]].notna().all().all() and p[R12_PAIR].is_unique and p[R12_PID].is_unique,
                'Primary 必須一人一列且 ID 唯一／非缺失。')
    r12_require(master[R12_PAIR].notna().all() and master[R12_PAIR].is_unique
        and set(p[R12_PAIR])==set(master.loc[master.is_included_primary,R12_PAIR]),'Primary 與 R05 母體旗標不符。')
    # R05.row_flags 不建立分類標籤；核對其臨床值，再於下方驗證 Primary 既有標籤。
    master_cols=[c for c in cols[1:] if c!='is_osteoporosis']
    pd.testing.assert_frame_equal(p.set_index(R12_PAIR)[master_cols],
        master.set_index(R12_PAIR).loc[p[R12_PAIR],master_cols],check_dtype=False)
    d=p[cols].copy(deep=True).reset_index(drop=True)
    numeric=R12_CLINICAL+['overall_T','is_osteoporosis']
    d[numeric]=d[numeric].apply(pd.to_numeric,errors='raise').astype(float)
    r12_require(np.isfinite(d[numeric]).all().all(),'臨床／結果欄位缺失或非有限；不靜默刪列。')
    r12_require(d.sex_bin.isin([0,1]).all() and d.is_osteoporosis.isin([0,1]).all(),'性別或分類標籤不是二元值。')
    r12_require(np.array_equal(d.is_osteoporosis,d.overall_T.le(-2.5).astype(int)),
                '原分類標籤與 minimum T-score ≤−2.5 的操作定義不同。')
    d['Target']=d.is_osteoporosis.astype(int)
    for prefix,col in [('DXA',R12_DXA),('Hb','Hb_Date')]:
        d[col]=pd.to_datetime(d[col],format='mixed',errors='raise')
        r12_require(d[col].notna().all(),f'{col} 缺失。')
        d[prefix+'_day']=d[col].dt.normalize()
        # 年份以數值趨勢處理，避免前推測試出現訓練時不存在的年份類別。
        d[prefix+'_year']=d[col].dt.year.astype(float)
        d[prefix+'_sin_m']=np.sin(2*np.pi*d[col].dt.month/12)
        d[prefix+'_cos_m']=np.cos(2*np.pi*d[col].dt.month/12)
    d['Record_available_day']=d[['DXA_day','Hb_day']].max(axis=1)
    d['Evaluation_year']=d.Record_available_day.dt.year.astype(int)
    d['Weather_window_start']=d.Hb_day-pd.Timedelta(days=R12_WINDOW_DAYS-1)
    first_year=int(d.Evaluation_year.min())+warmup_years
    years=list(range(first_year,int(d.Evaluation_year.max())+1))
    r12_require(len(years)>=2,'資料不足以在起始期間後作至少兩個逐年測試；不改用隨機切分。')
    definitions=[]
    for year in years:
        base_test=d.loc[d.Evaluation_year.eq(year)]
        r12_require(not base_test.empty,f'{year} 年原 Primary 無紀錄；不跳過事先定義的年度。')
        cutoff=base_test.Weather_window_start.min()
        definitions.append({'Test_year':year,'Test_calendar_start':pd.Timestamp(year,1,1),
            'Test_calendar_end':pd.Timestamp(year,12,31),'Train_available_before_exclusive':cutoff,
            'Original_primary_test_rows':len(base_test),'Earliest_test_Hb_day':base_test.Hb_day.min(),
            'Latest_test_record_day':base_test.Record_available_day.max()})
    definition=pd.DataFrame(definitions)
    r12_require(definition.Train_available_before_exclusive.is_monotonic_increasing,'訓練截止日不是逐年前推。')
    r12_require(set(r10['linked_candidates'])==set(R12_HOURS) and set(r10['weather_candidates'])==set(R12_HOURS),
                'R10 缺少明確的三個小時門檻候選。')
    datasets={};denominators=[];membership=[]
    weather_cols=list(dict.fromkeys(R12_SIX+R12_WEATHER))
    for h in R12_HOURS:
        link=r10['linked_candidates'][h]
        r12_require(link[R12_PAIR].notna().all() and link[R12_PAIR].is_unique
            and set(link[R12_PAIR])==set(master[R12_PAIR]),f'{h}h R10 母體配對 ID 不符。')
        r12_require(set(link.loc[link.is_included_primary,R12_PAIR])==set(d[R12_PAIR]),'R10 Primary 旗標不符。')
        q=link.set_index(R12_PAIR).loc[d[R12_PAIR]].reset_index()
        r12_require(np.array_equal(q[R12_PID],d[R12_PID]) and
            np.array_equal(pd.to_datetime(q.Hb_Date,format='mixed'),d.Hb_Date) and
            np.array_equal(pd.to_datetime(q.Window_start_365d),d.Weather_window_start),f'{h}h 病人／Hb 日期／365 天邊界不符。')
        r12_require(q.Minimum_hours.eq(h).all() and q.Weather_version.eq(R12_VERSION).all(),'R10 氣象版本不符。')
        new=q[weather_cols].apply(pd.to_numeric,errors='raise').astype(float)
        r12_require(not np.isinf(new.to_numpy()).any(),'氣象欄位有無限值，不轉成一般缺失。')
        cal=r10['weather_candidates'][h]
        r12_require(cal.index.is_unique,'R10 特徵日曆日期重複。')
        pd.testing.assert_frame_equal(new,cal.reindex(pd.DatetimeIndex(d.Hb_day))[weather_cols].reset_index(drop=True).astype(float),check_dtype=False)
        six=new[R12_SIX].notna().all(axis=1)
        complete=new.notna().all(axis=1)
        r12_require(np.array_equal(six,q.Original_six_feature_names_ready.eq(True)) and
            np.array_equal(complete,q.Secondary_frequency_bundle_ready.eq(True)), 'R10 完整度旗標與特徵數值不符。')
        dtr=new.DTR_mean_30d.between(*R12_DTR_BOUNDS)
        r11keep=six&dtr;keep=complete&dtr
        previous=r11['cases'][f'H{h}_calendar']['data']
        r12_require(set(previous[R12_PAIR])==set(d.loc[r11keep,R12_PAIR]),f'{h}h R11 子集 ID 與目前 R10 不符。')
        old=previous.set_index(R12_PAIR).loc[d.loc[r11keep,R12_PAIR]]
        r12_require(np.array_equal(old[R12_CLINICAL].to_numpy(dtype=float),d.loc[r11keep,R12_CLINICAL])
            and np.array_equal(old.overall_T.to_numpy(dtype=float),d.loc[r11keep,'overall_T'])
            and np.allclose(old[R12_SIX],new.loc[r11keep,R12_SIX]),'R11 臨床／氣象值已不同，不能混用版本。')
        sample=d.loc[keep].copy().reset_index(drop=True)
        r12_require(not sample.empty,f'{h}h 分類完整案例為空。')
        sample[R12_WEATHER]=new.loc[keep,R12_WEATHER].reset_index(drop=True)
        sample['Valid_days_365d']=q.loc[keep,'Valid_days_365d'].to_numpy()
        r12_require(sample.THI_hot_fraction_365d.between(0,1).all(),'熱日比例不在 0–1。')
        datasets[h]=sample
        denominators.append({'Minimum_hours':h,'Original_primary_rows':len(d),'R11_rows':int(r11keep.sum()),
            'R12_eligible_rows':len(sample),'R12_eligible_patients':sample[R12_PID].nunique(),
            'Additional_long_feature_missing_rows':int((r11keep&~complete).sum()),
            'Initial_years_not_tested_rows':int(sample.Evaluation_year.lt(first_year).sum()),
            'Forward_test_rows':int(sample.Evaluation_year.ge(first_year).sum()),
            'Operational_category_positive_rows':int(sample.Target.sum()),
            'Minimum_valid_days_365d':int(sample.Valid_days_365d.min()),'Maximum_valid_days_365d':int(sample.Valid_days_365d.max())})
        reasons=np.select([~six,~dtr,~complete],['original_six_weather_incomplete','DTR_outside_range','long_feature_incomplete'],default='eligible')
        membership.append(pd.DataFrame({'Minimum_hours':h,R12_PAIR:d[R12_PAIR],R12_PID:d[R12_PID],
            'Eligible':keep,'Reason':reasons,'Evaluation_year':d.Evaluation_year}))
    return d,datasets,definition,pd.DataFrame(denominators),pd.concat(membership,ignore_index=True)


def r12_folds(data,definition):
    folds=[];audit=[]
    for row in definition.itertuples(index=False):
        train=data.Record_available_day.lt(row.Train_available_before_exclusive)
        test=data.Evaluation_year.eq(row.Test_year)
        past=data.Record_available_day.lt(row.Test_calendar_start)
        purged=past&~train
        future=data.Record_available_day.gt(row.Test_calendar_end)
        tr=data.loc[train];te=data.loc[test]
        record={'Test_year':row.Test_year,'Train_rows':len(tr),'Test_rows':len(te),'Purged_past_rows':int(purged.sum()),
            'Future_rows':int(future.sum()),'Train_positive_rows':int(tr.Target.sum()),'Test_positive_rows':int(te.Target.sum()),
            'Train_last_available_day':tr.Record_available_day.max(),'Test_first_available_day':te.Record_available_day.min(),
            'Test_earliest_weather_start':te.Weather_window_start.min(),'Train_last_Hb_day':tr.Hb_day.max(),
            'Train_available_before_exclusive':row.Train_available_before_exclusive}
        r12_require(len(tr)>0 and len(te)>0,f'{row.Test_year} 年訓練或測試為空；不放寬排除或換切分。')
        r12_require(set(tr.Target)=={0,1} and set(te.Target)=={0,1},f'{row.Test_year} 年訓練／測試缺一類，AUC 不可評估；不跳過此折。')
        r12_require(not (train&test).any() and not set(tr[R12_PID])&set(te[R12_PID]),'訓練與測試病人重疊。')
        r12_require(tr.Record_available_day.max()<te.Weather_window_start.min()
            and tr.Hb_day.max()<te.Weather_window_start.min(),'訓練與測試氣象窗／資料可用日期交疊。')
        r12_require(int(train.sum()+test.sum()+purged.sum()+future.sum())==len(data),'各折資料角色不能加回分類分母。')
        record['No_patient_overlap']=True;record['No_train_test_weather_overlap']=True
        audit.append(record)
        roles=np.select([train,test,purged],['train','test','purged_past'],default='future')
        folds.append({'year':row.Test_year,'train':np.flatnonzero(train),'test':np.flatnonzero(test),'roles':roles})
    tested=np.concatenate([f['test'] for f in folds])
    expected=np.flatnonzero(data.Evaluation_year.isin(definition.Test_year))
    r12_require(len(np.unique(tested))==len(tested) and np.array_equal(np.sort(tested),expected),'前推測試列重複或未完整涵蓋評估期間。')
    return folds,pd.DataFrame(audit)


def r12_pipeline(algorithm,seed):
    # 與原 S5 的兩個 estimator constructor 相同；實際套件版本與有效參數另存。
    if algorithm=='Logistic_Regression':clf=LogisticRegression(max_iter=1000,random_state=seed)
    elif algorithm=='XGBoost':clf=XGBClassifier(n_estimators=100,eval_metric='logloss',random_state=seed,n_jobs=1)
    else:raise ValueError('未宣告的分類演算法。')
    return Pipeline([('s',StandardScaler()),('c',clf)])


def r12_score(y,prob):
    r12_require(np.isfinite(prob).all() and ((prob>=0)&(prob<=1)).all(),'預測機率無效。')
    brier=float(np.mean((np.asarray(y)-prob)**2))
    r12_require(np.isclose(brier,brier_score_loss(y,prob,pos_label=1),rtol=1e-10,atol=1e-12),'二元 Brier 尺度不一致。')
    return {'AUC':float(roc_auc_score(y,prob)),'Brier':brier}


def r12_summaries(metrics,predictions):
    summaries=[];increments=[];fold_changes=[]
    for (h,algorithm,feature),rows in metrics.groupby(['Minimum_hours','Algorithm','Feature_set'],sort=False):
        pred=predictions.query('Minimum_hours==@h and Algorithm==@algorithm and Feature_set==@feature')
        r12_require(pred[R12_PAIR].is_unique,'同一情境的前推預測列重複。')
        pooled=r12_score(pred.Target.to_numpy(),pred.Probability.to_numpy())
        r12_require(len(pred)==int(rows.Test_rows.sum()),'逐折測試筆數與預測檔不符。')
        summaries.append({'Minimum_hours':h,'Algorithm':algorithm,'Feature_set':feature,'Test_years':len(rows),
            'Test_rows_total':len(pred),'AUC_fold_mean':rows.AUC.mean(),'AUC_fold_SD':rows.AUC.std(ddof=1),
            'Brier_fold_mean':rows.Brier.mean(),'Brier_fold_SD':rows.Brier.std(ddof=1),
            'Pooled_test_AUC':pooled['AUC'],'Pooled_test_Brier':pooled['Brier']})
    for (h,algorithm),rows in metrics.groupby(['Minimum_hours','Algorithm'],sort=False):
        for label,base,aug in [('Added_calendar','Clinical','Clinical_Calendar'),
                               ('Added_weather_after_calendar','Clinical_Calendar','Clinical_Calendar_Weather')]:
            paired=rows.loc[rows.Feature_set.eq(base)].merge(rows.loc[rows.Feature_set.eq(aug)],
                on=['Test_year'],suffixes=('_base','_aug'),validate='one_to_one')
            r12_require(paired.Test_rows_base.eq(paired.Test_rows_aug).all() and paired.Train_rows_base.eq(paired.Train_rows_aug).all(),
                        '比較模型沒有使用相同訓練／測試筆數。')
            da=paired.AUC_aug-paired.AUC_base;db=paired.Brier_aug-paired.Brier_base
            for i,row in paired.iterrows():
                fold_changes.append({'Minimum_hours':h,'Algorithm':algorithm,'Comparison':label,
                    'Test_year':int(row.Test_year),'Test_rows':int(row.Test_rows_base),
                    'Delta_AUC':float(da.loc[i]),'Delta_Brier':float(db.loc[i])})
            base_p=predictions.query('Minimum_hours==@h and Algorithm==@algorithm and Feature_set==@base').sort_values(R12_PAIR)
            aug_p=predictions.query('Minimum_hours==@h and Algorithm==@algorithm and Feature_set==@aug').sort_values(R12_PAIR)
            r12_require(np.array_equal(base_p[R12_PAIR],aug_p[R12_PAIR]) and np.array_equal(base_p.Target,aug_p.Target),
                        '比較模型的實際測試 ID／結果不同。')
            bs=r12_score(base_p.Target.to_numpy(),base_p.Probability.to_numpy())
            us=r12_score(aug_p.Target.to_numpy(),aug_p.Probability.to_numpy())
            increments.append({'Minimum_hours':h,'Algorithm':algorithm,'Comparison':label,'Test_years':len(paired),
                'Mean_delta_AUC':da.mean(),'SD_delta_AUC_across_years':da.std(ddof=1),'Min_delta_AUC':da.min(),'Max_delta_AUC':da.max(),
                'Years_AUC_increased':int(da.gt(0).sum()),'Mean_delta_Brier':db.mean(),
                'SD_delta_Brier_across_years':db.std(ddof=1),'Years_Brier_decreased':int(db.lt(0).sum()),
                'Pooled_delta_AUC':us['AUC']-bs['AUC'],'Pooled_delta_Brier':us['Brier']-bs['Brier']})
    return pd.DataFrame(summaries),pd.DataFrame(increments),pd.DataFrame(fold_changes)


def r12_run(r05,r10,r11,out,warmup_years=R12_WARMUP_YEARS,seed=R12_SEED):
    out=Path(out);out.mkdir(parents=True,exist_ok=False)
    tables,checks,ledger,warnlog={ },[],[],[]
    pipelines={};predictions=[];scores=[];splits=[];role_tables=[]
    status={'Completed':False,'Classification_sensitivity_updated':False,'Original_cohorts_changed':False,
        'Primary_reselected':False,'Formal_weather_replaced':False,'Formal_tables_replaced':False}
    def check(name,ok):
        checks.append({'Check':name,'Passed':bool(ok)})
        r12_require(ok,'R12 驗證失敗：'+name)
    try:
        check('Valid_configuration',isinstance(warmup_years,int) and warmup_years>=1 and isinstance(seed,int) and seed>=0)
        d,datasets,definition,denominators,membership=r12_prepare(r05,r10,r11,warmup_years)
        original=r05['df_primary'].copy(deep=True);master_before=r05['row_flags'].copy(deep=True)
        links_before={h:c.copy(deep=True) for h,c in r10['linked_candidates'].items()}
        features_before={h:c.copy(deep=True) for h,c in r10['weather_candidates'].items()}
        previous_before={h:r11['cases'][f'H{h}_calendar']['data'].copy(deep=True) for h in R12_HOURS}
        tables.update(eligible_cohorts=denominators,forward_year_definitions=definition)
        tables['feature_dictionary']=pd.DataFrame([{'Feature_set':k,'Features':', '.join(v),'Number_of_features':len(v)} for k,v in R12_FEATURES.items()])
        membership.to_csv(out/'classification_eligibility_PRIVATE.csv',index=False,encoding='utf-8-sig')
        check('Only_prespecified_predictors_no_outcome_or_ID',all(not set(v)&{R12_PAIR,R12_PID,'Target','is_osteoporosis','overall_T'} for v in R12_FEATURES.values()))
        specification={'Base_uploaded_notebook':'self-contained analysis implementation','Inserted_after':'R11 in previous delivered integrated notebook',
            'Reviewers':['R1 Major 4','R1 Major 6','R2-9'],'Purpose':'Exploratory same-record information comparison, not prospective diagnosis or clinical utility validation',
            'Outcome':'Existing operational category: minimum available T-score <= -2.5, checked against R05 is_osteoporosis; not adjudicated diagnosis',
            'Algorithms':'Original S5 LogisticRegression(max_iter=1000, random_state=seed) and XGBClassifier(n_estimators=100, eval_metric=logloss, random_state=seed, n_jobs=1)',
            'Feature_sets':R12_FEATURES,'Calendar':'Numeric year trend and month sin/cos for BOTH DXA and Hb report dates; no unseen-year one-hot encoding',
            'Calendar_limit':'Linear year trend in logistic regression; calendar adjustment is not saturated year fixed effects. Trees do not guarantee trend extrapolation.',
            'Hot_feature':'Observed-day hot fraction with R10 valid-day minimum; no old annual hot-count alias or missing-as-zero coding',
            'Primary_selection':'Existing R05 representatives held fixed; every feature set uses identical complete cases per hourly threshold',
            'Record_available_day':'max(DXA date, Hb report date); one patient per row',
            'Validation':'Annual expanding-window forward validation with purging of overlapping weather windows; not GroupKFold or random KFold',
            'Initial_calendar_years':warmup_years,'Evaluation_years':definition.Test_year.tolist(),
            'Purging':'For each test year, use earliest Hb_day-(365-1) among ORIGINAL Primary test-year records as cutoff. Training record_available_day must be strictly earlier.',
            'Purging_limit':'Removes training-test overlap of the observed exposure windows; does not prove all temporal dependence is absent',
            'Split_consistency':'Calendar boundaries/cutoffs fixed across all hourly candidates; same training and test IDs across feature sets/algorithms within each candidate',
            'Fit':'Scaler and estimator fit on training rows only; no outcome-based feature selection, tuning, early stopping or recalibration on test rows',
            'Metrics':'AUC and binary Brier mean((y-p)^2), [0,1]. Mean/SD of annual folds and separately pooled forward-test scores.',
            'Increment':'Augmented minus baseline; positive delta AUC and negative delta Brier indicate improvement.',
            'Uncertainty':'Fold SD describes variation across test years, NOT an SE or CI; no paired fold t-test or IID case-bootstrap P/CI',
            'Pooled_limit':'Pooled AUC combines probabilities from different fitted years; inspect annual and mean-fold results, not pooled score alone',
            'Failure_policy':'Any missing class, empty fold, convergence/numeric failure stops; no skipped folds or substitute classifier',
            'Seed':seed,'Formal_tables_replaced':False,'Software':{'numpy':np.__version__,'pandas':pd.__version__,
                'scikit_learn':sklearn.__version__,'xgboost':xgboost.__version__}}
        (out/'analysis_specification.json').write_text(json.dumps(specification,ensure_ascii=False,indent=2),encoding='utf-8')
        parameters={a:r12_pipeline(a,seed).named_steps['c'].get_params(deep=False) for a in R12_ALGORITHMS}
        (out/'estimator_parameters.json').write_text(json.dumps(parameters,ensure_ascii=False,indent=2,default=str),encoding='utf-8')
        expected=len(R12_HOURS)*len(definition)*len(R12_ALGORITHMS)*len(R12_FEATURES)
        print(f'R12：{len(definition)} 個逐年測試區間、{len(R12_HOURS)} 個小時門檻，預計配適 {expected} 個分類模型。',flush=True)
        for h,data in datasets.items():
            folds,audit=r12_folds(data,definition);audit.insert(0,'Minimum_hours',h);splits.append(audit)
            tables['fold_audit']=pd.concat(splits,ignore_index=True)
            check(f'{h}h_date_patient_and_window_separation',audit.No_patient_overlap.all() and audit.No_train_test_weather_overlap.all())
            for fold in folds:
                year=fold['year'];tr=data.iloc[fold['train']];te=data.iloc[fold['test']]
                roles=data[[R12_PAIR,R12_PID]].copy();roles.insert(0,'Test_year',year);roles.insert(0,'Minimum_hours',h);roles['Role']=fold['roles'];role_tables.append(roles)
                for algorithm in R12_ALGORITHMS:
                    for feature,cols in R12_FEATURES.items():
                        key=f'H{h}_{year}_{algorithm}_{feature}'
                        rec={'Minimum_hours':h,'Test_year':year,'Algorithm':algorithm,'Feature_set':feature,
                            'Train_rows':len(tr),'Test_rows':len(te),'Status':'started','Seconds':np.nan,'Error':''}
                        ledger.append(rec);started=time.perf_counter();caught=[]
                        try:
                            pipe=r12_pipeline(algorithm,seed)
                            with warnings.catch_warnings(record=True) as caught:
                                warnings.simplefilter('always')
                                pipe.fit(tr[cols],tr.Target.to_numpy())
                                probs=pipe.predict_proba(te[cols])
                            warnlog.extend({'Model':key,'Category':w.category.__name__,'Message':str(w.message)} for w in caught)
                            check(key+'_no_fit_convergence_or_numeric_warning',not any(issubclass(w.category,(ConvergenceWarning,RuntimeWarning)) for w in caught))
                            check(key+'_scaler_fitted_to_training_only',np.all(np.asarray(pipe.named_steps['s'].n_samples_seen_)==len(tr))
                                and np.allclose(pipe.named_steps['s'].mean_,tr[cols].mean().to_numpy(),rtol=1e-10,atol=1e-10))
                            classes=np.asarray(pipe.classes_)
                            check(key+'_binary_probabilities_valid',np.array_equal(classes,[0,1]) and probs.shape==(len(te),2)
                                and np.isfinite(probs).all() and np.allclose(probs.sum(axis=1),1.,rtol=1e-6,atol=1e-6))
                            prob=probs[:,int(np.flatnonzero(classes==1)[0])].astype(float)
                            score=r12_score(te.Target.to_numpy(),prob)
                            scores.append({k:rec[k] for k in ['Minimum_hours','Test_year','Algorithm','Feature_set','Train_rows','Test_rows']}|
                                {'Test_positive_rows':int(te.Target.sum()),**score})
                            pr=te[[R12_PAIR,R12_PID,'Target','Record_available_day']].copy()
                            pr['Minimum_hours']=h;pr['Test_year']=year;pr['Algorithm']=algorithm;pr['Feature_set']=feature;pr['Probability']=prob
                            predictions.append(pr);pipelines[key]=pipe
                            if algorithm=='XGBoost':
                                config=out/'xgboost_configs';config.mkdir(exist_ok=True)
                                (config/(key+'.json')).write_text(pipe.named_steps['c'].get_booster().save_config(),encoding='utf-8')
                            rec['Status']='success'
                        except Exception as exc:
                            rec.update(Status='failed',Error=f'{type(exc).__name__}: {exc}')
                            raise
                        finally:rec['Seconds']=time.perf_counter()-started
                    print(f'R12 {h}h／測試年 {year}／{algorithm}：三組特徵完成；訓練 {len(tr)}、測試 {len(te)}。',flush=True)
        pred=pd.concat(predictions,ignore_index=True);metrics=pd.DataFrame(scores)
        tables['fold_metrics']=metrics
        performance,increment,annual_delta=r12_summaries(metrics,pred)
        tables.update(performance_summary=performance,increment_summary=increment,annual_increment=annual_delta)
        pred.to_csv(out/'forward_test_predictions_PRIVATE.csv',index=False,encoding='utf-8-sig')
        pd.concat(role_tables,ignore_index=True).to_csv(out/'fold_membership_PRIVATE.csv',index=False,encoding='utf-8-sig')
        check('All_requested_fits_succeeded',len(ledger)==expected and all(r['Status']=='success' for r in ledger))
        check('Each_eligible_evaluation_record_tested_once_per_model',all(
            len(g)==denominators.set_index('Minimum_hours').loc[h,'Forward_test_rows'] and g[R12_PAIR].is_unique
            for (h,a,f),g in pred.groupby(['Minimum_hours','Algorithm','Feature_set'])))
        check('No_training_initial_years_in_test_metrics',pred.Test_year.ge(definition.Test_year.min()).all())
        check('Complete_cases_split_into_initial_and_test_periods',denominators.Initial_years_not_tested_rows.add(
            denominators.Forward_test_rows).eq(denominators.R12_eligible_rows).all())
        pd.testing.assert_frame_equal(original,r05['df_primary']);pd.testing.assert_frame_equal(master_before,r05['row_flags'])
        for h in R12_HOURS:
            pd.testing.assert_frame_equal(links_before[h],r10['linked_candidates'][h])
            pd.testing.assert_frame_equal(features_before[h],r10['weather_candidates'][h])
            pd.testing.assert_frame_equal(previous_before[h],r11['cases'][f'H{h}_calendar']['data'])
        check('R05_R10_R11_inputs_unchanged',True)
        tables['fit_counts']=pd.DataFrame(ledger).groupby(['Minimum_hours','Algorithm'],sort=False).agg(
            Attempted=('Status','size'),Succeeded=('Status',lambda s:int(s.eq('success').sum())),Failed=('Status',lambda s:int(s.ne('success').sum()))).reset_index()
        tables['S5_R12_candidate']=performance.copy()
        status.update(Completed=True,Classification_sensitivity_updated=True,Evaluation_years=len(definition),
            Fits_requested=expected,Fits_succeeded=sum(r['Status']=='success' for r in ledger),Fits_failed=0,
            Warning_count=len(warnlog),Formal_hour_threshold_selected=False,Age_values_changed=False,
            External_validation_performed=False,Prospective_prediction_claim=False)
        for title,table in [('1 分母與特徵',denominators),('2 逐年前推與窗格隔離',tables['fold_audit']),
            ('3 分類效能',performance),('4 日曆與氣象的增量',increment),('5 配適紀錄',tables['fit_counts'])]:
            print(f'\n=== 請回傳：R12 {title} ===');print(table.to_string(index=False,float_format=lambda v:f'{v:.8g}'))
            if title.startswith('1 '):print(tables['feature_dictionary'].to_string(index=False))
            if title.startswith('2 '):print(definition.to_string(index=False))
            if title.startswith('4 '):print(annual_delta.query('Comparison=="Added_weather_after_calendar"').to_string(index=False,float_format=lambda v:f'{v:.8g}'))
        print('\n=== 請回傳：R12 6 驗證與狀態 ===')
        print(pd.DataFrame([{'Checks':len(checks),'All_passed':all(c['Passed'] for c in checks),**status}]).to_string(index=False))
        print('警告：無。' if not warnlog else pd.DataFrame(warnlog).to_string(index=False))
        print(f'\n輸出位置：{out}')

        return {'Completed':True,'datasets':datasets,'models':pipelines,'predictions':pred,'tables':tables,'status':status,'output_dir':str(out)}
    except Exception as exc:
        status.update(Error_type=type(exc).__name__,Error=str(exc))
        print(f'R12 未完成；診斷保留於 {out}。沒有跳過失敗折、換模型或退回舊氣象。')
        raise
    finally:
        for name,table in tables.items():table.to_csv(out/(name+'.csv'),index=False,encoding='utf-8-sig')
        pd.DataFrame(checks,columns=['Check','Passed']).to_csv(out/'validation.csv',index=False,encoding='utf-8-sig')
        pd.DataFrame(ledger).to_csv(out/'fit_ledger.csv',index=False,encoding='utf-8-sig')
        pd.DataFrame(warnlog,columns=['Model','Category','Message']).to_csv(out/'fit_warnings.csv',index=False,encoding='utf-8-sig')
        if scores:pd.DataFrame(scores).to_csv(out/'fold_metrics_completed_so_far.csv',index=False,encoding='utf-8-sig')
        (out/'run_status.json').write_text(json.dumps(status,ensure_ascii=False,indent=2),encoding='utf-8')


