"""## S8 Complete Model and Table Notes Integration

The existing Primary and LMM models, variance, and resampling results are used without any new adaptations. Table notes list the actual reference year and the number of successful resamplings for each model; a distinction is made between the fixed-effects Wald inference and the parametric REML bootstrap inference for variance/ICC. Time dependence is referenced in S10, the original completeness analysis in S6, and the reconstructed meteorological sensitivity in S14.
"""

from pathlib import Path
from datetime import datetime, timezone
import hashlib, json, re, uuid, math, textwrap
import numpy as np
import pandas as pd
import patsy
from openpyxl import Workbook, load_workbook
from openpyxl.styles import Font, PatternFill, Alignment
from openpyxl.utils import get_column_letter

R21_FIELDS=['pairing_row_id','去個資編號','骨密度檢查執行日期','Hb_Date',
            'Age','年齡','sex_bin','Hb_Value','overall_T','THI_mean_30d','DTR_mean_30d']

def r21_require(ok,message):
    if not bool(ok):raise ValueError('R21：'+message+'；停止，不使用替代來源。')

def r21_sha(path):return hashlib.sha256(Path(path).read_bytes()).hexdigest()

def r21_json(path,data):
    Path(path).write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')

def r21_source(obj,label):
    r21_require(isinstance(obj,dict) and obj.get('Completed') is True,label+' 尚未完成')
    p=Path(obj['output_dir'])
    r21_require(p.is_dir(),label+' output_dir 不存在')
    status=json.loads((p/'run_status.json').read_text(encoding='utf-8'))
    r21_require(status.get('Completed') is True,label+' 存檔狀態未完成')
    return p

def r21_same(a,b):
    pd.testing.assert_frame_equal(a.reset_index(drop=True),b.reset_index(drop=True),
        check_dtype=False,check_exact=False,rtol=1e-9,atol=1e-11)

def r21_csv_check(table,path):
    read=pd.read_csv(path,keep_default_na=False,na_values=[''])
    # CSV 空字串與缺失值僅在文字欄位做序列化核對，不修改原表。
    a=table.reset_index(drop=True).copy();b=read.copy()
    for c in a:
        if pd.api.types.is_object_dtype(a[c]) or pd.api.types.is_string_dtype(a[c]):
            a[c]=a[c].fillna('').astype(str);b[c]=b[c].fillna('').astype(str)
    r21_same(a,b)

def r21_book(tables,path):
    wb=Workbook();wb.remove(wb.active)
    for title,frame in tables.items():
        ws=wb.create_sheet(title);ws.append([str(c).replace('_',' ') for c in frame.columns])
        for row in frame.itertuples(index=False,name=None):
            values=[]
            for v in row:
                if pd.isna(v):v=None
                elif isinstance(v,np.generic):v=v.item()
                values.append(v)
            ws.append(values)
        ws.freeze_panes='C2';ws.auto_filter.ref=ws.dimensions
        for cell in ws[1]:
            cell.fill=PatternFill('solid',fgColor='17365D');cell.font=Font(name='Arial',bold=True,color='FFFFFF',size=11)
            cell.alignment=Alignment(wrap_text=True,vertical='center')
        ws.row_dimensions[1].height=34
        for j,col in enumerate(frame.columns,1):
            width=18
            if col in ['Model','Outcome','Parameter','Inference','Topic','Calendar_anchor']:width=32
            if col in ['Term','Formula','Description','Message']:width=75 if col in ['Formula','Description'] else 48
            if len(str(col))>24:width=max(width,28)
            if col=='Iteration_count_source':width=34
            if col=='Inference':width=42
            ws.column_dimensions[get_column_letter(j)].width=width
            header_lines=len(textwrap.wrap(str(col).replace('_',' '),max(8,int(width*.85))))
            ws.row_dimensions[1].height=max(ws.row_dimensions[1].height,header_lines*15+10)
            for row in range(2,ws.max_row+1):
                c=ws.cell(row,j);c.font=Font(name='Arial',size=10)
                c.alignment=Alignment(vertical='center',wrap_text=True)
                if isinstance(c.value,float):c.number_format='0.000E+00' if col in ['P','P_value'] else '0.00000000'
                elif isinstance(c.value,int) and not isinstance(c.value,bool):c.number_format='#,##0'
                if col=='Reference_year':c.number_format='0'
                if col in ['Iterations','Function_calls','Warning_count']:c.number_format='#,##0'
                if row%2==0:c.fill=PatternFill('solid',fgColor='F2F6FA')
                lines=max(1,math.ceil(len(str(c.value or ''))/(width*0.9)))
                ws.row_dimensions[row].height=max(ws.row_dimensions[row].height or 30,lines*14+8)
        ws.sheet_view.showGridLines=False
        ws.sheet_properties.pageSetUpPr.fitToPage=True
        ws.page_setup.orientation='landscape';ws.page_setup.paperSize=ws.PAPERSIZE_A3
        ws.page_setup.fitToWidth=1;ws.page_setup.fitToHeight=0;ws.print_title_rows='1:1'
    wb.save(path)
    saved=load_workbook(path,data_only=False)
    for name,frame in tables.items():
        for rr,row in enumerate(frame.itertuples(index=False,name=None),2):
            for cc,v in enumerate(row,1):
                got=saved[name].cell(rr,cc).value
                if pd.isna(v) or v=='':r21_require(got is None,name+' 缺失值輸出改變')
                elif isinstance(v,(float,np.floating)):r21_require(np.isclose(v,got,rtol=1e-12,atol=1e-12),name+' 數值回讀不符')
                else:r21_require(got==v,name+' 數值／標籤回讀不符')
    saved.close()

def r21_prepared(frame):
    r21_require(set(R21_FIELDS).issubset(frame.columns),'世代缺少必要欄位')
    d=frame[R21_FIELDS].copy(deep=True).reset_index(drop=True)
    r21_require(d.pairing_row_id.notna().all() and d.pairing_row_id.is_unique,'配對 ID 不唯一')
    r21_require(d['去個資編號'].notna().all(),'病人 ID 缺失')
    for prefix,col in [('hb','Hb_Date'),('dxa','骨密度檢查執行日期')]:
        d[col]=pd.to_datetime(d[col],errors='raise')
        r21_require(d[col].notna().all(),'模型日期缺失')
        d[prefix+'_year']=d[col].dt.year.astype(int)
        d[prefix+'_sin']=np.sin(2*np.pi*d[col].dt.month/12)
        d[prefix+'_cos']=np.cos(2*np.pi*d[col].dt.month/12)
    r21_require(np.array_equal(d.Age,d['年齡']),'年齡別名不符')
    return d

def r21_run_a(r05,r08,r15,primary,repeated,out):
    out=Path(out);out.mkdir(parents=True,exist_ok=False)
    for sub in ['Tables','Figures','Text','Audit']:(out/sub).mkdir()
    audit=out/'Audit';checks=[]
    status={'Completed':False,'S8_exported':False,'New_models_fitted':0,'New_bootstrap_draws':0,
            'Cohorts_changed':False,'Age_values_changed':False,'Weather_values_changed':False,'Patient_records_exported':False}
    def check(label,ok=True):r21_require(ok,label);checks.append({'Check':label,'Passed':True})
    try:
        check('R05_completed',r05.get('Completed') is True)
        roots={'R08':r21_source(r08,'R08'),'R15':r21_source(r15,'R15')}
        snapshots=[(x,x.copy(deep=True)) for x in [primary,repeated,r05['df_primary'],r05['df_sensitivity'],r05['row_flags']]]
        p=r21_prepared(primary);d=r21_prepared(repeated)
        for current,saved in [(primary,r05['df_primary']),(repeated,r05['df_sensitivity'])]:
            r21_same(current[R21_FIELDS],saved[R21_FIELDS])
        check('Current_cohorts_equal_R05')
        check('Primary_one_row_per_patient_and_repeated_membership',p['去個資編號'].is_unique
              and set(p.pairing_row_id).issubset(set(d.pairing_row_id)) and set(p['去個資編號'])==set(d['去個資編號']))
        source_files=[]
        def source_table(obj,name,label):
            tab=obj['tables'][name];path=roots[label]/(name+'.csv')
            r21_csv_check(tab,path);source_files.append({'Source':label,'File':path.name,'SHA256':r21_sha(path)})
            return tab.copy(deep=True)
        ps=source_table(r08,'model_specifications','R08')
        old_inference=source_table(r08,'S10_R08_candidate','R08')
        rt={k:source_table(r15,k,'R15') for k in ['Model_specifications','Variance_and_ICC','Scale_audit',
            'Fit_diagnostics','Bootstrap_counts','Native_profile_checks']}
        check('Source_tables_equal_saved_current_exports')
        check('Bootstrap_complete',rt['Bootstrap_counts'].Failed.eq(0).all()
              and rt['Bootstrap_counts'].Succeeded.eq(rt['Bootstrap_counts'].Requested).all()
              and rt['Native_profile_checks'].Passed.all())
        check('Variance_P_not_transferred',rt['Variance_and_ICC'].P_value.isna().all())
        fixed=[];specs=[];diagnostics=[];targets=[];model_snapshots=[]
        for name in ['Primary_A','Primary_B','Repeated_A','Repeated_B']:
            is_primary=name.startswith('Primary');which=name[-1];data=p if is_primary else d
            row=(ps.loc[ps.Model.eq(which)] if is_primary else rt['Model_specifications'].loc[rt['Model_specifications'].Model.eq(name)])
            check(name+'_one_specification',len(row)==1);row=row.iloc[0]
            fit=r08['models'][which]['hc3'] if is_primary else r15['models'][name]
            y,X=patsy.dmatrices(row.Formula,data,return_type='dataframe',NA_action='raise',eval_env=-1)
            check(name+'_design_rows_columns_and_values',list(X)==list(fit.model.exog_names)
                and np.array_equal(np.asarray(fit.model.endog),y.iloc[:,0].to_numpy())
                and np.allclose(np.asarray(fit.model.exog),X.to_numpy(),rtol=1e-12,atol=1e-12))
            check(name+'_denominators',int(fit.nobs)==len(data) and int(row.Rows)==len(data)
                and int(row.Patients)==data['去個資編號'].nunique())
            k=X.shape[1];params=np.asarray(fit.params).copy();cov=np.asarray(fit.cov_params()).copy()
            model_snapshots.append((fit,params,cov))
            if is_primary:
                check(name+'_HC3_normal',fit.cov_type=='HC3' and not fit.use_t)
                beta=params;se=np.asarray(fit.bse);inf='HC3_normal_Wald'
                diagnostics.append({'Model':name,'Method':'OLS closed form; HC3 covariance','Converged':None,
                    'Iterations':None,'Iteration_count_source':'not_applicable','Warning_count':None})
            else:
                check(name+'_REML_converged_single_random_intercept',bool(fit.converged) and fit.reml and fit.k_re==1 and fit.k_vc==0)
                check(name+'_patient_grouping',np.array_equal(fit.model.groups,pd.factorize(data['去個資編號'],sort=False)[0]))
                beta=np.asarray(fit.fe_params);se=np.asarray(fit.bse_fe);inf='LMM_model_based_normal_Wald'
                diag=rt['Fit_diagnostics'].loc[rt['Fit_diagnostics'].Model.eq(name)]
                check(name+'_observed_diagnostic_present',len(diag)==1 and diag.Converged.eq(True).all())
                diagnostics.append(diag.iloc[0].to_dict())
                values={'Random_intercept_variance':float(np.asarray(fit.cov_re)[0,0]),'Residual_variance':float(fit.scale)}
                values['ICC']=values['Random_intercept_variance']/sum(values.values())
                vr=rt['Variance_and_ICC'].loc[rt['Variance_and_ICC'].Model.eq(name)].set_index('Parameter')
                check(name+'_original_variance_points_and_denominators',set(vr.index)==set(values)
                    and all(np.isclose(vr.loc[q,'Estimate'],v,rtol=1e-9) for q,v in values.items())
                    and vr.Rows.eq(len(data)).all() and vr.Patients.eq(data['去個資編號'].nunique()).all())
                draws=r15['draws'][name]
                count_row=rt['Bootstrap_counts'].loc[rt['Bootstrap_counts'].Model.eq(name)]
                check(name+'_bootstrap_denominator_and_convergence',len(count_row)==1 and len(draws)==int(count_row.iloc[0].Succeeded)
                    and draws.Profile_converged.eq(True).all() and np.isfinite(draws[['sigma_u2','sigma_e2','ICC']]).all().all())
                check(name+'_existing_bootstrap_inference_matches',draws.Status.eq('success').all()
                    and np.allclose(vr.loc[list(values),'Bootstrap_SE'],draws[['sigma_u2','sigma_e2','ICC']].std(ddof=1)))
                alpha=float(r15['specification']['Alpha'])
                check(name+'_bootstrap_CI_preserved',np.allclose(vr.loc[list(values),['CI_low','CI_high']],
                    np.quantile(draws[['sigma_u2','sigma_e2','ICC']],[alpha/2,1-alpha/2],axis=0).T))
            ci=np.asarray(fit.conf_int(alpha=.05))[:k];pv=np.asarray(fit.pvalues)[:k];stat=np.asarray(fit.tvalues)[:k]
            check(name+'_finite_fixed_effects',np.isfinite(np.r_[beta,se,ci.ravel(),pv,stat]).all() and (se>0).all())
            for j,term in enumerate(X.columns):
                label={'Intercept':'Intercept','Age':'Age (per year)','sex_bin':'Male vs female',
                    'Hb_Value':'Hemoglobin (per g/dL)','THI_mean_30d':'30-day THI (per unit)',
                    'DTR_mean_30d':'30-day DTR (per degree C)','hb_sin':'Hb report month: sine','hb_cos':'Hb report month: cosine','dxa_sin':'DXA month: sine','dxa_cos':'DXA month: cosine'}.get(term,term)
                match=re.search(r'\[T\.(\d+)\]$',term)
                if match:label=f'Year {match.group(1)} vs {int(row.Reference_year)}'
                fixed.append({'Model':name,'Parameter':label,'Estimate':float(beta[j]),'SE':float(se[j]),
                    'CI_low':float(ci[j,0]),'CI_high':float(ci[j,1]),'Statistic':float(stat[j]),'P':float(pv[j]),'Inference':inf})
            target='THI_mean_30d' if which=='A' else 'Hb_Value';j=list(X).index(target)
            targets.append({'Model':name,'Target':target,'Estimate':beta[j],'SE':se[j],'CI_low':ci[j,0],'CI_high':ci[j,1],'P':pv[j]})
            if is_primary:
                old=old_inference.loc[old_inference.Model.eq(which)&old_inference.Method.eq('HC3_normal_Wald')]
                check(name+'_published_target_reproduced',len(old)==1 and np.allclose(old[['Beta','SE','CI_low','CI_high','P']].iloc[0],
                    [beta[j],se[j],*ci[j],pv[j]],rtol=1e-9,atol=1e-12))
            specs.append({'Model':name,'Outcome':y.columns[0],'Rows':len(data),'Patients':data['去個資編號'].nunique(),
                'Design_columns':k,'Reference_year':int(row.Reference_year),
                'Calendar_anchor':'Hb laboratory report date' if which=='A' else 'DXA execution date','Formula':row.Formula,'Inference':inf})
        methods=pd.DataFrame([
            ('Scope','Fixed_effects reports Primary_A, Primary_B, Repeated_A and Repeated_B. Variance_and_ICC reports the random-intercept variance, residual variance and ICC for Repeated_A and Repeated_B. These panels use the existing fitted models; this assembly does not refit them.'),
            ('Primary inference','Primary OLS coefficients use HC3 standard errors and normal-Wald 95% confidence intervals and P values. Date-clustered and dependent-wild-bootstrap inference is reported separately in S10 Table. S6 Table reports the original strict calendar-window completeness analysis; reconstructed-weather model sensitivities are reported separately in S14 Table.'),
            ('Repeated inference','Fixed-effect estimates, model-based SE and normal-Wald CI/P from R15. Only fe_params/bse_fe are fixed effects; profile variance ratios are excluded.'),
            ('Variance scale','Random-intercept variance from cov_re; residual variance from scale, in squared outcome units. ICC is conditional on the fitted covariance model.'),
            # 只從既有重抽樣彙總產生表註；不重抽樣、不寫死成功次數。
            ('Variance uncertainty',
                'For random-intercept variance, residual variance and ICC, SE is the sample SD (ddof=1) '
                'of Gaussian parametric REML bootstrap estimates; '
                f'{100*(1-float(r15["specification"]["Alpha"])):g}% confidence intervals are equal-tailed percentile intervals. '
                + '; '.join(f'{r.Model}: {int(r.Succeeded):,} successful draws of {int(r.Requested):,} requested'
                            for r in rt['Bootstrap_counts'].itertuples(index=False))
                + '. These model-based intervals condition on the fixed design and the assumed Gaussian covariance model. '
                'No variance-component or ICC P values are reported; ratio-scale or fixed-effect P values are not used for these quantities.'),
            # 參考年沿用上方已核對的模型規格；截距與年度係數不重新編碼。
            ('Reference years',
                '; '.join(f'{s["Model"]}: {int(s["Reference_year"])} reference' for s in specs)
                + '. Each intercept and year coefficient is reported under its own fitted reference coding. '
                'Different reference years do not imply different weather linkage; no coefficient is relabelled to a common reference year.'),
            ('Source and limits','Current R05 ages, cohorts and original weather features are retained. This export does not resolve residual confounding, date-proxy identity or calendar dependence.'),
            ('Sources','R08 and R15 current runtime objects and explicitly named saved files. Source hashes and checks are in Audit. Blank fields mean unavailable or not applicable, never zero.')
        ],columns=['Topic','Description'])
        tables={'Fixed_effects':pd.DataFrame(fixed),'Variance_and_ICC':rt['Variance_and_ICC'],
            'Model_specifications':pd.DataFrame(specs),'Fit_diagnostics':pd.DataFrame(diagnostics),
            'Bootstrap_counts':rt['Bootstrap_counts'],'Scale_audit':rt['Scale_audit'],'Methods':methods}
        for obj,before in snapshots:pd.testing.assert_frame_equal(obj,before)
        for fit,params,cov in model_snapshots:
            check('Model_parameters_and_covariance_unchanged',np.array_equal(fit.params,params) and np.array_equal(fit.cov_params(),cov))
        for name,table in tables.items():table.to_csv(audit/(name+'.csv'),index=False,encoding='utf-8-sig')
        book=out/'Tables/S8_Table_R21_Complete_Model_Results.xlsx';r21_book(tables,book)
        check('Workbook_roundtrip_and_inputs_unchanged')
        notes='S8 Table. Complete fixed-effect estimates, mixed-model variance components and intraclass correlations.\n\n'+'\n\n'.join(
            f'{r.Topic}: {r.Description}' for r in methods.itertuples(index=False))
        (out/'Text/S8_Table_R21_caption_and_notes.txt').write_text(notes,encoding='utf-8')
        r21_json(audit/'R21A_provenance.json',{'Base_notebook':'self-contained analysis implementation',
            'Source_directories':{k:str(v) for k,v in roots.items()},'Source_files':source_files})
        status.update(Completed=True,S8_exported=True,Existing_models=4,Fixed_effect_rows=len(fixed),Variance_rows=len(rt['Variance_and_ICC']),
            Checks=len(checks),All_passed=True)
        print('\n=== 請回傳：R21A 1 模型與參考年 ===');print(tables['Model_specifications'].drop(columns='Formula').to_string(index=False))
        print('\n=== 請回傳：R21A 2 目標係數 ===');print(pd.DataFrame(targets).to_string(index=False))
        print('\n=== 請回傳：R21A 3 變異數與 ICC ===');print(tables['Variance_and_ICC'].to_string(index=False))
        print('\n=== 請回傳：R21A 4 輸出與驗證 ===');print(pd.DataFrame([status]).to_string(index=False));print(book)
        return {'Completed':True,'tables':tables,'status':status,'output_dir':str(out),'xlsx':str(book),
            'targets':pd.DataFrame(targets),'primary_fingerprint':hashlib.sha256(p[R21_FIELDS].to_csv(index=False).encode()).hexdigest(),
            'repeated_fingerprint':hashlib.sha256(d[R21_FIELDS].to_csv(index=False).encode()).hexdigest()}
    except Exception as exc:
        status.update(Completed=False,Error_type=type(exc).__name__,Error=str(exc));raise
    finally:
        pd.DataFrame(checks).to_csv(audit/'R21A_validation.csv',index=False,encoding='utf-8-sig')
        r21_json(audit/'R21A_status.json',status)


R21A=None
_r21_missing=[k for k in ['R05','R08','R15','df_primary','df_sensitivity','folder_path'] if k not in globals()]
if _r21_missing:raise NameError(f'請先完成既有來源；缺少 {_r21_missing}。不自動重跑模型。')
r21_require(Path(folder_path).is_dir(),'folder_path 不存在')
_r21_root=Path(folder_path)/'OUTPUT'/('R21_'+datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')+'_'+uuid.uuid4().hex[:8])
R21A=r21_run_a(R05,R08,R15,df_primary,df_sensitivity,_r21_root)

"""## Intermediate Fig1 layout

Input objects are produced by preceding cells in this notebook. Outputs remain private working artifacts until the publication export section.

"""

# 僅重現 Fig 1；Fig 2 凍結，不建立替換候選。
import matplotlib.pyplot as plt
from matplotlib.patches import FancyBboxPatch
from PIL import Image

R21_STAGE_LABELS={
 'Stage1a_Date_unevaluable':'Dates not evaluable',
 'Stage1b_Gap_over_180d':'Evaluable interval exceeds limit',
 'Stage2a_DXA_missing_after_mask':'DXA T-score unavailable after masking',
 'Stage2b_Hb_missing_after_mask':'Hb unavailable after masking',
 'Stage2c_Age_missing':'Age unavailable',
 'Stage2d_Sex_unmapped_or_missing':'Sex unavailable / unmapped',
 'Stage3_Weather_incomplete':'Required weather features incomplete',
 'Stage4a_Hb_outside_range':'Hb outside analysis range',
 'Stage4b_T_outside_range':'T-score outside analysis range',
 'Stage4c_Age_outside_range':'Age outside analysis range',
 'Stage4d_DTR_outside_range':'DTR outside analysis range'}

def r21_box(ax,x,y,w,h,text,color='#24557A',fill='#F0F5FA',size=12):
    ax.add_patch(FancyBboxPatch((x,y),w,h,boxstyle='round,pad=0.008,rounding_size=0.012',
        linewidth=1.4,edgecolor=color,facecolor=fill,zorder=2))
    return ax.text(x+w/2,y+h/2,text,ha='center',va='center',fontsize=size,color='#17324D',linespacing=1.4,zorder=3)

def r21_arrow(ax,start,end):
    ax.annotate('',xy=end,xytext=start,arrowprops={'arrowstyle':'-|>','lw':1.5,'color':'#53677B'},zorder=1)

def r21_save_figure(fig,root,stem):
    # 英吋 × DPI 決定像素；座標範圍不是像素規格。不使用 bbox_inches='tight' 改變尺寸。
    files=[]
    for ext in ['png','tif']:
        path=root/'Figures'/f'{stem}.{ext}'
        if ext=='tif':fig.savefig(path,dpi=300,facecolor='white',format='tiff',pil_kwargs={'compression':'tiff_lzw'})
        else:fig.savefig(path,dpi=300,facecolor='white')
        with Image.open(path) as im:
            rgb=im.convert('RGB')
            if ext=='tif':rgb.save(path,dpi=(300,300),compression='tiff_lzw')
            else:rgb.save(path,dpi=(300,300))
        with Image.open(path) as im:
            r21_require(im.mode=='RGB' and all(abs(x-300)<.1 for x in im.info['dpi']),'圖檔規格不符')
            files.append({'File':path.name,'Width':im.width,'Height':im.height,'DPI':300,'Mode':im.mode,'Bytes':path.stat().st_size})
    plt.show();plt.close(fig)
    return files

def slim_run_fig1(r21a,r05,r19,r10,primary,repeated):
    r21_require(r21a.get('Completed') is True,'先完成 R21A')
    root=Path(r21a['output_dir']);audit=root/'Audit';status={'Completed':False,'New_models_fitted':0,'Cohorts_refiltered':False}
    checks=[]
    def check(label,ok=True):r21_require(ok,label);checks.append({'Check':label,'Passed':True})
    try:
        for label,d in [('primary',primary),('repeated',repeated)]:
            fingerprint=hashlib.sha256(r21_prepared(d)[R21_FIELDS].to_csv(index=False).encode()).hexdigest()
            check(label+'_matches_R21A',fingerprint==r21a[label+'_fingerprint'])
        src=r21_source(r19,'R19');weather_src=r21_source(r10,'R10')
        check('R19_uses_current_R05',Path(r19['provenance']['Source_R05_directory']).resolve()==Path(r05['Output_dir']).resolve())
        f=r19['tables']['PartB_Flow'].copy(deep=True);tot=r19['tables']['PartB_Totals'].copy(deep=True)
        r21_csv_check(f,src/'PartB_Flow.csv');r21_csv_check(tot,src/'PartB_Totals.csv')
        r21_same(f,r05['tables']['sequential_attrition']);r21_same(tot,r05['tables']['attrition_totals'])
        check('R19_flow_and_totals_equal_current_R05_and_saved_files')
        check('Known_stages_once_in_existing_order',f.Stage.tolist()==list(R21_STAGE_LABELS))
        check('Sequential_arithmetic',f.Rows_entering.sub(f.Rows_removed).eq(f.Rows_remaining).all()
              and np.array_equal(f.Rows_remaining.iloc[:-1],f.Rows_entering.iloc[1:]))
        check('Final_counts_match_current_cohorts',len(tot)==1 and int(f.iloc[0].Rows_entering)==len(r05['row_flags'])
              and int(f.iloc[-1].Rows_remaining)==len(repeated) and int(tot.iloc[0].Primary_rows)==len(primary))
        s=f.set_index('Stage');n=lambda key:int(s.loc[key,'Rows_remaining']);removed=lambda key:int(s.loc[key,'Rows_removed'])
        count=lambda x:f'{int(x):,}'
        spec=r19['provenance']['Source_specification'];limits=spec['Limits'];gap=limits['Gap_days_inclusive']
        ws=json.loads((weather_src/'analysis_specification.json').read_text(encoding='utf-8'))
        hours=sorted(int(h) for h in r10['weather_candidates']);windows=ws['Windows_days']
        check('Calendar_settings_present',len(hours)>0 and len(windows)>0 and 0<ws['Minimum_valid_fraction']<=1)
        flow=f.assign(Label=f.Stage.map(R21_STAGE_LABELS))
        flow.to_csv(audit/'Fig1_R21_plot_data.csv',index=False,encoding='utf-8-sig')
        # Fig. 1：左側顯示保留列；右側列出既有順序下所有互斥排除數，包括 0。
        with plt.rc_context({'font.family':'DejaVu Sans','font.size':11}):
            fig,ax=plt.subplots(figsize=(12,10));fig.subplots_adjust(0.02,0.02,.98,.98)
            ax.set(xlim=(0,1),ylim=(0,1));ax.axis('off')
            ax.text(.5,.974,'Cohort assembly and sequential exclusions',ha='center',fontsize=19,weight='bold',color='#17324D')
            ax.text(.5,.936,'Counts are linked records unless patients are explicitly specified.',ha='center',fontsize=11,color='#53677B')
            boxes=[(.80,f'Initial linked records\nn = {count(len(r05["row_flags"]))}'),
                (.66,f'Evaluable dates and |Hb report date − DXA date| ≤ {gap:g} days\nn = {count(n("Stage1b_Gap_over_180d"))}'),
                (.52,f'At least one available DXA T-score after masking\nn = {count(n("Stage2a_DXA_missing_after_mask"))}'),
                (.38,f'Clinical completeness: Hb, age and sex\nn = {count(n("Stage2d_Sex_unmapped_or_missing"))}'),
                (.24,f'Complete-case repeated-record cohort\n{count(len(repeated))} records; {count(repeated["去個資編號"].nunique())} patients')]
            for i,(y,t) in enumerate(boxes):
                r21_box(ax,.035,y,.57,.10,t,size=11.5)
                if i:r21_arrow(ax,(.32,boxes[i-1][0]-.008),(.32,y+.112))
            r21_box(ax,.035,.075,.57,.105,f'Primary analysis: one representative record per patient\n{count(len(primary))} records; {count(primary["去個資編號"].nunique())} patients',fill='#E7F2ED',color='#326F55',size=11.5)
            r21_arrow(ax,(.32,.232),(.32,.192))
            ax.text(.32,.207,f'{count(len(repeated)-len(primary))} eligible records not selected for primary',ha='center',fontsize=9.5,color='#53677B',bbox={'facecolor':'white','edgecolor':'none','pad':2})
            ax.text(.66,.88,'Sequential exclusions',fontsize=13,weight='bold',color='#17324D')
            for i,row in enumerate(flow.itertuples(index=False)):
                y=.827-i*.054
                label=row.Label.replace(' after masking','\nafter masking').replace(' / unmapped',' / unmapped')
                if row.Stage=='Stage1b_Gap_over_180d':label=f'Evaluable interval > {gap:g} days'
                if len(label)>37 and '\n' not in label:
                    import textwrap
                    label=textwrap.fill(label,35)
                ax.text(.66,y,label,va='center',fontsize=9.5,color='#243B53')
                ax.text(.97,y,count(row.Rows_removed),ha='right',va='center',fontsize=11,weight='bold')
            ax.plot([.65,.98],[.223,.223],color='#C4D0DB',lw=1)
            ax.text(.66,.193,'Total excluded',fontsize=11,weight='bold')
            ax.text(.97,.193,count(f.Rows_removed.sum()),ha='right',fontsize=12,weight='bold')
            ax.text(.5,.025,'Reason-specific counts depend on this order. Patients may have both included and excluded records.\nWeather exclusion denotes incomplete features in the existing linkage; specific upstream causes were not adjudicated.',ha='center',fontsize=9,color='#53677B',linespacing=1.5)
            files=r21_save_figure(fig,root,'Fig1_R21_Attrition')
        caption1=('Fig 1. Cohort assembly and sequential complete-case exclusions. '+
            f'Of {count(len(r05["row_flags"]))} linked records, {count(removed("Stage1a_Date_unevaluable"))} had unevaluable dates and '+
            f'{count(removed("Stage1b_Gap_over_180d"))} had an evaluable absolute interval exceeding {gap:g} days. '+
            'Subsequent mutually exclusive counts follow the stated processing order; missing T-score and Hb values include values masked by prespecified bounds. '+
            f'The complete-case cohort contains {count(len(repeated))} records from {count(repeated["去個資編號"].nunique())} patients; the primary analysis retains one representative record per patient. '+
            'Nonselected eligible records remain available for repeated-record analyses. Patient groups may overlap. Required-weather-feature incompleteness does not identify a specific station-level or spatial matching cause.')
        for stem,text in [('Fig1_R21',caption1)]:
            (root/'Text'/f'{stem}_caption.txt').write_text(text+'\n',encoding='utf-8')
        replacements=[{'Location':'Results — cohort assembly / Fig. 1 caption','Replacement':caption1},
            {'Location':'Methods — repeated-record sensitivity models','Replacement':'A supplementary within–between (Mundlak) random-intercept model was fitted to one selected record per patient–DXA-date proxy. Hb and varying adjustment columns were decomposed into patient means and within-patient deviations. Date proxies were not verified examination or specimen identifiers; random slopes were not fitted. See S9 Table.'},
            {'Location':'Methods — S8 reporting','Replacement':'S8 Table reports all fixed effects for the primary HC3 OLS and repeated-record REML random-intercept models. Random-intercept and residual variances are reported in squared outcome units with ICC. Variance-component standard errors and percentile intervals use the existing parametric REML bootstrap; no variance-component Wald P values are reported.'}]
        pd.DataFrame(replacements).to_csv(root/'Text/R21_targeted_manuscript_replacements.csv',index=False,encoding='utf-8-sig')
        check('Figure1_totals_from_existing_sources')
        r21_json(audit/'SLIM_FIG1_provenance.json',{'Source_R19':str(src),'Source_R10':str(weather_src),
            'R19_flow_SHA256':r21_sha(src/'PartB_Flow.csv'),'R10_specification_SHA256':r21_sha(weather_src/'analysis_specification.json'),
            'Hb_date_meaning':'laboratory_report_date','Gap_limit_days':gap,'Weather_hours':hours,'Windows_days':windows})
        status.update(Completed=True,Figures_exported=1,Checks=len(checks),All_passed=True)
        print('\n=== 請回傳：SLIM_FIG1 1 排除明細 ===');print(flow.to_string(index=False))
        print('\n=== 請回傳：SLIM_FIG1 2 圖檔規格 ===');print(pd.DataFrame(files).to_string(index=False))
        print('\n=== 請回傳：SLIM_FIG1 3 驗證 ===');print(pd.DataFrame([status]).to_string(index=False));print(root)
        return {'Completed':True,'status':status,'output_dir':str(root),'files':pd.DataFrame(files)}
    except Exception as exc:status.update(Error_type=type(exc).__name__,Error=str(exc));raise
    finally:
        pd.DataFrame(checks).to_csv(audit/'SLIM_FIG1_validation.csv',index=False,encoding='utf-8-sig')
        r21_json(audit/'SLIM_FIG1_status.json',status)


SLIM_FIG1=None
_r21_missing=[k for k in ['R21A','R05','R19','R10','df_primary','df_sensitivity'] if k not in globals()]
if _r21_missing:raise NameError(f'請先完成來源格；缺少 {_r21_missing}。')
SLIM_FIG1=slim_run_fig1(R21A,R05,R19,R10,df_primary,df_sensitivity)

"""## Intermediate aggregate collection

Input objects are produced by preceding cells in this notebook. Outputs remain private working artifacts until the publication export section.

"""

# 凍結原圖表；僅從明確的本次來源收集新增／核准修訂候選。
import shutil
import importlib.metadata

R21C_STATUS_FILES={
 'R13':'R13_run_status.json',
 'R14':'R14_run_status.json',
 'R16':'run_status.json',
 'R17':'run_status.json',
 'R18':'run_status.json',
 'R19':'run_status.json',
 'R20':'run_status.json'}

def r21c_source(obj,label):
    # 明確對應原模組的輸出契約；缺檔就停止，不試讀其他檔名或舊資料夾。
    r21_require(label in R21C_STATUS_FILES,'未定義來源狀態檔名：'+label)
    r21_require(isinstance(obj,dict) and obj.get('Completed') is True,label+' 尚未完成')
    p=Path(obj['output_dir'])
    r21_require(p.is_dir(),label+' output_dir 不存在')
    status_path=p/R21C_STATUS_FILES[label]
    if not status_path.is_file():
        raise FileNotFoundError(f'R21C：{label} 應有的狀態檔不存在：{status_path}；停止，不使用替代來源。')
    saved=json.loads(status_path.read_text(encoding='utf-8'))
    r21_require(isinstance(saved,dict) and saved.get('Completed') is True,label+' 存檔狀態未完成')
    # R13／R14／R20 將 All_passed 寫入狀態；R16–R19 僅在獨立驗證表報告。
    if label in {'R13','R14','R20'}:
        r21_require(saved.get('All_passed') is True,label+' 存檔驗證未全部通過')
    memory=obj.get('status')
    r21_require(isinstance(memory,dict) and memory.get('Completed') is True,label+' 記憶體完成狀態缺失')
    normalized=json.loads(json.dumps(memory,ensure_ascii=False,default=str))
    r21_require(saved==normalized,label+' 記憶體與存檔狀態不同')
    return p

R21_EXPORTS={
 'R13':('S13_Table_R13_Calendar_Weather_Classification.xlsx','S13_Table_R13_notes.txt'),
 'R14':('S14_Table_R14_Weather_Completeness_and_Model_Sensitivity.xlsx','S14_Table_R14_caption_and_notes.txt'),
 'R16':('S9_Table_R16_Date_Proxy_and_Mundlak.xlsx','S9_Table_R16_caption_and_notes.txt'),
 'R17':('S10_Table_R17_Temporal_Dependence.xlsx','S10_Table_R17_caption_and_notes.txt'),
 'R18':('S11_Table_R18_Fixed_Site_Common_Subset.xlsx','S11_Table_R18_caption_and_notes.txt'),
 'R19':('S12_Table_R19_Attrition_and_Group_Description.xlsx','S12_Table_R19_caption_and_notes.txt')}

def r21_check_existing_book(path,tables,label,caption_path):
    # R13 的出版標籤與數值代碼有明確轉換；其餘出版表僅將欄名底線改為空白。
    prepared={}
    labels={'Minimum_hours':'Minimum valid hours/day','Test_rows_total':'Forward-test participants (n)',
        'Test_years':'Test years (n)','AUC_fold_mean':'Annual AUC mean','AUC_fold_SD':'Annual AUC SD',
        'Brier_fold_mean':'Annual Brier mean','Brier_fold_SD':'Annual Brier SD','R11_rows':'30-day eligible rows',
        'R12_eligible_rows':'Classification eligible rows','R12_eligible_patients':'Classification eligible patients',
        'Initial_years_not_tested_rows':'Initial-year rows not tested','Operational_category_positive_rows':'Positive category among eligible rows',
        'SD_delta_AUC_across_years':'SD of annual delta AUC','SD_delta_Brier_across_years':'SD of annual delta Brier'}
    for name,table in tables.items():
        t=table.copy(deep=True)
        if label=='R13':
            if 'Algorithm' in t:t['Algorithm']=t.Algorithm.replace({'Logistic_Regression':'Logistic regression'})
            if 'Feature_set' in t:t['Feature_set']=t.Feature_set.replace(dict(zip(R13_FEATURES,R13_LABELS)))
            if 'Comparison' in t:t['Comparison']=t.Comparison.replace({'Added_calendar':'Calendar added to clinical','Added_weather_after_calendar':'Weather added after calendar'})
            for c in t:
                if pd.api.types.is_bool_dtype(t[c]):t[c]=t[c].map({True:'Yes',False:'No'})
            t=t.rename(columns={c:labels.get(c,c.replace('_',' ')) for c in t})
        else:t=t.rename(columns={c:str(c).replace('_',' ') for c in t})
        prepared[name]=t
    tables=prepared
    book=load_workbook(path,data_only=False)
    try:
        expected_sheets=set(tables)
        if label=='R13':
            # R13 回傳的 tables 不含 Methods；該頁由原 notes 清單另外建立。
            # Topic 可為 "Features: Clinical"，不能以第一個冒號拆回兩欄。
            r21_require('Methods' not in tables,'R13 tables 結構與本版來源定義不同')
            expected_sheets.add('Methods')
        r21_require(set(book.sheetnames)==expected_sheets,'既有活頁簿工作表與本次物件不同：'+path.name)
        if label=='R13':
            ws=book['Methods']
            r21_require(ws.max_column==2 and ws.max_row>1
                and [c.value for c in ws[1]]==['Topic','Description'],'R13 Methods 欄位結構不符')
            notes=list(ws.iter_rows(min_row=2,values_only=True))
            r21_require(all(isinstance(a,str) and a and isinstance(b,str) and b for a,b in notes),
                'R13 Methods 標題或說明缺失')
            r21_require(all(c.data_type!='f' for row in ws.iter_rows(min_row=2) for c in row),
                'R13 Methods 不應含公式')
            # 與原 r13_run 相同：先組回 "Topic: Description"，再以空白行連接。
            # 不刪除冒號、不改大小寫、不壓縮空白，也不跳過說明核對。
            serialized='\n\n'.join(f'{a}: {b}' for a,b in notes)+'\n'
            saved_notes=Path(caption_path).read_text(encoding='utf-8')
            r21_require(serialized==saved_notes,
                f'{path.name}／Methods 說明與 {Path(caption_path).name} 不一致')
        for name,t in tables.items():
            ws=book[name]
            r21_require([c.value for c in ws[1]]==list(t.columns),'工作表欄位不同：'+name)
            r21_require(ws.max_row==max(1,len(t)+1),'工作表列數不同：'+name)
            for rr,row in enumerate(t.itertuples(index=False,name=None),2):
                for cc,v in enumerate(row,1):
                    got=ws.cell(rr,cc).value
                    if pd.isna(v) or v=='':ok=got is None
                    elif isinstance(v,(pd.Timestamp,datetime,np.datetime64)):ok=pd.Timestamp(got)==pd.Timestamp(v)
                    elif isinstance(v,(float,np.floating)):ok=isinstance(got,(int,float)) and np.isclose(v,got,rtol=1e-9,atol=1e-11)
                    else:ok=got==v
                    r21_require(ok,f'{path.name}／{name}!{ws.cell(rr,cc).coordinate}（{t.columns[cc-1]}）的既有輸出與物件不一致')
    finally:book.close()

def slim_collect(sources, s8, fig1, fig3_paths, root, versions):
    # 先查驗全部來源，再進行複製；中途失敗不標示 Completed。
    required=set(R21_EXPORTS)|{'R20'}
    r21_require(set(sources)==required,'彙總來源清單不符')
    r21_require(s8.get('Completed') is True and fig1.get('Completed') is True,'S8／Fig1 尚未完成')
    s8root=Path(s8['output_dir'])
    r21_require(s8root==Path(fig1['output_dir']),'S8 與 Fig1 執行版本不同')
    r21_require(s8['status']['All_passed'] is True and fig1['status']['All_passed'] is True,'S8／Fig1 驗證未完成')
    for name,table in s8['tables'].items():r21_csv_check(table,s8root/'Audit'/(name+'.csv'))
    r21_check_existing_book(s8root/'Tables/S8_Table_R21_Complete_Model_Results.xlsx',
        s8['tables'],'S8',s8root/'Text/S8_Table_R21_caption_and_notes.txt')
    queue=[]
    def add(path,section,label):
        p=Path(path)
        r21_require(p.is_file(),'明列來源不存在：'+str(p))
        queue.append((p,section,label,r21_sha(p)))
    for label,(book,caption) in R21_EXPORTS.items():
        directory=r21c_source(sources[label],label)
        r21_check_existing_book(directory/book,sources[label]['tables'],label,directory/caption)
        add(directory/book,'Tables',label);add(directory/caption,'Text',label)
    r20root=r21c_source(sources['R20'],'R20')
    for name,table in sources['R20']['tables'].items():r21_csv_check(table,r20root/(name+'.csv'))
    add(r20root/'R20_count_definitions.txt','Text','R20')
    r13root=Path(sources['R13']['output_dir'])
    for ext in ['png','tif']:add(r13root/f'S3_Fig_R13.{ext}','Figures','R13')
    add(r13root/'S3_Fig_R13_caption.txt','Text','R13')
    add(r13root/'S3_Fig_R13_plot_data.csv','Audit','R13 aggregate plot data')
    add(s8root/'Tables/S8_Table_R21_Complete_Model_Results.xlsx','Tables','R21A')
    add(s8root/'Text/S8_Table_R21_caption_and_notes.txt','Text','R21A')
    for ext in ['png','tif']:add(s8root/f'Figures/Fig1_R21_Attrition.{ext}','Figures','Fig1')
    add(s8root/'Text/Fig1_R21_caption.txt','Text','Fig1')
    add(s8root/'Audit/Fig1_R21_plot_data.csv','Audit','Fig1 aggregate plot data')
    for p in fig3_paths:
        with Image.open(p) as im:
            r21_require(im.mode=='RGB' and all(abs(x-300)<.1 for x in im.info['dpi']),'Fig3 規格未通過')
        add(p,'Figures','Fig3')
    r21_require(len(queue)==len({(section,p.name) for p,section,_,_ in queue}),'輸出名稱重複')
    # 時間戳新目錄；不複寫舊 OUTPUT、原稿、原表或原圖。
    out=Path(root)/'OUTPUT'/('Supplement_First_'+datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')+'_'+uuid.uuid4().hex[:8])
    out.mkdir(parents=True,exist_ok=False)
    for section in ['Tables','Figures','Text','Audit']:(out/section).mkdir()
    status={'Completed':False,'New_models_fitted':0,'Patient_records_exported':False,
        'Original_manuscript_modified':False,'Original_supplement_modified':False,
        'Frozen_items_overwritten':False,'Final_submission_package_complete':False}
    records=[]
    try:
        for p,section,label,digest in queue:
            r21_require(r21_sha(p)==digest,'複製前來源變動：'+p.name)
            dest=out/section/p.name
            shutil.copy2(p,dest)
            r21_require(r21_sha(dest)==digest and r21_sha(p)==digest,'複製後雜湊不符：'+p.name)
            records.append({'Artifact':dest.name,'Section':section,'Source_module':label,
                'Source_path':str(p),'SHA256':digest,'Bytes':dest.stat().st_size})
        # S15 僅格式化既有 R20 彙總，不重新讀個案或計算分母。
        r21_book(sources['R20']['tables'],out/'Tables/S15_Table_Age_Sex_Counts.xlsx')
        caption=('S15 Table. Recorded age and sex distributions in the primary and repeated-record cohorts. '
            'Values are existing R20 counts. Primary counts represent one selected record per patient. '
            'Repeated-record rows are eligible pairs; unique patients may occur in more than one age band. '
            'Age and sex do not establish menopause status, availability of Z-scores, or adjudicated diagnostic eligibility. '
            'Recorded age values and the original cohort selection were retained.')
        (out/'Text/S15_Table_caption_and_notes.txt').write_text(caption+'\n',encoding='utf-8')
        caption3=('Fig 3. Conceptual distinction between short-term systemic context and longer-term skeletal status. '
            'Solid arrows depict proposed mechanisms, not pathways established by this study. '
            'The undirected dashed Hb–DXA link denotes a cross-sectional non-causal association. '
            'Listed host factors were not necessarily measured or adjusted for; the figure does not establish mediation.')
        (out/'Text/Fig3_caption.txt').write_text(caption3+'\n',encoding='utf-8')
        disposition=[
            ('Table 1–5; Fig 2; S1–S7 Table; S1–S2 Fig','Frozen original items','No original file copied, replaced or renumbered by this cell'),
            ('Fig 1; Fig 3; S8 Table','Same-number revision candidates','Adopt after manuscript and caption integration'),
            ('S9 Table','Existing addition retained','R06/R07/R16: date proxies, reuse, models and Mundlak'),
            ('S10 Table','Existing addition retained','R08/R17: temporal dependence and dependent wild bootstrap'),
            ('S11 Table','Existing addition retained','R01/R02/R18: fixed-site and common-subset sensitivity'),
            ('S12 Table','Existing addition retained','R05/R19: attrition and included/excluded descriptions'),
            ('S13 Table; S3 Fig','New supplementary items','R12/R13: calendar-adjusted forward classification; original S5 and S2 Fig preserved'),
            ('S14 Table','New supplementary item','R09/R10/R11/R14: hourly coverage, calendar windows and model sensitivity; original S6 preserved'),
            ('S15 Table','New supplementary item','R20: recorded age and sex counts; original Table 2 preserved')]
        pd.DataFrame(disposition,columns=['Item','Disposition','Source_and_scope']).to_csv(
            out/'Text/Publication_status_map.csv',index=False,encoding='utf-8-sig')
        note=('Supplementary interpretation and version note\n\n'
            'Original Tables 1–5, Fig 2, S1–S7 Tables and S1–S2 Figs are retained as the submitted historical analyses. '
            'They are not revalidated by exporting the new supplementary analyses. The calendar-window and dependence '
            'checks cannot be transferred to the retained historical classifier benchmarks, coefficient product or spline diagnostic. '
            'Unreconstructed historical long-window features remain a methodological limitation.\n\n'
            'The expanded analyses are S9 (date proxies and Mundlak), S10 (temporal dependence), S11 (fixed-site outcomes), '
            'S12 (attrition), S13 and S3 Fig (calendar-adjusted forward classification), S14 (weather completeness and model sensitivity), '
            'and S15 (age/sex counts). Earlier R13/R14 internal outputs were labelled revised S5/S6 and S2 Fig; '
            'those are lineage labels, not the publication labels in this package.\n\n'
            'Hb_Date denotes laboratory report date. Date proxies are not verified examination or specimen identifiers. '
            'Hip subregion, scanner/reference information, residual clinical confounding and unresolved temporal age consistency '
            'must retain their stated limitations. Classification remains exploratory; within/between decomposition is associational.\n\n'
            'Methods and Results should replace obsolete statements that attrition was not partitioned or that no Mundlak analysis '
            'was performed, and cite the new supplements. Original tables and their numbering remain unchanged. '
            'The original frozen Table 3 conditional-THI P display and current S8 may differ in the last printed decimal; '
            'this discrepancy should be disclosed in the supplementary version note rather than silently overwritten.\n\n'
            'Abstract/Discussion revision and public code/data-dictionary archive/DOI are deferred. '
            'This local output directory is not a public deposit or a completed submission package.\n')
        (out/'Text/Supplementary_Interpretation_and_Version_Note.txt').write_text(note,encoding='utf-8')
        # 建立全檔名單；僅列出本函式明確產出的三個資料夾，不收集 PRIVATE 稽核。
        registered={(r['Section'],r['Artifact']) for r in records}
        for section in ['Tables','Figures','Text']:
            for p in sorted((out/section).iterdir()):
                if (section,p.name) not in registered:
                    records.append({'Artifact':p.name,'Section':section,'Source_module':'Supplement-first packaging',
                        'Source_path':'','SHA256':r21_sha(p),'Bytes':p.stat().st_size})
        manifest=pd.DataFrame(records)
        manifest.to_csv(out/'Audit/Publication_manifest.csv',index=False,encoding='utf-8-sig')
        r21_json(out/'Audit/runtime_versions.json',versions)
        r21_json(out/'Audit/source_directories.json',{k:v['output_dir'] for k,v in sources.items()})
        status.update(Completed=True,All_passed=True,Files_registered=len(manifest),
            S9_to_S12_numbering_preserved=True,Original_fig2_not_redrawn=True,
            Publication_labels=['S8','S9','S10','S11','S12','S13','S14','S15','Fig1','Fig3','S3 Fig'])
        print('\n=== 請回傳：精簡版 1 出版檔案清單 ===')
        print(manifest[['Artifact','Section','Bytes']].to_string(index=False))
        print('\n=== 請回傳：精簡版 2 凍結與新增對照 ===')
        print(pd.DataFrame(disposition,columns=['Item','Disposition','Source_and_scope']).to_string(index=False))
        print('\n=== 請回傳：精簡版 3 輸出狀態 ===')
        print(pd.DataFrame([status]).to_string(index=False))
        print('集中輸出：',out)
        return {'Completed':True,'output_dir':str(out),'manifest':manifest,'status':status}
    finally:
        r21_json(out/'Audit/run_status.json',status)

