"""## Original-specification utilities

Input objects are produced by preceding cells in this notebook. Outputs remain private working artifacts until the publication export section.

"""

# 原稿數字只存為 legacy fixed benchmark；所有新表格由本次資料／模型計算。
from pathlib import Path
from datetime import datetime, timezone
import json, hashlib, uuid, re, warnings, shutil, html, sys, importlib, importlib.util, subprocess
import numpy as np
import pandas as pd
import scipy.stats as st
import statsmodels.api as sm
import patsy
from openpyxl import load_workbook
from openpyxl.styles import Font, PatternFill, Alignment

ORIGINAL_REPRODUCTION = None
OR_SEED = 42
OR_BOOTSTRAP_DRAWS = 5000        # 原稿已指定的重抽樣規格，非預期結果筆數。
OR_CV_FOLDS = 5
OR_AGE_CUT = 65
OR_S6_WINDOW = 30
OR_S6_MIN_VALID = 27
OR_ALPHA = .05
OR_PID = '去個資編號'
OR_PAIR = 'pairing_row_id'
OR_DXA = '骨密度檢查執行日期'
OR_WEATHER = ['THI_mean_30d','DTR_mean_30d','THI_std_30d','T_std_30d',
              'THI_mean_180d','THI_hot_days_365d','THI_Trend_Shock']

def or_require(ok, message):
    if not bool(ok):
        raise ValueError('原稿重現：'+message+'；停止，不改用固定數字或其他資料。')

def or_sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()

def or_json(path, value):
    Path(path).write_text(json.dumps(value, ensure_ascii=False, indent=2, default=str), encoding='utf-8')

def or_fingerprint(d):
    return hashlib.sha256(pd.util.hash_pandas_object(d, index=True).values.tobytes()
        + repr(list(d.columns)).encode()+repr(list(d.dtypes.astype(str))).encode()).hexdigest()

def or_prepare(d, primary=False):
    required=[OR_PID,OR_PAIR,OR_DXA,'Hb_Date','Age','年齡','sex_bin','Hb_Value','overall_T',
              'L_T','Left_T','Right_T','is_osteoporosis',*OR_WEATHER]
    or_require(not d.empty and d.columns.is_unique and not set(required)-set(d),'來源缺欄位／空表')
    q=d.copy(deep=True).reset_index(drop=True)
    or_require(q[[OR_PID,OR_PAIR]].notna().all().all() and q[OR_PAIR].is_unique,'配對 ID 缺失或重複')
    if primary:or_require(q[OR_PID].is_unique,'Primary 不是一人一列')
    nums=['Age','年齡','sex_bin','Hb_Value','overall_T','THI_mean_30d','DTR_mean_30d']
    q[nums]=q[nums].apply(pd.to_numeric,errors='raise')
    or_require(np.isfinite(q[nums]).all().all(),'主要數值缺失／無限值')
    or_require(np.array_equal(q.Age,q['年齡']),'年齡別名不同')
    or_require(q.sex_bin.isin([0,1]).all(),'性別編碼不是 0／1')
    or_require(np.allclose(q.overall_T,q[['L_T','Left_T','Right_T']].min(axis=1)), 'minimum T 不一致')
    or_require(np.array_equal(q.is_osteoporosis,q.overall_T.le(-2.5).astype(int)),'操作性類別不一致')
    for prefix,col in [('hb','Hb_Date'),('dxa',OR_DXA)]:
        q[col]=pd.to_datetime(q[col],errors='raise')
        or_require(q[col].notna().all(),col+' 缺失')
        q[prefix+'_year']=q[col].dt.year.astype(int)
        q[prefix+'_sin']=np.sin(2*np.pi*q[col].dt.month/12)
        q[prefix+'_cos']=np.cos(2*np.pi*q[col].dt.month/12)
    q['signed_gap_days']=(q[OR_DXA]-q.Hb_Date).dt.days
    q['abs_gap_days']=q.signed_gap_days.abs()
    or_require(q.abs_gap_days.le(180).all(),'原世代出現超出原配對窗列')
    return q

def or_formula(which, calendar='full', anchor=None, thi='THI_mean_30d', dtr='DTR_mean_30d'):
    anchor=anchor or ('hb' if which=='A' else 'dxa')
    lhs='Hb_Value' if which=='A' else 'overall_T'
    rhs=([] if which=='A' else ['Hb_Value'])+[thi,dtr,'Age','sex_bin']
    if calendar in ['month','full']:rhs += [anchor+'_sin',anchor+'_cos']
    if calendar in ['year','full']:rhs += [f'C({anchor}_year)']
    return lhs+' ~ '+' + '.join(rhs)

def or_fit(formula, d, label, allow_spline_rank=False):
    y,X=patsy.dmatrices(formula,d,return_type='dataframe',NA_action='raise',eval_env=-1)
    rank=np.linalg.matrix_rank(X)
    or_require(len(X)==len(d) and len(X)>rank, label+' 模型列數或自由度不合法')
    # 原 cr(df=4) 加截距有一個預期常數冗餘；只允許這個已記錄的特例。
    or_require(rank==X.shape[1] or (allow_spline_rank and rank==X.shape[1]-1), label+' 設計矩陣非預期秩不足')
    with warnings.catch_warnings(record=True) as ws:
        warnings.simplefilter('always')
        fit=sm.OLS(y.iloc[:,0],X,missing='raise').fit()
        robust=fit.get_robustcov_results(cov_type='HC3',use_t=False)
    or_require(np.isfinite(fit.params).all() and np.isfinite(robust.bse).all(),label+' 非有限配適值')
    return {'fit':fit,'hc3':robust,'X':X,'y':y.iloc[:,0].to_numpy(),'label':label,
            'formula':formula,'n':len(d),'patients':d[OR_PID].nunique(),
            'warnings':[str(w.message) for w in ws], 'rank':int(rank)}

def or_term(model, term, label=None):
    if isinstance(model,dict):
        fit=model['hc3'];names=list(model['X']);n=model['n'];patients=model['patients'];inf='HC3_normal_Wald'
    else:
        fit=model;names=list(fit.model.exog_names);n=int(fit.nobs)
        patients=len(np.unique(fit.model.groups));inf='LMM_model_based_normal_Wald'
    j=names.index(term);ci=np.asarray(fit.conf_int(alpha=OR_ALPHA))[j]
    return {'Model':label or (model['label'] if isinstance(model,dict) else 'LMM'),
        'Term':term,'N':n,'Patients':patients,'Beta':float(np.asarray(fit.params)[j]),
        'SE':float(np.asarray(fit.bse)[j]),'CI_low':float(ci[0]),'CI_high':float(ci[1]),
        'P':float(np.asarray(fit.pvalues)[j]),'Inference':inf}

def or_vif(X):
    rows=[];a=np.asarray(X,dtype=float)
    for j,c in enumerate(X.columns):
        if c=='Intercept':continue
        fit=sm.OLS(a[:,j],np.delete(a,j,axis=1),missing='raise').fit()
        r=float(fit.rsquared)
        or_require(np.isfinite(r) and r<1, f'{c} 的 auxiliary R² 不合法／完全共線')
        rows.append({'Term':c,'VIF':1/(1-r),'Auxiliary_R2':r})
    return pd.DataFrame(rows)

def or_p(p):
    return '< 0.001' if p<.001 else f'{p:.4f}'

def or_coef(r, ci=False):
    s=f"{r['Beta']:+.4f} ({r['SE']:.4f})"
    return s+(f"; 95% CI [{r['CI_low']:+.4f}, {r['CI_high']:+.4f}]; P {or_p(r['P'])}" if ci else '')

def or_same_inputs(ctx):
    for label,d in [('Primary',R05['df_primary']),('Repeated',R05['df_sensitivity']),('Weather',R05['weather_df'])]:
        or_require(or_fingerprint(d)==ctx['input_hashes'][label],label+' 在 O00 後變更；請從 O00 重跑')

def or_export(ctx,key,tables,notes,section='Supplementary_Tables'):
    or_same_inputs(ctx)
    or_require(key not in ctx['completed'],key+' 已存在；重跑請從 O00 開新版本，避免混用結果')
    dest=ctx['out']/section;dest.mkdir(exist_ok=True)
    book=dest/(key+'_rerun.xlsx')
    with pd.ExcelWriter(book,engine='openpyxl') as writer:
        for name,t in tables.items():
            or_require(len(name)<=31 and t.columns.is_unique,'工作表名稱／欄名不合法')
            or_require(not {OR_PID,OR_PAIR,'source_row_id','raw_row_id'} & set(t.columns),'出版表不得包含個案 ID')
            t.to_excel(writer,sheet_name=name,index=False)
            t.to_csv(ctx['out']/'Audit'/(key+'__'+name+'.csv'),index=False,encoding='utf-8-sig')
        notes_df=pd.DataFrame({'Notes':notes if isinstance(notes,list) else [notes]})
        notes_df.to_excel(writer,sheet_name='Notes',index=False)
        for ws in writer.book.worksheets:
            ws.freeze_panes='A2';ws.auto_filter.ref=ws.dimensions
            for c in ws[1]:c.font=Font(name='Arial',bold=True,color='FFFFFF');c.fill=PatternFill('solid',fgColor='17365D')
            for col in ws.columns:
                letter=col[0].column_letter
                ws.column_dimensions[letter].width=min(72,max(15,max(len(str(c.value or '')) for c in col[:25])+2))
                for c in col[1:]:c.alignment=Alignment(vertical='top',wrap_text=True)
    # 寫檔後逐格核對值與數值精度；不把「有檔案」當成結果完整。
    check=load_workbook(book,read_only=True,data_only=True)
    for name,t in tables.items():
        ws=check[name]
        or_require(ws.max_row==len(t)+1,key+'/'+name+' 輸出列數不符')
        for saved,original in zip(ws.iter_rows(min_row=2,values_only=True),t.itertuples(index=False,name=None)):
            for a,b in zip(saved,original):
                if pd.isna(b) or b=='':ok=(a is None or a=='')
                elif isinstance(b,(bool,np.bool_)):ok=isinstance(a,bool) and a==bool(b)
                elif isinstance(b,(int,float,np.number)):ok=isinstance(a,(int,float)) and np.isclose(a,b,rtol=1e-12,atol=1e-14)
                elif isinstance(b,(pd.Timestamp,datetime)):ok=pd.Timestamp(a)==pd.Timestamp(b)
                else:ok=str(a)==str(b)
                or_require(ok,key+'/'+name+' 匯出後數值不一致')
    check.close()
    text='\n\n'.join(notes_df.Notes.astype(str))
    (ctx['out']/'Notes'/(key+'_caption_and_notes.txt')).write_text(text,encoding='utf-8')
    display_tables={k:v for k,v in tables.items() if k.startswith('Display')}
    if display_tables:
        body='\n'.join('<h2>'+html.escape(k)+'</h2>'+v.to_html(index=False,escape=True) for k,v in display_tables.items())
        (dest/(key+'_for_Word.html')).write_text('<meta charset="utf-8"><style>table{border-collapse:collapse;font:10pt Arial}th,td{border:1px solid #aaa;padding:6px}th{background:#eaf0f6}</style>'+body+'<p>'+html.escape(text)+'</p>',encoding='utf-8')
    ctx['completed'][key]={'path':str(book),'SHA256':or_sha(book),'sheets':list(tables)}
    or_json(ctx['out']/'Audit/module_status.json',ctx['completed'])
    print(key+' 已輸出：'+str(book))

def or_start(r05,r08,r15,r21a,package,root):
    for name,obj in [('R05',r05),('R08',r08),('R15',r15),('R21A',r21a),('SLIM_PACKAGE',package)]:
        or_require(isinstance(obj,dict) and obj.get('Completed') is True,name+' 未完成')
    p=or_prepare(r05['df_primary'],True);r=or_prepare(r05['df_sensitivity'])
    out=Path(root)/'OUTPUT'/('Full_Reproduction_'+datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')+'_'+uuid.uuid4().hex[:8])
    out.mkdir(parents=True,exist_ok=False)
    for part in ['Main_Tables','Supplementary_Tables','Figures','Notes','Audit']: (out/part).mkdir()
    versions={x:importlib.import_module(x).__version__ for x in ['numpy','pandas','scipy','statsmodels','patsy']}
    ctx={'out':out,'primary':p,'repeated':r,'completed':{},'checks':[],'models':{},'versions':versions,
         'input_hashes':{k:or_fingerprint(d) for k,d in [('Primary',r05['df_primary']),('Repeated',r05['df_sensitivity']),('Weather',r05['weather_df'])]},
         'revision_package':package,'table_cache':{},'legacy_checks':[]}
    or_json(out/'Audit/runtime_versions.json',versions)
    or_json(out/'Audit/source_scope.json',{'Code_reference':'self-contained analysis implementation',
        'Cohort_source':'R05 current; no reselection','Weather_source':'R05 legacy row-window features for original-specification reproduction',
        'Revised_weather_results':'Separate S13/S14/S3 Fig from R09–R14; not used to replace legacy feature definitions',
        'Bootstrap_draws':OR_BOOTSTRAP_DRAWS,'CV_folds':OR_CV_FOLDS,'Seed':OR_SEED,
        'Historical_display_values':'Legacy fixed benchmarks only; never model inputs or output fallbacks'})
    return ctx

