"""## Table2 and S1 descriptions

Input objects are produced by preceding cells in this notebook. Outputs remain private working artifacts until the publication export section. Manuscript items: Table 2; S1 Table.

"""

def or_descriptive(d, repeated=False):
    t=d.overall_T
    groups=[pd.Series(True,index=d.index),t.le(-2.5),t.gt(-2.5)&t.lt(-1),t.ge(-1)]
    counts=[int(x.sum()) for x in groups]
    or_require(sum(counts[1:])==counts[0],'T-score 分組沒有完整分割世代')
    headers=['Characteristic',f"{'All records' if repeated else 'Total'} (N = {len(d):,})",
        f'T-score ≤−2.5 (n = {counts[1]:,})',f'−2.5 < T-score <−1.0 (n = {counts[2]:,})',f'T-score ≥−1.0 (n = {counts[3]:,})']
    rows=[];numeric=[]
    if not repeated:
        rows.append(['Unique patients, n (%)',f'{len(d):,}',*[f'{n:,} ({n/len(d)*100:.1f}%)' for n in counts[1:]]])
    for name,c in [('Age, years (mean ± SD)','Age'),('Hemoglobin, g/dL (mean ± SD)','Hb_Value'),
                   ('30-day mean THI (mean ± SD)','THI_mean_30d'),('30-day mean DTR, °C (mean ± SD)','DTR_mean_30d')]:
        values=[]
        for j,g in enumerate(groups):
            v=pd.to_numeric(d.loc[g,c],errors='raise');n=int(v.notna().sum())
            or_require(n==int(g.sum()) and n>1 and np.isfinite(v).all(),'描述欄位缺失／分組太小：'+name)
            values.append(f'{v.mean():.1f} ± {v.std(ddof=1):.1f}')
            numeric.append({'Variable':c,'Group':j,'N':n,'Mean':v.mean(),'SD':v.std(ddof=1),'Count':np.nan,'Denominator':n,'Percent':np.nan})
        rows.append([name,*values])
    anemia=((d.sex_bin.eq(1)&d.Hb_Value.lt(13))|(d.sex_bin.eq(0)&d.Hb_Value.lt(12)))
    families=[('Age subgroups, n (row %)',[
        ('<65 years','Age <65 years, n (%)',d.Age.lt(65)),
        ('65–79 years','Age 65–79 years, n (%)',d.Age.ge(65)&d.Age.lt(80)),
        ('≥80 years','Age ≥80 years, n (%)',d.Age.ge(80))]),
        ('Sex, n (row %)',[('Female','Female sex, n (%)',d.sex_bin.eq(0)),('Male','Male sex, n (%)',d.sex_bin.eq(1))]),
        ('Hematologic status, n (row %)',[('Normal','Normal hemoglobin, n (%)',~anemia),('Anemia','Anemia, n (%)',anemia)]),
        ('30-day THI descriptive bins, n (row %)',[
        ('THI <21','THI <21, n (%)',d.THI_mean_30d.lt(21)),
        ('21≤THI<24','21 ≤ THI <24, n (%)',d.THI_mean_30d.ge(21)&d.THI_mean_30d.lt(24)),
        ('24≤THI<27','24 ≤ THI <27, n (%)',d.THI_mean_30d.ge(24)&d.THI_mean_30d.lt(27)),
        ('THI≥27','THI ≥27, n (%)',d.THI_mean_30d.ge(27))])]
    for family,levels in families:
        or_require(np.asarray([x[2] for x in levels]).sum(axis=0).tolist()==[1]*len(d),family+' 分組不互斥／不完整')
        if not repeated:rows.append([family,'','','',''])
        for label,slabel,mask in levels:
            n=int(mask.sum());total=f'{n:,} ({n/len(d)*100:.1f}%)' if repeated else f'{n:,}'
            vals=[total]
            for j,g in enumerate(groups):
                m=int((mask&g).sum());den=len(d) if j==0 else n
                pct=100*m/den if den else np.nan
                numeric.append({'Variable':slabel,'Group':j,'N':int(g.sum()),'Mean':np.nan,'SD':np.nan,
                    'Count':m,'Denominator':den,'Percent':pct})
                if j:vals.append(f'{m:,} ({pct:.1f}%)' if den else '0 (not applicable)')
            rows.append([slabel if repeated else '• '+label,*vals])
    return pd.DataFrame(rows,columns=headers),pd.DataFrame(numeric),pd.DataFrame({'Group':range(4),'Analysis_rows':counts})

def or_run_descriptive(ctx):
    or_same_inputs(ctx)
    for label,data,rep,section in [('Table2',ctx['primary'],False,'Main_Tables'),('S1_Table',ctx['repeated'],True,'Supplementary_Tables')]:
        display,numeric,den=or_descriptive(data,rep)
        or_export(ctx,label,{'Display':display,'Numeric':numeric,'Group_denominators':den},[
            label+'. Baseline characteristics and clinical profile across bone-density categories in the primary patient cohort (N = 5,003).',
            'Continuous values: mean and sample SD within each T-score column. Category-cell percentages use the categorical row total; repeated-record total-column percentages use all repeated records.',
            'T-score categories are operational labels, not adjudicated diagnoses. Repeated records are not independent patients. No ANOVA, chi-square or independence-based group P values are produced.'],section)
        ctx['table_cache'][label]=display
        print(display.to_string(index=False))
    ctx['checks'].append({'Check':'Table2_and_S1_all_Tscore_groups_computed','Passed':True})
    return {'Completed':True}

