"""## Table3/Table4 and S2 model diagnostics

Input objects are produced by preceding cells in this notebook. Outputs remain private working artifacts until the publication export section. Manuscript items: Table 3; Table 4.

"""

def or_borrow_primary(ctx,which):
    src=R08['models'][which];d=ctx['primary']
    formula=R08['tables']['model_specifications'].set_index('Model').loc[which,'Formula']
    y,X=patsy.dmatrices(formula,d,return_type='dataframe',NA_action='raise',eval_env=-1)
    or_require(list(X)==list(src['X']) and np.allclose(X,src['X'],rtol=1e-12,atol=1e-12)
        and np.array_equal(y.iloc[:,0],src['y']),'R08 Model '+which+' 與現行列序／數值不同')
    return {**src,'label':'Primary_'+which,'formula':formula,'n':len(d),'patients':d[OR_PID].nunique(),
            'warnings':[],'rank':int(np.linalg.matrix_rank(X))}

def or_run_models(ctx):
    or_same_inputs(ctx);p=ctx['primary'];models=ctx['models']
    for which in ['A','B']:
        models['Unadjusted_'+which]=or_fit(or_formula(which,'none'),p,'Unadjusted_'+which)
        models['Primary_'+which]=or_borrow_primary(ctx,which)
    for key,cal,anchor in [('Year_A','year','hb'),('Month_A','month','hb'),('DXA_calendar_A','full','dxa')]:
        models[key]=or_fit(or_formula('A',cal,anchor),p,key)
    for name in ['Repeated_A','Repeated_B']:
        fit=R15['models'][name];r=ctx['repeated']
        spec=R15['tables']['Model_specifications'].set_index('Model').loc[name,'Formula']
        y,X=patsy.dmatrices(spec,r,return_type='dataframe',NA_action='raise',eval_env=-1)
        or_require(fit.converged and np.array_equal(y.iloc[:,0],fit.model.endog) and
            list(X)==list(fit.model.exog_names) and np.allclose(X,fit.model.exog),name+' 與現行 repeated 不同')
        expected_groups=pd.factorize(r[OR_PID],sort=False)[0]
        fitted_groups=pd.factorize(fit.model.groups,sort=False)[0]
        or_require(np.array_equal(expected_groups,fitted_groups),name+' 的病人分群與現行 repeated 不同')
        models[name]=fit
    descriptions={'Unadjusted':'Calendar-unadjusted OLS','Primary':'Primary OLS (HC3)','Repeated':'Patient-random-intercept LMM'}
    rows=[];disp=[]
    for assoc,which,term in [('THI–hemoglobin','A','THI_mean_30d'),('Hemoglobin–minimum T-score','B','Hb_Value'),
                           ('THI–minimum T-score, conditional on hemoglobin','B','THI_mean_30d')]:
        for kind in ['Unadjusted','Primary','Repeated']:
            name=kind+'_'+which;r=or_term(models[name],term,name);r['Association']=assoc
            anchor='None' if kind=='Unadjusted' else ('Hb laboratory report date' if which=='A' else 'DXA execution date')
            rows.append({**r,'Calendar_anchor':anchor})
            sample=f"{r['N']:,} records; {r['Patients']:,} patients" if kind=='Repeated' else f"{r['N']:,} patients"
            disp.append([assoc,descriptions[kind]+'; '+sample,or_coef(r),or_p(r['P']),anchor])
    table3=pd.DataFrame(disp,columns=['Association','Specification / cohort','β (SE)','P value','Calendar anchor'])
    numeric3=pd.DataFrame(rows)
    or_export(ctx,'Table3',{'Display':table3,'Numeric':numeric3},[
        'Table 3. Patient-level primary and sensitivity associations, with date-aligned repeated-record estimates.'], 'Main_Tables')
    table4rows=[];num4=[];vifs=[]
    order=[('Unadjusted_A','None (sensitivity)'),('Year_A','Hb_Date year only'),('Month_A','Hb_Date month harmonics only'),
           ('Primary_A','Hb_Date year + harmonics (primary)'),('DXA_calendar_A','DXA_Date year + harmonics (sensitivity)')]
    for key,label in order:
        r=or_term(models[key],'THI_mean_30d',key);v=or_vif(models[key]['X']);v['Model']=key;vifs.append(v)
        vr=v.set_index('Term').loc['THI_mean_30d'];r.update(VIF=vr.VIF,Auxiliary_R2=vr.Auxiliary_R2,Specification=label)
        num4.append(r);table4rows.append([label,or_coef(r),f"[{r['CI_low']:+.4f}, {r['CI_high']:+.4f}]",or_p(r['P']),f'{vr.VIF:.2f}',f'{vr.Auxiliary_R2:.4f}'])
    vb=or_vif(models['Primary_B']['X']);vb['Model']='Primary_B';vifs.append(vb)
    table4=pd.DataFrame(table4rows,columns=['Calendar terms','THI β (HC3 SE)','95% CI','P value','THI VIF','Auxiliary R²'])
    fullvif=pd.concat(vifs,ignore_index=True)
    ctx.update(table3_numeric=numeric3,table4_numeric=pd.DataFrame(num4),vif_all=fullvif)
    or_export(ctx,'Table4',{'Display':table4,'Numeric':pd.DataFrame(num4),'Full_VIF':fullvif},[
        'Table 4. Sequential calendar adjustment and THI collinearity diagnostics for the hemoglobin model.'], 'Main_Tables')
    ctx['table_cache'].update(Table3=table3,Table4=table4)
    diagnostics=[];params=[]
    for key,m in models.items():
        if not isinstance(m,dict):continue
        diagnostics.append({'Model':key,'N':m['n'],'Patients':m['patients'],'Design_columns':len(m['X'].columns),
            'Rank':m['rank'],'Formula':m['formula'],'Warnings':' | '.join(m['warnings'])})
        for term in m['X'].columns:params.append(or_term(m,term,key))
    pd.DataFrame(params).to_csv(ctx['out']/'Audit/Original_OLS_full_parameters.csv',index=False,encoding='utf-8-sig')
    pd.DataFrame(diagnostics).to_csv(ctx['out']/'Audit/Original_OLS_model_diagnostics.csv',index=False,encoding='utf-8-sig')
    ctx['checks'].append({'Check':'Table3_nine_rows_and_Table4_five_current_models','Passed':len(numeric3)==9 and len(num4)==5})
    print(table3.to_string(index=False));print(table4.to_string(index=False))
    return {'Completed':True}

