"""## S3 Time Order/Proximity Analysis and S7 A Age Restriction Analysis

The original model and subset rules are retained. The S3 sequential subset is explicitly defined as "Hb test report date earlier than or equal to the DXA execution date, including the same day"; the 95% CI is directly taken from this HC3 model. Same day does not imply confirmation of intra-day sequence or sampling time. The original subset model will still be completed during the actual execution.
"""

def or_run_temporal_age(ctx):
    or_same_inputs(ctx);p=ctx['primary']
    subsets=[('Hb laboratory report date on or before DXA execution date, including same-day records',p.signed_gap_days.ge(0))]
    subsets += [(f'Absolute gap {lo}–{hi} days (both directions)',p.abs_gap_days.between(lo,hi))
                for lo,hi in [(0,30),(31,90),(91,180)]]
    or_require(sum(int(m.sum()) for _,m in subsets[1:])==len(p),'三段間隔沒有完整分割 Primary')
    rows=[];display=[];summary=[]
    for i,(label,mask) in enumerate(subsets):
        d=p.loc[mask].copy()
        or_require(not d.empty,label+' 無觀測')
        results=[]
        for which,term in [('A','THI_mean_30d'),('B','Hb_Value')]:
            name=f'S3_{i}_{which}';m=or_fit(or_formula(which),d,name);ctx['models'][name]=m
            r={**or_term(m,term), 'Subset':label};rows.append(r);results.append(r)
        display.append([label,len(d),or_coef(results[0],True),or_coef(results[1],True)])
        summary.append({'Subset':label,'N':len(d),'Patients':d[OR_PID].nunique(),
            'Before_DXA':int(d.signed_gap_days.gt(0).sum()),'Same_calendar_day':int(d.signed_gap_days.eq(0).sum()),
            'After_DXA':int(d.signed_gap_days.lt(0).sum())})
    table=pd.DataFrame(display,columns=['Temporal subset','N','THI–hemoglobin (HC3)','Hemoglobin–minimum T-score (HC3)'])
    order=pd.DataFrame([{'Position':label,'Patients':int(mask.sum()),'Denominator':len(p),'Percent':100*mask.mean()}
        for label,mask in [('Report before DXA',p.signed_gap_days.gt(0)),('Same day',p.signed_gap_days.eq(0)),('Report after DXA',p.signed_gap_days.lt(0))]])
    or_export(ctx,'S3_Table',{'Display':table,'Numeric':pd.DataFrame(rows),'Subset_counts':pd.DataFrame(summary),'Full_primary_order':order},[
        'S3 Table. Temporal-order and proximity sensitivities, recomputed on current Primary representatives.',
        'Hb_Date denotes the laboratory report date. The ordered subset requires Hb_Date ≤ DXA execution date and includes same-day records. This criterion does not establish within-day ordering, specimen-collection timing or prospective predictor availability. Absolute-gap strata include both temporal directions and are separate from the ordered subset.',
        'Model A uses Hb laboratory report-date year indicators and month harmonics; Model B uses DXA execution-date year indicators and month harmonics. Both retain the clinical covariates. All reported 95% confidence intervals, including those for the ordered subset, are calculated directly from the fitted models using HC3 normal-Wald inference, not reconstructed from rounded historical estimates. These comparisons do not establish causal lag effects.'])
    d=p.loc[p.Age.ge(OR_AGE_CUT)].copy();name='S7A_age_restricted'
    m=or_fit(or_formula('B'),d,name);ctx['models'][name]=m
    out=[or_term(m,t,name) for t in ['Hb_Value','THI_mean_30d']]
    npos=int(d.overall_T.le(-2.5).sum())
    age_display=pd.DataFrame([[f'Age ≥{OR_AGE_CUT} years: age-restricted sensitivity analysis',
        f'{len(d):,} / {npos:,} ({100*npos/len(d):.1f}%)',or_coef(out[0],True),or_coef(out[1],True),
        'DXA execution-date year indicators + month sine/cosine terms']],columns=[
        'Population','N / T-score ≤−2.5, n (%)','Hemoglobin (HC3)','Conditional THI (HC3)','Calendar adjustment'])
    ctx.update(s7a_display=age_display,s7a_numeric=pd.DataFrame(out),s7a_counts=pd.DataFrame([{
        'Age_cutoff':OR_AGE_CUT,'Patients':len(d),'Tscore_category_n':npos,'Female':int(d.sex_bin.eq(0).sum()),
        'Male':int(d.sex_bin.eq(1).sum()),'Primary_denominator':len(p)}]))
    ctx['table_cache']['S3_Table']=table
    ctx['checks'].append({'Check':'S3_current_subsets_and_S7A_current_age_model','Passed':True})
    print(table.to_string(index=False));print(age_display.to_string(index=False));print(order.to_string(index=False))
    return {'Completed':True}

