"""## Original S6 completeness

Input objects are produced by preceding cells in this notebook. Outputs remain private working artifacts until the publication export section. Manuscript items: S6 Table.

"""

def or_run_strict_weather(ctx):
    or_same_inputs(ctx);p=ctx['primary']
    cols=['T_daily_mean','DTR_daily','RH_daily_mean']
    w=R05['weather_df'][['日期',*cols]].copy(deep=True)
    w['日期']=pd.to_datetime(w['日期'],errors='raise')
    or_require(w['日期'].notna().all() and w['日期'].is_unique,'原 S6 日摘要日期缺失／重複；不得自動去重')
    or_require(w['日期'].eq(w['日期'].dt.normalize()).all(),'原 S6 的日期含日內時間')
    w=w.sort_values('日期').set_index('日期')
    idx=pd.date_range(w.index.min(),w.index.max(),freq='D')
    w=w.reindex(idx);w.index.name='Hb_Date'
    valid=w[cols].notna().all(axis=1)
    w['valid_days_30d']=valid.astype(int).rolling(OR_S6_WINDOW,min_periods=1).sum()
    joint=w[cols].where(valid,axis=0)
    av=joint.rolling(OR_S6_WINDOW,min_periods=OR_S6_MIN_VALID).mean()
    w['THI_mean_30d_27']=av.T_daily_mean-.55*(1-av.RH_daily_mean/100)*(av.T_daily_mean-14.4)
    w['DTR_mean_30d_27']=av.DTR_daily
    p=p.merge(w[['valid_days_30d','THI_mean_30d_27','DTR_mean_30d_27']].reset_index(),on='Hb_Date',how='left',validate='many_to_one',sort=False)
    or_require(np.array_equal(p[OR_PAIR],ctx['primary'][OR_PAIR]),'S6 merge 改變代表列或順序')
    d=p.loc[p.valid_days_30d.ge(OR_S6_MIN_VALID)].copy()
    or_require(not d.empty and d[['THI_mean_30d_27','DTR_mean_30d_27']].notna().all().all(),'原 S6 無可用列／條件不一致')
    m=or_fit(or_formula('A',thi='THI_mean_30d_27',dtr='DTR_mean_30d_27'),d,'S6_strict27')
    ctx['models']['S6_strict27']=m
    rows=[];display=[]
    for key,model,term,label in [('Primary',ctx['models']['Primary_A'],'THI_mean_30d','Primary Hb_Date-aligned'),
                               ('Strict27',m,'THI_mean_30d_27','Complete calendar; ≥27 valid days')]:
        r=or_term(model,term,key);v=or_vif(model['X']).set_index('Term').loc[term]
        r.update(Retention_percent=100*r['N']/len(p),VIF=float(v.VIF),Auxiliary_R2=float(v.Auxiliary_R2))
        rows.append(r);display.append([label,f"{r['N']:,} / {r['Retention_percent']:.1f}%",or_coef(r),
            f"[{r['CI_low']:+.4f}, {r['CI_high']:+.4f}]; P {or_p(r['P'])}",f"{r['VIF']:.2f} / {r['Auxiliary_R2']:.4f}"])
    table=pd.DataFrame(display,columns=['Specification','N / retention','THI β (HC3 SE)','95% CI; P value','THI VIF / R²'])
    v=p.valid_days_30d.dropna()
    summary=pd.DataFrame([{'Denominator_scope':'Original Primary, before restriction','Primary_rows':len(p),
        'Evaluable_valid_day_counts':len(v),'Median':v.median(),'Q1':v.quantile(.25),'Q3':v.quantile(.75),
        'Retained_rows':len(d),'Excluded_rows':len(p)-len(d),'Calendar_start':idx.min(),'Calendar_end':idx.max(),
        'Window_days':OR_S6_WINDOW,'Minimum_valid_days':OR_S6_MIN_VALID}])
    counts=p.valid_days_30d.value_counts(dropna=False).rename_axis('Valid_days').reset_index(name='Primary_rows')
    or_export(ctx,'S6_Table',{'Display':table,'Numeric':pd.DataFrame(rows),'Completeness':summary,'Valid_day_distribution':counts},[
        'S6 Table. Original strict calendar-window completeness sensitivity, reconstructed from the R05 daily means.',
        'T, DTR and RH use the same jointly valid dates on a complete daily calendar. At least 27 of 30 calendar days are required, including the report day. THI is calculated from window-mean T and RH.',
        'This reproduces the original S6 specification without an hourly-count threshold; revised hourly/calendar analyses remain separately in S14. The retained N is calculated, never forced to the historical 4,924.',
        'Valid-day median/IQR refer to the original Primary cohort, before the completeness restriction. HC3 does not address temporal dependence.'])
    ctx['table_cache']['S6_Table']=table;ctx['s6_numeric']=pd.DataFrame(rows)
    ctx['checks'].append({'Check':'Original_S6_joint_calendar_window_reconstructed','Passed':True})
    print(table.to_string(index=False));print(summary.to_string(index=False))
    return {'Completed':True}

