OR_STRICT_WEATHER=None
OR_STRICT_WEATHER=or_run_strict_weather(ORIGINAL_REPRODUCTION)

"""## S2 Coefficient Product and Spline Specification

Maintain the original model, paired resampling, and spline basis. Inner nodes are taken from the actual Patsy transform and defined as the empirical quantiles of one-third and two-thirds of the distinct THI values; the table displays two decimal places, and the full precision and full data column quantile comparisons are kept separately. The original resampling will still be performed during this process.
"""

def or_product_bootstrap(a,b,draws,seed,path):
    rng=np.random.default_rng(seed);n=len(a['y']);ledger=[]
    Xa=np.asarray(a['X']);Xb=np.asarray(b['X']);ya=a['y'];yb=b['y']
    ja=list(a['X']).index('THI_mean_30d');jb=list(b['X']).index('Hb_Value')
    for j in range(draws):
        rec={'Draw':j+1,'Status':'success','Product':np.nan,'Error':''}
        try:
            idx=rng.choice(n,size=n,replace=True)
            ba,_,ra,_=np.linalg.lstsq(Xa[idx],ya[idx],rcond=None)
            bb,_,rb,_=np.linalg.lstsq(Xb[idx],yb[idx],rcond=None)
            or_require(ra==Xa.shape[1] and rb==Xb.shape[1],'case bootstrap 非預期秩不足')
            rec['Product']=float(ba[ja]*bb[jb]);or_require(np.isfinite(rec['Product']),'case bootstrap 非有限值')
            if j==0:
                direct_a=sm.OLS(ya[idx],Xa[idx]).fit();direct_b=sm.OLS(yb[idx],Xb[idx]).fit()
                or_require(np.allclose(ba,direct_a.params,rtol=1e-8,atol=1e-9) and
                    np.allclose(bb,direct_b.params,rtol=1e-8,atol=1e-9),'直接 OLS 與加速重抽樣不一致')
        except Exception as exc:
            rec.update(Status='failed',Error=f'{type(exc).__name__}: {exc}')
        ledger.append(rec)
        if rec['Status']!='success' or (j+1)%500==0 or j+1==draws:
            pd.DataFrame(ledger).to_csv(path,index=False,encoding='utf-8-sig')
            print(f'原 S2 係數乘積：{j+1}/{draws}；失敗 {sum(x["Status"]!="success" for x in ledger)}。',flush=True)
        if rec['Status']!='success':raise RuntimeError('係數乘積重抽樣失敗；已保存紀錄，不靜默略過。')
    return pd.DataFrame(ledger)

def or_run_s2(ctx,draws=OR_BOOTSTRAP_DRAWS):
    or_same_inputs(ctx);p=ctx['primary'];m=ctx['models']
    ledger=or_product_bootstrap(m['Unadjusted_A'],m['Unadjusted_B'],draws,OR_SEED,ctx['out']/'Audit/S2_product_draws.csv')
    ar=or_term(m['Unadjusted_A'],'THI_mean_30d');br=or_term(m['Unadjusted_B'],'Hb_Value')
    ci=np.quantile(ledger.Product,[OR_ALPHA/2,1-OR_ALPHA/2])
    product=pd.DataFrame([{'Product':ar['Beta']*br['Beta'],'A_beta':ar['Beta'],'B_beta':br['Beta'],
        'Bootstrap_SE':ledger.Product.std(ddof=1),'CI_low':ci[0],'CI_high':ci[1],
        'Requested':draws,'Attempted':len(ledger),'Succeeded':int(ledger.Status.eq('success').sum()),'Failed':int(ledger.Status.ne('success').sum()),
        'Seed':OR_SEED,'Inference':'Patient-case percentile bootstrap; no calendar dependence correction'}])
    spline=or_fit('overall_T ~ Hb_Value + cr(THI_mean_30d, df=4) + DTR_mean_30d + Age + sex_bin',p,'S2_spline',True)
    linear=m['Unadjusted_B'];lr=2*(spline['fit'].llf-linear['fit'].llf)
    ddf=float(spline['fit'].df_model-linear['fit'].df_model)
    or_require(lr>=-1e-8 and ddf>0,'spline 的巢狀比較不合法')
    transforms=[]
    for factor in spline['X'].design_info.factor_infos.values():
        for obj in factor.state.get('transforms',{}).values():
            if hasattr(obj,'_all_knots'):transforms.append(np.asarray(obj._all_knots,dtype=float))
    or_require(len(transforms)==1,'無法從配適的 Patsy basis 取得唯一 spline 結點')
    knots=transforms[0]
    # 同時列出舊程式印出的全列經驗分位數；它不必等於 Patsy 實際 basis 結點。
    reported_quantiles=np.quantile(p.THI_mean_30d,[1/3,2/3])
    spline_numbers=pd.DataFrame([{'Linear_loglik':linear['fit'].llf,'Spline_loglik':spline['fit'].llf,
        'LR':lr,'DF_difference':ddf,'P':st.chi2.sf(max(0,lr),ddf),
        'Spline_design_columns':len(spline['X'].columns),'Spline_rank':spline['rank'],
        'Basis_columns':len([x for x in spline['X'].columns if x.startswith('cr(')]),
        'Boundary_low':knots[0],'Boundary_high':knots[-1]}])
    ctx['models']['S2_spline']=spline
    specs=[('Unadjusted_A','THI_mean_30d','THI–hemoglobin coefficient, calendar-unadjusted'),
        ('Year_A','THI_mean_30d','THI–hemoglobin coefficient, Hb_Date year FE'),
        ('Month_A','THI_mean_30d','THI–hemoglobin coefficient, Hb_Date month harmonics'),
        ('Primary_A','THI_mean_30d','THI–hemoglobin coefficient, Hb_Date full calendar (primary)'),
        ('Unadjusted_B','Hb_Value','Hemoglobin–minimum T-score coefficient, calendar-unadjusted'),
        ('Primary_B','Hb_Value','Hemoglobin–minimum T-score coefficient, DXA_Date full calendar'),
        ('Unadjusted_B','THI_mean_30d','Conditional THI term, calendar-unadjusted'),
        ('Primary_B','THI_mean_30d','Conditional THI term, DXA_Date full calendar'),
        ('Repeated_A','THI_mean_30d','Repeated-record THI–hemoglobin coefficient, Hb_Date-aligned'),
        ('Repeated_B','Hb_Value','Repeated-record hemoglobin–minimum-T-score coefficient, DXA_Date-aligned'),
        ('Repeated_B','THI_mean_30d','Repeated-record conditional THI term, DXA_Date-aligned')]
    nums=[];display=[]
    for key,term,label in specs:
        r=or_term(m[key],term,key);nums.append({**r,'Description':label})
        display.append([label,f"{r['Beta']:+.4f}",f"{r['SE']:.4f}",
            f"P {or_p(r['P'])}; 95% CI [{r['CI_low']:+.4f}, {r['CI_high']:+.4f}]",r['Inference']])
    pr=product.iloc[0]
    display.append(['Calendar-unadjusted coefficient product',f'{pr.Product:+.6f}','Not a model-coefficient SE',
        f'95% CI [{pr.CI_low:+.6f}, {pr.CI_high:+.6f}]',f'{draws:,} patient-case resamples; descriptive only'])
    a=pd.DataFrame(display,columns=['Model term','Estimate','SE','P value / interval','Specification'])
    b=[]
    for key,anchor,terms in [('Primary_A','Hb_Date',['THI_mean_30d','DTR_mean_30d','hb_sin','hb_cos']),
        ('Primary_B','DXA_Date',['THI_mean_30d','DTR_mean_30d','Age','sex_bin','Hb_Value','dxa_sin','dxa_cos'])]:
        v=ctx['vif_all'].loc[ctx['vif_all'].Model.eq(key)].set_index('Term')
        for term in terms:b.append([key,term,f'{v.loc[term,"VIF"]:.4f}'])
        year=v.loc[v.index.str.startswith('C('),'VIF']
        or_require(len(year)>0,key+' 無年指示項')
        b.append([key,anchor+' year indicators, range',f'{year.min():.4f}–{year.max():.4f}'])
    b=pd.DataFrame(b,columns=['Model','Design-matrix term','VIF'])
    sr=spline_numbers.iloc[0]
    c=pd.DataFrame([
        ('Software / function',f'patsy {patsy.__version__}; cr(THI_mean_30d, df=4); statsmodels OLS','Original natural cubic spline specification'),
        ('Linear formula',linear['formula'],'No year/month terms'),('Spline formula',spline['formula'],'Same outcome and covariates'),
        ('Interior knots',', '.join(f'{x:.2f}' for x in knots[1:-1]),'Default one-third and two-thirds empirical quantiles of distinct THI values'),
        ('Boundary support',f'[{knots[0]:.2f}, {knots[-1]:.2f}]','Actual fitted boundary knots'),
        ('Basis output',str(int(sr.Basis_columns))+' columns','One constant direction is redundant with the formula intercept'),
        ('Rank logic',f'Design columns={int(sr.Spline_design_columns)}; rank={int(sr.Spline_rank)}; Δdf={ddf:g}','Use fitted rank difference'),
        ('Scaling','Native generated basis','No centering constraint or orthonormalization'),
        ('Linear log likelihood',f'{sr.Linear_loglik:.4f}','Gaussian OLS'),('Spline log likelihood',f'{sr.Spline_loglik:.4f}','Gaussian OLS'),
        ('Likelihood-ratio comparison',f'LR={lr:.4f}; Δdf={ddf:g}; P {or_p(sr.P)}','Nominal calendar-unadjusted diagnostic')
        ],columns=['Item','Specification / value','Interpretation'])
    or_export(ctx,'S2_Table',{'Display_A':a,'Display_B':b,'Display_C':c,'Association_numeric':pd.DataFrame(nums),
        'Full_VIF':ctx['vif_all'],'Product_numeric':product,'Spline_numeric':spline_numbers,
        'Actual_spline_knots':pd.DataFrame({'Knot':knots}),
        'Empirical_quantile_audit':pd.DataFrame({'Quantile':[1/3,2/3],
            'All_rows_empirical_quantile':reported_quantiles,'Actual_basis_interior_knot':knots[1:-1]})},[
        'S2 Table. Original selected coefficients, collinearity diagnostics, coefficient product and spline diagnostic, recomputed.',
        'The coefficient product is descriptive, not mediation. Case resampling refits both calendar-unadjusted models on the same sampled patients; it does not preserve calendar dependence.',
        'The spline LR comparison uses Gaussian OLS likelihoods and actual fitted-rank difference. It is neither heteroscedasticity-robust nor calendar-adjusted, and is not evidence of an independent thermal threshold.',
        'Interior knots are the default one-third and two-thirds empirical quantiles of distinct THI values, read from the fitted Patsy transform. Display_C rounds these actual knots to two decimal places; Actual_spline_knots retains full precision. The historical quantiles over all observation rows are retained separately in Empirical_quantile_audit and are not substituted for fitted basis knots. The fitted formula is unchanged.',
        'All bootstrap attempts are retained in the audit ledger; a failed draw stops completion. R07 Mundlak and R08 time-dependence analyses remain separate.'])
    ctx.update(product_numeric=product,spline_numeric=spline_numbers,actual_spline_knots=knots)
    ctx['table_cache'].update(S2A=a,S2B=b,S2C=c)
    ctx['checks'].append({'Check':'S2_product_all_draws_and_spline_rank_recorded','Passed':True})
    print(product.to_string(index=False));print(spline_numbers.to_string(index=False))
    return {'Completed':True}

# BEGIN EXECUTION
OR_PRODUCT_SPLINE=None
OR_PRODUCT_SPLINE=or_run_s2(ORIGINAL_REPRODUCTION)

"""## Original Classification Specifications: Table 5, S4, S5, and S7 B/C

The classifier, parameters, folding, and preprocessing remain unchanged. The difference between old and new features in S7 is calculated using unrounded estimates before display; it is not subtracted to four decimal places, nor is a dead difference value written. The table notes are supplemented with definitions for AUC, Brier, and folding SD. The original classification adaptation will still be completed during this process.
"""

def or_ml_imports():
    # 缺套件就明確安裝；無替代演算法、不略過 LightGBM。
    if importlib.util.find_spec('lightgbm') is None:
        raise ImportError('lightgbm is required; install requirements.txt and restart the kernel.')
    import sklearn, xgboost, lightgbm
    from sklearn.model_selection import StratifiedKFold, train_test_split
    from sklearn.pipeline import Pipeline
    from sklearn.preprocessing import StandardScaler
    from sklearn.linear_model import LogisticRegression
    from sklearn.neighbors import KNeighborsClassifier
    from sklearn.ensemble import RandomForestClassifier, AdaBoostClassifier
    from sklearn.tree import DecisionTreeClassifier
    from sklearn.metrics import roc_auc_score, brier_score_loss, accuracy_score, f1_score, precision_score, recall_score
    from xgboost import XGBClassifier
    from lightgbm import LGBMClassifier
    return locals()

def or_ml_data(p,age65=False):
    d=p.loc[p.Age.ge(OR_AGE_CUT)].copy() if age65 else p.copy()
    fields=['Age','sex_bin','Hb_Value',*OR_WEATHER,'overall_T']
    eligible=d[fields].notna().all(axis=1)
    s=d.loc[eligible].copy()
    or_require(len(s)>0 and np.isfinite(s[fields]).all().all(),'分類資料空值／無限值')
    y=s.overall_T.le(-2.5).astype(int).to_numpy()
    or_require(pd.Series(y).value_counts().min()>=OR_CV_FOLDS and len(np.unique(y))==2,'分類標籤不足兩類或不夠分折')
    return s,y,pd.DataFrame([{'Population':'Age65' if age65 else 'Primary','Rows_before_feature_completeness':len(d),
        'Rows_removed_missing_features':int((~eligible).sum()),'Rows_used':len(s),'Patients':s[OR_PID].nunique(),
        'Operational_positive':int(y.sum()),'Features':'Legacy row-window seven weather variables'}])

def or_engineer18(d):

    X=d[['Age','sex_bin','Hb_Value','THI_mean_30d','DTR_mean_30d','THI_mean_180d',
         'THI_hot_days_365d','THI_std_30d','T_std_30d','THI_Trend_Shock']].copy()
    X['Age_Squared']=X.Age**2;X['Severe_Heat_Stress']=X.THI_mean_30d.ge(27).astype(int)
    X['Extreme_Anemia']=X.Hb_Value.lt(11).astype(int)
    X['Hb_Deficit']=np.where(X.sex_bin.eq(1),X.Hb_Value-13,X.Hb_Value-12)
    X['Month_Sin']=np.sin(2*np.pi*d.Hb_Date.dt.month/12)
    X['Month_Cos']=np.cos(2*np.pi*d.Hb_Date.dt.month/12)
    X['THI_x_Hb']=X.THI_mean_30d*X.Hb_Value;X['THI_x_Age']=X.THI_mean_30d*X.Age
    or_require(X.shape[1]==18 and np.isfinite(X).all().all(),'S4 18 特徵規格不一致')
    return X

def or_estimator(lib,algorithm,benchmark=False,age65=False):
    if benchmark:
        params={
            'Logistic regression':('LogisticRegression',dict(max_iter=3000,class_weight='balanced',random_state=OR_SEED)),
            'K-nearest neighbors':('KNeighborsClassifier',dict(n_neighbors=15,weights='distance')),
            'Random forest':('RandomForestClassifier',dict(n_estimators=500,max_depth=8,min_samples_leaf=15,class_weight='balanced',random_state=OR_SEED)),
            'AdaBoost':('AdaBoostClassifier',dict(estimator=lib['DecisionTreeClassifier'](max_depth=2,class_weight='balanced'),n_estimators=200,learning_rate=.05,random_state=OR_SEED)),
            'XGBoost':('XGBClassifier',dict(n_estimators=500,max_depth=4,learning_rate=.01,subsample=.8,colsample_bytree=.8,random_state=OR_SEED,eval_metric='logloss',n_jobs=1)),
            'LightGBM':('LGBMClassifier',dict(n_estimators=500,max_depth=5,learning_rate=.01,class_weight='balanced',reg_alpha=1.5,reg_lambda=2.,random_state=OR_SEED,verbose=-1,n_jobs=1))}
        cls,kw=params[algorithm];est=lib[cls](**kw)
    elif algorithm=='Logistic regression':est=lib['LogisticRegression'](max_iter=1000,random_state=OR_SEED)
    elif algorithm=='XGBoost':est=lib['XGBClassifier'](n_estimators=100,eval_metric='logloss',random_state=OR_SEED,n_jobs=1)
    else:raise ValueError('未定義的原稿分類器：'+algorithm)
    # 原 S7 XGBoost 不縮放，原全體 XGBoost 與六分類器都使用 fold-wise StandardScaler。
    if age65 and not benchmark and algorithm=='XGBoost':return est
    return lib['Pipeline']([('scaler',lib['StandardScaler']()),('clf',est)])

def or_predict_fit(est,X,y,tr,te,label,ledger,ctx):
    rec={'Fit':label,'Train_n':len(tr),'Test_n':len(te),'Status':'started','Warning_count':0,'Warnings':'','Error':''}
    or_require(not np.intersect1d(tr,te).size,'訓練／測試列交疊')
    try:
        with warnings.catch_warnings(record=True) as ws:
            warnings.simplefilter('always');est.fit(X[tr],y[tr]);prob=est.predict_proba(X[te])[:,1];pred=est.predict(X[te])
        rec.update(Warning_count=len(ws),Warnings=' | '.join(type(w.message).__name__+': '+str(w.message) for w in ws))
        or_require(np.isfinite(prob).all() and ((prob>=0)&(prob<=1)).all(),'分類機率不合法')
        rec['Status']='success'
    except Exception as exc:
        rec.update(Status='failed',Error=f'{type(exc).__name__}: {exc}');ledger.append(rec)
        pd.DataFrame(ledger).to_csv(ctx['out']/'Audit/Original_classifier_fit_ledger.csv',index=False,encoding='utf-8-sig')
        raise
    ledger.append(rec)
    pd.DataFrame(ledger).to_csv(ctx['out']/'Audit/Original_classifier_fit_ledger.csv',index=False,encoding='utf-8-sig')
    return prob,pred

def or_pair_cv(d,y,lib,ledger,ctx,age65=False):
    feature_sets={'Clinical':['Age','sex_bin','Hb_Value'],
                  'Clinical_weather':['Age','sex_bin','Hb_Value',*OR_WEATHER]}
    folds=list(lib['StratifiedKFold'](n_splits=OR_CV_FOLDS,shuffle=True,random_state=OR_SEED).split(d,y))
    rows=[];coverage=np.zeros(len(d),dtype=int);foldinfo=[]
    for f,(tr,te) in enumerate(folds,1):
        coverage[te]+=1;foldinfo.append({'Population':'Age65' if age65 else 'Primary','Fold':f,'Train_n':len(tr),'Test_n':len(te),
            'Train_positive':int(y[tr].sum()),'Test_positive':int(y[te].sum())})
        for alg in ['Logistic regression','XGBoost']:
            for fs,cols in feature_sets.items():
                est=or_estimator(lib,alg,age65=age65)
                probs,_=or_predict_fit(est,d[cols].to_numpy(),y,tr,te,f'{"Age65" if age65 else "Primary"}/{f}/{alg}/{fs}',ledger,ctx)
                rows.append({'Algorithm':alg,'Feature_set':fs,'Fold':f,'AUC':lib['roc_auc_score'](y[te],probs),
                    'Brier':lib['brier_score_loss'](y[te],probs),'Train_n':len(tr),'Test_n':len(te)})
        print(f'原稿分類 {"Age≥65" if age65 else "Primary"}：第 {f}/{OR_CV_FOLDS} 折完成。',flush=True)
    or_require((coverage==1).all(),'原稿 CV 不是每人恰好測試一次')
    foldtable=pd.DataFrame(rows);summary=[]
    for alg in ['Logistic regression','XGBoost']:
        a=foldtable.loc[(foldtable.Algorithm==alg)&(foldtable.Feature_set=='Clinical')].sort_values('Fold')
        b=foldtable.loc[(foldtable.Algorithm==alg)&(foldtable.Feature_set=='Clinical_weather')].sort_values('Fold')
        summary.append({'Algorithm':alg,'N':len(d),'Clinical_AUC_mean':a.AUC.mean(),'Clinical_AUC_SD':a.AUC.std(ddof=0),
            'Weather_AUC_mean':b.AUC.mean(),'Weather_AUC_SD':b.AUC.std(ddof=0),
            'Delta_AUC':float(np.mean(b.AUC.to_numpy()-a.AUC.to_numpy())),
            'Clinical_Brier':a.Brier.mean(),'Weather_Brier':b.Brier.mean(),
            'Delta_Brier':float(np.mean(b.Brier.to_numpy()-a.Brier.to_numpy()))})
    return pd.DataFrame(summary),foldtable,pd.DataFrame(foldinfo)

def or_pair_display(summary,auc_only=False,brier_only=False):
    rows=[]
    for r in summary.itertuples(index=False):
        vals=[r.Algorithm]
        if not brier_only:vals += [f'{r.Clinical_AUC_mean:.4f} ± {r.Clinical_AUC_SD:.4f}',f'{r.Weather_AUC_mean:.4f} ± {r.Weather_AUC_SD:.4f}',f'{r.Delta_AUC:+.4f}']
        if not auc_only:vals += [f'{r.Clinical_Brier:.4f}',f'{r.Weather_Brier:.4f}',f'{r.Delta_Brier:+.4f}']
        rows.append(vals)
    cols=['Algorithm']+([] if brier_only else ['Clinical AUC','Clinical + weather AUC','ΔAUC'])+([] if auc_only else ['Clinical Brier','Clinical + weather Brier','ΔBrier'])
    return pd.DataFrame(rows,columns=cols)

def or_run_classification(ctx,draws=OR_BOOTSTRAP_DRAWS):
    or_same_inputs(ctx);lib=or_ml_imports();ledger=[]
    ctx['versions'].update({x:lib[x].__version__ for x in ['sklearn','xgboost','lightgbm']})
    or_json(ctx['out']/'Audit/runtime_versions.json',ctx['versions'])
    d,y,den=or_ml_data(ctx['primary']);d65,y65,den65=or_ml_data(ctx['primary'],True)
    # 原 S4 直接採全部 Primary；不能因額外特徵缺失而悄悄改成別的世代。
    or_require(len(d)==len(ctx['primary']),'原 S4 所需長視窗特徵不完整；不能完整重現原設計')
    X=or_engineer18(d);folds=list(lib['StratifiedKFold'](n_splits=OR_CV_FOLDS,shuffle=True,random_state=OR_SEED).split(X,y))
    algorithms=['Logistic regression','K-nearest neighbors','Random forest','AdaBoost','XGBoost','LightGBM']
    bench=[];specs=[]
    for alg in algorithms:
        spec=or_estimator(lib,alg,True)
        specs.append({'Algorithm':alg,'Settings':repr(spec),'Full_resolved_parameters':json.dumps(spec.get_params(deep=True),default=str,ensure_ascii=False)})
        for f,(tr,te) in enumerate(folds,1):
            probs,pred=or_predict_fit(or_estimator(lib,alg,True),X.to_numpy(),y,tr,te,f'S4/{alg}/{f}',ledger,ctx)
            bench.append({'Algorithm':alg,'Fold':f,'Train_n':len(tr),'Test_n':len(te),
                'AUC':lib['roc_auc_score'](y[te],probs),'Accuracy':lib['accuracy_score'](y[te],pred),
                'F1':lib['f1_score'](y[te],pred,zero_division=0),
                'Precision':lib['precision_score'](y[te],pred,zero_division=0),'Recall':lib['recall_score'](y[te],pred,zero_division=0),
                'No_predicted_positives':bool(np.sum(pred)==0)})
        print('原 S4 六分類器：'+alg+' 完成。',flush=True)
    bench=pd.DataFrame(bench);summ=[];disp=[]
    for alg in algorithms:
        b=bench.loc[bench.Algorithm.eq(alg)];r={'Algorithm':alg};row=[alg]
        for metric in ['AUC','Accuracy','F1','Precision','Recall']:
            r[metric+'_mean']=b[metric].mean();r[metric+'_SD']=b[metric].std(ddof=0)
            row.append(f'{r[metric+"_mean"]:.4f} ± {r[metric+"_SD"]:.4f}')
        summ.append(r);disp.append(row)
    s4display=pd.DataFrame(disp,columns=['Classifier','AUC','Accuracy','F1','Precision','Recall'])
    or_export(ctx,'S4_Table',{'Display_A':s4display,'Display_B':pd.DataFrame(specs)[['Algorithm','Settings']],
        'Numeric':pd.DataFrame(summ),'Fold_metrics':bench,'Feature_order':pd.DataFrame({'Feature':X.columns}),
        'Resolved_parameters':pd.DataFrame(specs),'Denominators':den},[
        'S4 Table. Original 18-feature six-classifier benchmark, recomputed; five stratified folds, shuffle=True, seed=42.',
        'Scaling is fitted within each training fold. Displayed SD uses ddof=0. No fold-paired significance tests or superiority claims are produced.',
        'The signed Hb_Deficit is Hb−13 in men and Hb−12 in women, not clipped. Original row-window weather features are deliberately retained for reproducibility; this does not satisfy the separate request to update all affected classifiers with calendar-window weather.'])
    primary,foldtable,splitinfo=or_pair_cv(d,y,lib,ledger,ctx)
    t5=or_pair_display(primary)
    or_export(ctx,'Table5',{'Display':t5,'Numeric':primary,'Fold_metrics':foldtable,'Fold_counts':splitinfo},[
        'Table 5. Original clinical-only versus clinical-plus-weather comparison, recomputed with the same five-fold splits.',
        'Clinical predictors: age, sex, Hb. Seven legacy weather features are added. Both Logistic regression and full-cohort XGBoost use training-fold StandardScaler.',
        'This is the original three-versus-ten-feature comparison without calendar covariates. S13 reports a separate clinical-plus-calendar comparator and forward evaluation. Fold SD is not a CI.'], 'Main_Tables')
    # 原 S5 固定 80:20 holdout，兩個模型固定；RandomState 與原 np.random.seed 相同序列。
    tr,te=lib['train_test_split'](np.arange(len(d)),test_size=.20,random_state=OR_SEED,stratify=y)
    errors=[]
    for label,cols in [('Clinical',['Age','sex_bin','Hb_Value']),('Weather',['Age','sex_bin','Hb_Value',*OR_WEATHER])]:
        probs,_=or_predict_fit(or_estimator(lib,'Logistic regression'),d[cols].to_numpy(),y,tr,te,'S5_holdout/'+label,ledger,ctx)
        errors.append((y[te]-probs)**2)
    rng=np.random.RandomState(OR_SEED);boot=np.empty((draws,3))
    for j in range(draws):
        idx=rng.choice(len(te),size=len(te),replace=True)
        bc=float(np.mean(errors[0][idx]));bw=float(np.mean(errors[1][idx]));boot[j]=[bc,bw,bw-bc]
    or_require(np.isfinite(boot).all(),'S5 paired bootstrap 非有限值')
    points=[errors[0].mean(),errors[1].mean(),errors[1].mean()-errors[0].mean()]
    cis=np.quantile(boot,[OR_ALPHA/2,1-OR_ALPHA/2],axis=0);hold=[]
    for j,label in enumerate(['Clinical','Weather','Weather_minus_clinical']):
        hold.append({'Quantity':label,'Estimate':points[j],'CI_low':cis[0,j],'CI_high':cis[1,j],
            'Bootstrap_SE':boot[:,j].std(ddof=1),'Train_n':len(tr),'Test_n':len(te),
            'Requested':draws,'Succeeded':draws,'Failed':0})
    hold=pd.DataFrame(hold)
    pd.DataFrame(boot,columns=['Clinical_Brier','Weather_Brier','Delta_Brier']).assign(Draw=np.arange(1,draws+1),Status='success').to_csv(ctx['out']/'Audit/S5_holdout_draws.csv',index=False,encoding='utf-8-sig')
    hd=pd.DataFrame([[f'{points[j]:.4f} [{cis[0,j]:.4f}, {cis[1,j]:.4f}]' for j in range(3)]],
        columns=['Clinical-only Brier [95% CI]','Clinical + weather Brier [95% CI]','ΔBrier [95% CI]'])
    specification=pd.DataFrame([
        ('Predictors','Age, sex_bin, Hb_Value','Same plus '+', '.join(OR_WEATHER)),
        ('Sample and split',f'{len(d)} patients; {OR_CV_FOLDS} stratified folds; shuffle=True; seed={OR_SEED}','Identical subjects and folds'),
        ('Preprocessing','Training-fold StandardScaler','Training-fold StandardScaler'),
        ('Logistic regression','max_iter=1000; random_state=42','Same settings'),
        ('XGBoost','n_estimators=100; eval_metric=logloss; random_state=42; n_jobs=1','Same settings'),
        ('Difference','Reference','Weather minus clinical'),
        ('Holdout',f'80:20 stratified split; train={len(tr)}; test={len(te)}',f'{draws} paired test-record bootstrap draws; models fixed')],
        columns=['Element','Clinical-only model','Clinical-plus-weather model'])
    or_export(ctx,'S5_Table',{'Display_A':specification,'Display_B':hd,'Holdout_numeric':hold,'Denominators':den},[
        'S5 Table. Original weather-comparison specification and fixed-holdout Brier check, recomputed.',
        'Same test rows are resampled for both fixed fitted logistic models; percentile CIs use 5,000 paired resamples, seed 42. The holdout differs from the five-fold comparison.',
        'Uncertainty conditions on this split and these fitted models, excluding training/split/calendar dependence. Historical row-based weather features remain labelled as such.'])
    age,agefold,agesplits=or_pair_cv(d65,y65,lib,ledger,ctx,True)
    ageauc=or_pair_display(age,auc_only=True);agebrier=or_pair_display(age,brier_only=True)
    or_export(ctx,'S7_Table',{'Display_A':ctx['s7a_display'],'Display_B':ageauc,'Display_C':agebrier,
        'Continuous_numeric':ctx['s7a_numeric'],'Classification_numeric':age,'Fold_metrics':agefold,
        'Fold_counts':agesplits,'Continuous_counts':ctx['s7a_counts'],'Classification_counts':den65},[
        f'S7 Table. Original age ≥{OR_AGE_CUT}-year sensitivity: continuous skeletal model and classification comparisons.',
        'A uses DXA-date-aligned HC3 OLS. B/C use the original age-restricted five-fold design: scaled logistic regression and unscaled XGBoost, both seed 42. Full-cohort XGBoost instead uses scaling.',
        'Panel B reports AUC mean ± fold SD (ddof=0); Panel C reports mean fold Brier scores. Differences are clinical-plus-weather minus clinical-only. Differences were calculated from unrounded estimates before display rounding. Subtracting the displayed rounded means may therefore differ from the displayed difference. Fold SDs are not confidence intervals.',
        'This is an age-restricted sensitivity analysis, not adjudication of menopause, diagnostic eligibility or skeletal-site comparability. No classification bootstrap CI or age-interaction test is added.'])
    led=pd.DataFrame(ledger);or_require(led.Status.eq('success').all(),'存在失敗分類配適')
    ctx.update(primary_classification=primary,holdout_numeric=hold,classification_ledger=led)
    ctx['table_cache'].update(Table5=t5,S4_Table=s4display,S5B=hd,S7A=ctx['s7a_display'],S7B=ageauc,S7C=agebrier)
    ctx['checks'].append({'Check':'Original_classifier_all_fits_and_holdout_draws_complete','Passed':True})
    print(t5.to_string(index=False));print(hd.to_string(index=False));print(age.to_string(index=False))
    print('原稿分類配適成功／嘗試：',int(led.Status.eq('success').sum()),'/',len(led))
    return {'Completed':True}

# BEGIN EXECUTION
OR_CLASSIFICATION=None
OR_CLASSIFICATION=or_run_classification(ORIGINAL_REPRODUCTION)

"""## S1/S2 figures from calculated summaries

Input objects are produced by preceding cells in this notebook. Outputs remain private working artifacts until the publication export section. Manuscript items: S1 Fig; S2 Fig.

"""

import matplotlib.pyplot as plt
from PIL import Image

def or_save_figure(ctx,fig,name,caption,data):
    png=ctx['out']/'Figures'/(name+'_rerun.png');tif=png.with_suffix('.tif')
    fig.savefig(png,dpi=300,bbox_inches='tight',facecolor='white')
    with Image.open(png) as im:
        im.convert('RGB').save(tif,format='TIFF',dpi=(300,300),compression='tiff_lzw')
    data.to_csv(ctx['out']/'Audit'/(name+'_plot_data.csv'),index=False,encoding='utf-8-sig')
    (ctx['out']/'Notes'/(name+'_caption.txt')).write_text(caption,encoding='utf-8')
    with Image.open(tif) as im:
        or_require(im.mode=='RGB' and im.width>0 and im.height>0,'圖檔格式無效')
        dims={'Width':im.width,'Height':im.height,'DPI':im.info.get('dpi'),'Mode':im.mode}
    ctx['completed'][name]={'path':str(tif),'SHA256':or_sha(tif),'PNG':str(png),**dims}
    plt.show();plt.close(fig)

def or_run_figures(ctx):
    or_same_inputs(ctx);r=ctx['repeated']
    # 原稿 S1 定義：65–79 歲、Hb 報告年度、研究 DXA 年度範圍；明確指定 repeated。
    lo=int(r.dxa_year.min());hi=int(r.dxa_year.max())
    mask=r.Age.between(65,79)&r.hb_year.between(lo,hi)
    d=r.loc[mask].copy();or_require(not d.empty,'S1 Fig 沒有符合原定義的紀錄')
    annual=d.groupby('hb_year').agg(Records=('overall_T','size'),Patients=(OR_PID,'nunique'),
        Mean_T=('overall_T','mean'),T_le25=('overall_T',lambda v:int(v.le(-2.5).sum()))).reset_index().rename(columns={'hb_year':'Year'})
    annual['Percent_T_le25']=100*annual.T_le25/annual.Records
    or_require(int(annual.Records.sum())==len(d),'S1 Fig 年度分母不一致')
    fig,axes=plt.subplots(3,1,figsize=(10,11),sharex=True)
    fig.subplots_adjust(top=.91,bottom=.12,hspace=.38)
    fig.suptitle('Annual record-level skeletal summaries, ages 65–79 years',fontsize=15,fontweight='bold')
    years=annual.Year.to_numpy();vals=annual.Records.to_numpy()
    axes[0].bar(years,vals,color='#3c768c',width=.55)
    axes[0].set_ylim(0,max(vals)*1.22)
    for x,y in zip(years,vals):axes[0].text(x,y+max(vals)*.025,f'{y:,}',ha='center',fontsize=10)
    axes[0].set_title('A  Eligible records (not unique patients)',loc='left',fontweight='bold')
    for ax,col,title,color,fmt in [(axes[1],'Mean_T','B  Mean minimum DXA T-score','#875c27','.2f'),
        (axes[2],'Percent_T_le25','C  Records with minimum T-score ≤−2.5 (%)','#2d755e','.1f')]:
        v=annual[col].to_numpy();span=max(np.ptp(v),.2 if col=='Mean_T' else 2)
        ax.plot(years,v,marker='o',color=color,linewidth=2)
        ax.set_ylim(v.min()-.25*span,v.max()+.35*span);ax.set_title(title,loc='left',fontweight='bold')
        for x,y in zip(years,v):ax.text(x,y+.07*span,format(y,fmt),ha='center',fontsize=10)
        # A、B、C 三個面板下方皆顯示年度；年份取自本次彙總資料。
    year_labels = [str(int(year)) for year in years]

    for ax in axes:
        ax.spines[['top', 'right']].set_visible(False)
        ax.grid(axis='y', alpha=.2)
        ax.set_axisbelow(True)

        ax.set_xticks(years, labels=year_labels)
        ax.tick_params(
            axis='x',
            which='both',
            bottom=True,
            labelbottom=True,
            labelrotation=0,
            labelsize=10
        )
    caption='S1 Fig. Annual record-level skeletal summaries among ages 65–79, recomputed from the current repeated-record cohort. Year is the Hb laboratory report year, restricted to the observed DXA study-year range. Patients can contribute multiple records. These are not population prevalence or within-person change.'
    fig.text(.5,.035,'Year is the Hb laboratory report year. Multiple records per patient are retained.\nSelected clinical records; not population prevalence or within-person bone change.',ha='center',fontsize=10)
    or_save_figure(ctx,fig,'S1_Fig',caption,annual);ctx['annual_summary']=annual
    s=ctx['primary_classification'];h=ctx['holdout_numeric'].set_index('Quantity')
    or_require(set(s.Algorithm)=={'Logistic regression','XGBoost'},'S2 Fig 缺少 Table 5 來源')
    fig=plt.figure(figsize=(10.5,9.5));gs=fig.add_gridspec(3,2,height_ratios=[1.1,.15,.8],hspace=.5,wspace=.35)
    a=fig.add_subplot(gs[0,0]);b=fig.add_subplot(gs[0,1]);leg=fig.add_subplot(gs[1,:]);leg.axis('off');c=fig.add_subplot(gs[2,:])
    colors=['#335c7d','#b85e24'];labels=['Clinical only','Clinical + weather'];plot=[]
    for i,row in enumerate(s.itertuples(index=False)):
        for j,prefix in enumerate(['Clinical','Weather']):
            x=i+(-.14 if j==0 else .14);mean=getattr(row,prefix+'_AUC_mean');sd=getattr(row,prefix+'_AUC_SD')
            a.errorbar(x,mean,yerr=sd,fmt='o',color=colors[j],capsize=5,label=labels[j] if i==0 else None)
            bv=getattr(row,prefix+'_Brier');b.scatter(x,bv,color=colors[j]);b.annotate(f'{bv:.4f}',(x,bv),xytext=(0,10 if j==0 else -17),textcoords='offset points',ha='center',fontsize=9)
            plot.append({'Panel':'A/B','Algorithm':row.Algorithm,'Feature_set':prefix,'AUC':mean,'Fold_SD':sd,'Brier':bv})
    for ax,title in [(a,'A  Five-fold discrimination'),(b,'B  Five-fold probability error')]:
        ax.set_title(title,loc='left',fontweight='bold',pad=18);ax.set_xticks([0,1],['Logistic\nregression','XGBoost']);ax.set_xlim(-.5,1.5)
        ax.margins(y=.35);ax.grid(axis='y',alpha=.2)
    a.set_ylabel('AUC (mean ± fold SD)');b.set_ylabel('Mean Brier score')
    handles,labels_=a.get_legend_handles_labels();leg.legend(handles,labels_,ncol=2,loc='center',frameon=False)
    row=h.loc['Weather_minus_clinical'];c.axvline(0,color='#6b7280',linestyle='--')
    # 使用端點線段而非假設點估計一定落在 percentile CI 內。
    c.hlines(0,row.CI_low,row.CI_high,color=colors[1],linewidth=2)
    c.plot([row.CI_low,row.CI_high],[0,0],marker='|',linestyle='None',markersize=12,color=colors[1]);c.plot(row.Estimate,0,'o',color=colors[1])
    c.set_yticks([0],['Logistic regression']);c.set_ylim(-.5,.5);c.margins(x=.3)
    c.text(.5,.8,f'{row.Estimate:+.4f} [{row.CI_low:+.4f}, {row.CI_high:+.4f}]',transform=c.transAxes,ha='center')
    c.set_title(f'C  Fixed holdout: {int(row.Test_n):,} test records',loc='left',fontweight='bold',pad=16)
    c.set_xlabel(f'ΔBrier (weather minus clinical)\n{int(row.Succeeded):,}-resample paired-bootstrap percentile 95% CI')
    for ax in [a,b,c]:ax.spines[['top','right']].set_visible(False)
    fig.subplots_adjust(bottom=.12)
    plot.append({'Panel':'C','Algorithm':'Logistic regression','Feature_set':'Weather_minus_clinical','Estimate':row.Estimate,'CI_low':row.CI_low,'CI_high':row.CI_high,'Test_n':row.Test_n})
    caption='S2 Fig. Original weather-information diagnostics regenerated from the current Table 5 and S5 results. A: five-fold AUC mean and fold SD (not CI). B: mean fold Brier. C: separate fixed-holdout logistic ΔBrier with paired-bootstrap percentile CI conditional on fitted models. Legacy row-window features; this is distinct from revised S3 Fig.'
    or_save_figure(ctx,fig,'S2_Fig',caption,pd.DataFrame(plot))
    ctx['checks'].append({'Check':'S1_S2_figures_use_current_tables_no_fixed_fallback','Passed':True})
    print(annual.to_string(index=False))
    return {'Completed':True}

# BEGIN EXECUTION
OR_FIGURES=None
OR_FIGURES=or_run_figures(ORIGINAL_REPRODUCTION)

"""## Fig 1 Original Layout and Step-by-Step Elimination Captions

The existing R05/R19 workflow and graphic layout are used without re-selecting generations. The captions dynamically list dates that cannot be evaluated, those that can be evaluated but have exceeded the interval limit, and subsequent reasons from the step-by-step elimination table; the counts are mutually exclusive according to the existing processing order and are not equal to the total number of failures for each condition.
"""

# 使用現有 R05／R19 結果；輸出至 HB-DXA/OUTPUT 的獨立新資料夾。
from pathlib import Path
from datetime import datetime, timezone
import hashlib
import json
import uuid
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from matplotlib.patches import FancyBboxPatch
from PIL import Image


def fig1_original_layout(r05, r19, base_folder):
    def require(condition, message):
        if not bool(condition):
            raise ValueError('Fig 1：' + message + '；停止，不使用替代資料。')

    require(r05.get('Completed') is True and r19.get('Completed') is True,
            '請先完成 R05 與 R19')
    source = Path(r19['output_dir'])
    require(Path(r19['provenance']['Source_R05_directory']).resolve()
            == Path(r05['Output_dir']).resolve(), 'R19 與 R05 來源版本不同')

    # 直接使用既有互斥排除彙總，不重新篩選世代。
    flow = r19['tables']['PartB_Flow'].copy(deep=True)
    totals = r19['tables']['PartB_Totals'].copy(deep=True)
    for table, key, filename in [
        (flow, 'sequential_attrition', 'PartB_Flow.csv'),
        (totals, 'attrition_totals', 'PartB_Totals.csv')
    ]:
        path = source / filename
        require(path.is_file(), '缺少來源檔：' + filename)
        pd.testing.assert_frame_equal(table, r05['tables'][key], check_dtype=False)
        pd.testing.assert_frame_equal(
            table, pd.read_csv(path), check_dtype=False, check_exact=True)

    stages = [
        'Stage1a_Date_unevaluable', 'Stage1b_Gap_over_180d',
        'Stage2a_DXA_missing_after_mask', 'Stage2b_Hb_missing_after_mask',
        'Stage2c_Age_missing', 'Stage2d_Sex_unmapped_or_missing',
        'Stage3_Weather_incomplete', 'Stage4a_Hb_outside_range',
        'Stage4b_T_outside_range', 'Stage4c_Age_outside_range',
        'Stage4d_DTR_outside_range'
    ]
    require(flow['Stage'].tolist() == stages, '既有排除階段或順序改變')
    counts = flow[['Rows_entering', 'Rows_removed', 'Rows_remaining']]
    require(np.isfinite(counts.to_numpy(dtype=float)).all()
            and counts.ge(0).all().all()
            and counts.eq(counts.round()).all().all(), '排除筆數不是有效非負整數')
    require(flow.Rows_entering.sub(flow.Rows_removed).eq(flow.Rows_remaining).all()
            and np.array_equal(flow.Rows_remaining.iloc[:-1], flow.Rows_entering.iloc[1:]),
            '逐步排除算術不一致')

    master = r05['row_flags']
    primary = r05['df_primary']
    repeated = r05['df_sensitivity']
    pid, pair, dxa = '去個資編號', 'pairing_row_id', '骨密度檢查執行日期'
    for label, data in [('Master', master), ('Primary', primary), ('Repeated', repeated)]:
        require(data[pair].notna().all() and data[pair].is_unique
                and data[pid].notna().all(), label + ' 的 ID 不完整或重複')
    require(primary[pid].is_unique, 'Primary 不是每人一列')
    for flag, data in [('is_included_primary', primary), ('is_included_sensitivity', repeated)]:
        require(pd.api.types.is_bool_dtype(master[flag]) and master[flag].notna().all(),
                '既有納入旗標格式不符')
        require(set(data[pair]) == set(master.loc[master[flag], pair]), '納入 ID 與旗標不同')
    require(set(primary[pair]).issubset(set(repeated[pair])), 'Primary 不在 repeated 世代內')
    require(len(totals) == 1
            and int(flow.iloc[0].Rows_entering) == len(master)
            and int(flow.iloc[-1].Rows_remaining) == len(repeated)
            and int(totals.iloc[0].Primary_rows) == len(primary), '世代分母不一致')

    spec = r19['provenance']['Source_specification']
    require(spec['Hb_date_meaning'] == 'laboratory_report_date', 'Hb 日期定義不同')
    limits = spec['Limits']
    gap_limit = float(limits['Gap_days_inclusive'])
    require(gap_limit > 0 and np.isfinite(gap_limit), '間隔門檻無效')
    primary_gap = pd.to_numeric(primary['Time_Gap_Days'], errors='raise')
    calculated_gap = (pd.to_datetime(primary[dxa], errors='raise')
                      - pd.to_datetime(primary['Hb_Date'], errors='raise')).dt.days.abs()
    require(primary_gap.notna().all() and np.isfinite(primary_gap).all()
            and primary_gap.between(0, gap_limit).all()
            and np.array_equal(primary_gap.to_numpy(), calculated_gap.to_numpy()),
            '既有 Primary 間隔與檢驗報告日期／DXA 日期不一致')
    dxa_dates = pd.to_datetime(master[dxa], errors='raise').dropna()
    require(not dxa_dates.empty, '沒有可用的 DXA 日期')
    years = f'{dxa_dates.dt.year.min()}–{dxa_dates.dt.year.max()}'

    s = flow.set_index('Stage')
    removed = lambda stage: int(s.loc[stage, 'Rows_removed'])
    kept = lambda stage: int(s.loc[stage, 'Rows_remaining'])
    count = lambda value: f'{int(value):,}'
    interval = f'{gap_limit:g}'
    temporal_excluded = sum(removed(k) for k in stages[:2])
    after_temporal = kept('Stage1b_Gap_over_180d')
    later_excluded = int(flow.iloc[2:]['Rows_removed'].sum())
    key_reasons = ['Stage2a_DXA_missing_after_mask', 'Stage2b_Hb_missing_after_mask',
                   'Stage3_Weather_incomplete']
    other_excluded = sum(removed(k) for k in stages[2:] if k not in key_reasons)
    require(len(master) - temporal_excluded - later_excluded == len(repeated),
            '總排除數與最終世代不一致')
    mean_gap = float(primary_gap.mean())
    n_primary_patients = primary[pid].nunique()
    n_repeated_patients = repeated[pid].nunique()
    additional = len(repeated) - len(primary)

    # 保留原圖的四個主方框、右側排除分支與中間說明。
    blue, text_color = '#507F9C', '#183A53'
    main_fill, excluded_fill, primary_fill = '#EDF6FA', '#FFF5EF', '#EDF8F4'
    with plt.rc_context({'font.family': 'DejaVu Sans', 'font.size': 16}):
        fig = plt.figure(figsize=(14.24, 11.04), dpi=100, facecolor='white')
        ax = fig.add_axes([0, 0, 1, 1])
        ax.set(xlim=(0, 1424), ylim=(1104, 0))
        ax.axis('off')
        text_regions = []

        def box(x, y, w, h, label='', fill=main_fill, size=19):
            ax.add_patch(FancyBboxPatch(
                (x, y), w, h, boxstyle='round,pad=0,rounding_size=11',
                linewidth=1.3, edgecolor=blue, facecolor=fill, zorder=2))
            if label:
                artist = ax.text(x+w/2, y+h/2, label, ha='center', va='center',
                                 fontsize=size, color=text_color, linespacing=1.25, zorder=3)
                text_regions.append((artist, (x+12, y+7, x+w-12, y+h-7)))

        def arrow(start, end):
            ax.annotate('', xy=end, xytext=start, zorder=1,
                        arrowprops={'arrowstyle': '-|>', 'lw': 1.5, 'color': blue,
                                    'shrinkA': 0, 'shrinkB': 0, 'mutation_scale': 12})

        box(65, 85, 800, 111,
            f'Consolidated DXA-linked clinical records\n{count(len(master))} ') # 移除年度records ({years})') 改在在文中說明
        box(65, 270, 800, 105,
            f'Temporal pairing criterion satisfied\n{count(after_temporal)} records')
        box(65, 660, 800, 112,
            f'Repeated-record sensitivity cohort\n{count(len(repeated))} records from '
            f'{count(n_repeated_patients)} patients')
        box(65, 952, 800, 110,
            f'Primary patient-level cohort: {count(n_primary_patients)} patients\n'
            f'Mean absolute Hb report–DXA interval: {mean_gap:.1f} days', fill=primary_fill)

        box(940, 180, 440, 142,
            f'Excluded: {count(temporal_excluded)} records\n'
            f'Dates not evaluable: {count(removed(stages[0]))}\n'
            f'Evaluable |Hb report–DXA| gap\n> {interval} days: {count(removed(stages[1]))}',
            fill=excluded_fill, size=16)
        box(940, 386, 440, 244,
            f'Excluded: {count(later_excluded)} records\n'
            f'DXA T-score unavailable*: {count(removed(key_reasons[0]))}\n'
            f'Hb unavailable*: {count(removed(key_reasons[1]))}\n'
            f'Required weather features\nincomplete: {count(removed(key_reasons[2]))}',
         #   f'Other age / sex / range filters: {count(other_excluded)}',
            fill=excluded_fill, size=15.5)

        arrow((465, 196), (465, 270))
        arrow((465, 234), (940, 234))
        ax.plot([465, 465, 916, 916, 465], [375, 400, 400, 621, 621],
                color=blue, lw=1.5, zorder=1)
        arrow((916, 508), (940, 508))
        arrow((465, 621), (465, 660))

        ax.text(92, 440,
                'Required: age, sex, hemoglobin, minimum T-score,\n'
                'Hb report date, and the specified weather summaries.',
                ha='left', va='top', fontsize=16, color=text_color, linespacing=1.25)
        bounds = lambda name: f'{limits[name][0]:g}–{limits[name][1]:g}'
        ax.text(92, 523,
                f'Retained ranges: age {bounds("Age")} years; Hb {bounds("Hb")} g/dL;\n'
                f'minimum T-score {limits["T"][0]:g} to {limits["T"][1]:+g}; '
                f'30-day DTR {bounds("DTR")}°C.',
                ha='left', va='top', fontsize=16, color=text_color, linespacing=1.25)
        ax.plot([465, 465], [772, 808], color=blue, lw=1.5)
        ax.text(465, 859,
                'Select one record per patient:\n'
                'shortest absolute Hb report–DXA gap; then earliest DXA date\n'
                f'{count(additional)} additional records retained only for sensitivity models',
                ha='center', va='center', fontsize=15, color=text_color, linespacing=1.25)
        arrow((465, 910), (465, 952))
        ax.text(1160, 762, 'No allocation or\nrandomization\nObservational selection',
                ha='center', va='center', fontsize=17, color=text_color, linespacing=1.3)
        ax.text(712, 1086,
                '*Unavailable after masking. Exclusion counts follow the stated processing order; see S12 Table.',
                ha='center', va='center', fontsize=11, color=text_color)

        # 檢查方框文字是否超出邊界；不以裁切輸出隱藏排版問題。
        fig.canvas.draw()
        renderer = fig.canvas.get_renderer()
        for artist, (x0, y0, x1, y1) in text_regions:
            actual = artist.get_window_extent(renderer)
            corners = ax.transData.transform([[x0, y0], [x1, y1]])
            low, high = corners.min(axis=0), corners.max(axis=0)
            require(actual.x0 >= low[0] and actual.x1 <= high[0]
                    and actual.y0 >= low[1] and actual.y1 <= high[1],
                    '方框文字超出邊界，需調整字級或換行')

        # 使用獨立版本資料夾，不覆蓋原 TIFF 或既有整包輸出。
        base = Path(base_folder)
        require(base.is_dir(), 'HB-DXA 路徑不存在')
        out = base / 'OUTPUT' / ('Fig1_Original_Layout_'
              + datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')
              + '_' + uuid.uuid4().hex[:8])
        out.mkdir(parents=True, exist_ok=False)
        files = []
        for extension in ['png', 'tif']:
            path = out / f'Fig1_original_layout_revised.{extension}'
            options = {'format': 'tiff', 'pil_kwargs': {'compression': 'tiff_lzw'}} if extension == 'tif' else {}
            fig.savefig(path, dpi=300, facecolor='white', **options)
            with Image.open(path) as image:
                rgb = image.convert('RGB')
            if extension == 'tif':
                rgb.save(path, dpi=(300, 300), compression='tiff_lzw')
            else:
                rgb.save(path, dpi=(300, 300))
            with Image.open(path) as image:
                require(image.mode == 'RGB' and all(abs(d-300) < .1 for d in image.info['dpi']),
                        '輸出圖檔規格不符')
                files.append({'File': path.name, 'Width': image.width, 'Height': image.height,
                              'DPI': 300, 'Mode': image.mode, 'Bytes': path.stat().st_size})
        plt.show()
        plt.close(fig)

    caption = (
        'Fig 1. Cohort assembly and sequential exclusions. Counts refer to linked records unless '
        'patients are specified. Hb date denotes the laboratory report date. '
        # 圖註直接使用已驗證的逐步排除表，區分日期不可評估與真正超限。
        f'Of {count(len(master))} initial records, {count(temporal_excluded)} were excluded at the temporal stage: '
        f'{count(removed(stages[0]))} had non-evaluable dates and '
        f'{count(removed(stages[1]))} had an evaluable absolute Hb report–DXA interval exceeding {interval} days. '
        f'The subsequent {count(later_excluded)} exclusions comprised '
        f'{count(removed(key_reasons[0]))} with unavailable DXA T-scores after masking, '
        f'{count(removed(key_reasons[1]))} with unavailable Hb after masking, '
        f'{count(removed(key_reasons[2]))} with incomplete required weather features, and '
        f'{count(other_excluded)} under the remaining age/sex completeness or subsequent range checks. '
        'These are mutually exclusive sequential exclusion counts; they are not counts of all overlapping failed criteria. '
        'Unavailable T-score or Hb values include values masked by the prespecified bounds. '
        'Individual stage counts and the processing order are reported in S12 Table. '
        'Required-weather-feature incompleteness does not identify a specific station-level or spatial '
        'matching cause. Reason-specific counts depend on the stated sequential order. '
        'Eligible records not selected for the primary analysis remain in the repeated-record cohort. '
        f'The primary cohort includes {count(n_primary_patients)} patients; its mean absolute '
        f'Hb report–DXA interval is {mean_gap:.1f} days. Selection reproduces the existing pipeline, '
        'including its handling of remaining ties; no representative records are reselected here.'
    )
    (out/'Fig1_caption.txt').write_text(caption+'\n', encoding='utf-8')
    flow.to_csv(out/'Fig1_exclusion_detail.csv', index=False, encoding='utf-8-sig')
    summary = pd.DataFrame([{
        'Master_records': len(master), 'Date_unevaluable': removed(stages[0]),
        'Evaluable_gap_exceeds_limit': removed(stages[1]), 'After_temporal': after_temporal,
        'Subsequent_exclusions': later_excluded, 'Repeated_records': len(repeated),
        'Repeated_patients': n_repeated_patients, 'Primary_patients': n_primary_patients,
        'Eligible_records_not_selected_for_primary': additional,
        'Primary_mean_absolute_gap_days': mean_gap}])
    summary.to_csv(out/'Fig1_count_summary.csv', index=False, encoding='utf-8-sig')
    status = {'Completed': True, 'Layout_reference': 'Fig1_20260921.tif',
              'Source_R05': r05['Output_dir'], 'Source_R19': str(source),
              'Source_flow_SHA256': hashlib.sha256((source/'PartB_Flow.csv').read_bytes()).hexdigest(),
              'New_models_fitted': 0, 'Cohorts_refiltered': False, 'Primary_reselected': False,
              'Original_files_overwritten': False, 'Existing_package_replaced': False,
              'Patient_records_exported': False, 'Box_text_bounds_passed': True}
    (out/'Fig1_run_status.json').write_text(json.dumps(status, ensure_ascii=False, indent=2), encoding='utf-8')
    print('\n=== 請回傳：Fig1 原圖版面 1 筆數核對 ===')
    print(summary.to_string(index=False))
    print('\n=== 請回傳：Fig1 原圖版面 2 輸出圖檔 ===')
    print(pd.DataFrame(files).to_string(index=False))
    print('\n=== 請回傳：Fig1 原圖版面 3 狀態 ===')
    print(pd.DataFrame([status]).to_string(index=False))
    print('\n輸出資料夾：', out)
    return {'Completed': True, 'output_dir': str(out), 'files': files, 'status': status}


_fig1_missing = [name for name in ['R05', 'R19', 'folder_path'] if name not in globals()]
if _fig1_missing:
    raise NameError(f'缺少目前 runtime 來源：{_fig1_missing}；請先執行相應來源格。')
FIG1_ORIGINAL_LAYOUT = fig1_original_layout(R05, R19, folder_path)

"""## S16 paired original/reconstructed weather classification

Input objects are produced by preceding cells in this notebook. Outputs remain private working artifacts until the publication export section. Manuscript items: S16 Table.

"""

# 原六分類器、參數、18 個特徵位置及預測規則均沿用 O06，不調參、不重新選 Primary。
from pathlib import Path
from datetime import datetime, timezone
import hashlib
import json
import time
import uuid
import warnings
import numpy as np
import pandas as pd

R34_HOURS = (18, 20, 24)       # 已指定的全部小時門檻，不按結果挑選。
R34_METRICS = ('AUC', 'Accuracy', 'F1', 'Precision', 'Recall')
R34_PAIR, R34_PID = 'pairing_row_id', '去個資編號'
R34_NEW_WEATHER = ['THI_mean_30d', 'DTR_mean_30d', 'THI_std_30d',
    'T_std_30d', 'THI_mean_180d', 'THI_hot_fraction_365d', 'THI_Trend_Shock']
R34_UNCHANGED_FEATURES = ['Age', 'sex_bin', 'Hb_Value', 'Age_Squared',
    'Extreme_Anemia', 'Hb_Deficit', 'Month_Sin', 'Month_Cos']


def r34_require(ok, message):
    if not bool(ok):
        raise ValueError('R34：' + message + '；停止，不改用其他來源或略過失敗模型。')


def r34_json(value):
    # 僅用於記錄／比較參數，保留原 estimator 的完整 resolved parameters。
    return json.dumps(value, ensure_ascii=False, sort_keys=True, default=str)


def r34_frame_hash(frame):
    return hashlib.sha256(pd.util.hash_pandas_object(frame, index=True).values.tobytes()
        + repr(list(frame.columns)).encode() + repr(list(frame.dtypes.astype(str))).encode()).hexdigest()


def r34_id_hash(values):
    return hashlib.sha256(r34_json(list(values)).encode()).hexdigest()


def r34_prepare(ctx, r05, r10, r12):
    """明確指定來源、恢復原 S4 分折，並建立同人同折的新舊氣象資料。"""
    for label, obj in [('R05', r05), ('R10', r10), ('R12', r12)]:
        r34_require(isinstance(obj, dict) and obj.get('Completed') is True, label + ' 未完成')
    r34_require(isinstance(ctx, dict) and 'S4_Table' in ctx.get('completed', {}),
                '請先完成 Cell 51／O00 與 Cell 63／O06')
    or_same_inputs(ctx)
    expected_primary = or_prepare(r05['df_primary'], primary=True)
    pd.testing.assert_frame_equal(ctx['primary'], expected_primary)
    p = ctx['primary'].copy(deep=True).reset_index(drop=True)
    d, y, _ = or_ml_data(p)
    r34_require(len(d) == len(p) and d[R34_PAIR].tolist() == p[R34_PAIR].tolist(),
                '原 S4 資料不是目前完整 Primary，不能另刪舊版缺失列')
    X_old = or_engineer18(d)

    # 只讀本次 O06 登錄的 S4；不掃資料夾、不以固定筆數猜來源。
    entry = ctx['completed']['S4_Table']
    s4_path = Path(entry['path'])
    r34_require(s4_path.is_file() and or_sha(s4_path) == entry['SHA256'], '本次 S4 檔案缺失或 SHA256 不符')
    sheets = pd.read_excel(s4_path, sheet_name=None)
    required = {'Numeric', 'Fold_metrics', 'Feature_order', 'Resolved_parameters', 'Denominators'}
    r34_require(required <= set(sheets), 'S4 缺少數值、逐折、特徵或參數工作表')
    r34_require(sheets['Feature_order']['Feature'].tolist() == list(X_old), 'S4 特徵順序與 O06 不符')
    reference = sheets['Numeric'].copy()
    algorithms = reference['Algorithm'].tolist()
    parameters = sheets['Resolved_parameters'].set_index('Algorithm', verify_integrity=True)
    r34_require(len(algorithms) == 6 and len(set(algorithms)) == len(algorithms)
        and set(algorithms) == set(parameters.index), '原六分類器來源不完整或重複')
    den = sheets['Denominators']
    r34_require(len(den) == 1 and int(den.iloc[0].Rows_used) == len(p)
        and int(den.iloc[0].Patients) == p[R34_PID].nunique()
        and int(den.iloc[0].Operational_positive) == int(y.sum()), 'S4 分母／結果類別與目前 Primary 不符')

    scope_path = Path(ctx['out']) / 'Audit' / 'source_scope.json'
    scope = json.loads(scope_path.read_text(encoding='utf-8'))
    seed, nfold = int(scope['Seed']), int(scope['CV_folds'])
    r34_require(seed == OR_SEED and nfold == OR_CV_FOLDS, 'O06 seed／fold 設定在原配適後被改動')
    lib = or_ml_imports()
    versions = {name: lib[name].__version__ for name in ['sklearn', 'xgboost', 'lightgbm']}
    r34_require(all(ctx['versions'].get(k) == v for k, v in versions.items()),
                '分類套件版本與 O06 不同；請在同一版本環境完成比較')
    templates = {}
    for alg in algorithms:
        est = or_estimator(lib, alg, benchmark=True)
        current = json.loads(json.dumps(est.get_params(deep=True), ensure_ascii=False, default=str))
        saved = json.loads(parameters.loc[alg, 'Full_resolved_parameters'])
        r34_require(r34_json(current) == r34_json(saved), alg + ' 參數與原 S4 不同')
        templates[alg] = est

    # 先在原完整 Primary 恢復原五折，再限制到各門檻共同可用者；不重新抽折。
    original_folds = list(lib['StratifiedKFold'](n_splits=nfold, shuffle=True,
        random_state=seed).split(X_old, y))
    fold_of_row = np.zeros(len(p), dtype=int)
    oldfold = sheets['Fold_metrics']
    r34_require(not oldfold.duplicated(['Algorithm', 'Fold']).any()
        and len(oldfold) == len(algorithms) * nfold, '原 S4 逐折資料不完整')
    for f, (tr, te) in enumerate(original_folds, 1):
        fold_of_row[te] = f
        rows = oldfold.loc[oldfold.Fold.eq(f)]
        r34_require(set(rows.Algorithm) == set(algorithms)
            and rows.Train_n.eq(len(tr)).all() and rows.Test_n.eq(len(te)).all(),
            f'原 S4 第 {f} 折分母不符')
    for alg in algorithms:
        rows = oldfold.loc[oldfold.Algorithm.eq(alg)]
        ref = reference.loc[reference.Algorithm.eq(alg)].iloc[0]
        for m in R34_METRICS:
            r34_require(np.isfinite(rows[m]).all()
                and np.isclose(rows[m].mean(), ref[m + '_mean'], rtol=1e-10, atol=1e-12)
                and np.isclose(rows[m].std(ddof=0), ref[m + '_SD'], rtol=1e-10, atol=1e-12),
                '原 S4 逐折與彙總不一致：' + alg + '/' + m)

    r05_spec = json.loads((Path(r05['Output_dir']) / 'analysis_specification.json').read_text())
    r10_spec = json.loads((Path(r10['output_dir']) / 'analysis_specification.json').read_text())
    bounds = tuple(r05_spec['Limits']['DTR'])
    r34_require(set(r10['linked_candidates']) == set(R34_HOURS)
        and set(r10['weather_candidates']) == set(R34_HOURS)
        and set(r12['datasets']) == set(R34_HOURS), '缺少已指定的 18／20／24 小時候選')
    r34_require(r10_spec['Windows_days'] == [30, 180, 365], 'R10 日曆窗格規格不同')
    master = r05['row_flags']
    ids = p[R34_PAIR].tolist()
    weather_cols = list(dict.fromkeys(R12_SIX + R34_NEW_WEATHER))
    cases, denominators, fold_counts, changes, heat, snapshots = {}, [], [], [], [], {}
    clinical = ['Age', 'sex_bin', 'Hb_Value', 'overall_T']
    for h in R34_HOURS:
        link = r10['linked_candidates'][h]
        cal = r10['weather_candidates'][h]
        r34_require(link[R34_PAIR].notna().all() and link[R34_PAIR].is_unique
            and set(link[R34_PAIR]) == set(master[R34_PAIR]), f'{h}h R10 母體 ID 不符')
        r34_require(set(link.loc[link.is_included_primary.eq(True), R34_PAIR]) == set(ids),
                    f'{h}h R10 Primary 旗標不符')
        q = link.set_index(R34_PAIR).loc[ids].reset_index()
        day = pd.to_datetime(p.Hb_Date).dt.normalize()
        r34_require(q[R34_PID].tolist() == p[R34_PID].tolist()
            and pd.to_datetime(q.Hb_Date).reset_index(drop=True).equals(p.Hb_Date)
            and pd.to_datetime(q.Hb_report_day).reset_index(drop=True).equals(day),
            f'{h}h 病人或檢驗報告日期與 Primary 不符')
        r34_require(q.Minimum_hours.eq(h).all() and q.Weather_version.eq(r10_spec['Version']).all(),
                    f'{h}h 氣象門檻或版本不符')
        r34_require(cal.index.is_unique, f'{h}h 氣象日曆日期重複')
        new = q[weather_cols].apply(pd.to_numeric, errors='raise').astype(float)
        r34_require(not np.isinf(new.to_numpy()).any(), f'{h}h 氣象有無限值')
        pd.testing.assert_frame_equal(new, cal.reindex(pd.DatetimeIndex(day))[weather_cols]
            .reset_index(drop=True).astype(float), check_dtype=False)
        complete = new.notna().all(axis=1)
        windows = np.ones(len(p), dtype=bool)
        for W in r10_spec['Windows_days']:
            ready = q[f'Window_ready_{W}d'].eq(True)
            windows &= ready.to_numpy()
            r34_require((pd.to_datetime(q.Window_end_day) - pd.to_datetime(q[f'Window_start_{W}d']))
                .dt.days.eq(W - 1).all(), f'{h}h {W} 日窗格邊界不符')
            r34_require(q[f'Required_valid_days_{W}d'].eq(r10_spec['Required_days'][str(W)]).all(),
                        f'{h}h 有效日門檻與 R10 規格不符')
        r34_require(np.array_equal(complete, q.Secondary_frequency_bundle_ready.eq(True))
            and np.array_equal(complete, windows), f'{h}h 特徵完整度與窗格旗標不符')
        dtr_ok = new.DTR_mean_30d.between(*bounds)
        keep = (complete & dtr_ok).to_numpy()
        r34_require(keep.any(), f'{h}h 無共同可用個案')
        # 同時核對已完成 R12 的個案與新氣象值；本格並不重新執行 R12。
        previous = r12['datasets'][h]
        r34_require(previous[R34_PAIR].is_unique and set(previous[R34_PAIR]) == set(p.loc[keep, R34_PAIR]),
                    f'{h}h 可用 ID 與 R12 不同')
        aligned = previous.set_index(R34_PAIR).loc[p.loc[keep, R34_PAIR]]
        r34_require(aligned[R34_PID].tolist() == p.loc[keep, R34_PID].tolist()
            and np.array_equal(aligned[clinical].to_numpy(float), p.loc[keep, clinical].to_numpy(float))
            and np.array_equal(aligned.Target.to_numpy(), y[keep]), f'{h}h R12 臨床或類別資料不同')
        r34_require(np.allclose(aligned[R34_NEW_WEATHER], new.loc[keep, R34_NEW_WEATHER],
            rtol=1e-12, atol=1e-12), f'{h}h R12 氣象數值不同')
        hot = q.loc[keep, 'THI_hot_days_365d_observed'].to_numpy(float)
        valid = q.loc[keep, 'Valid_days_365d'].to_numpy(float)
        fraction = new.loc[keep, 'THI_hot_fraction_365d'].to_numpy()
        r34_require(np.isfinite(hot).all() and np.isfinite(valid).all()
            and (valid > 0).all() and ((hot >= 0) & (hot <= valid)).all()
            and np.allclose(fraction, hot / valid, rtol=1e-12, atol=1e-12), f'{h}h 熱日比例／分母不符')

        selected = p.loc[keep].copy().reset_index(drop=True)
        updated = selected.copy(deep=True)
        for col in R34_NEW_WEATHER:
            if col != 'THI_hot_fraction_365d':
                updated[col] = new.loc[keep, col].to_numpy()
        legacy_X = X_old.loc[keep].reset_index(drop=True)
        calendar_X = or_engineer18(updated)  # 重算熱指標及 THI 交互作用，不沿用舊衍生值。
        # 第 7 個位置明確改成「有效日熱日比例」；不把比例冒名為熱日計數。
        calendar_X['THI_hot_days_365d'] = fraction
        calendar_X = calendar_X.rename(columns={'THI_hot_days_365d': 'THI_hot_fraction_365d'})
        new_names = ['THI_hot_fraction_365d' if c == 'THI_hot_days_365d' else c for c in X_old]
        r34_require(list(calendar_X) == new_names and np.isfinite(calendar_X.to_numpy()).all(),
                    f'{h}h 新特徵非有限或位置改變')
        pd.testing.assert_frame_equal(legacy_X[R34_UNCHANGED_FEATURES], calendar_X[R34_UNCHANGED_FEATURES])
        r34_require(np.allclose(calendar_X.THI_x_Hb, calendar_X.THI_mean_30d * calendar_X.Hb_Value)
            and np.allclose(calendar_X.THI_x_Age, calendar_X.THI_mean_30d * calendar_X.Age),
            f'{h}h THI 交互作用未同步更新')

        member_folds = fold_of_row[keep]
        folds = []
        for f in range(1, nfold + 1):
            tr, te = np.flatnonzero(member_folds != f), np.flatnonzero(member_folds == f)
            r34_require(len(tr) > 0 and len(te) > 0 and set(y[keep][tr]) == {0, 1}
                and set(y[keep][te]) == {0, 1}, f'{h}h 第 {f} 折空白或不足兩類')
            r34_require(len(tr) >= templates['K-nearest neighbors'].named_steps['clf'].n_neighbors,
                        f'{h}h 訓練筆數不足原 KNN 鄰居數')
            r34_require(not np.intersect1d(tr, te).size, f'{h}h 分折交疊')
            folds.append((tr, te))
            fold_counts.append({'Minimum_hours': h, 'Fold': f, 'Train_rows': len(tr), 'Test_rows': len(te),
                'Train_positive': int(y[keep][tr].sum()), 'Test_positive': int(y[keep][te].sum()),
                'Train_ID_order_SHA256': r34_id_hash(selected.iloc[tr][R34_PAIR]),
                'Test_ID_order_SHA256': r34_id_hash(selected.iloc[te][R34_PAIR]),
                'Same_rows_and_folds_for_both_weather_versions': True})
        r34_require(np.array_equal(np.sort(np.concatenate([te for _, te in folds])), np.arange(len(selected))),
                    f'{h}h 不是每人恰好測試一次')
        cases[h] = {'data': selected, 'X': {'Legacy_subset': legacy_X, 'Calendar_subset': calendar_X},
                    'y': y[keep].copy(), 'folds': folds}
        denominators.append({'Minimum_hours': h, 'Original_primary_rows': len(p),
            'Eligible_rows': len(selected), 'Eligible_patients': selected[R34_PID].nunique(),
            'Excluded_weather_or_DTR': int((~keep).sum()), 'Incomplete_weather_rows': int((~complete).sum()),
            'Complete_weather_but_DTR_outside': int((complete & ~dtr_ok).sum()),
            'Tested_once_rows': sum(len(te) for _, te in folds), 'Positive_rows': int(y[keep].sum()),
            'Same_eligible_IDs_as_R12': True})
        for old_col, new_col in zip(legacy_X, calendar_X):
            comparable = old_col == new_col
            delta = calendar_X[new_col] - legacy_X[old_col] if comparable else pd.Series(dtype=float)
            changes.append({'Minimum_hours': h, 'Legacy_feature': old_col, 'Calendar_feature': new_col,
                'Units_comparable': comparable, 'Legacy_mean': legacy_X[old_col].mean(),
                'Calendar_mean': calendar_X[new_col].mean(),
                'Changed_rows': int((~np.isclose(legacy_X[old_col], calendar_X[new_col], rtol=1e-10, atol=1e-10)).sum()) if comparable else np.nan,
                'Mean_new_minus_legacy': delta.mean()})
        heat.append({'Minimum_hours': h, 'Rows': len(selected), 'Minimum_valid_days_365d': int(valid.min()),
            'Maximum_valid_days_365d': int(valid.max()), 'Observed_hot_days_mean': hot.mean(),
            'Observed_day_hot_fraction_mean': fraction.mean(), 'Missing_days_counted_as_nonhot': False})
        snapshots[f'R10_link_{h}'] = r34_frame_hash(link)
        snapshots[f'R10_calendar_{h}'] = r34_frame_hash(cal)
        snapshots[f'R12_data_{h}'] = r34_frame_hash(previous)
    return {'p': p, 'lib': lib, 'cases': cases, 'reference': reference, 'algorithms': algorithms,
        'parameters': parameters.reset_index(), 'templates': templates, 'old_names': list(X_old),
        'denominators': pd.DataFrame(denominators), 'fold_counts': pd.DataFrame(fold_counts),
        'feature_changes': pd.DataFrame(changes), 'heat': pd.DataFrame(heat), 'snapshots': snapshots,
        'source_s4': s4_path, 'source_s4_sha': entry['SHA256'], 'seed': seed, 'nfold': nfold,
        'versions': versions, 'r10_spec': r10_spec, 'dtr_bounds': bounds}


def r34_fit_one(est, X, y, tr, te, lib):
    from sklearn.exceptions import ConvergenceWarning
    with warnings.catch_warnings(record=True) as caught:
        warnings.simplefilter('always')
        est.fit(X[tr], y[tr])
        probabilities = est.predict_proba(X[te])
        predicted = est.predict(X[te])  # 完全沿用原 O06 預測規則，包括邊界時的類別選擇。
    warning_rows = [{'Category': w.category.__name__, 'Message': str(w.message)} for w in caught]
    bad_warning = any(issubclass(w.category, (ConvergenceWarning, RuntimeWarning)) for w in caught)
    scaler = est.named_steps['scaler']
    r34_require(np.all(np.asarray(scaler.n_samples_seen_) == len(tr))
        and np.allclose(scaler.mean_, X[tr].mean(axis=0), rtol=1e-10, atol=1e-10), '標準化未限於訓練折')
    r34_require(np.array_equal(est.classes_, [0, 1]) and probabilities.shape == (len(te), 2)
        and np.isfinite(probabilities).all() and ((probabilities >= 0) & (probabilities <= 1)).all()
        and np.allclose(probabilities.sum(axis=1), 1, atol=1e-6)
        and np.isin(predicted, [0, 1]).all(), '分類輸出不合法')
    prob = probabilities[:, 1]
    scores = {'AUC': lib['roc_auc_score'](y[te], prob), 'Accuracy': lib['accuracy_score'](y[te], predicted),
        'F1': lib['f1_score'](y[te], predicted, zero_division=0),
        'Precision': lib['precision_score'](y[te], predicted, zero_division=0),
        'Recall': lib['recall_score'](y[te], predicted, zero_division=0),
        'No_predicted_positives': bool(np.sum(predicted) == 0)}
    r34_require(all(np.isfinite(scores[m]) for m in R34_METRICS), '效能指標不是有限值')
    return scores, warning_rows, bad_warning


def r34_summarize(metrics, reference, algorithms):
    keys = ['Minimum_hours', 'Algorithm', 'Fold', 'Train_rows', 'Test_rows']
    old = metrics.loc[metrics.Weather_version.eq('Legacy_subset'), keys + list(R34_METRICS)]
    new = metrics.loc[metrics.Weather_version.eq('Calendar_subset'), keys + list(R34_METRICS)]
    paired = old.merge(new, on=keys, suffixes=('_legacy', '_calendar'), validate='one_to_one')
    r34_require(len(paired) == len(old) == len(new), '新舊配適未逐折一對一對應')
    for m in R34_METRICS:
        paired['Delta_' + m] = paired[m + '_calendar'] - paired[m + '_legacy']
    numeric, performance, deltas = [], [], []
    for h in R34_HOURS:
        for alg in algorithms:
            p = paired.loc[paired.Minimum_hours.eq(h) & paired.Algorithm.eq(alg)]
            ref = reference.loc[reference.Algorithm.eq(alg)].iloc[0]
            display_delta = {'Minimum_hours': h, 'Algorithm': alg}
            for weather, suffix in [('Legacy_subset', '_legacy'), ('Calendar_subset', '_calendar')]:
                row = {'Minimum_hours': h, 'Algorithm': alg, 'Weather_version': weather,
                       'Participants': int(p.Test_rows.sum())}
                for m in R34_METRICS:
                    v = p[m + suffix]
                    row[m] = f'{v.mean():.4f} ± {v.std(ddof=0):.4f}'
                performance.append(row)
            for m in R34_METRICS:
                a, b, delta = p[m + '_legacy'], p[m + '_calendar'], p['Delta_' + m]
                numeric.append({'Minimum_hours': h, 'Algorithm': alg, 'Metric': m,
                    'Participants': int(p.Test_rows.sum()), 'Folds': len(p),
                    'Full_S4_legacy_mean': ref[m + '_mean'], 'Full_S4_legacy_SD': ref[m + '_SD'],
                    'Legacy_subset_mean': a.mean(), 'Legacy_subset_SD': a.std(ddof=0),
                    'Calendar_subset_mean': b.mean(), 'Calendar_subset_SD': b.std(ddof=0),
                    'Delta_mean': delta.mean(), 'Delta_fold_SD': delta.std(ddof=0),
                    'Delta_min': delta.min(), 'Delta_max': delta.max(),
                    'Legacy_subset_minus_full_S4': a.mean() - ref[m + '_mean']})
                display_delta[m] = f'{delta.mean():+.4f} ± {delta.std(ddof=0):.4f}'
            deltas.append(display_delta)
    return pd.DataFrame(numeric), pd.DataFrame(performance), pd.DataFrame(deltas), paired


def r34_run(ctx, r05, r10, r12, root):
    """完成來源檢查後才配適；任何失敗均記錄並停止，不產生完成標記。"""
    run_id = datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ') + '_' + uuid.uuid4().hex[:8]
    out = Path(root) / 'OUTPUT' / ('R34_S16_' + run_id)
    for part in ['Supplementary_Tables', 'Notes', 'Audit']:
        (out / part).mkdir(parents=True, exist_ok=False)
    ledger, warnlog, scores, checks = [], [], [], []
    status = {'Completed': False, 'S16_exported': False, 'Original_tables_modified': False,
        'Original_cohorts_changed': False, 'Primary_reselected': False, 'Age_values_changed': False,
        'Original_weather_modified': False, 'Patient_records_exported': False,
        'Hour_threshold_selected': False, 'Hyperparameters_tuned': False,
        'New_significance_tests': 0, 'New_bootstrap_draws': 0, 'S13_refitted': False}
    def check(name, ok):
        checks.append({'Check': name, 'Passed': bool(ok)})
        r34_require(ok, name)
    try:
        z = r34_prepare(ctx, r05, r10, r12)
        check('S4_source_versions_parameters_and_reference_summary_verified', True)
        check('R10_R12_IDs_clinical_values_dates_weather_and_window_rules_verified', True)
        check('All_thresholds_preserve_original_fold_assignment_and_pair_versions', True)
        before_primary = r34_frame_hash(ctx['primary'])
        before_completed = r34_json(ctx['completed'])
        expected = sum(len(c['folds']) * len(c['X']) * len(z['algorithms']) for c in z['cases'].values())
        status['Fits_requested'] = expected
        params = z['parameters'].copy()
        params.to_csv(out / 'Audit' / 'Inherited_S4_parameters.csv', index=False, encoding='utf-8-sig')
        provenance = {'Module': 'R34', 'Reviewer': 'R1 Major 4', 'Source_notebook':
            'self-contained analysis implementation',
            'Original_reproduction': str(ctx['out']), 'Source_S4': str(z['source_s4']),
            'Source_S4_SHA256': z['source_s4_sha'], 'Source_R05': r05['Output_dir'],
            'Source_R10': r10['output_dir'], 'Source_R12': r12['output_dir'],
            'Seed': z['seed'], 'Folds': z['nfold'], 'Thresholds': list(R34_HOURS),
            'Primary_fingerprint': before_primary, 'Input_fingerprints': z['snapshots'],
            'Software': {'numpy': np.__version__, 'pandas': pd.__version__, **z['versions']},
            'Original_parameters_reused': True, 'Full_S4_reference_refitted': False,
            'Window_specification': z['r10_spec'], 'DTR_bounds': z['dtr_bounds'],
            'Prediction_rule': 'Original O06 estimator.predict, no threshold tuning',
            'Fold_rule': 'Original full-primary StratifiedKFold assignments, restricted to each common eligible subset',
            'Hot_feature_change': 'Legacy row-window count replaced in the same feature position by observed-hot-days / valid-days in 365 calendar days',
            'Interpretation': 'Joint sensitivity to weather reconstruction and hot-feature definition; not an isolated window-only effect or temporal validation'}
        or_json(out / 'Audit' / 'R34_provenance.json', provenance)
        z['denominators'].to_csv(out / 'Audit' / 'Cohort_counts.csv', index=False, encoding='utf-8-sig')
        z['fold_counts'].to_csv(out / 'Audit' / 'Fold_counts.csv', index=False, encoding='utf-8-sig')
        print(f'R34：{len(z["algorithms"])} 種原分類器 × {len(R34_HOURS)} 個門檻 × '
              f'{z["nfold"]} 折 × 2 種氣象，預計 {expected} 次配適。', flush=True)
        from sklearn.base import clone
        for h, case in z['cases'].items():
            for alg in z['algorithms']:
                for f, (tr, te) in enumerate(case['folds'], 1):
                    for weather, frame in case['X'].items():
                        rec = {'Minimum_hours': h, 'Algorithm': alg, 'Fold': f, 'Weather_version': weather,
                            'Train_rows': len(tr), 'Test_rows': len(te), 'Status': 'started',
                            'Seconds': np.nan, 'Warning_count': 0, 'Error': ''}
                        ledger.append(rec)
                        started = time.perf_counter()
                        try:
                            model = clone(z['templates'][alg])
                            result, caught, bad_warning = r34_fit_one(model, frame.to_numpy(float),
                                case['y'], tr, te, z['lib'])
                            rec['Warning_count'] = len(caught)
                            warnlog.extend({k: rec[k] for k in ['Minimum_hours', 'Algorithm', 'Fold', 'Weather_version']}
                                | w for w in caught)
                            r34_require(not bad_warning, f'{h}h／{alg}／fold {f}／{weather} 有收斂或數值警告，詳見 fit_warnings.csv')
                            scores.append({k: rec[k] for k in ['Minimum_hours', 'Algorithm', 'Fold',
                                'Weather_version', 'Train_rows', 'Test_rows']} | result)
                            rec['Status'] = 'success'
                        except Exception as exc:
                            rec.update(Status='failed', Error=f'{type(exc).__name__}: {exc}')
                            raise
                        finally:
                            rec['Seconds'] = time.perf_counter() - started
                # 每個演算法完成便寫入進度，保留已完成配適，不靜默跳過失敗。
                pd.DataFrame(ledger).to_csv(out / 'Audit' / 'fit_ledger.csv', index=False, encoding='utf-8-sig')
                pd.DataFrame(scores).to_csv(out / 'Audit' / 'fold_metrics_partial.csv', index=False, encoding='utf-8-sig')
                print(f'R34 {h}h／{alg}：新舊氣象全部折數完成；進度 {len(scores)}/{expected}。', flush=True)
        metrics = pd.DataFrame(scores)
        numeric, performance, deltas, paired = r34_summarize(metrics, z['reference'], z['algorithms'])
        check('Every_requested_fit_succeeded', len(ledger) == expected and all(r['Status'] == 'success' for r in ledger))
        check('Every_fit_has_one_metric_row', len(metrics) == expected
            and not metrics.duplicated(['Minimum_hours', 'Algorithm', 'Fold', 'Weather_version']).any())
        check('Every_algorithm_and_version_tests_each_eligible_person_once', all(
            g.Test_rows.sum() == len(z['cases'][h]['data'])
            for (h, _, _), g in metrics.groupby(['Minimum_hours', 'Algorithm', 'Weather_version'])))
        check('Paired_delta_mean_equals_difference_of_means', np.allclose(numeric.Delta_mean,
            numeric.Calendar_subset_mean - numeric.Legacy_subset_mean, atol=1e-12))
        for h in R34_HOURS:
            check(f'{h}h_R10_link_unchanged', r34_frame_hash(r10['linked_candidates'][h]) == z['snapshots'][f'R10_link_{h}'])
            check(f'{h}h_R10_calendar_unchanged', r34_frame_hash(r10['weather_candidates'][h]) == z['snapshots'][f'R10_calendar_{h}'])
            check(f'{h}h_R12_dataset_unchanged', r34_frame_hash(r12['datasets'][h]) == z['snapshots'][f'R12_data_{h}'])
        or_same_inputs(ctx)
        check('Original_primary_and_output_registry_unchanged', r34_frame_hash(ctx['primary']) == before_primary
            and r34_json(ctx['completed']) == before_completed and or_sha(z['source_s4']) == z['source_s4_sha'])
        definitions = []
        for i, name in enumerate(z['old_names'], 1):
            definitions.append({'Position': i, 'Legacy_feature': name,
                'Calendar_feature': 'THI_hot_fraction_365d' if name == 'THI_hot_days_365d' else name,
                'Action': ('Replace count with observed-day hot fraction; explicit unit/definition change'
                    if name == 'THI_hot_days_365d' else 'Unchanged clinical/month feature'
                    if name in R34_UNCHANGED_FEATURES else 'Recalculate from R10 calendar weather')})
        fits = pd.DataFrame(ledger).groupby(['Minimum_hours', 'Algorithm'], sort=False).agg(
            Attempted=('Status', 'size'), Succeeded=('Status', lambda s: int(s.eq('success').sum())),
            Failed=('Status', lambda s: int(s.ne('success').sum())), Warnings=('Warning_count', 'sum')).reset_index()
        notes = [
            'S16 Table. Sensitivity of the original S4 six-classifier benchmark to calendar-based weather reconstruction.',
            'The original primary cohort and S4 table remain unchanged. All six original classifier specifications, feature positions, preprocessing and estimator.predict rules are retained. No tuning, algorithm selection or outcome-based hourly-threshold selection is performed.',
            f'The original {z["nfold"]}-fold stratified shuffled split (seed {z["seed"]}) is reconstructed on the original Primary order, then restricted to eligible records at each hourly threshold. Legacy and calendar models are refitted using identical training and test patients within each threshold. These restricted folds are not newly re-stratified.',
            'The full original S4 results are read from its verified workbook as context. The restricted legacy arm is refitted: merely restricting saved full-cohort predictions would retain training subjects excluded from the calendar arm and would not provide the intended matched comparison.',
            'Calendar weather is taken from R10 at 18, 20 and 24 jointly valid hours/day. Windows include the Hb laboratory report date. Existing minimum-valid-day and DTR rules are retained. Included IDs and weather values are checked against the completed R12 inputs; no participants are reselected.',
            'The 365-day feature changes from the legacy THI_hot_days_365d to THI_hot_fraction_365d: observed hot days divided by valid days in the calendar window. Missing THI is not a non-hot day. No annualization is performed. This is a joint sensitivity to weather construction and feature definition, not an isolated change in window indexing.',
            'Severe_Heat_Stress and the THI-by-Hb and THI-by-age terms are regenerated by the original O06 feature function from updated THI. Age, sex, Hb and their non-weather transformations and report-month terms are unchanged.',
            'Performance values are unweighted fold means and population SDs (ddof=0), matching S4. Deltas are calendar minus legacy on corresponding folds. Delta_fold_SD is the SD of foldwise differences, not the difference of SDs, an SE or a confidence interval. No significance tests or superiority claims are produced.',
            'Full_S4_legacy_mean is a different-denominator reference. Legacy_subset_minus_full_S4 describes changes in both training and evaluation composition; it is not a causal estimate of selection bias.',
            'AUC uses positive-class probabilities; Accuracy, F1, Precision and Recall use the original estimator.predict rule. Undefined precision/F1 uses zero_division=0 as in S4; no-predicted-positive folds are explicitly flagged.',
            'This retains random-fold same-record classification to isolate the weather comparison within the S4 specification. Shared-date dependence and temporal generalization are not resolved here. Refer to S13 for clinical-plus-calendar comparisons and temporally separated evaluation; S13 is not refitted.',
            'The outcome is the existing operational minimum-available-T-score category, not adjudicated osteoporosis or evidence of clinical utility. No individual IDs, predictions or clinical records are exported in this publication supplement.'
        ]
        tables = {'Display_Performance': performance, 'Display_Delta': deltas, 'Numeric': numeric,
            'Fold_metrics': metrics, 'Fold_deltas': paired, 'Cohort_counts': z['denominators'],
            'Fold_counts': z['fold_counts'], 'Feature_definitions': pd.DataFrame(definitions),
            'Feature_changes': z['feature_changes'], 'Hot_feature_denominators': z['heat'],
            'Original_S4_reference': z['reference'], 'Resolved_parameters': params, 'Fit_counts': fits}
        # 複用原輸出工具，但使用獨立 registry／新資料夾；不改動 O08 的既有成品。
        export_ctx = dict(ctx)
        export_ctx.update(out=out, completed={})
        or_export(export_ctx, 'S16_Table', tables, notes)
        check('Original_registry_still_unchanged_after_export', r34_json(ctx['completed']) == before_completed)
        status.update(Completed=True, S16_exported=True, Fits_succeeded=len(scores), Fits_failed=0,
            Algorithms=len(z['algorithms']), Hour_thresholds=len(R34_HOURS), Folds=z['nfold'],
            Same_patients_and_folds=True, Source_S4_verified=True, Checks=len(checks),
            All_passed=all(c['Passed'] for c in checks))
        for title, table in [
            ('1 世代與保留分母', z['denominators']),
            ('2 AUC 新舊配對比較', numeric.loc[numeric.Metric.eq('AUC'), ['Minimum_hours', 'Algorithm',
                'Participants', 'Full_S4_legacy_mean', 'Legacy_subset_mean', 'Calendar_subset_mean', 'Delta_mean', 'Delta_fold_SD']]),
            ('3 五項指標差值（新減舊；平均 ± 折間 SD）', deltas),
            ('4 熱日比例與有效日分母', z['heat']), ('5 配適紀錄', fits),
            ('6 驗證與狀態', pd.DataFrame([status]))]:
            print('\n=== 請回傳：R34／S16 ' + title + ' ===')
            print(table.to_string(index=False, float_format=lambda v: f'{v:.8g}'))
        print('\n輸出位置：' + str(out))

        return {'Completed': True, 'tables': tables, 'status': status, 'output_dir': str(out),
                'publication': export_ctx['completed']['S16_Table'], 'provenance': provenance}
    except Exception as exc:
        status.update(Error_type=type(exc).__name__, Error=str(exc),
            Fits_succeeded=sum(r['Status'] == 'success' for r in ledger),
            Fits_failed=sum(r['Status'] == 'failed' for r in ledger))
        print('R34 未完成；錯誤及已執行紀錄保留於：' + str(out))
        raise
    finally:
        pd.DataFrame(ledger).to_csv(out / 'Audit' / 'fit_ledger.csv', index=False, encoding='utf-8-sig')
        pd.DataFrame(warnlog, columns=['Minimum_hours', 'Algorithm', 'Fold', 'Weather_version', 'Category', 'Message']).to_csv(
            out / 'Audit' / 'fit_warnings.csv', index=False, encoding='utf-8-sig')
        pd.DataFrame(checks, columns=['Check', 'Passed']).to_csv(out / 'Audit' / 'validation.csv', index=False, encoding='utf-8-sig')
        if scores:
            pd.DataFrame(scores).to_csv(out / 'Audit' / 'fold_metrics_completed.csv', index=False, encoding='utf-8-sig')
        or_json(out / 'Audit' / 'run_status.json', status)


