from pathlib import Path
import pandas as pd

if "R34" not in globals() or not isinstance(R34, dict):
    raise NameError("缺少本次 R34 物件；請使用完成 S16 的同一 runtime。")

warning_file = Path(R34["output_dir"]) / "Audit" / "fit_warnings.csv"
if not warning_file.is_file():
    raise FileNotFoundError(f"找不到本次警告紀錄：{warning_file}")

w = pd.read_csv(warning_file)

print("=== 請回傳：R34／S16 警告內容彙總 ===")
if w.empty:
    print("沒有警告紀錄。")
else:
    summary = (
        w.groupby(["Algorithm", "Category", "Message"], dropna=False)
         .size()
         .reset_index(name="Warnings")
    )
    print(summary.to_string(index=False))

