# OR_LEGACY_FIXED 由交付版內嵌的原 Word 表格建立，僅作舊版固定基準。

def or_numbers(s):
    s=str(s).replace('−','-').replace('–','-').replace(',','')
    return re.findall(r'[+-]?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?',s)

def or_display_check(ctx,item,row,column,old,current):
    old_tokens=or_numbers(old);new_tokens=or_numbers(current)
    if not old_tokens:return
    old_signs=str(old).replace('−','-');new_signs=str(current).replace('−','-')
    if len(old_tokens)!=len(new_tokens):
        ctx['legacy_checks'].append({'Item':item,'Row':row,'Column':column,'Legacy_fixed_display':str(old),
            'Current_display':str(current),'Comparable':False,'Matches_display_precision':False,'Reason':'不同顯示結構；不能自動證明一致'})
        return
    matches=[]
    for a,b in zip(old_tokens,new_tokens):
        # 百分比／係數依原稿顯示位數；整數是精確計數，不能以寬容差通過。
        decimals=len(a.split('.')[1].split('e')[0].split('E')[0]) if '.' in a else 0
        tol=(.500001*10**(-decimals)) if decimals else 1e-10
        matches.append(abs(float(a)-float(b))<=tol)
    if ('<' in old_signs)!=('<' in new_signs):matches.append(False)
    ctx['legacy_checks'].append({'Item':item,'Row':row,'Column':column,'Legacy_fixed_display':str(old),
        'Current_display':str(current),'Comparable':True,'Matches_display_precision':bool(all(matches)),
        'Reason':'依原稿顯示精度比對；不是個案 ID 等同性檢驗'})

# 僅解析 S3 的已報告欄位；95% 是 CI 層級，不是 CI 端點。
def or_s3_parse_reported(text):
    s = str(text).replace('−', '-').replace('–', '-').strip()
    number = r'[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?'
    pattern = (
        rf'(?P<Beta>{number})\s*\(\s*SE\s+(?P<SE>{number})\s*\)\s*;\s*'
        rf'(?:(?P<CI_level>\d+(?:\.\d+)?)\s*%\s*CI\s*'
        rf'(?P<open>\[)?\s*(?P<CI_low>{number})\s*(?:to|,)\s*'
        rf'(?P<CI_high>{number})\s*(?P<close>\])?\s*;\s*)?'
        rf'P\s*(?P<P_operator><=|<|=)\s*(?P<P>{number})'
    )
    match = re.fullmatch(pattern, s, flags=re.IGNORECASE)
    or_require(match is not None, 'S3 原稿文字格式無法明確解析：' + s)
    fields = match.groupdict()
    result = {'Beta': fields['Beta'], 'SE': fields['SE']}
    if fields['CI_level'] is not None:
        or_require(np.isclose(float(fields['CI_level']), 100 * (1 - OR_ALPHA)),
                   'S3 原稿 CI 層級與目前模型區間不同')
        or_require(bool(fields['open']) == bool(fields['close']), 'S3 CI 括號不完整')
        or_require(float(fields['CI_low']) <= float(fields['CI_high']), 'S3 CI 端點順序錯誤')
        result.update(CI_low=fields['CI_low'], CI_high=fields['CI_high'])
    result['P'] = fields['P']
    or_require(all(np.isfinite(float(v)) for v in result.values()), 'S3 原稿數值非有限')
    or_require(float(result['SE']) > 0 and 0 <= float(result['P']) <= 1,
               'S3 原稿 SE 或 P 不合法')
    return result, fields['P_operator']


def or_s3_reconciliation_rows(ctx):
    scratch = {'legacy_checks': []}
    original_rows = OR_LEGACY_FIXED['supplement'][4]['rows'][1:]
    for i, row in enumerate(original_rows):
        n_a = ctx['models'][f'S3_{i}_A']['n']
        n_b = ctx['models'][f'S3_{i}_B']['n']
        or_require(n_a == n_b, f'S3 第 {i + 1} 列兩個模型分母不同')
        for j, (which, term) in enumerate([('A', 'THI_mean_30d'), ('B', 'Hb_Value')]):
            current = or_term(ctx['models'][f'S3_{i}_{which}'], term)
            fixed, operator = or_s3_parse_reported(row[j + 2])
            # 原稿 ordered 子集沒有 CI：只核對原稿實際報告的欄位。
            for field, original in fixed.items():
                value = current[field]
                or_require(np.isfinite(value), f'S3 {which}_{field} 本次數值非有限')
                if field == 'P' and operator in ('<', '<='):
                    passed = value < float(original) if operator == '<' else value <= float(original)
                    scratch['legacy_checks'].append({
                        'Item': 'S3_Table', 'Row': i + 1, 'Column': which + '_P',
                        'Legacy_fixed_display': operator + original,
                        'Current_display': str(value), 'Comparable': True,
                        'Matches_display_precision': bool(passed), 'Reason': '歷史 P 值上界'})
                else:
                    or_display_check(scratch, 'S3_Table', i + 1, which + '_' + field,
                                     original, str(value))
        or_display_check(scratch, 'S3_Table', i + 1, 'N', row[1], str(n_a))
    return scratch['legacy_checks']


def or_reconcile(ctx):
    # 只比較有相同結構的欄位；不把新區間與舊缺失區間當成數值不一致。
    plan=[('Table2','main',2,'Table2',None),('S1_Table','supplement',1,'S1_Table',None),
        ('Table3','main',3,'Table3',[2,3]),('Table4','main',4,'Table4',[1,2,3,4,5]),
        ('Table5','main',5,'Table5',list(range(1,7))),('S4_Table','supplement',6,'S4_Table',list(range(1,6))),
        ('S2B','supplement',3,'S2B',[2]),('S5B','supplement',9,'S5B',[0,1,2]),
        ('S6_Table','supplement',10,'S6_Table',[1,2,3,4]),
        ('S7B','supplement',12,'S7B',[1,2,3]),('S7C','supplement',13,'S7C',[1,2,3])]
    for label,source,tn,key,cols in plan:
        old=OR_LEGACY_FIXED[source][tn-1]['rows'];new=ctx['table_cache'][key]
        or_require(len(old)-1==len(new),label+' 表格結構改變，無法逐格對帳')
        for i in range(len(new)):
            for j in (cols if cols is not None else range(1,len(old[0]))):
                or_display_check(ctx,label,i+1,j,old[i+1][j],new.iloc[i,j])
        if label in ['Table2','S1_Table']:
            for j in range(1,len(old[0])):or_display_check(ctx,label,'Header',j,old[0][j],new.columns[j])
    # S3 依 Beta／SE／CI／P 標記解析；95% 是 CI 層級，不是 CI 端點。
    ctx['legacy_checks'].extend(or_s3_reconciliation_rows(ctx))
    product=ctx['product_numeric'].iloc[0]
    for field,fixed in [('Product','-0.000634'),('CI_low','-0.001440'),('CI_high','+0.000051')]:
        or_display_check(ctx,'S2_product',1,field,fixed,str(product[field]))
    sp=ctx['spline_numeric'].iloc[0]
    for field,fixed in [('Linear_loglik','-7791.9246'),('Spline_loglik','-7780.2917'),('LR','23.2657'),('DF_difference','2')]:
        or_display_check(ctx,'S2_spline',1,field,fixed,str(sp[field]))
    old_spline=OR_LEGACY_FIXED['supplement'][3]['rows']
    for row,label,vals in [(4,'Actual_basis_interior_knots',ctx['actual_spline_knots'][1:-1]),
        (5,'Boundary_support',[sp.Boundary_low,sp.Boundary_high])]:
        or_display_check(ctx,'S2_spline',row,label,old_spline[row][1],' / '.join(map(str,vals)))
    age=ctx['s7a_numeric']
    old=OR_LEGACY_FIXED['supplement'][10]['rows'][1]
    for j,term in enumerate(['Hb_Value','THI_mean_30d']):
        cur=age.loc[age.Term.eq(term)].iloc[0];oldv=or_numbers(old[j+2])
        for k,f in enumerate(['Beta','SE','CI_low','CI_high','P']):
            if f=='P' and '<' in old[j+2]:
                ctx['legacy_checks'].append({'Item':'S7A','Row':1,'Column':term+'_P','Legacy_fixed_display':'<'+oldv[k],
                    'Current_display':str(cur.P),'Comparable':True,'Matches_display_precision':bool(cur.P<float(oldv[k])),'Reason':'歷史 P 值上界'})
            else:or_display_check(ctx,'S7A',1,term+'_'+f,oldv[k],str(cur[f]))
    or_display_check(ctx,'S7A',1,'N_and_operational_category',old[1],ctx['s7a_display'].iloc[0,1])
    # 舊 S1 Fig 的程式內固定序列僅作來源對照，絕不作繪圖的替代資料。
    legacy=OR_LEGACY_FIXED['S1_Fig_legacy_fixed_benchmark']
    annual=ctx['annual_summary'].set_index('Year')
    for r in legacy:
        if r['Year'] not in annual.index:
            ctx['legacy_checks'].append({'Item':'S1_Fig','Row':r['Year'],'Column':'Year','Legacy_fixed_display':str(r['Year']),
                'Current_display':'absent','Comparable':False,'Matches_display_precision':False,'Reason':'本次沒有該年度'})
        else:
            for f in ['Records','Mean_T','Percent_T_le25']:or_display_check(ctx,'S1_Fig',r['Year'],f,str(r[f]),str(annual.loc[r['Year'],f]))
    audit=pd.DataFrame(ctx['legacy_checks'])
    audit.to_csv(ctx['out']/'Audit/Legacy_fixed_vs_current_reconciliation.csv',index=False,encoding='utf-8-sig')
    audit.loc[~audit.Matches_display_precision].to_csv(ctx['out']/'Audit/Legacy_differences_to_review.csv',index=False,encoding='utf-8-sig')
    return audit


# R36／O08：只整合既有成品；不配適模型、不篩選世代、不修改原稿比較基準。
R36_KNOT_INTERPRETATION = 'Default one-third and two-thirds empirical quantiles of distinct THI values'
R36_OLD_KNOT_INTERPRETATION = 'Actual fitted Patsy knots, rounded for display'


def r36_check_s16_book(path, tables, caption_path):
    """S16 沿用 O00 匯出格式：欄名含底線、另有 Notes；不可套用 R21 的欄名轉換。"""
    book = load_workbook(path, read_only=True, data_only=False)
    try:
        or_require(set(book.sheetnames) == set(tables) | {'Notes'}, 'S16 工作表集合不符')
        for name, table in tables.items():
            ws = book[name]
            or_require([c.value for c in ws[1]] == list(table.columns), 'S16 欄名不同：' + name)
            or_require(ws.max_row == max(1, len(table) + 1) and ws.max_column == len(table.columns),
                       'S16 工作表尺寸不同：' + name)
            for cells, values in zip(ws.iter_rows(min_row=2), table.itertuples(index=False, name=None)):
                for cell, value in zip(cells, values):
                    got = cell.value
                    or_require(cell.data_type != 'f', 'S16 不應出現試算表公式：' + name)
                    if pd.isna(value) or value == '':
                        valid = got is None or got == ''
                    elif isinstance(value, (bool, np.bool_)):
                        valid = isinstance(got, bool) and got == bool(value)
                    elif isinstance(value, (float, int, np.number)):
                        valid = isinstance(got, (float, int)) and np.isclose(value, got, rtol=1e-12, atol=1e-14)
                    elif isinstance(value, (pd.Timestamp, datetime, np.datetime64)):
                        valid = pd.Timestamp(got) == pd.Timestamp(value)
                    else:
                        valid = str(got) == str(value)
                    or_require(valid, 'S16 記憶體與工作簿不同：' + name + '!' + cell.coordinate)
        ws = book['Notes']
        or_require([c.value for c in ws[1]] == ['Notes'] and ws.max_column == 1, 'S16 Notes 格式不同')
        notes = [row[0] for row in ws.iter_rows(min_row=2, values_only=True)]
        or_require(all(isinstance(v, str) for v in notes), 'S16 Notes 內容缺失')
        or_require('\n\n'.join(notes) == Path(caption_path).read_text(encoding='utf-8'),
                   'S16 表註與工作簿 Notes 不同')
    finally:
        book.close()


def r36_difference_register(audit):
    """差異仍維持 False；補上位置、來源與待稿件處置，不將差異改成驗證通過。"""
    pending = audit.loc[audit.Matches_display_precision.eq(False)].copy()
    locations, sources, notes, actions = [], [], [], []
    for row in pending.itertuples(index=False):
        location = f'資料列 {row.Row}／欄位 {row.Column}'
        source, note = 'O08 原稿數值對帳', '新發現的差異；需人工確認來源與稿件採值，不自動判定原因。'
        action = 'Needs_source_review'
        if row.Item == 'S4_Table':
            old = OR_LEGACY_FIXED['supplement'][5]['rows']
            location = f'{old[int(row.Row)][0]}／{old[0][int(row.Column)]}'
            source = 'O06 / S4_Table_rerun.xlsx; original classifier specification'
            note = '保留本次原規格重跑值與原稿基準；此處不是 S16 新氣象結果。不推定差異來自套件版本或四捨五入。'
            action = 'Current_result_available_manuscript_adoption_pending'
        elif row.Item == 'Table3' and str(row.Row) == '8' and str(row.Column) == '3':
            source = 'O02 / Table3_rerun.xlsx; current Primary Model B conditional THI P'
            note = '保留現行模型 P 值與原稿顯示值；後續同步稿件，不改寫 legacy 基準。'
            action = 'Current_result_available_manuscript_adoption_pending'
        elif row.Item == 'Table4' and str(row.Row) == '2' and str(row.Column) == '4':
            source = 'O02 / Table4_rerun.xlsx; year-only THI VIF'
            note = '保留本次原規格 VIF 與原稿顯示值；不放寬比對容差，不宣稱兩值相同。'
            action = 'Current_result_available_manuscript_adoption_pending'
        elif row.Item == 'S7B' and str(row.Row) == '2' and str(row.Column) == '3':
            source = 'O06 / S7_Table_rerun.xlsx; age-restricted XGBoost delta AUC'
            note = 'ΔAUC 使用本次未先四捨五入的結果計算後顯示；原稿基準照留。'
            action = 'Current_result_available_manuscript_adoption_pending'
        elif row.Item == 'S2_spline' and str(row.Column) == 'Actual_basis_interior_knots':
            location = str(row.Column)
            source = 'O05 / S2_Table_rerun.xlsx; Actual_spline_knots'
            note = '原稿列的是全資料列經驗分位數；目前列實際配適 basis 的 distinct-value 結點。模型未改，顯示取兩位小數，完整精度另存。'
            action = 'Definition_and_label_corrected_manuscript_adoption_pending'
        locations.append(location); sources.append(source); notes.append(note); actions.append(action)
    pending.insert(1, 'Location', locations)
    pending['Current_source'] = sources
    pending['Revision_note'] = notes
    pending['Disposition'] = actions
    pending['Manuscript_modified'] = False
    return pending


def r36_s2_label_only(out):
    """支援接續 R35 runtime：只修改新複本的結點說明；所有數值及原檔保留。"""
    book_path = out / 'Supplementary_Tables/S2_Table_rerun.xlsx'
    book = load_workbook(book_path)
    before = {ws.title: list(ws.values) for ws in book.worksheets}
    found = []
    for ws in book.worksheets:
        headers = [c.value for c in ws[1]]
        if 'Item' not in headers or 'Interpretation' not in headers:
            continue
        for row in ws.iter_rows(min_row=2):
            if row[headers.index('Item')].value == 'Interior knots':
                target = row[headers.index('Interpretation')]
                or_require(target.value in [R36_OLD_KNOT_INTERPRETATION, R36_KNOT_INTERPRETATION],
                           'S2 結點說明不是明列的舊／新版，停止，不猜測替代欄位')
                found.append((ws.title, target.coordinate))
                target.value = R36_KNOT_INTERPRETATION
    or_require(len(found) == 1, 'S2 C Interior knots 說明並非唯一')
    changed = before != {ws.title: list(ws.values) for ws in book.worksheets}
    if changed:
        book.save(book_path)
    book.close()
    after_book = load_workbook(book_path, read_only=True, data_only=False)
    after = {ws.title: list(ws.values) for ws in after_book.worksheets}
    # 唯一允許的值差異是指定的 Interpretation；數值、公式與其他文字必須一致。
    allowed_sheet, allowed_cell = found[0]
    from openpyxl.utils.cell import coordinate_to_tuple
    rr, cc = coordinate_to_tuple(allowed_cell)
    expected = {name: [list(row) for row in rows] for name, rows in before.items()}
    expected[allowed_sheet][rr - 1][cc - 1] = R36_KNOT_INTERPRETATION
    or_require(expected == {name: [list(row) for row in rows] for name, rows in after.items()},
               'S2 結點文字同步改變了其他儲存格')
    after_book.close()
    # HTML 與 CSV 採原字串替換，避免重新序列化數值造成顯示精度改變。
    for path in [out / 'Supplementary_Tables/S2_Table_for_Word.html',
                 out / 'Audit' / f'S2_Table__{allowed_sheet}.csv']:
        text = path.read_text(encoding='utf-8')
        or_require(text.count(R36_OLD_KNOT_INTERPRETATION) + text.count(R36_KNOT_INTERPRETATION) == 1,
                   'S2 顯示檔結點說明不是唯一：' + path.name)
        if R36_OLD_KNOT_INTERPRETATION in text:
            path.write_text(text.replace(R36_OLD_KNOT_INTERPRETATION, R36_KNOT_INTERPRETATION), encoding='utf-8')
    return {'Interpretation': R36_KNOT_INTERPRETATION, 'Copied_workbook_text_updated': changed,
            'Other_cell_values_unchanged': True, 'Original_source_modified': False}


def or_collect_full(ctx, fig2_source, s16, fig1, r19, root_folder):
    """同一 runtime 可單獨重跑此格：每次建立新集中資料夾，來源只讀。"""
    import copy
    from PIL import Image

    or_same_inputs(ctx)
    checks, queue, source_hashes = [], [], {}
    def check(name, ok):
        checks.append({'Check': name, 'Passed': bool(ok)})
        or_require(ok, name)
    def same_path(a, b):
        return Path(a).resolve() == Path(b).resolve()
    def json_equal(a, b):
        return json.dumps(a, sort_keys=True, default=str) == json.dumps(b, sort_keys=True, default=str)
    def add(src, dest, label):
        src, dest = Path(src), Path(dest)
        check('Source_exists: ' + label + '/' + src.name, src.is_file())
        check('Relative_destination: ' + str(dest), not dest.is_absolute() and '..' not in dest.parts)
        digest = or_sha(src)
        source_hashes[str(src)] = digest
        queue.append({'Source': str(src), 'Destination': str(dest), 'Module': label, 'SHA256': digest})
    required = ['Table2', 'Table3', 'Table4', 'Table5', 'S1_Table', 'S2_Table', 'S3_Table',
                'S4_Table', 'S5_Table', 'S6_Table', 'S7_Table', 'S1_Fig', 'S2_Fig']
    check('Original_modules_complete', set(required).issubset(ctx['completed']))
    source_root = Path(ctx['out'])
    registry_before = copy.deepcopy(ctx['completed'])
    legacy_before = json.dumps(OR_LEGACY_FIXED, sort_keys=True, ensure_ascii=False)
    legacy_checks_before = copy.deepcopy(ctx['legacy_checks'])
    for key in required:
        rec = ctx['completed'][key]
        path = Path(rec['path'])
        check('Registered_hash: ' + key, path.is_file() and or_sha(path) == rec['SHA256'])
        section = 'Figures' if key.endswith('_Fig') else 'Main_Tables' if key.startswith('Table') else 'Supplementary_Tables'
        add(path, Path(section) / path.name, key)
        if key.endswith('_Fig'):
            add(rec['PNG'], Path(section) / Path(rec['PNG']).name, key)
            add(source_root / 'Notes' / (key + '_caption.txt'), Path('Notes') / (key + '_caption.txt'), key)
            add(source_root / 'Audit' / (key + '_plot_data.csv'), Path('Audit') / (key + '_plot_data.csv'), key)
        else:
            add(path.with_name(key + '_for_Word.html'), Path(section) / (key + '_for_Word.html'), key)
            add(source_root / 'Notes' / (key + '_caption_and_notes.txt'), Path('Notes') / (key + '_caption_and_notes.txt'), key)
            for sheet in rec['sheets']:
                name = key + '__' + sheet + '.csv'
                add(source_root / 'Audit' / name, Path('Audit') / name, key)
    # 僅明列無個案資料的彙總／配適紀錄；不掃描或複製私人列級稽核資料夾。
    for name in ['runtime_versions.json', 'source_scope.json', 'Original_OLS_full_parameters.csv',
                 'Original_OLS_model_diagnostics.csv', 'S2_product_draws.csv',
                 'Original_classifier_fit_ledger.csv', 'S5_holdout_draws.csv']:
        add(source_root / 'Audit' / name, Path('Audit') / name, 'Original reproduction audit')

    package = ctx['revision_package']; rev_root = Path(package['output_dir'])
    check('Revision_package_complete', package.get('Completed') is True)
    disk = pd.read_csv(rev_root / 'Audit/Publication_manifest.csv')
    manifest = package['manifest']
    check('Revision_manifest_matches', set(zip(disk.Section, disk.Artifact, disk.SHA256)) ==
          set(zip(manifest.Section, manifest.Artifact, manifest.SHA256)))
    revision_tables = {}
    for rec in manifest.itertuples(index=False):
        src = rev_root / rec.Section / rec.Artifact
        check('Revision_hash: ' + rec.Artifact, src.is_file() and or_sha(src) == rec.SHA256)
        if rec.Artifact.startswith('Fig1_R21_'):
            dest = Path('Archive/Fig1_previous_layout') / rec.Artifact
        elif rec.Section == 'Tables':
            dest = Path('Supplementary_Tables') / rec.Artifact
            match = re.fullmatch(r'(S\d+)_Table.*\.xlsx', rec.Artifact)
            if match:
                check('Unique_revision_label: ' + match[1], match[1] not in revision_tables)
                revision_tables[match[1]] = str(dest)
        elif rec.Section == 'Figures':
            dest = Path('Figures') / rec.Artifact
        else:
            dest = Path('Notes' if rec.Section == 'Text' else 'Audit') / 'Revision_sources' / rec.Artifact
        add(src, dest, 'Revision package')
    check('S8_to_S15_present', set(revision_tables) == {f'S{i}' for i in range(8, 16)})

    # S16 的工作簿、來源版本及成功紀錄需與明確的本次物件一致。
    sroot = Path(s16['output_dir'])
    check('S16_complete', s16.get('Completed') is True and s16['status'].get('All_passed') is True)
    check('S16_status_matches_disk', json_equal(s16['status'], json.loads((sroot / 'Audit/run_status.json').read_text())))
    prov = s16['provenance']
    check('S16_provenance_matches_disk', json_equal(prov, json.loads((sroot / 'Audit/R34_provenance.json').read_text())))
    check('S16_current_original_reproduction', same_path(prov['Original_reproduction'], source_root))
    check('S16_current_S4', same_path(prov['Source_S4'], ctx['completed']['S4_Table']['path'])
          and prov['Source_S4_SHA256'] == ctx['completed']['S4_Table']['SHA256'])
    check('S16_current_R05', same_path(prov['Source_R05'], R05['Output_dir']))
    check('S16_current_R10_R12', same_path(prov['Source_R10'], R10['output_dir'])
          and same_path(prov['Source_R12'], R12['output_dir']))
    check('S16_current_Primary', prov['Primary_fingerprint'] == r34_frame_hash(ctx['primary']))
    sbook = Path(s16['publication']['path'])
    check('S16_registered_book', same_path(sbook, sroot / 'Supplementary_Tables/S16_Table_rerun.xlsx')
          and sbook.is_file() and or_sha(sbook) == s16['publication']['SHA256'])
    r36_check_s16_book(sbook, s16['tables'], sroot / 'Notes/S16_Table_caption_and_notes.txt')
    check('S16_saved_tables_match_objects', True)
    check('S16_notes_match_workbook', True)
    fitlog = pd.read_csv(sroot / 'Audit/fit_ledger.csv')
    validation = pd.read_csv(sroot / 'Audit/validation.csv')
    check('S16_fit_ledger_complete', len(fitlog) == s16['status']['Fits_requested'] == s16['status']['Fits_succeeded']
          and fitlog.Status.eq('success').all() and s16['status']['Fits_failed'] == 0)
    check('S16_validation_complete', len(validation) == s16['status']['Checks'] and validation.Passed.eq(True).all())
    add(sbook, 'Supplementary_Tables/S16_Table_rerun.xlsx', 'S16')
    add(sroot / 'Supplementary_Tables/S16_Table_for_Word.html', 'Supplementary_Tables/S16_Table_for_Word.html', 'S16')
    add(sroot / 'Notes/S16_Table_caption_and_notes.txt', 'Notes/S16_Table_caption_and_notes.txt', 'S16')
    for name in [*['S16_Table__' + sheet + '.csv' for sheet in s16['tables']],
                 'Inherited_S4_parameters.csv', 'R34_provenance.json', 'Cohort_counts.csv', 'Fold_counts.csv',
                 'fit_ledger.csv', 'fit_warnings.csv', 'validation.csv', 'fold_metrics_completed.csv',
                 'run_status.json', 'module_status.json']:
        add(sroot / 'Audit' / name, Path('Audit/S16') / name, 'S16 audit')

    # 正式 Fig 1 採使用者指定的原圖版面；舊版面保留於 Archive。
    froot = Path(fig1['output_dir']); fstatus = fig1['status']
    check('Fig1_complete', fig1.get('Completed') is True and fstatus.get('Box_text_bounds_passed') is True)
    check('Fig1_status_matches_disk', json_equal(fstatus, json.loads((froot / 'Fig1_run_status.json').read_text())))
    check('Fig1_current_R05_R19', same_path(fstatus['Source_R05'], R05['Output_dir'])
          and same_path(fstatus['Source_R19'], r19['output_dir']))
    flow_path = Path(r19['output_dir']) / 'PartB_Flow.csv'
    check('Fig1_source_flow_hash', or_sha(flow_path) == fstatus['Source_flow_SHA256'])
    source_hashes[str(flow_path)] = fstatus['Source_flow_SHA256']
    pd.testing.assert_frame_equal(pd.read_csv(froot / 'Fig1_exclusion_detail.csv'),
                                  r19['tables']['PartB_Flow'], check_dtype=False, check_exact=True)
    check('Fig1_flow_matches_S12', True)
    for rec in fig1['files']:
        check('Fig1_declared_filename', rec['File'] in ['Fig1_original_layout_revised.png', 'Fig1_original_layout_revised.tif'])
        path = froot / rec['File']
        with Image.open(path) as im:
            check('Fig1_image_spec: ' + path.name, im.mode == rec['Mode'] == 'RGB'
                  and im.size == (rec['Width'], rec['Height']) and all(abs(d - rec['DPI']) < .1 for d in im.info['dpi']))
        add(path, Path('Figures') / path.name, 'Selected Fig1 original layout')
    check('Fig1_both_formats', {r['File'] for r in fig1['files']} ==
          {'Fig1_original_layout_revised.png', 'Fig1_original_layout_revised.tif'} and len(fig1['files']) == 2)
    add(froot / 'Fig1_caption.txt', 'Notes/Fig1_caption.txt', 'Selected Fig1 original layout')
    for name in ['Fig1_exclusion_detail.csv', 'Fig1_count_summary.csv', 'Fig1_run_status.json']:
        add(froot / name, Path('Audit/Fig1') / name, 'Selected Fig1 original layout')
    p2 = Path(fig2_source)
    check('Original_Fig2_hash', p2.is_file() and or_sha(p2) == OR_LEGACY_FIXED['Fig2_SHA256'])
    add(p2, 'Figures/Fig2_original_unchanged.tif', 'Frozen original Fig2')
    check('Unique_destinations', len(queue) == len({r['Destination'] for r in queue}))

    # 前置查驗完畢才建立新包；重跑只建立另一個時間戳版本，不覆寫舊成果。
    out = Path(root_folder) / 'OUTPUT' / ('Full_Publication_R36_' +
        datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ') + '_' + uuid.uuid4().hex[:8])
    out.mkdir(parents=True, exist_ok=False)
    for part in ['Main_Tables', 'Supplementary_Tables', 'Figures', 'Notes', 'Audit', 'Archive']:
        (out / part).mkdir()
    status = {'Completed': False, 'New_models_fitted': 0, 'New_bootstrap_draws': 0,
              'Cohorts_changed': False, 'Age_values_changed': False, 'Weather_values_changed': False,
              'Original_files_overwritten': False, 'Manuscript_modified': False, 'Patient_records_exported': False,
              'All_reviewer_methods_completed': False, 'Final_submission_ready': False}
    try:
        for rec in queue:
            src, dest = Path(rec['Source']), out / rec['Destination']
            check('Copy_source_unchanged: ' + rec['Destination'], or_sha(src) == rec['SHA256'])
            dest.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, dest)
            check('Copy_hash: ' + rec['Destination'], or_sha(dest) == rec['SHA256'])
        label_status = r36_s2_label_only(out)
        with Image.open(out / 'Figures/Fig2_original_unchanged.tif') as im:
            im.convert('RGB').save(out / 'Figures/Fig2_original_unchanged.png', dpi=(300, 300))
        # 使用獨立對帳容器，避免重跑時累積原 ctx 的 legacy_checks。
        local = dict(ctx, out=out, completed={}, legacy_checks=[], checks=[])
        # Static analytic descriptions, with every sample count from this execution.
        primary_n = len(ctx['primary'])
        repeated_n = len(ctx['repeated'])
        strict_n = int(ctx['s6_numeric'].loc[ctx['s6_numeric'].Model.eq('Strict27'), 'N'].iloc[0])
        older_n = int(ctx['s7a_counts'].Patients.iloc[0])
        framework = pd.DataFrame([
            ['Primary environmental', 'Recent THI–hemoglobin association', f'Hb_Date year + month harmonics; HC3 OLS; {primary_n:,} patients', 'Conditional cross-sectional association; seasonal overlap limits precision'],
            ['Primary skeletal', 'Hemoglobin–minimum-T-score association', f'DXA_Date year + month harmonics; HC3 OLS; {primary_n:,} patients', 'Co-occurrence, not within-person skeletal change'],
            ['Calendar sensitivity', 'Dependence on adjustment / date anchor', 'Calendar-unadjusted, year-only, month-only, and DXA_Date models', 'No causal separation of seasonal physiology and healthcare utilization'],
            ['Repeated records', 'Patient-level correlation sensitivity', f'Date-aligned random-intercept LMMs; {repeated_n:,} records', 'Combines within- and between-patient information'],
            ['Temporal sensitivity', 'Ordering and proximity', 'Hb ≤ DXA; absolute gaps 0–30, 31–90, 91–180 days; S3 Table', 'Not causal lag or prospective validation'],
            ['Completeness / age', 'Window completeness; younger-adult classification', f'≥{OR_S6_MIN_VALID} valid days, N = {strict_n:,} (S6); age ≥{OR_AGE_CUT} years, N = {older_n:,} (S7)', 'Targeted robustness checks, not validation of all measurements'],
            ['Exploratory diagnostics', 'Functional form; descriptive products; annual distributions', 'Minimum-T-score spline and product (S2); annual record summaries (S1 Fig)', 'No mediation or independent threshold claim'],
            ['Secondary information', 'Weather increment; classifier benchmark', 'Clinical-versus-weather comparison and six-classifier benchmark', 'Same-record ranking and probability error; not clinical utility']
        ], columns=['Analytic level', 'Question / outcome', 'Specification and cohort', 'Interpretive boundary'])
        counts = pd.DataFrame([
            ('Primary', 5003, len(ctx['primary'])), ('Repeated', 19515, len(ctx['repeated'])),
            ('S6 strict27', 4924, int(ctx['s6_numeric'].loc[ctx['s6_numeric'].Model.eq('Strict27'), 'N'].iloc[0])),
            ('S7 age65', 4043, int(ctx['s7a_counts'].Patients.iloc[0]))],
            columns=['Definition', 'Legacy_fixed_benchmark', 'Current_value'])
        counts['Matches'] = counts.Legacy_fixed_benchmark.eq(counts.Current_value)
        or_export(local, 'Table1', {'Display_original_framework': framework, 'Current_count_reconciliation': counts}, [
            'Table 1. Analytic hierarchy, target estimands, and operational interpretation framework.'], 'Main_Tables')
        for rec in counts.itertuples(index=False):
            or_display_check(local, 'Table1', rec.Definition, 'N', str(rec.Legacy_fixed_benchmark), str(rec.Current_value))
        audit = or_reconcile(local)
        register = r36_difference_register(audit)
        register.to_csv(out / 'Notes/Manuscript_difference_register.csv', index=False, encoding='utf-8-sig')
        or_json(out / 'Audit/Legacy_fixed_reference.json', OR_LEGACY_FIXED)
        or_json(out / 'Audit/S2_label_only_update.json', label_status)

        publication = []
        for n in range(1, 6):
            publication.append({'Item': f'Table {n}', 'File': f'Main_Tables/Table{n}_rerun.xlsx',
                'Caption': f'Notes/Table{n}_caption_and_notes.txt',
                'Status': 'Frozen framework with count audit' if n == 1 else 'Current rerun of original specification'})
        for n in range(1, 8):
            publication.append({'Item': f'S{n} Table', 'File': f'Supplementary_Tables/S{n}_Table_rerun.xlsx',
                'Caption': f'Notes/S{n}_Table_caption_and_notes.txt', 'Status': 'Current rerun of original specification'})
        # 既有修訂表的表註由已驗證 manifest 精確對應，不依檔案修改時間猜來源。
        for n in range(8, 16):
            candidates = [r['Destination'] for r in queue if r['Module'] == 'Revision package'
                          and re.match(rf'^S{n}_Table.*(?:notes|caption).*\.txt$', Path(r['Destination']).name)]
            check('Unique_caption: S' + str(n), len(candidates) == 1)
            publication.append({'Item': f'S{n} Table', 'File': revision_tables[f'S{n}'],
                'Caption': candidates[0], 'Status': 'Existing verified revision results'})
        publication.append({'Item': 'S16 Table', 'File': 'Supplementary_Tables/S16_Table_rerun.xlsx',
            'Caption': 'Notes/S16_Table_caption_and_notes.txt', 'Status': 'Existing R34 paired weather sensitivity; copied without refitting'})
        figure_names = [
            ('Fig 1', 'Fig1_original_layout_revised.tif', 'Notes/Fig1_caption.txt', 'Selected original-layout revision'),
            ('Fig 2', 'Fig2_original_unchanged.tif', '', 'Frozen original asset; caption remains in manuscript'),
            ('Fig 3', 'Fig3_revised.tif', 'Notes/Revision_sources/Fig3_caption.txt', 'Existing non-causal conceptual figure'),
            ('S1 Fig', 'S1_Fig_rerun.tif', 'Notes/S1_Fig_caption.txt', 'Existing rerun'),
            ('S2 Fig', 'S2_Fig_rerun.tif', 'Notes/S2_Fig_caption.txt', 'Existing rerun'),
            ('S3 Fig', 'S3_Fig_R13.tif', 'Notes/Revision_sources/S3_Fig_R13_caption.txt', 'Existing forward classification')]
        for item, name, caption, disposition in figure_names:
            publication.append({'Item': item, 'File': 'Figures/' + name, 'Caption': caption, 'Status': disposition})
        index = pd.DataFrame(publication)
        expected = {f'Table {n}' for n in range(1, 6)} | {f'S{n} Table' for n in range(1, 17)} | {x[0] for x in figure_names}
        check('Publication_labels_complete_unique', set(index.Item) == expected and index.Item.is_unique)
        for rec in index.itertuples(index=False):
            check('Publication_file: ' + rec.Item, (out / rec.File).is_file())
            if rec.Caption:
                check('Publication_caption: ' + rec.Item, (out / rec.Caption).is_file())
        index.to_csv(out / 'Publication_Index.csv', index=False, encoding='utf-8-sig')
        # 將完整包 registry 補齊，不留下只有 Table 1 的中間匯出狀態。
        or_json(out / 'Audit/module_status.json', {rec.Item: {
            'path': str(out / rec.File), 'SHA256': or_sha(out / rec.File),
            'Caption': rec.Caption, 'Status': rec.Status} for rec in index.itertuples(index=False)})
        pd.DataFrame(queue).to_csv(out / 'Audit/Source_file_manifest.csv', index=False, encoding='utf-8-sig')
        or_json(out / 'Audit/Source_directories.json', {'Original_reproduction': str(source_root),
            'Revision_package': str(rev_root), 'S16': str(sroot), 'Selected_Fig1': str(froot)})
        (out / '先讀我.txt').write_text(
            'R36 集中輸出：以 Publication_Index.csv 指定正式圖表及表註；編號沿用原稿。\n'
            '主文 Table 1–5、S1–S16 Table、Fig 1–3、S1–S3 Fig 均列入。\n'
            'Fig 1 使用原圖版面修訂版；舊 Fig1_R21 版面保留於 Archive/Fig1_previous_layout，不作正式圖。\n'
            'S16 沿用既有六分類器新舊氣象配對結果；來源、配適、警告與驗證記錄位於 Audit/S16。\n'
            'S2 C 僅同步結點 Interpretation。數值不變：完整 basis 結點另存，顯示取兩位小數。\n'
            'Notes/Manuscript_difference_register.csv 列出本次所有差異與處置；不強制要求剛好九項。\n'
            'Legacy 固定基準與 Matches_display_precision 不變；稿件採值仍待整合，不以改基準使差異通過。\n'
            'Notes/Revision_sources 內是先前修訂階段的原樣紀錄，其範圍以當時階段為限；本包覆蓋範圍以本索引為準。\n'
            '本格未配適模型；原有分析規格、世代、年齡與氣象數值均未改變。\n'
            '完成集中輸出不等於所有審稿方法問題完成或稿件可提交。原 S7 B/C、S5 及 spline 的已註記限制仍保留。\n', encoding='utf-8')
        or_same_inputs(ctx)
        check('Original_registry_unchanged', ctx['completed'] == registry_before)
        check('Original_reconciliation_unchanged', ctx['legacy_checks'] == legacy_checks_before)
        check('Legacy_fixed_benchmarks_unchanged', json.dumps(OR_LEGACY_FIXED, sort_keys=True, ensure_ascii=False) == legacy_before)
        check('All_source_files_unchanged', all(or_sha(path) == digest for path, digest in source_hashes.items()))
        status.update(Completed=True, All_passed=all(r['Passed'] for r in checks), Checks=len(checks),
            Main_tables=int(index.Item.str.match(r'^Table \d+$').sum()),
            Supplementary_tables=int(index.Item.str.match(r'^S\d+ Table$').sum()), Figures=len(figure_names),
            Publication_items=len(index), S16_integrated=True, Original_layout_Fig1_selected=True,
            Previous_Fig1_layout_preserved=True, S2_numeric_values_changed=False,
            Legacy_display_values_checked=len(audit), Legacy_display_differences_or_unmatched=len(register),
            All_checked_legacy_display_values_reproduced=bool(audit.Matches_display_precision.all()))
        or_json(out / 'run_status.json', status)
        pd.DataFrame(checks).to_csv(out / 'Audit/Execution_checks.csv', index=False, encoding='utf-8-sig')
        files = [{'File': str(p.relative_to(out)), 'Bytes': p.stat().st_size, 'SHA256': or_sha(p)}
                 for p in sorted(out.rglob('*')) if p.is_file() and p.name != 'File_manifest.csv']
        # manifest 最後寫入；包含成功狀態與全部驗證檔，不包含自身。
        pd.DataFrame(files).to_csv(out / 'File_manifest.csv', index=False, encoding='utf-8-sig')
        print('\n=== 請回傳：R36 1 完整圖表清單 ==='); print(index.to_string(index=False))
        print('\n=== 請回傳：R36 2 原稿數值對帳 ===')
        print(audit.groupby('Item', sort=False).agg(Checked=('Matches_display_precision', 'size'),
              Matched=('Matches_display_precision', 'sum')).to_string())
        print('\n=== 請回傳：R36 3 整合與驗證 ==='); print(pd.DataFrame([status]).to_string(index=False))
        print('本次完整輸出：', out)
        return {'Completed': True, 'output_dir': str(out), 'status': status,
                'publication_index': index, 'difference_register': register}
    except Exception as exc:
        status.update(Completed=False, Error_type=type(exc).__name__, Error=str(exc))
        or_json(out / 'run_status.json', status)
        pd.DataFrame(checks).to_csv(out / 'Audit/Execution_checks.csv', index=False, encoding='utf-8-sig')
        raise


