"""## Cell 135　R41／S17　補齊原分類規格的長視窗氣象重建敏感度

**接在原 Cell 133「Export checks」之後。原有 133 格內容、模型、輸出及編號保留。**

本格回應 R1 Major 4 的剩餘範圍：原 Table 5、S5、S7 B／C。
R10 已完成 30／180／365 日重建，S16 已驗證原 S4 六分類器；本格不重做這兩項。

- 沿用原 Logistic regression／XGBoost 及其參數，3 個臨床特徵對 10 個臨床＋氣象特徵。
- 保留 18／20／24 小時門檻。各門檻先取共同可用個案，再使用由完整原分析母群恢復的原分組。
- Table 5 與 S7 B/C 分別保留各自五折；S5 保留原固定 80:20 分組，篩選後比例不強制回到 80:20。
- 三臂為 Clinical、Legacy_weather、Calendar_weather；新舊差值只在相同個案與分組間計算。
- S7 的 XGBoost 維持不縮放；其餘沿用訓練折 StandardScaler。沒有新增日曆項或 S4 的交互作用。
- 365 日熱日計數改為有效觀測日熱日比例，明列定義改變；不把缺測當非熱日。
- S5 保留 5,000 次配對測試列 bootstrap，固定模型；不新增顯著性檢定。

**前置來源**：本次 R05、R10（Cell 23）、R12（Cell 27）、O00（Cell 53）、O06（Cell 65）、R34 函式（Cell 71）及其上游，均須在同一 runtime。
若本版原流程已執行完畢，只需執行下方新增格；不需為加入本格重跑既有模型。

**輸出**：`OUTPUT_DIR/S17_R41_<UTC時間>_<run id>/`，含 S17 Excel／Word 可貼上的 HTML、表註、逐折差值、分母、有效日數、配適與重抽樣紀錄、來源及檔案清單。
既有 27 項出版輸出與總清單維持原樣；S17 以獨立追加資料夾及 `S17_manifest.csv` 登錄。
不輸出個案列或預測紀錄。若資料／來源不符或配適失敗，停止並保留失敗狀態。

請回傳執行後的 **R41／S17 1–4** 四段摘要。正式研究結果未預先填入本格。

"""

# R41／S17：補齊 Table 5、S5、S7 B／C 的長視窗氣象重建敏感度。
# 插入位置：最新版原 Cell 133 後；沿用已執行 O06、R10、R12、R34 的來源。
# 原表不覆寫；同一門檻內，新舊氣象使用相同病人、相同原始分組與原參數。
from pathlib import Path
from datetime import datetime, timezone
import json, uuid, warnings
import numpy as np
import pandas as pd

R41_HOURS = (18, 20, 24)
R41_ALGORITHMS = ('Logistic regression', 'XGBoost')
R41_ARMS = ('Clinical', 'Legacy_weather', 'Calendar_weather')
R41_CLINICAL = ['Age', 'sex_bin', 'Hb_Value']
R41_SOURCE_NOTEBOOK = 'R40_20261111_2120_analysis_caption_notes_revised_v2.ipynb'
R41_SOURCE_SHA256 = 'ca150e8a346b647a43ebacedeb833e67ca0265b9d9a2f4ba4b3b1f3c51b4252d'


def r41_require(ok, message):
    if not bool(ok):
        raise ValueError('R41／S17：' + message + '；停止，不使用替代來源或固定結果。')


def r41_original_splits(d, y, lib, holdout=False):
    """先在完整原分析母群恢復分組；不可在氣象篩選後重新分組。"""
    if holdout:
        tr, te = lib['train_test_split'](np.arange(len(d)), test_size=.20,
                                        random_state=OR_SEED, stratify=y)
        return [(tr, te)]
    return list(lib['StratifiedKFold'](n_splits=OR_CV_FOLDS, shuffle=True,
                                      random_state=OR_SEED).split(d, y))


def r41_restrict_splits(original, selected, splits):
    r41_require(original[OR_PAIR].is_unique and selected[OR_PAIR].is_unique,
                '分組來源 ID 重複')
    lookup = pd.Index(selected[OR_PAIR])
    r41_require(lookup.isin(original[OR_PAIR]).all(), '子集包含原分析以外 ID')
    result = []
    for tr, te in splits:
        # get_indexer 保留原 holdout 的隨機列順序，而非另排序或重新抽樣。
        a = lookup.get_indexer(original.iloc[tr][OR_PAIR])
        b = lookup.get_indexer(original.iloc[te][OR_PAIR])
        a, b = a[a >= 0], b[b >= 0]
        r41_require(len(a) and len(b) and not np.intersect1d(a, b).size,
                    '共同可用子集的訓練／測試分組為空或重疊')
        r41_require(np.array_equal(np.sort(np.r_[a, b]), np.arange(len(selected))),
                    '訓練／測試分組未完整涵蓋共同可用子集')
        result.append((a, b))
    return result


def r41_sources(ctx, r05, r10, r12):
    # 重用已驗證的 R34 來源對應；這個 prepare 函式不配適 S4 模型。
    z = r34_prepare(ctx, r05, r10, r12)
    r41_require(tuple(sorted(z['cases'])) == R41_HOURS, '小時門檻來源不符')
    books, source_rows = {}, []
    for key in ('Table5', 'S5_Table', 'S7_Table'):
        entry = ctx['completed'].get(key)
        r41_require(isinstance(entry, dict), key + ' 尚未完成 O06')
        path = Path(entry['path'])
        r41_require(path.is_file() and or_sha(path) == entry['SHA256'], key + ' 缺失或雜湊不符')
        books[key] = pd.read_excel(path, sheet_name=None)
        source_rows.append({'Source': key, 'File': path.name, 'SHA256': entry['SHA256']})
    scope = json.loads((Path(ctx['out']) / 'Audit/source_scope.json').read_text(encoding='utf-8'))
    r41_require(int(scope['Bootstrap_draws']) == OR_BOOTSTRAP_DRAWS
        and int(scope['Seed']) == OR_SEED and int(scope['CV_folds']) == OR_CV_FOLDS,
        '原 O06 的重抽樣次數、seed 或折數已變更')
    r41_require(OR_BOOTSTRAP_DRAWS >= 2 and 0 < OR_ALPHA < 1, 'bootstrap／CI 設定不合法')
    bases, full_splits, references, params = {}, {}, [], []
    for population, age65, key in [('Primary', False, 'Table5'), ('Age65', True, 'S7_Table')]:
        d, y, den = or_ml_data(z['p'], age65)
        d = d.reset_index(drop=True)
        r41_require(int(den.Rows_removed_missing_features.iloc[0]) == 0,
                    population + ' 原規格額外刪除了缺失特徵列')
        bases[population] = (d, y)
        splits = r41_original_splits(d, y, z['lib'])
        full_splits[population] = splits
        book = books[key]
        needed = {'Fold_metrics', 'Fold_counts', 'Numeric' if not age65 else 'Classification_numeric'}
        r41_require(needed <= set(book), key + ' 缺少原逐折／彙總結果')
        fm, fc = book['Fold_metrics'], book['Fold_counts']
        summary = book['Classification_numeric' if age65 else 'Numeric']
        r41_require(len(fm) == OR_CV_FOLDS * len(R41_ALGORITHMS) * 2
            and not fm.duplicated(['Algorithm', 'Feature_set', 'Fold']).any()
            and set(fm.Algorithm) == set(R41_ALGORITHMS)
            and set(fm.Feature_set) == {'Clinical', 'Clinical_weather'}
            and set(fm.Fold) == set(range(1, OR_CV_FOLDS + 1))
            and len(fc) == OR_CV_FOLDS and fc.Fold.is_unique
            and len(summary) == len(R41_ALGORITHMS) and summary.Algorithm.is_unique,
            key + ' 原分類結果不完整／重複')
        for f, (tr, te) in enumerate(splits, 1):
            count = fc.loc[fc.Fold.eq(f)].iloc[0]
            old = fm.loc[fm.Fold.eq(f)]
            r41_require(int(count.Train_n) == len(tr) and int(count.Test_n) == len(te)
                and int(count.Train_positive) == int(y[tr].sum())
                and int(count.Test_positive) == int(y[te].sum())
                and old.Train_n.eq(len(tr)).all() and old.Test_n.eq(len(te)).all(),
                key + f' 原第 {f} 折分母／類別未能重現')
        for alg in R41_ALGORITHMS:
            ref = summary.loc[summary.Algorithm.eq(alg)].iloc[0]
            r41_require(int(ref.N) == len(d), key + ' 原分類分母不符')
            a = fm.loc[fm.Algorithm.eq(alg) & fm.Feature_set.eq('Clinical')].sort_values('Fold')
            b = fm.loc[fm.Algorithm.eq(alg) & fm.Feature_set.eq('Clinical_weather')].sort_values('Fold')
            for prefix, g in [('Clinical', a), ('Weather', b)]:
                for suffix, value in [('AUC_mean', g.AUC.mean()), ('AUC_SD', g.AUC.std(ddof=0)),
                                      ('Brier', g.Brier.mean())]:
                    r41_require(np.isclose(value, ref[prefix + '_' + suffix], rtol=1e-10, atol=1e-12),
                                key + ' 原逐折與彙總不符')
            for metric in ('AUC', 'Brier'):
                r41_require(np.isclose((b[metric].to_numpy() - a[metric].to_numpy()).mean(),
                    ref['Delta_' + metric], rtol=1e-10, atol=1e-12), key + ' 原差值不符')
            est = or_estimator(z['lib'], alg, age65=age65)
            params.append({'Population': population, 'Algorithm': alg,
                'Preprocessing': 'None (original S7 XGBoost)' if age65 and alg == 'XGBoost' else 'Training-fold StandardScaler',
                'Full_resolved_parameters': json.dumps(est.get_params(deep=True), default=str, ensure_ascii=False)})
        references.append(summary.assign(Population=population, Source=key,
            Comparison_role='Full original cohort reference; NOT the matched-weather comparator'))
    holdout = r41_original_splits(*bases['Primary'], z['lib'], holdout=True)
    hold = books['S5_Table']['Holdout_numeric']
    r41_require(len(hold) == 3 and set(hold.Quantity) == {'Clinical', 'Weather', 'Weather_minus_clinical'}
        and hold.Train_n.eq(len(holdout[0][0])).all() and hold.Test_n.eq(len(holdout[0][1])).all()
        and hold.Requested.eq(OR_BOOTSTRAP_DRAWS).all()
        and hold.Succeeded.eq(OR_BOOTSTRAP_DRAWS).all() and hold.Failed.eq(0).all(),
        'S5 原 holdout／bootstrap 分母不符')
    full_splits['Holdout'] = holdout
    z.update(bases=bases, full_splits=full_splits, books=books,
             sources=pd.DataFrame(source_rows), parameters=pd.DataFrame(params),
             original_reference=pd.concat(references, ignore_index=True))
    return z


def r41_case(z, h, population, holdout=False):
    case = z['cases'][h]
    use = case['data'].Age.ge(OR_AGE_CUT).to_numpy() if population == 'Age65' else np.ones(len(case['data']), bool)
    data = case['data'].loc[use].reset_index(drop=True)
    y = data.overall_T.le(-2.5).astype(int).to_numpy()
    original, original_y = z['bases'][population]
    aligned = original.set_index(OR_PAIR).loc[data[OR_PAIR]].reset_index()
    pd.testing.assert_frame_equal(data[original.columns], aligned[original.columns], check_dtype=False)
    old_cols = R41_CLINICAL + list(OR_WEATHER)
    new_cols = ['THI_hot_fraction_365d' if c == 'THI_hot_days_365d' else c for c in old_cols]
    # Table 5／S5／S7 B/C 是 3 對 10 特徵；不加入 S4 的交互作用或 18 特徵規格。
    old = case['X']['Legacy_subset'].loc[use, old_cols].reset_index(drop=True)
    new = case['X']['Calendar_subset'].loc[use, new_cols].reset_index(drop=True)
    pd.testing.assert_frame_equal(old, data[old_cols], check_dtype=False)
    pd.testing.assert_frame_equal(old[R41_CLINICAL], new[R41_CLINICAL])
    r41_require(np.isfinite(old).all().all() and np.isfinite(new).all().all(), '共同特徵含缺失／無限值')
    splitkey = 'Holdout' if holdout else population
    splits = r41_restrict_splits(original, data, z['full_splits'][splitkey])
    for tr, te in splits:
        r41_require(set(y[tr]) == {0, 1} and set(y[te]) == {0, 1}, '共同子集訓練／測試不足兩類')
    if not holdout:
        r41_require(np.array_equal(np.sort(np.concatenate([te for _, te in splits])), np.arange(len(data))),
                    'CV 不是每人恰好測試一次')
    return data, y, {'Clinical': old[R41_CLINICAL].to_numpy(float),
        'Legacy_weather': old.to_numpy(float), 'Calendar_weather': new.to_numpy(float)}, splits


def r41_fit(X, y, tr, te, alg, age65, lib, label, ledger, warning_rows, out):
    from sklearn.exceptions import ConvergenceWarning
    est = or_estimator(lib, alg, age65=age65)
    rec = dict(label, Algorithm=alg, Train_n=len(tr), Test_n=len(te), Features=X.shape[1], Status='started')
    try:
        with warnings.catch_warnings(record=True) as caught:
            warnings.simplefilter('always')
            est.fit(X[tr], y[tr])
            probabilities = est.predict_proba(X[te])
        warning_rows.extend(dict(label, Algorithm=alg, Category=w.category.__name__, Message=str(w.message)) for w in caught)
        r41_require(not any(issubclass(w.category, (ConvergenceWarning, RuntimeWarning)) for w in caught),
                    '配適有收斂／數值警告；不將失敗配適計入彙總')
        if hasattr(est, 'named_steps'):
            scaler = est.named_steps['scaler']
            r41_require(np.all(np.asarray(scaler.n_samples_seen_) == len(tr)) and
                np.allclose(scaler.mean_, X[tr].mean(axis=0), rtol=1e-10, atol=1e-10), '標準化不限於訓練列')
        else:
            r41_require(age65 and alg == 'XGBoost', '非預期未標準化分類器')
        r41_require(np.array_equal(est.classes_, [0, 1]) and probabilities.shape == (len(te), 2)
            and np.isfinite(probabilities).all() and ((probabilities >= 0) & (probabilities <= 1)).all()
            and np.allclose(probabilities.sum(axis=1), 1, atol=1e-6), '預測機率不合法')
        rec.update(Status='success', Warning_count=len(caught))
        return probabilities[:, 1]
    except Exception as exc:
        rec.update(Status='failed', Error=str(exc))
        raise
    finally:
        ledger.append(rec)
        pd.DataFrame(ledger).to_csv(out / 'Audit/Fit_ledger.csv', index=False)
        pd.DataFrame(warning_rows, columns=['Minimum_hours', 'Population', 'Design', 'Fold',
            'Arm', 'Algorithm', 'Category', 'Message']).to_csv(out / 'Audit/Warnings.csv', index=False)


def r41_bootstrap(errors, draws, seed, alpha):
    # 相同測試列同時抽取三臂；固定模型、不重訓。只報 S5 原有的 Brier 不確定性。
    r41_require(errors.ndim == 2 and errors.shape[1] == 3 and len(errors) > 0
        and np.isfinite(errors).all(), 'holdout 平方誤差不合法')
    names = list(R41_ARMS) + ['Legacy_minus_clinical', 'Calendar_minus_clinical', 'Calendar_minus_legacy']
    def contrasts(v):
        return np.r_[v, v[1] - v[0], v[2] - v[0], v[2] - v[1]]
    rng = np.random.RandomState(seed)
    boot = np.empty((draws, len(names)))
    for j in range(draws):
        idx = rng.choice(len(errors), size=len(errors), replace=True)
        boot[j] = contrasts(errors[idx].mean(axis=0))
    points = contrasts(errors.mean(axis=0))
    ci = np.quantile(boot, [alpha / 2, 1 - alpha / 2], axis=0)
    table = pd.DataFrame({'Quantity': names, 'Estimate': points, 'Bootstrap_SE': boot.std(axis=0, ddof=1),
                          'CI_low': ci[0], 'CI_high': ci[1]})
    return table, pd.DataFrame(boot, columns=names).assign(Draw=np.arange(1, draws + 1))


def r41_cv_summary(metrics):
    records, paired = [], []
    for keys, g in metrics.groupby(['Population', 'Minimum_hours', 'Algorithm'], sort=False):
        base = dict(zip(['Population', 'Minimum_hours', 'Algorithm'], keys))
        arms = {a: g.loc[g.Arm.eq(a)].sort_values('Fold') for a in R41_ARMS}
        c, old, new = [arms[a] for a in R41_ARMS]
        r41_require(all(len(v) == OR_CV_FOLDS for v in arms.values()), 'CV 配適不完整')
        for v in (old, new):
            pd.testing.assert_frame_equal(c[['Fold', 'Train_n', 'Test_n']].reset_index(drop=True),
                                          v[['Fold', 'Train_n', 'Test_n']].reset_index(drop=True))
        for metric in ('AUC', 'Brier'):
            row = dict(base, Metric=metric, Participants=int(c.Test_n.sum()), Folds=len(c))
            for arm, v in arms.items():
                row[arm + '_mean'] = v[metric].mean()
                row[arm + '_SD'] = v[metric].std(ddof=0)
            for name, lhs, rhs in [('Legacy_minus_clinical', old, c), ('Calendar_minus_clinical', new, c),
                                   ('Calendar_minus_legacy', new, old)]:
                delta = lhs[metric].to_numpy() - rhs[metric].to_numpy()
                row[name + '_mean'] = delta.mean()
                row[name + '_SD'] = delta.std(ddof=0)
            records.append(row)
        for i in range(len(c)):
            row = dict(base, Fold=int(c.iloc[i].Fold), Train_n=int(c.iloc[i].Train_n), Test_n=int(c.iloc[i].Test_n))
            for metric in ('AUC', 'Brier'):
                row['Delta_' + metric] = new.iloc[i][metric] - old.iloc[i][metric]
            paired.append(row)
    return pd.DataFrame(records), pd.DataFrame(paired)


def r41_run(ctx, r05, r10, r12, output_root):
    z = r41_sources(ctx, r05, r10, r12)
    registry_before = r34_json(ctx['completed'])
    out = Path(output_root) / ('S17_R41_' + datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ') + '_' + uuid.uuid4().hex[:8])
    out.mkdir(parents=True, exist_ok=False)
    for part in ('Audit', 'Notes', 'Supplementary_Tables'):
        (out / part).mkdir()
    or_json(out / 'run_status.json', {'Completed': False, 'Status': 'running'})
    ledger, warning_rows, metrics, counts, split_rows, hold_tables, hold_metrics, window_rows = [], [], [], [], [], [], [], []
    expected_fits = len(R41_HOURS) * (2 * OR_CV_FOLDS * len(R41_ALGORITHMS) * len(R41_ARMS) + len(R41_ARMS))
    print(f'R41／S17：預計 {expected_fits} 次配適；沿用原規格，所有小時門檻均保留。', flush=True)
    try:
        for h in R41_HOURS:
            for population, holdout in [('Primary', False), ('Age65', False), ('Primary', True)]:
                data, y, Xs, splits = r41_case(z, h, population, holdout)
                design = 'S5_fixed_holdout' if holdout else ('Table5_CV' if population == 'Primary' else 'S7BC_CV')
                original = z['bases'][population][0]
                original_splits = z['full_splits']['Holdout' if holdout else population]
                counts.append({'Design': design, 'Population': population, 'Minimum_hours': h,
                    'Original_rows': len(original), 'Eligible_rows': len(data),
                    'Eligible_patients': data[OR_PID].nunique(), 'Removed_for_current_weather': len(original) - len(data),
                    'Positive_rows': int(y.sum()), 'Tested_rows': sum(len(te) for _, te in splits)})
                if not holdout:
                    linked = r10['linked_candidates'][h].set_index(OR_PAIR).loc[data[OR_PAIR]]
                    for window in z['r10_spec']['Windows_days']:
                        valid = linked[f'Valid_days_{window}d']
                        required = int(z['r10_spec']['Required_days'][str(window)])
                        r41_require(valid.ge(required).all(), '納入分類子集未達視窗有效日數門檻')
                        window_rows.append({'Population': population, 'Minimum_hours': h,
                            'Window_days': window, 'Participants': len(data), 'Required_valid_days': required,
                            'Valid_days_min': int(valid.min()), 'Valid_days_median': valid.median(),
                            'Valid_days_max': int(valid.max()), 'All_days_observed_rows': int(valid.eq(window).sum())})
                for f, ((tr, te), (otr, ote)) in enumerate(zip(splits, original_splits), 1):
                    split_rows.append({'Design': design, 'Population': population, 'Minimum_hours': h, 'Fold': f,
                        'Original_train_n': len(otr), 'Original_test_n': len(ote), 'Train_n': len(tr), 'Test_n': len(te),
                        'Train_positive': int(y[tr].sum()), 'Test_positive': int(y[te].sum()),
                        'Test_fraction_after_restriction': len(te) / len(data),
                        'Train_ID_order_SHA256': r34_id_hash(data.iloc[tr][OR_PAIR]),
                        'Test_ID_order_SHA256': r34_id_hash(data.iloc[te][OR_PAIR]), 'Same_split_all_arms': True})
                    algorithms = ('Logistic regression',) if holdout else R41_ALGORITHMS
                    for alg in algorithms:
                        errors = []
                        for arm in R41_ARMS:
                            label = {'Minimum_hours': h, 'Population': population, 'Design': design, 'Fold': f, 'Arm': arm}
                            prob = r41_fit(Xs[arm], y, tr, te, alg, population == 'Age65', z['lib'], label, ledger, warning_rows, out)
                            result = dict(label, Algorithm=alg, Train_n=len(tr), Test_n=len(te),
                                AUC=float(z['lib']['roc_auc_score'](y[te], prob)),
                                Brier=float(z['lib']['brier_score_loss'](y[te], prob)))
                            (hold_metrics if holdout else metrics).append(result)
                            errors.append((y[te] - prob) ** 2)
                        if holdout:
                            hold, draws = r41_bootstrap(np.column_stack(errors), OR_BOOTSTRAP_DRAWS, OR_SEED, OR_ALPHA)
                            hold = hold.assign(Minimum_hours=h, Train_n=len(tr), Test_n=len(te),
                                Requested=OR_BOOTSTRAP_DRAWS, Succeeded=OR_BOOTSTRAP_DRAWS, Failed=0)
                            hold_tables.append(hold)
                            draws.to_csv(out / f'Audit/Holdout_{h}h_paired_draws.csv', index=False)
                    print(f'R41 {h}h／{design}／第 {f}/{len(splits)} 組完成。', flush=True)
        fm = pd.DataFrame(metrics)
        summary, deltas = r41_cv_summary(fm)
        hold = pd.concat(hold_tables, ignore_index=True)
        ledger_df = pd.DataFrame(ledger)
        r41_require(len(ledger_df) == expected_fits and ledger_df.Status.eq('success').all(), '配適未全部完成')
        r41_require(len(summary) == len(R41_HOURS) * 2 * len(R41_ALGORITHMS) * 2
            and len(hold) == len(R41_HOURS) * 6, '彙總列不完整')
        # 不把兩個臂不同分母、或完整舊世代與保留子集之差，當作新舊氣象效果。
        checks = [{'Check': 'All_requested_fits_succeeded', 'Passed': True},
            {'Check': 'Original_fold_and_holdout_membership_preserved', 'Passed': True},
            {'Check': 'Identical_patients_and_splits_across_three_arms', 'Passed': True},
            {'Check': 'Original_estimators_and_preprocessing_used', 'Passed': True},
            {'Check': 'All_hour_thresholds_retained', 'Passed': True}]
        or_same_inputs(ctx)
        for h in R41_HOURS:
            r41_require(r34_frame_hash(r10['linked_candidates'][h]) == z['snapshots'][f'R10_link_{h}']
                and r34_frame_hash(r10['weather_candidates'][h]) == z['snapshots'][f'R10_calendar_{h}']
                and r34_frame_hash(r12['datasets'][h]) == z['snapshots'][f'R12_data_{h}'], '上游資料在配適中改變')
        r41_require(r34_json(ctx['completed']) == registry_before, '原出版登錄被改動')
        for key in ('Table5', 'S5_Table', 'S7_Table'):
            entry = ctx['completed'][key]
            r41_require(or_sha(entry['path']) == entry['SHA256'], key + ' 原檔被改動')
        checks.append({'Check': 'Original_inputs_files_and_registry_unchanged', 'Passed': True})
        display_cv = summary[['Population', 'Minimum_hours', 'Algorithm', 'Metric', 'Participants']].copy()
        for arm in R41_ARMS:
            display_cv[arm + ' mean (fold SD)'] = [f'{m:.4f} ({s:.4f})' for m, s in zip(summary[arm + '_mean'], summary[arm + '_SD'])]
        for contrast in ('Legacy_minus_clinical', 'Calendar_minus_clinical', 'Calendar_minus_legacy'):
            display_cv[contrast] = summary[contrast + '_mean'].map(lambda x: f'{x:+.4f}')
        display_hold = hold[['Minimum_hours', 'Quantity', 'Train_n', 'Test_n']].copy()
        display_hold[f'Brier estimate [{100 * (1 - OR_ALPHA):g}% CI]'] = [f'{r.Estimate:+.4f} [{r.CI_low:+.4f}, {r.CI_high:+.4f}]' for r in hold.itertuples()]
        notes = [
            'S17 Table. Sensitivity of the original Table 5, S5 and S7 B/C classification specifications to calendar-based reconstruction of weather features, including 180- and 365-day features.',
            f'All {"/".join(map(str, R41_HOURS))}-hour thresholds are reported. Within each threshold and analysis population, clinical-only, clinical-plus-legacy-weather and clinical-plus-reconstructed-weather models use identical participants and training/test assignments. The eligible participants may differ between thresholds; cross-threshold differences cannot be attributed solely to hourly completeness.',
            f'The original full Primary and recorded-age ≥{OR_AGE_CUT} populations first define separate {OR_CV_FOLDS}-fold stratified splits (shuffle=True, seed={OR_SEED}). These splits are then restricted to participants with evaluable reconstructed weather. Folds are not redrawn after restriction. AUC and Brier values are unweighted fold means; SD uses ddof=0 and is not a confidence interval.',
            'The original S5 stratified 80:20 split is restricted in the same way, retaining original training/test membership and order. Consequently, the retained subset need not have an exact 80:20 ratio. Only logistic regression is used for this holdout comparison.',
            f'Holdout Brier percentile CIs and bootstrap SEs use {OR_BOOTSTRAP_DRAWS} paired test-record resamples (seed={OR_SEED}); all three fitted models are fixed. SE is the bootstrap SD (ddof=1). This conditions on the selected split and fitted models and does not account for training uncertainty or calendar dependence. No additional significance tests are performed.',
            'Clinical predictors are recorded DXA age, sex and hemoglobin. Seven weather predictors are added in the original order; no calendar covariates, new interactions, new algorithms or tuning are introduced. Logistic regression and full-Primary XGBoost retain training-fold StandardScaler; age-restricted XGBoost retains the original unscaled input.',
            f'Weather windows end on the Hb laboratory report date, including that date and the preceding W−1 calendar days. R10 requires at least ceil({z["r10_spec"]["Minimum_valid_fraction"]:g}×W) jointly valid days: '
                + ', '.join(f'{z["r10_spec"]["Required_days"][str(w)]}/{w}' for w in z['r10_spec']['Windows_days'])
                + '. Hourly completeness and daily temperature-range processing are inherited from R09/R10; missing days are not treated as observed non-hot days. A window meeting the valid-day requirement is not necessarily fully observed on every day.',
            f'The 365-day legacy hot-day count is replaced by the fraction of valid observed days with daily THI ≥{z["r10_spec"]["Hot_threshold"]:g}; the denominator is the valid-day count, not 365. This is an explicit definition change. THI mean at 180 days and the 30-minus-180-day THI contrast use reconstructed calendar features. Window-mean THI retains the R10 formula applied to window-mean temperature and humidity, rather than the mean of daily THI. This comparison estimates the combined effect of weather reconstruction and definition changes, not the isolated effect of changing only a long-window feature.',
            'New-minus-legacy differences use unrounded estimates on the same retained participants. Positive ΔAUC and negative ΔBrier indicate better performance of the reconstructed-weather arm within this comparison; no equivalence, superiority or causal claim is inferred from small differences alone.',
            'Original tables and original full-cohort numerical references remain unchanged. Full original cohort references are not the matched comparator. S13 Table/S3 Fig provide the separate clinical-plus-calendar and forward-evaluation analyses; S16 Table covers the original six-classifier S4 specification. No prospective validation is claimed by S17.',
        ]
        tables = {'Display_A_CV': display_cv, 'Display_B_S5_holdout': display_hold,
                  'CV_numeric': summary, 'Holdout_numeric': hold, 'Denominators': pd.DataFrame(counts),
                  'Definitions': pd.DataFrame({'Legacy_feature': OR_WEATHER,
                      'Calendar_feature': ['THI_hot_fraction_365d' if c == 'THI_hot_days_365d' else c for c in OR_WEATHER]}),
                  'Parameters': z['parameters']}
        export_ctx = dict(ctx, out=out, completed={})
        or_export(export_ctx, 'S17_Table', tables, notes)
        extra = {'Fold_metrics': fm, 'Fold_deltas': deltas, 'Holdout_metrics': pd.DataFrame(hold_metrics),
                 'Split_counts': pd.DataFrame(split_rows), 'Original_full_CV_reference': z['original_reference'],
                 'Original_full_S5_reference': z['books']['S5_Table']['Holdout_numeric'],
                 'Sources': z['sources'], 'Window_coverage': pd.DataFrame(window_rows),
                 'Hot_fraction_denominators': z['heat'], 'Validation': pd.DataFrame(checks)}
        for name, table in extra.items():
            r41_require(not {OR_PID, OR_PAIR, 'raw_row_id', 'source_row_id'} & set(table.columns), '輸出含個案識別欄')
            table.to_csv(out / 'Audit' / (name + '.csv'), index=False, encoding='utf-8-sig')
        status = {'Completed': True, 'S17_exported': True, 'Fits_requested': expected_fits,
            'Fits_succeeded': len(ledger_df), 'Bootstrap_draws_per_threshold': OR_BOOTSTRAP_DRAWS,
            'Hour_thresholds': len(R41_HOURS), 'Cohorts_changed': False, 'Age_values_changed': False,
            'Original_models_replaced': False, 'Original_files_overwritten': False,
            'Patient_records_exported': False, 'All_passed': all(c['Passed'] for c in checks),
            'New_experiment_results_require_interpretation': True}
        provenance = {'Notebook_reference': R41_SOURCE_NOTEBOOK, 'Notebook_SHA256': R41_SOURCE_SHA256,
            'Sources': z['sources'].to_dict('records'), 'Versions': dict(ctx['versions']),
            'R10_specification': z['r10_spec'], 'Seed': OR_SEED, 'CV_folds': OR_CV_FOLDS,
            'Age_cut': OR_AGE_CUT, 'Bootstrap_draws': OR_BOOTSTRAP_DRAWS,
            'Original_registry_unchanged': r34_json(ctx['completed']) == registry_before}
        # 來源規格可能含私人路徑；公開 provenance 僅保留分析定義，不複製整份來源檔。
        provenance['R10_specification'] = {k: z['r10_spec'][k] for k in
            ('Version', 'Windows_days', 'Required_days', 'Minimum_valid_fraction', 'Hot_threshold')}
        or_json(out / 'Audit/S17_provenance.json', provenance)
        or_json(out / 'run_status.json', status)
        manifest = pd.DataFrame([{'File': p.relative_to(out).as_posix(), 'Bytes': p.stat().st_size,
            'SHA256': or_sha(p)} for p in sorted(out.rglob('*')) if p.is_file()])
        manifest.to_csv(out / 'S17_manifest.csv', index=False)
        print('\n=== 請回傳：R41／S17 1 世代與保留分母 ===\n' + pd.DataFrame(counts).to_string(index=False))
        print('\n=== 請回傳：R41／S17 2 同人同折分類比較 ===\n' + display_cv.to_string(index=False))
        print('\n=== 請回傳：R41／S17 3 固定測試集 Brier ===\n' + display_hold.to_string(index=False))
        print('\n=== 請回傳：R41／S17 4 驗證與輸出 ===\n' + pd.DataFrame([status]).to_string(index=False))
        print('S17 輸出位置：', out)
        return {'Completed': True, 'tables': tables, 'audit': extra, 'status': status,
                'output_dir': str(out), 'publication': export_ctx['completed']['S17_Table']}
    except Exception as exc:
        or_json(out / 'run_status.json', {'Completed': False, 'Status': 'failed',
            'Fits_attempted': len(ledger), 'Error': str(exc)})
        raise


# BEGIN EXECUTION
R41 = None
_r41_required = ['ORIGINAL_REPRODUCTION', 'OR_CLASSIFICATION', 'R05', 'R10', 'R12',
                 'r34_prepare', 'or_estimator', 'or_export', 'OUTPUT_DIR']
_r41_missing = [name for name in _r41_required if name not in globals()]
if _r41_missing:
    raise NameError('R41 缺少本次來源：' + str(_r41_missing) + '。請先執行原 Cell 23、27、53、65、71 及其上游。')
r41_require(OR_CLASSIFICATION.get('Completed') is True, 'O06 原分類分析尚未完成')
R41 = r41_run(ORIGINAL_REPRODUCTION, R05, R10, R12, OUTPUT_DIR)